    pub fn layer_blend_interior_group(&self, id: u32) -> bool {
        self.layer_index(id)
            .map(|i| self.layers[i].blend_interior_group)
            .unwrap_or(false)
    }
    /// Advanced Blending ▸ Channels (Blending Options): the R/G/B bits this
    /// layer is allowed to blend into. Photoshop's default is all three; a
    /// cleared bit means the composite keeps the underlying value there, which
    /// is how channel-split looks are built. Bits outside R/G/B are ignored.
    pub fn set_layer_blend_channels(&mut self, id: u32, mask: u8) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            self.layers[i].blend_channels = mask & ALL_BLEND_CHANNELS;
            self.composite();
        }
    }
    pub fn layer_blend_channels(&self, id: u32) -> u8 {
        self.layer_index(id)
            .map(|i| self.layers[i].blend_channels)
            .unwrap_or(ALL_BLEND_CHANNELS)
    }
    /// Blend Clipped Layers as Group (set on a clip base). Default false.
    pub fn set_layer_blend_clipped_group(&mut self, id: u32, on: bool) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            self.layers[i].blend_clipped_group = on;
            self.composite();
        }
    }
    pub fn layer_blend_clipped_group(&self, id: u32) -> bool {
        self.layer_index(id)
            .map(|i| self.layers[i].blend_clipped_group)
            .unwrap_or(false)
    }
    // Blend-If sliders: empty disables; else 32 floats (gray/r/g/b × 8).
    pub fn set_layer_blend_if(&mut self, id: u32, vals: &[f32]) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            self.layers[i].blend_if = vals.to_vec();
            self.composite();
        }
    }
    pub fn layer_blend_if(&self, id: u32) -> Vec<f32> {
        self.layer_index(id)
            .map(|i| self.layers[i].blend_if.clone())
            .unwrap_or_default()
    }
    // One layer effect's params (see effects.rs for layouts). Empty params clears
    // it. This is the whole-type op: it collapses a multi-instance stack down to
    // the single instance given (and is how a pasted style / preset defines one).
    pub fn set_layer_effect(&mut self, id: u32, effect_id: u8, params: &[f32]) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            self.layers[i].effects.retain(|(eid, _)| *eid != effect_id);
            if !params.is_empty() {
                self.layers[i].effects.push((effect_id, params.to_vec()));
            }
            self.fx_cache.remove(&id);
            self.composite();
        }
    }
    /// How many instances of `effect_id` the layer carries. Photoshop stacks up
    /// to ten of a type (triple stroke, layered shadows); the Blending Options
    /// list addresses them through this + the `_at` pair below.
    pub fn layer_effect_count(&self, id: u32, effect_id: u8) -> u32 {
        self.layer_index(id)
            .map(|i| {
                self.layers[i]
                    .effects
                    .iter()
                    .filter(|(e, _)| *e == effect_id)
                    .count() as u32
            })
            .unwrap_or(0)
    }
    /// One *instance* of an effect. `index` counts instances of `effect_id` in
    /// render order (bottom→top within that type). Empty params removes the
    /// instance; an out-of-range index appends a new one, capped at
    /// `FX_MAX_INSTANCES` so a runaway caller can't grow the list unbounded.
    pub fn set_layer_effect_at(&mut self, id: u32, effect_id: u8, index: u32, params: &[f32]) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        let Some(i) = self.layer_index(id) else {
            return;
        };
        // Position of that instance within the layer's flat effect list.
        let at = self.layers[i]
            .effects
            .iter()
            .enumerate()
            .filter(|(_, (e, _))| *e == effect_id)
            .map(|(k, _)| k)
            .nth(index as usize);
        match (at, params.is_empty()) {
            (Some(k), true) => {
                self.layers[i].effects.remove(k);
            }
            (Some(k), false) => self.layers[i].effects[k].1 = params.to_vec(),
            (None, true) => return, // nothing there to clear
            (None, false) => {
                if self.layer_effect_count(id, effect_id) as usize >= effects::FX_MAX_INSTANCES {
                    return;
                }
                self.layers[i].effects.push((effect_id, params.to_vec()));
            }
        }
        self.fx_cache.remove(&id);
        self.composite();
    }
    /// Params of one instance (see `set_layer_effect_at`); empty when absent.
    pub fn layer_effect_params_at(&self, id: u32, effect_id: u8, index: u32) -> Vec<f32> {
        self.layer_index(id)
            .and_then(|i| {
                self.layers[i]
                    .effects
                    .iter()
                    .filter(|(e, _)| *e == effect_id)
                    .nth(index as usize)
                    .map(|(_, p)| p.clone())
            })
            .unwrap_or_default()
    }
    pub fn clear_layer_effects(&mut self, id: u32) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            self.layers[i].effects.clear();
            self.fx_cache.remove(&id);
            self.composite();
        }
    }
    pub fn layer_effect_params(&self, id: u32, effect_id: u8) -> Vec<f32> {
        self.layer_index(id)
            .and_then(|i| {
                self.layers[i]
                    .effects
                    .iter()
                    .find(|(e, _)| *e == effect_id)
                    .map(|(_, p)| p.clone())
            })
            .unwrap_or_default()
    }
    pub fn layer_has_effects(&self, id: u32) -> bool {
        self.layer_index(id)
            .map(|i| {
                self.layers[i]
                    .effects
                    .iter()
                    .any(|(_, p)| p.first().copied().unwrap_or(0.0) >= 0.5)
            })
            .unwrap_or(false)
    }

    pub fn set_layer_locked(&mut self, id: u32, locked: bool) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].locked == locked {
                return;
            }
            if self.push_stack_undo(if locked { "Lock Layer" } else { "Unlock Layer" }) {
                return;
            }
            self.layers[i].locked = locked;
        }
    }
    pub fn layer_locked(&self, id: u32) -> bool {
        self.layer_index(id)
            .map(|i| self.layers[i].locked)
            .unwrap_or(false)
    }

    /// Photoshop's three independent locks, as a bitfield so the panel and the
    /// Lock Layers dialog can set them in one undo step: 1 transparent pixels ·
    /// 2 image pixels · 4 position. Lock All stays `set_layer_locked`.
    pub fn set_layer_locks(&mut self, id: u32, flags: u8) {
        let Some(i) = self.layer_index(id) else {
            return;
        };
        let (t, im, p) = (flags & 1 != 0, flags & 2 != 0, flags & 4 != 0);
        if self.layers[i].lock_transparent == t
            && self.layers[i].lock_image == im
            && self.layers[i].lock_position == p
        {
            return;
        }
        if self.push_stack_undo("Lock Layers") {
            return;
        }
        self.layers[i].lock_transparent = t;
        self.layers[i].lock_image = im;
        self.layers[i].lock_position = p;
    }

    /// The layer's lock bitfield (see `set_layer_locks`).
    /// Layer Style ▸ Contour Editor: install the document's custom curves.
    /// `flat` is the curves end to end and `lengths` how many samples each takes,
    /// because wasm-bindgen cannot hand over a Vec<Vec<f32>>. A slot selects
    /// curve `n` with contour index `100 + n`. Replaces the whole library, which
    /// is how the editor commits an add/rename/delete in one step.
    pub fn set_contours(&mut self, flat: &[f32], lengths: &[u32]) {
        let total: usize = lengths.iter().map(|n| *n as usize).sum();
        if total != flat.len() || lengths.iter().any(|n| *n < 2) {
            return; // malformed: keep the library rather than half-replacing it
        }
        let mut curves = Vec::with_capacity(lengths.len());
        let mut at = 0usize;
        for n in lengths {
            let n = *n as usize;
            curves.push(flat[at..at + n].iter().map(|v| v.clamp(0.0, 1.0)).collect());
            at += n;
        }
        self.contours = curves;
        // Every cached effect render may have used a curve that just changed.
        self.fx_cache.clear();
        self.composite();
    }

    /// Replace the Layer Style pattern library — the tiles an effect's pattern
    /// picker can name, flattened because wasm-bindgen cannot hand over nested
    /// vectors. `widths`/`heights` are per tile and `flat` holds their rgba16
    /// pixels back to back; a 0×0 tile is an empty slot that keeps the indices
    /// after it aligned with the host's library.
    pub fn set_style_patterns(&mut self, flat: &[u16], widths: &[u32], heights: &[u32], ids: &[i32]) {
        if widths.len() != heights.len()
            || widths.len() != ids.len()
            || flat.len() > MAX_STYLE_PATTERN_SAMPLES
        {
            return;
        }
        let total: usize = widths
            .iter()
            .zip(heights)
            .map(|(w, h)| *w as usize * *h as usize * 4)
            .sum();
        if total != flat.len() {
            return; // malformed: keep the library rather than half-replacing it
        }
        let mut tiles = Vec::with_capacity(widths.len());
        let mut at = 0usize;
        for ((w, h), id) in widths.iter().zip(heights).zip(ids) {
            let n = *w as usize * *h as usize * 4;
            tiles.push((*id, *w, *h, flat[at..at + n].to_vec()));
            at += n;
        }
        self.style_patterns = tiles;
        // Every cached effect render may have used a tile that just changed.
        self.fx_cache.clear();
        self.composite();
    }

    /// How many Layer Style pattern slots the engine holds.
    pub fn style_pattern_count(&self) -> usize {
        self.style_patterns.len()
    }

    /// The style pattern library as borrowed tiles, by id; an entry the host
    /// sent empty stays `None` and renders as the checker.
    fn style_pattern_tiles(&self) -> Vec<(i32, Option<effects::Tile<'_>>)> {
        self.style_patterns
            .iter()
            .map(|(id, w, h, px)| {
                let (w, h) = (*w as usize, *h as usize);
                let tile = (w > 0 && h > 0 && px.len() >= w * h * 4)
                    .then_some(effects::Tile { px, w, h });
                (*id, tile)
            })
            .collect()
    }

    /// How many custom contour curves the document holds.
    pub fn contour_count(&self) -> usize {
        self.contours.len()
    }

    /// One custom curve's samples (empty for an unknown index).
    pub fn contour_curve(&self, index: usize) -> Vec<f32> {
        self.contours.get(index).cloned().unwrap_or_default()
    }

    pub fn layer_locks(&self, id: u32) -> u8 {
        self.layer_index(id).map_or(0, |i| {
            let l = &self.layers[i];
            (l.lock_transparent as u8) | ((l.lock_image as u8) << 1) | ((l.lock_position as u8) << 2)
        })
    }

    /// Whether the layer's pixel writes must be clipped to its existing alpha —
    /// Photoshop's Lock Transparent Pixels, which is Preserve Transparency made
    /// persistent. Read by the paint and fill paths.
    pub fn layer_locks_transparency(&self, id: u32) -> bool {
        self.layer_index(id)
            .map_or(false, |i| self.layers[i].lock_transparent)
    }
    // Add a layer mask: from the current selection if active, else fully opaque.
    pub fn add_layer_mask(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            if !self.layers[i].mask.is_empty() {
                return;
            }
            if self.push_stack_undo("Add Layer Mask") {
                return;
            }
            let n = (self.w * self.h) as usize;
            let mut mask = vec![255u8; n];
            if self.sel.active {
                for k in 0..n {
                    mask[k] = self.sel.mask[k];
                }
            }
            self.layers[i].mask = mask.into();
            self.layers[i].psd_mask = None;
            self.composite();
        }
    }

    // Layer ▸ Layer Mask ▸ Hide All / Hide Selection: the hidden counterpart of
    // add_layer_mask — a black mask (everything hidden), or, with an active
    // selection, black inside the selection and white outside (Hide Selection).
    pub fn add_layer_mask_hidden(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            if !self.layers[i].mask.is_empty() {
                return;
            }
            if self.push_stack_undo("Hide Layer Mask") {
                return;
            }
            let n = (self.w * self.h) as usize;
            let mut mask = vec![0u8; n]; // Hide All
            if self.sel.active {
                for k in 0..n {
                    mask[k] = 255 - self.sel.mask[k]; // Hide Selection: 0 in, 255 out
                }
            }
            self.layers[i].mask = mask.into();
            self.layers[i].psd_mask = None;
            self.composite();
        }
    }
    // Layer ▸ Layer Mask ▸ Reveal Selection: a mask that reveals (white) inside
    // the active selection and hides (black) outside it. Requires an active
    // selection and no existing mask (Photoshop greys it out otherwise).
    pub fn add_layer_mask_reveal_selection(&mut self, id: u32) {
        if !self.sel.active {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            if !self.layers[i].mask.is_empty() {
                return;
            }
            if self.push_stack_undo("Reveal Selection") {
                return;
            }
            let n = (self.w * self.h) as usize;
            let mut mask = vec![0u8; n];
            mask[..n].copy_from_slice(&self.sel.mask[..n]); // selection coverage reveals
            self.layers[i].mask = mask.into();
            self.layers[i].psd_mask = None;
            self.composite();
        }
    }

    // Layer ▸ Vector Mask ▸ Current Path: mask the layer to a closed polygon
    // (xs/ys, doc-space). The path is STORED on the layer (resolution-independent
    // vector data that survives save/load and can be re-rasterized), and also
    // rasterized into the layer's mask so the compositor clips to its shape.
    pub fn set_layer_vector_mask(&mut self, id: u32, xs: &[f32], ys: &[f32]) {
        if xs.len() != ys.len() {
            return;
        }
        let contour: MaskContour = xs.iter().zip(ys).map(|(&x, &y)| [x as f64, y as f64]).collect();
        self.set_vector_mask_impl(id, &[contour], Vec::new(), Vec::new());
    }

    // Bezier variant: `anchors` is 6 f32 per anchor [x,y,inX,inY,outX,outY] with
    // RELATIVE handles (the vector crate's Anchor model / the TS AnchorPath).
    // The curve source is kept on the layer and rasterized via sub-pixel
    // adaptive flattening, so the clip stays smooth at any resolution and
    // Paths-to-Illustrator exports real `C` segments instead of a polygon.
    pub fn set_layer_vector_mask_bezier(&mut self, id: u32, anchors: &[f32]) {
        // Trust boundary (scripting/MCP reach this): need ≥3 well-formed anchors
        // of finite floats to enclose an area.
        if anchors.len() % 6 != 0 || anchors.len() < 18 || anchors.iter().any(|c| !c.is_finite()) {
            return;
        }
        let (xs, ys) = flatten_anchor_loop(anchors, 0.25);
        let contour: MaskContour = xs.iter().zip(&ys).map(|(&x, &y)| [x as f64, y as f64]).collect();
        self.set_vector_mask_impl(id, &[contour], anchors.to_vec(), Vec::new());
    }

    // Several closed bezier loops as one mask — a Type ▸ Create Work Path glyph
    // outline and its counters. `lens` is the anchor count of each loop, so the
    // loops stay separate contours (holes stay holes under even-odd) and export
    // as one `M…C…Z` subpath each. (#452)
    pub fn set_layer_vector_mask_bezier_loops(&mut self, id: u32, anchors: &[f32], lens: &[u32]) {
        // Trust boundary (scripting/MCP reach this): every loop needs ≥2 anchors,
        // the lens must cover the anchors exactly, and every float is finite.
        let total = lens
            .iter()
            .try_fold(0usize, |sum, &n| sum.checked_add(n as usize))
            .and_then(|n| n.checked_mul(6));
        if lens.is_empty()
            || lens.iter().any(|&n| n < 2)
            || total != Some(anchors.len())
            || anchors.iter().any(|c| !c.is_finite())
        {
            return;
        }
        let mut contours = Vec::with_capacity(lens.len());
        let mut off = 0usize;
        for &n in lens {
            let end = off + n as usize * 6;
            let (xs, ys) = flatten_anchor_loop(&anchors[off..end], 0.25);
            contours.push(xs.iter().zip(&ys).map(|(&x, &y)| [x as f64, y as f64]).collect());
            off = end;
        }
        self.set_vector_mask_impl(id, &contours, anchors.to_vec(), lens.to_vec());
    }

    fn set_vector_mask_impl(
        &mut self,
        id: u32,
        contours: &[MaskContour],
        anchors: Vec<f32>,
        mut anchor_lens: Vec<u32>,
    ) {
        let i = match self.layer_index(id) {
            Some(i) => i,
            None => return,
        };
        // Trust boundary (scripting/MCP reach this): closed polygons of finite
        // floats. Non-finite coordinates would silently blank the mask.
        if contours.is_empty()
            || contours
                .iter()
                .any(|c| c.len() < 3 || c.iter().flatten().any(|v| !v.is_finite()))
        {
            return;
        }
        if self.push_stack_undo("Add Vector Mask") {
            return;
        }
        let mask = rasterize_mask_contours(contours, self.w, self.h);
        let (path, lens) = flat_mask_contours(contours); // one contour writes no lens
        if anchor_lens.len() <= 1 {
            anchor_lens.clear(); // empty = one loop, like the contour lens
        }
        self.layers[i].vector_path = path;
        self.layers[i].vector_subpath_lens = lens;
        self.layers[i].vector_anchors = anchors;
        self.layers[i].vector_anchor_lens = anchor_lens;
        self.layers[i].vector_is_mask = true;
        self.layers[i].mask = mask.into();
        self.layers[i].psd_mask = None;
        self.layers[i].mask_enabled = true;
        self.composite();
    }

    // Layer ▸ Vector Mask ▸ Path Operations: fold one closed polygon (xs/ys,
    // doc space) into the layer's vector mask with a Photoshop path operation —
    // 0 Combine, 1 Subtract Front Shape, 2 Intersect, 3 Exclude Overlapping —
    // so a mask can hold several subpaths and cut holes. The boolean is
    // resolved on the stored contours, so the mask stays resolution-independent
    // vector data and re-rasterizes anti-aliased. Returns false when rejected.
    pub fn combine_layer_vector_mask(&mut self, id: u32, xs: &[f32], ys: &[f32], op: u32) -> bool {
        let i = match self.layer_index(id) {
            Some(i) => i,
            None => return false,
        };
        let np = xs.len();
        if np < 3 || np != ys.len() || xs.iter().chain(ys.iter()).any(|c| !c.is_finite()) {
            return false;
        }
        let clip: Vec<MaskContour> = vec![(0..np).map(|k| [xs[k] as f64, ys[k] as f64]).collect()];
        // A work path / shape outline is not a mask, so it is never the subject:
        // the first operation on such a layer builds the mask from scratch.
        let subj = if self.layers[i].vector_is_mask {
            vector_mask_contours(
                &self.layers[i].vector_path,
                &self.layers[i].vector_subpath_lens,
            )
        } else {
            Vec::new()
        };
        let out = match boolean_mask_contours(&subj, &clip, op) {
            Some(out) => out,
            None => return false, // unknown path operation
        };
        if out.is_empty() {
            // The op cut everything away — that is Hide All, which already has a
            // representation (full-canvas frame + black mask). It pushes its own
            // undo step, so nothing has been mutated up to here.
            self.add_full_vector_mask(id, 0);
            return true;
        }
        if self.push_stack_undo("Vector Mask Path Operation") {
            return false;
        }
        let mask = rasterize_mask_contours(&out, self.w, self.h);
        let (path, lens) = flat_mask_contours(&out);
        self.layers[i].vector_path = path;
        self.layers[i].vector_subpath_lens = lens;
        // ponytail: a compound path has no single anchor loop, so the bezier
        // source is dropped; upgrade to per-subpath anchors when the Pen tool
        // needs to re-edit curves after a path operation.
        self.layers[i].vector_anchors.clear();
        self.layers[i].vector_anchor_lens.clear();
        self.layers[i].vector_is_mask = true;
        self.layers[i].mask = mask.into();
        self.layers[i].psd_mask = None;
        self.layers[i].mask_enabled = true;
        self.composite();
        true
    }

    // Bezier variant of the path operations — same anchor layout as
    // `set_layer_vector_mask_bezier`, so the Pen tool can cut a curved hole.
    pub fn combine_layer_vector_mask_bezier(&mut self, id: u32, anchors: &[f32], op: u32) -> bool {
        if anchors.len() % 6 != 0 || anchors.len() < 18 || anchors.iter().any(|c| !c.is_finite()) {
            return false;
        }
        let (xs, ys) = flatten_anchor_loop(anchors, 0.25);
        self.combine_layer_vector_mask(id, &xs, &ys, op)
    }

    // True only for an actual vector MASK (clips the layer) — not a work-path /
    // shape outline, which also stores a vector_path but doesn't mask.
    pub fn has_vector_mask(&self, id: u32) -> bool {
        self.layer_index(id)
            .map(|i| !self.layers[i].vector_path.is_empty() && self.layers[i].vector_is_mask)
            .unwrap_or(false)
    }

    // Layer ▸ Vector Mask ▸ Reveal All / Hide All: a full-canvas vector mask that
    // starts fully revealed (white) or fully hidden (black).
    pub fn add_vector_mask_reveal_all(&mut self, id: u32) {
        self.add_full_vector_mask(id, 255);
    }
    pub fn add_vector_mask_hide_all(&mut self, id: u32) {
        self.add_full_vector_mask(id, 0);
    }
    fn add_full_vector_mask(&mut self, id: u32, fill: u8) {
        if let Some(i) = self.layer_index(id) {
            if self.push_stack_undo("Add Vector Mask") {
                return;
            }
            let (w, h) = (self.w as f32, self.h as f32);
            self.layers[i].vector_path = vec![0.0, 0.0, w, 0.0, w, h, 0.0, h];
            self.layers[i].vector_subpath_lens.clear();
            self.layers[i].vector_anchors.clear();
            self.layers[i].vector_anchor_lens.clear();
            self.layers[i].vector_is_mask = true;
            self.layers[i].mask = vec![fill; (self.w * self.h) as usize].into();
            self.layers[i].psd_mask = None;
            self.layers[i].mask_enabled = true;
            self.composite();
        }
    }

    // Visible, unlocked pixel layers named by `ids`, bottom-most first. The bool
    // is true when a named layer was skipped because it is locked or position-locked.
    fn align_blend_targets(&self, ids: &[u32]) -> (Vec<usize>, bool) {
        let mut eligible = Vec::new();
        let mut skipped_locked = false;
        for &id in ids {
            let Some(i) = self.layer_index(id) else {
                continue;
            };
            let layer = &self.layers[i];
            if layer.kind != 0 || !layer.visible {
                continue;
            }
            if layer.locked || layer.lock_position {
                skipped_locked = true;
                continue;
            }
            if !eligible.contains(&i) {
                eligible.push(i);
            }
        }
        eligible.sort_unstable();
        (eligible, skipped_locked)
    }

    // Edit ▸ Auto-Align Layers: translation-only registration of the named pixel
    // layers. The bottom-most eligible layer is the reference; the others shift
    // to match it by a luminance SAD search. An empty id list aligns nothing —
    // it does not mean "every visible layer". Locked and position-locked layers
    // are left where they are. (Rotation/scale/perspective is not modelled.)
    pub fn auto_align_layers(&mut self, ids: &[u32]) {
        if self.reject_document_float_edit("Auto Align Layers") {
            return;
        }
        if ids.is_empty() {
            return;
        }
        let (eligible, skipped_locked) = self.align_blend_targets(ids);
        let Some((&ref_i, targets)) = eligible.split_first() else {
            return;
        };
        if targets.is_empty() {
            if skipped_locked {
                self.last_edit_error =
                    "Could not move the layer because its position is locked.".into();
            }
            return;
        }
        let w = self.w as i32;
        let h = self.h as i32;
        let gw = w.min(96);
        let gh = h.min(96);
        if gw < 4 || gh < 4 {
            return;
        }
        let r = 32i32;
        let luma = |layer: &Layer, fx: i32, fy: i32| -> Option<f32> {
            if fx < 0 || fy < 0 || fx >= w || fy >= h {
                return None;
            }
            let pixel = Engine::sample_layer(layer, fx, fy, w, h);
            if pixel.a <= 0.0 {
                return None;
            }
            Some(0.299 * pixel.r + 0.587 * pixel.g + 0.114 * pixel.b)
        };
        if self.push_stack_undo("Auto-Align Layers") {
            return;
        }
        for &ti in targets {
            let mut best = (0i32, 0i32);
            let mut best_sad = f32::MAX;
            for sy in -r..=r {
                for sx in -r..=r {
                    let (mut sad, mut cnt) = (0f32, 0i32);
                    for gy in 0..gh {
                        for gx in 0..gw {
                            let fx = gx * w / gw;
                            let fy = gy * h / gh;
                            if let (Some(a), Some(b)) = (
                                luma(&self.layers[ref_i], fx, fy),
                                luma(&self.layers[ti], fx - sx, fy - sy),
                            ) {
                                sad += (a - b).abs();
                                cnt += 1;
                            }
                        }
                    }
                    // Require most of the grid to overlap, else a large offset
                    // that excludes the high-contrast features wins on a
                    // featureless (all-background) remainder.
                    if cnt * 5 > gw * gh * 3 {
                        let avg = sad / cnt as f32;
                        if avg < best_sad {
                            best_sad = avg;
                            best = (sx, sy);
                        }
                    }
                }
            }
            if best != (0, 0) {
                self.shift_layer(ti, best.0, best.1);
            }
        }
        self.composite();
    }

    // Edit ▸ Auto-Blend Layers (Stack Images / focus stacking): combine the named
    // pixel layers into a new layer by taking, at each pixel, the colour from the
    // layer that is locally SHARPEST there (highest local luminance variance).
    // An empty id list blends nothing. Locked and position-locked layers are skipped.
    pub fn auto_blend_layers(&mut self, ids: &[u32]) {
        if self.reject_document_float_edit("Auto Blend Layers") {
            return;
        }
        if ids.is_empty() {
            return;
        }
        let (srcs, skipped_locked) = self.align_blend_targets(ids);
        if srcs.len() < 2 {
            if skipped_locked {
                self.last_edit_error =
                    "Could not move the layer because its position is locked.".into();
            }
            return;
        }
        let w = self.w as i32;
        let h = self.h as i32;
        let n = (w * h) as usize;
        // Each source is its OWN plane while the blend output is canvas-sized, so
        // resolve one rect per source and read every source through it. Resolved
        // before the undo push: if any source's plane is unusable we bail without
        // leaving a history step. (#65)
        let Some(rects) = srcs
            .iter()
            .map(|&li| self.plane_rect(li))
            .collect::<Option<Vec<Bounds>>>()
        else {
            return;
        };
        if self.push_stack_undo("Auto-Blend Layers") {
            return;
        }
        // Luminance maps are canvas-sized so the sharpness window can be walked in
        // canvas space; a canvas point outside a source's plane reads 0.
        let lums: Vec<Vec<f32>> = srcs
            .iter()
            .zip(rects.iter())
            .map(|(&li, &rect)| {
                let px = &self.layers[li].pixels;
                (0..n)
                    .map(|i| {
                        let (x, y) = ((i % w as usize) as i32, (i / w as usize) as i32);
                        match checked_plane_index(rect, x, y, 4) {
                            Some(p) => {
                                0.299 * px[p] as f32
                                    + 0.587 * px[p + 1] as f32
                                    + 0.114 * px[p + 2] as f32
                            }
                            None => 0.0,
                        }
                    })
                    .collect()
            })
            .collect();
        let r = 2i32;
        let mut out = vec![0u16; n * 4];
        for y in 0..h {
            for x in 0..w {
                let ci = (y * w + x) as usize;
                let mut best_li = usize::MAX;
                let mut best_pi = 0usize;
                let mut best_sharp = -1.0f32;
                for (k, &li) in srcs.iter().enumerate() {
                    // Off this source's plane == nothing to contribute here.
                    let Some(pi) = checked_plane_index(rects[k], x, y, 4) else {
                        continue;
                    };
                    if Arc::make_mut(&mut self.layers[li].pixels)[pi + 3] == 0 {
                        continue;
                    }
                    let (mut sum, mut sum2, mut cnt) = (0f32, 0f32, 0f32);
                    for dy in -r..=r {
                        for dx in -r..=r {
                            let (xx, yy) = (x + dx, y + dy);
                            if xx >= 0 && yy >= 0 && xx < w && yy < h {
                                let v = lums[k][(yy * w + xx) as usize];
                                sum += v;
                                sum2 += v * v;
                                cnt += 1.0;
                            }
                        }
                    }
                    let mean = sum / cnt;
                    let var = (sum2 / cnt - mean * mean).max(0.0);
                    if var > best_sharp {
                        best_sharp = var;
                        best_li = li;
                        best_pi = pi;
                    }
                }
                if best_li != usize::MAX {
                    for c in 0..4 {
                        out[ci * 4 + c] = self.layers[best_li].pixels[best_pi + c];
                    }
                }
            }
        }
        let mut layer = Layer::transparent(self.next_id, "Auto-Blend", self.w, self.h);
        self.next_id += 1;
        layer.pixels = out.into();
        self.layers.push(layer);
        self.active = self.layers.len() - 1;
        self.composite();
    }

    // File ▸ Automate ▸ Photomerge: stitch the visible pixel layers into a single
    // panorama layer. First register the tiles (Auto-Align), then blend their
    // overlapping content with a feathered seam so exposure and edges cross-fade
    // instead of showing a hard join.
    pub fn photomerge(&mut self) {
        if self.reject_document_float_edit("Photomerge") {
            return;
        }
        let ids: Vec<u32> = self
            .layers
            .iter()
            .filter(|l| l.kind == 0 && l.visible)
            .map(|l| l.id)
            .collect();
        self.auto_align_layers(&ids);
        self.photomerge_blend();
    }

    // The feathered-seam blend half of Photomerge, split out so it can be tested
    // without the Auto-Align registration shifting the inputs. Each contributing
    // layer is weighted by its distance to its own content edge (ramped over a
    // feather band), so overlaps cross-fade and non-overlap regions pass through.
    fn photomerge_blend(&mut self) {
        let w = self.w as i32;
        let h = self.h as i32;
        let n = (w * h) as usize;
        let srcs: Vec<usize> = (0..self.layers.len())
            .filter(|&i| self.layers[i].kind == 0 && self.layers[i].visible)
            .collect();
        if srcs.len() < 2 {
            return;
        }
        // Each source is its OWN plane; the stitched output is canvas-sized. One rect
        // per source, resolved before the undo push. (#66)
        let Some(rects) = srcs
            .iter()
            .map(|&li| self.plane_rect(li))
            .collect::<Option<Vec<Bounds>>>()
        else {
            return;
        };
        if self.push_stack_undo("Photomerge") {
            return;
        }
        let feather = ((w.min(h) as f32) * 0.15).max(1.0);
        let mut acc = vec![0f32; n * 4];
        let mut wsum = vec![0f32; n];
        for (&li, &rect) in srcs.iter().zip(rects.iter()) {
            // Content bounding box (alpha>0 extent) for the feather weight, measured
            // in CANVAS space so the feather ramp matches where the layer actually
            // lands, while the alpha it reads comes from the layer's own plane.
            let px = &self.layers[li].pixels;
            let (mut x0, mut y0, mut x1, mut y1) = (w, h, -1, -1);
            for y in 0..h {
                for x in 0..w {
                    let Some(p) = checked_plane_index(rect, x, y, 4) else {
                        continue;
                    };
                    if px[p + 3] != 0 {
                        x0 = x0.min(x);
                        y0 = y0.min(y);
                        x1 = x1.max(x);
                        y1 = y1.max(y);
                    }
                }
            }
            if x1 < x0 {
                continue; // fully transparent layer
            }
            for y in 0..h {
                for x in 0..w {
                    let i = (y * w + x) as usize;
                    let Some(p) = checked_plane_index(rect, x, y, 4) else {
                        continue;
                    };
                    if px[p + 3] == 0 {
                        continue;
                    }
                    let d = (x - x0).min(x1 - x).min(y - y0).min(y1 - y).max(0) as f32;
                    let wgt = (d / feather + 0.02).min(1.0);
                    for c in 0..4 {
                        acc[i * 4 + c] += px[p + c] as f32 * wgt;
                    }
                    wsum[i] += wgt;
                }
            }
        }
        let mut out = vec![0u16; n * 4];
        for i in 0..n {
            if wsum[i] > 0.0 {
                for c in 0..4 {
                    out[i * 4 + c] = (acc[i * 4 + c] / wsum[i]).round().clamp(0.0, 65535.0) as u16;
                }
            }
        }
        let mut layer = Layer::transparent(self.next_id, "Photomerge", self.w, self.h);
        self.next_id += 1;
        layer.pixels = out.into();
        self.layers.push(layer);
        self.active = self.layers.len() - 1;
        self.composite();
    }

    // Layer ▸ Combine Shapes, PIXEL fallback — a kind-3 shape layer combines its
    // path components re-editably through `vector_boolean` instead.
    // Boolean-combine the active layer (front shape) with
    // the layer directly below it (back shape) by their alpha coverage, writing
    // the result into the back layer and dropping the front. mode: 0/4 unite
    // (union), 1 subtract front, 2 intersect (unite at overlap), 3 exclude (xor /
    // subtract at overlap). No-op without a layer below.
    pub fn combine_shapes(&mut self, mode: u8) {
        let ai = self.active;
        if ai == 0 {
            return; // index 0 = bottom: nothing below the active layer
        }
        if self.reject_document_float_edit("Combine Shapes") {
            return;
        }
        let bi = ai - 1; // the layer below has the lower index
        // Front and back are separate PLANES and the result is written into the
        // back's, so one canvas-linear index cannot address both: walk the back plane
        // and translate each pixel through canvas space to find its front counterpart.
        // Resolved before the undo push. (#67)
        let (Some(frect), Some(brect)) = (self.plane_rect(ai), self.plane_rect(bi)) else {
            return;
        };
        if brect.w == 0 || brect.h == 0 {
            return;
        }
        if self.push_stack_undo("Combine Shapes") {
            return;
        }
        let front = self.layers[ai].pixels.clone();
        let mut out = self.layers[bi].pixels.to_vec();
        let bw = brect.w as i32;
        for k in 0..out.len() / 4 {
            let p = k * 4;
            // Back-plane pixel -> canvas point -> front-plane pixel (None when the
            // front's plane does not reach here, which reads as fully transparent).
            let cx = brect.x + (k as i32) % bw;
            let cy = brect.y + (k as i32) / bw;
            let fp = checked_plane_index(frect, cx, cy, 4);
            let fa = fp.map_or(0.0, |q| front[q + 3] as f32 / 65535.0);
            let ba = out[p + 3] as f32 / 65535.0;
            match mode {
                1 => {
                    // subtract front from back
                    out[p + 3] = ((ba * (1.0 - fa)) * 65535.0) as u16;
                }
                2 => {
                    // intersect: back clipped to where front also covers
                    out[p + 3] = ((ba * fa) * 65535.0) as u16;
                }
                3 => {
                    // exclude (xor): where exactly one covers; front wins its area
                    let fo = fa * (1.0 - ba);
                    let bo = ba * (1.0 - fa);
                    if fo > bo {
                        if let Some(q) = fp {
                            out[p] = front[q];
                            out[p + 1] = front[q + 1];
                            out[p + 2] = front[q + 2];
                        }
                    }
                    out[p + 3] = ((fo + bo) * 65535.0) as u16;
                }
                _ => {
                    // unite: front composited over back (union of the two shapes)
                    let na = fa + ba * (1.0 - fa);
                    if na > 0.0 {
                        for c in 0..3 {
                            let fv = fp.map_or(0.0, |q| front[q + c] as f32);
                            let v = (fv * fa + out[p + c] as f32 * ba * (1.0 - fa)) / na;
                            out[p + c] = v as u16;
                        }
                    }
                    out[p + 3] = (na * 65535.0) as u16;
                }
            }
        }
        self.layers[bi].pixels = out.into();
        self.layers.remove(ai); // drop the front (higher index); back stays at bi
        self.active = bi;
        self.composite();
    }

    // Layer ▸ Type ▸ Create Work Path: a type layer's glyph outlines — real font
    // Béziers from the same shaper vector text layers render with — stored on
    // the layer as a work path (NO mask — an outline, exportable to SVG as
    // curves). Convert to Shape turns the type layer into a kind-3 shape layer
    // whose scene is that outline filled with the type color, so it stays
    // editable with the vector tools. Layers without glyph data (pixel layers,
    // type whose font is not registered) keep the pixel-alpha trace below.
    pub fn create_work_path(&mut self, id: u32) {
        self.make_vector_outline(id, false, None, true);
    }
    pub fn convert_to_shape(&mut self, id: u32) {
        self.make_vector_outline(id, true, None, true);
    }

    // A type layer's glyph outlines as bezier contours whose origin is the
    // spec's text-block anchor (`ax`,`ay`): the first baseline sits at
    // max(0.8·size, ink ascent) below the block top, the rule the host's type
    // rasterizer uses, so the curves land on the rendered pixels. None when the
    // spec's font stack has no registered face, or for warped / vertical /
    // on-path type, which the vector shaper does not lay out.
    // Legacy native callers may outline simple uniform point type. Rich type
    // is routed through the host compositor and set_type_outline instead.
    fn type_glyph_outline(&self, i: usize) -> Option<Vec<crate::vector::model::PathGeometry>> {
        let l = &self.layers[i];
        if l.kind != 2 || l.text_spec.is_empty() {
            return None;
        }
        let spec: serde_json::Value = serde_json::from_str(&l.text_spec).ok()?;
        let num = |k: &str| spec.get(k).and_then(|v| v.as_f64()).map(|v| v as f32);
        let flag = |k: &str| spec.get(k).and_then(|v| v.as_bool()).unwrap_or(false);
        let text = |k: &str| spec.get(k).and_then(|v| v.as_str());
        let warped = spec
            .pointer("/warp/style")
            .and_then(|v| v.as_str())
            .is_some_and(|style| style != "none");
        let on_path = spec
            .get("path")
            .and_then(|v| v.as_array())
            .is_some_and(|p| !p.is_empty());
        if warped || on_path || flag("vertical") {
            return None;
        }
        let content: String = spec
            .get("runs")?
            .as_array()?
            .iter()
            .filter_map(|run| run.get("text")?.as_str())
            .collect();
        if content.trim().is_empty() {
            return None;
        }
        let size = num("size").filter(|s| *s > 0.0)?;
        let leading = num("leading").unwrap_or(0.0);
        let auto_leading = spec
            .pointer("/justification/autoLeading")
            .and_then(|v| v.as_f64())
            .unwrap_or(120.0) as f32;
        let mut item = serde_json::json!({
            "type": "text",
            "text": content,
            "fontFamily": text("font")?,
            "fontSize": size,
            "fontWeight": if flag("bold") { 700.0 } else { 400.0 },
            "fontStyle": if flag("italic") { "italic" } else { "normal" },
            "letterSpacing": num("tracking").unwrap_or(0.0),
            "lineHeight": if leading > 0.0 { leading / size } else { auto_leading / 100.0 },
            "horizontalScale": num("hScale").unwrap_or(1.0) * 100.0,
            "verticalScale": num("vScale").unwrap_or(1.0) * 100.0,
            "align": match text("align") {
                Some("center") => "center",
                Some("right") => "right",
                _ => "left",
            },
            "direction": text("direction").unwrap_or("ltr"),
            "composer": text("composer").unwrap_or("latin"),
        });
        if text("kind") == Some("paragraph") {
            item["boxWidth"] = num("boxW").unwrap_or(0.0).into();
        }
        let item: crate::vector::model::Item = serde_json::from_value(item).ok()?;
        let mut geos = crate::vector::render::registered_text_outline(&item)?;
        let top = geos
            .iter()
            .filter_map(crate::vector::geom::bounds)
            .map(|r| r.y)
            .fold(f32::INFINITY, f32::min);
        if !top.is_finite() {
            return None;
        }
        let ax = num("ax").unwrap_or(l.text_x as f32);
        let ay = num("ay").unwrap_or(l.text_y as f32);
        let baseline = ay + (size * 0.8).max(-top);
        for g in &mut geos {
            for a in &mut g.anchors {
                a.point.x += ax;
                a.point.y += baseline;
            }
        }
        Some(geos)
    }

    /// Outline host-positioned text with the vector renderer's registered fonts.
    /// Empty means a requested glyph has no outline data; the host keeps the
    /// existing bitmap trace for that case.
    pub fn outline_text_scene(&self, scene_json: &str) -> String {
        let Ok(mut scene) = crate::vector::model::Document::parse(scene_json) else {
            return String::new();
        };
        for layer in &mut scene.layers {
            for item in &mut layer.items {
                if item.kind != "text" { continue; }
                let Some(geos) = crate::vector::render::registered_text_outline(item) else {
                    return String::new();
                };
                item.subpaths = Some(geos.iter().map(|g|
                    crate::vector::geom::transform_geometry(g, item.transform)).collect());
                item.transform = crate::vector::model::Matrix::default();
                item.kind = "compound".into();
                item.extra.clear();
            }
        }
        serde_json::to_string(&scene).unwrap_or_default()
    }

    /// The host owns rich-text placement and warp; commit its outlined scene
    /// with the same single undo step as the legacy Type commands.
    pub fn set_type_outline(&mut self, id: u32, scene_json: &str, shape: bool) {
        if !self.layer_index(id).is_some_and(|i| self.layers[i].kind == 2) { return; }
        if scene_json.is_empty() {
            self.make_vector_outline(id, shape, None, false);
        } else if let Ok(scene) = crate::vector::model::Document::parse(scene_json) {
            self.make_vector_outline(id, shape, Some(scene), false);
        }
    }

    fn make_vector_outline(&mut self, id: u32, rasterize_first: bool,
        prepared: Option<crate::vector::model::Document>, legacy_layout: bool) {
        let i = match self.layer_index(id) {
            Some(i) => i,
            None => return,
        };
        // The traced path is in CANVAS coordinates, so the alpha it reads must be
        // sampled from the layer's PLANE through its rect. Resolved before the undo
        // push. (#74)
        let Some(rect) = self.plane_rect(i) else {
            return;
        };
        if self.refuse_locked_vector(id) { return; }
        // The Type menu uses host layout -> outline_text_scene -> set_type_outline.
        // Raw compatibility calls must never silently trace or flatten rich type.
        if legacy_layout && self.layers[i].kind == 2 {
            if let Ok(spec) = serde_json::from_str::<serde_json::Value>(&self.layers[i].text_spec) {
                let rich = spec.get("vertical").and_then(|v| v.as_bool()) == Some(true)
                    || spec.get("kind").and_then(|v| v.as_str()) == Some("paragraph")
                    || spec.get("path").and_then(|v| v.as_array()).is_some_and(|p| p.len() >= 4)
                    || spec.pointer("/warp/style").and_then(|v| v.as_str()).is_some_and(|v| v != "none")
                    || spec.get("runs").and_then(|v| v.as_array()).is_some_and(|runs| runs.iter().any(|r|
                        r.as_object().is_some_and(|r| r.keys().any(|k| k != "text"))));
                if rich {
                    self.last_edit_error = "Rich Type outlines require the host text layout; use the Type menu.".into();
                    return;
                }
            }
        }
        let glyphs = prepared.or_else(|| {
            if !legacy_layout { return None; }
            let geos = self.type_glyph_outline(i)?;
            let rgba = text_spec_color(&self.layers[i].text_spec);
            crate::vector::model::Document::parse(&serde_json::json!({
                "layers": [{"id":"l1", "items": [{"type":"compound", "id":"c1",
                    "fill":{"type":"solid", "color":{"r":rgba[0], "g":rgba[1], "b":rgba[2], "a":rgba[3]/255.0}},
                    "subpaths":geos}]}]
            }).to_string()).ok()
        });
        if self.push_stack_undo(if rasterize_first { "Convert to Shape" } else { "Create Work Path" }) {
            return;
        }
        if let Some(doc) = glyphs {
            let l = &mut self.layers[i];
            if rasterize_first {
                // Convert to Shape: the type layer becomes a shape layer — one
                // compound item (nonzero winding, so counters stay holes) filled
                // with the type color, rasterized on demand like any kind-3 layer.
                l.kind = 3;
                l.text_spec.clear();
                l.text.clear();
                l.vector_scene = Some(Box::new(doc));
                l.vector_view = [0.0, 0.0, 1.0, 0.0];
                l.vector_id_counter = 1;
                l.vector_cache_key = None;
                self.render_vector(i);
            } else {
                // Create Work Path: the outline stays with the type layer, in
                // canvas coordinates like the traced form (the scene above is
                // rendered through the layer offset instead).
                let (mut path, mut lens, mut anchors, mut anchor_lens) =
                    (Vec::new(), Vec::new(), Vec::new(), Vec::new());
                for g in doc.layers.iter().flat_map(|layer| &layer.items)
                    .filter_map(|item| item.subpaths.as_ref()).flatten() {
                    let mut pts = crate::vector::geom::flatten(g, 0.25);
                    if g.closed {
                        pts.pop(); // the closing segment repeats anchor 0
                    }
                    if pts.len() < 3 || g.anchors.len() < 2 {
                        continue;
                    }
                    lens.push(pts.len() as u32);
                    anchor_lens.push(g.anchors.len() as u32);
                    for p in &pts {
                        path.extend([p.x + l.ox as f32, p.y + l.oy as f32]);
                    }
                    for a in &g.anchors {
                        anchors.extend([
                            a.point.x + l.ox as f32,
                            a.point.y + l.oy as f32,
                            a.handle_in.x,
                            a.handle_in.y,
                            a.handle_out.x,
                            a.handle_out.y,
                        ]);
                    }
                }
                l.vector_path = path;
                l.vector_subpath_lens = lens;
                l.vector_anchors = anchors;
                l.vector_anchor_lens = anchor_lens;
                l.vector_is_mask = false;
            }
            self.composite();
            return;
        }
        // ponytail: no glyph data (a pixel layer, or type whose font stack has no
        // registered face — bitmap fallback only): keep the pixel-alpha trace,
        // corner loops with no handles, and Convert to Shape keeps flipping the
        // type layer to pixels + outline. Upgrade path: provision the font.
        if rasterize_first && self.layers[i].kind == 2 {
            self.layers[i].kind = 0; // type → pixels (the shape's fill)
            self.layers[i].text_spec.clear();
        }
        let (cw, ch) = (self.w as i32, self.h as i32);
        let mut alpha = vec![0u8; (cw as usize) * (ch as usize)];
        {
            let px = &self.layers[i].pixels;
            for y in 0..ch {
                for x in 0..cw {
                    if let Some(p) = checked_plane_index(rect, x, y, 4) {
                        alpha[(y as usize) * (cw as usize) + x as usize] =
                            (px[p + 3] >> 8) as u8;
                    }
                }
            }
        }
        let (path, lens) = trace_mask_contours(&alpha, self.w as i32, self.h as i32);
        self.layers[i].vector_path = path;
        self.layers[i].vector_subpath_lens = lens;
        self.layers[i].vector_anchors.clear(); // traced contours are corner loops
        self.layers[i].vector_anchor_lens.clear();
        self.layers[i].vector_is_mask = false; // outline only — does not clip
        self.composite();
    }

    // File ▸ Export ▸ Paths to Illustrator: emit every layer's vector geometry as
    // SVG (Illustrator opens SVG). A kind-3 shape layer exports its whole scene —
    // real Béziers with fill, stroke, gradients and clip groups, matching what
    // Photoshop writes for shape layers; every other layer contributes its vector
    // mask / work path as a stroked outline. Empty document frame if there is no
    // vector content yet.
    pub fn export_paths_svg(&self) -> String {
        self.paths_svg(None)
    }

    // Layer ▸ Copy SVG: one layer's vector geometry as a standalone SVG document
    // — real `<path d="…">` art a vector app pastes as editable curves. Empty
    // string when the layer has no vector content, so the caller can fall back to
    // embedding pixels.
    pub fn export_layer_svg(&self, id: u32) -> String {
        self.paths_svg(Some(id))
    }

    fn paths_svg(&self, only: Option<u32>) -> String {
        let mut defs = String::new();
        let mut s = String::new();
        let mut uid = 0u32;
        for l in &self.layers {
            if only.is_some_and(|id| l.id != id) {
                continue;
            }
            // Shape layers first: the scene is the source of truth here, and the
            // same layer's `vector_path` (if any) is only its clipping mask.
            if l.kind == 3 && l.visible {
                if let Some(scene) = l.vector_scene.as_deref() {
                    let mut inner = String::new();
                    for sl in &scene.layers {
                        if !sl.visible || sl.template {
                            continue;
                        }
                        let mut items = String::new();
                        for item in &sl.items {
                            Self::svg_write_item(item, &mut defs, &mut uid, &mut items);
                        }
                        if !items.is_empty() {
                            inner.push_str(&format!(
                                "   <g{}>\n{}   </g>\n",
                                Self::svg_opacity_attr(sl.opacity),
                                items
                            ));
                        }
                    }
                    if !inner.is_empty() {
                        // Same world→canvas view the rasterizer uses, plus the
                        // layer offset, so the paths land on the composite.
                        let t = self.vector_view_transform(l.vector_view);
                        s.push_str(&format!(
                            "  <g transform=\"translate({},{}) matrix({:.4},{:.4},{:.4},{:.4},{:.3},{:.3})\"{}>\n{}  </g>\n",
                            l.ox, l.oy, t.sx, t.ky, t.kx, t.sy, t.tx, t.ty,
                            Self::svg_opacity_attr(l.opacity),
                            inner
                        ));
                    }
                }
            }
            if l.vector_path.len() < 6 {
                continue;
            }
            // A bezier-backed path exports as true curves — M + C segments per
            // contour — so Illustrator gets editable smooth outlines, not a
            // faceted polygon.
            if l.vector_anchors.len() >= 12 {
                let total = l.vector_anchors.len() / 6;
                let loops: Vec<usize> = if l.vector_anchor_lens.is_empty() {
                    vec![total]
                } else {
                    l.vector_anchor_lens.iter().map(|&n| n as usize).collect()
                };
                let mut d = String::new();
                let mut off = 0usize;
                for &n in &loops {
                    if n < 2 || off + n > total {
                        break;
                    }
                    let a = |i: usize, k: usize| l.vector_anchors[(off + i % n) * 6 + k];
                    d.push_str(&format!("M{:.2},{:.2} ", a(0, 0), a(0, 1)));
                    for i in 0..n {
                        let j = i + 1; // wraps: closes back to anchor 0
                        d.push_str(&format!(
                            "C{:.2},{:.2} {:.2},{:.2} {:.2},{:.2} ",
                            a(i, 0) + a(i, 4),
                            a(i, 1) + a(i, 5),
                            a(j, 0) + a(j, 2),
                            a(j, 1) + a(j, 3),
                            a(j, 0),
                            a(j, 1),
                        ));
                    }
                    d.push_str("Z ");
                    off += n;
                }
                s.push_str(&format!(
                    "  <path fill=\"none\" stroke=\"#000\" fill-rule=\"evenodd\" d=\"{}\" />\n",
                    d.trim()
                ));
                continue;
            }
            // Split the flat point list into sub-contours (lens empty = one).
            let total = l.vector_path.len() / 2;
            let lens: Vec<usize> = if l.vector_subpath_lens.is_empty() {
                vec![total]
            } else {
                l.vector_subpath_lens.iter().map(|&n| n as usize).collect()
            };
            let mut d = String::new();
            let mut off = 0usize;
            for &cnt in &lens {
                if cnt < 3 || off + cnt > total {
                    break;
                }
                for k in 0..cnt {
                    let (x, y) = (
                        l.vector_path[(off + k) * 2],
                        l.vector_path[(off + k) * 2 + 1],
                    );
                    d.push_str(&format!(
                        "{}{:.2},{:.2} ",
                        if k == 0 { "M" } else { "L" },
                        x,
                        y
                    ));
                }
                d.push_str("Z ");
                off += cnt;
            }
            s.push_str(&format!(
                "  <path fill=\"none\" stroke=\"#000\" fill-rule=\"evenodd\" d=\"{}\" />\n",
                d.trim()
            ));
        }
        // Single-layer requests report "no vector art" as an empty string rather
        // than an empty frame — the caller needs to tell the two apart.
        if only.is_some() && s.is_empty() {
            return String::new();
        }
        format!(
            "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" viewBox=\"0 0 {} {}\">\n{}{}</svg>\n",
            self.w,
            self.h,
            self.w,
            self.h,
            if defs.is_empty() {
                String::new()
            } else {
                format!("  <defs>\n{}  </defs>\n", defs)
            },
            s
        )
    }

    // ── kind-3 vector scene → SVG ───────────────────────────────────────────
    // A scene item's own affine, as an SVG attribute (omitted when identity).
    fn svg_transform_attr(m: crate::vector::model::Matrix) -> String {
        if m.a == 1.0 && m.b == 0.0 && m.c == 0.0 && m.d == 1.0 && m.e == 0.0 && m.f == 0.0 {
            return String::new();
        }
        format!(
            " transform=\"matrix({:.4},{:.4},{:.4},{:.4},{:.3},{:.3})\"",
            m.a, m.b, m.c, m.d, m.e, m.f
        )
    }

    fn svg_opacity_attr(o: f32) -> String {
        if o >= 1.0 {
            String::new()
        } else {
            format!(" opacity=\"{:.3}\"", o.clamp(0.0, 1.0))
        }
    }

    // Subpaths → an SVG `d`. Built from `geom::segments`, so the emitted curves
    // are exactly the cubics the rasterizer draws — no polyline flattening.
    fn svg_path_d(geos: &[crate::vector::model::PathGeometry]) -> String {
        let mut d = String::new();
        for g in geos {
            let Some(first) = g.anchors.first() else {
                continue;
            };
            d.push_str(&format!("M{:.3},{:.3}", first.point.x, first.point.y));
            for c in crate::vector::geom::segments(g) {
                d.push_str(&format!(
                    " C{:.3},{:.3} {:.3},{:.3} {:.3},{:.3}",
                    c.p1.x, c.p1.y, c.p2.x, c.p2.y, c.p3.x, c.p3.y
                ));
            }
            if g.closed {
                d.push_str(" Z");
            }
            d.push(' ');
        }
        d.trim_end().to_string()
    }

    // A paint as (attribute value, its own opacity). Gradients are hoisted into
    // `defs` in userSpaceOnUse against the item's local bounds, mapped with the
    // same objectBoundingBox→user formula `render::gradient_shader` uses, so the
    // exported ramp lands where the rasterizer puts it.
    fn svg_paint(
        paint: &crate::vector::model::Paint,
        bounds: Option<crate::vector::geom::Rect>,
        defs: &mut String,
        uid: &mut u32,
    ) -> (String, f32) {
        use crate::vector::model::Paint;
        let chan = |v: f32| v.clamp(0.0, 255.0).round() as u8;
        match paint {
            Paint::Solid { color } => (
                format!("rgb({},{},{})", chan(color.r), chan(color.g), chan(color.b)),
                color.a.clamp(0.0, 1.0),
            ),
            Paint::Gradient { gradient } if !gradient.stops.is_empty() && bounds.is_some() => {
                let b = bounds.expect("checked by the guard");
                let (bw, bh) = (b.w.max(1e-3), b.h.max(1e-3));
                let map = |ux: f32, uy: f32| (b.x + ux * bw, b.y + uy * bh);
                // ponytail: midpoint diamonds export as plain stops — the exact
                // expansion lives in the private `render::expanded_gradient_stops`;
                // make it pub(crate) and call it here if the drift shows.
                let mut stops = String::new();
                for st in &gradient.stops {
                    stops.push_str(&format!(
                        "<stop offset=\"{:.4}\" stop-color=\"rgb({},{},{})\" stop-opacity=\"{:.3}\"/>",
                        st.offset.clamp(0.0, 1.0),
                        chan(st.color.r),
                        chan(st.color.g),
                        chan(st.color.b),
                        st.color.a.clamp(0.0, 1.0)
                    ));
                }
                // Whitelisted: `spread` comes straight from document JSON.
                let spread = match gradient.spread.as_deref() {
                    Some("reflect") => " spreadMethod=\"reflect\"",
                    Some("repeat") => " spreadMethod=\"repeat\"",
                    _ => "",
                };
                *uid += 1;
                let id = format!("mg{}", uid);
                if gradient.kind == "radial" {
                    let (cx, cy) = map(gradient.cx, gradient.cy);
                    let (fx, fy) = match (gradient.fx, gradient.fy) {
                        (Some(x), Some(y)) => map(x, y),
                        _ => (cx, cy),
                    };
                    let r = (gradient.r * (bw + bh) * 0.5).max(1e-3);
                    defs.push_str(&format!(
                        "    <radialGradient id=\"{}\" gradientUnits=\"userSpaceOnUse\" cx=\"{:.3}\" cy=\"{:.3}\" r=\"{:.3}\" fx=\"{:.3}\" fy=\"{:.3}\"{}>{}</radialGradient>\n",
                        id, cx, cy, r, fx, fy, spread, stops
                    ));
                } else {
                    let (x1, y1) = map(gradient.x1, gradient.y1);
                    let (x2, y2) = map(gradient.x2, gradient.y2);
                    defs.push_str(&format!(
                        "    <linearGradient id=\"{}\" gradientUnits=\"userSpaceOnUse\" x1=\"{:.3}\" y1=\"{:.3}\" x2=\"{:.3}\" y2=\"{:.3}\"{}>{}</linearGradient>\n",
                        id, x1, y1, x2, y2, spread, stops
                    ));
                }
                (format!("url(#{})", id), 1.0)
            }
            // ponytail: pattern paints export as nothing — the tile is a nested
            // item list; re-emit it as an SVG <pattern> if authored tiles appear.
            _ => ("none".to_string(), 0.0),
        }
    }

    // One scene item → SVG, groups recursed. Mirrors `render::render_item`'s
    // visibility/clip semantics.
    // ponytail: text, images, effects, per-item masks and blend modes are not
    // vectorized — text needs the private glyph outliner (`render::build_text_path`)
    // and images need the `href` payload re-embedded. They still reach the file
    // through `exportDocumentSVG`'s raster plate; wire the outliner in when shape
    // layers routinely carry live type.
    fn svg_write_item(
        item: &crate::vector::model::Item,
        defs: &mut String,
        uid: &mut u32,
        out: &mut String,
    ) {
        if !item.visible || item.opacity <= 0.0 {
            return;
        }
        let head = format!(
            "{}{}",
            Self::svg_transform_attr(item.transform),
            Self::svg_opacity_attr(item.opacity)
        );
        if item.kind == "group" {
            let children = item.children.as_deref().unwrap_or(&[]);
            // Clip group: the first child is the clip shape (render_group_children).
            let (clip, kids) = match children.split_first() {
                Some((shape, rest)) if item.clip && !rest.is_empty() => {
                    let d = Self::svg_path_d(&crate::vector::shapes::local_paths(shape));
                    if d.is_empty() {
                        (String::new(), rest)
                    } else {
                        *uid += 1;
                        defs.push_str(&format!(
                            "    <clipPath id=\"mc{}\" clipPathUnits=\"userSpaceOnUse\"><path{} d=\"{}\"/></clipPath>\n",
                            uid,
                            Self::svg_transform_attr(shape.transform),
                            d
                        ));
                        (format!(" clip-path=\"url(#mc{})\"", uid), rest)
                    }
                }
                _ => (String::new(), children),
            };
            let mut inner = String::new();
            for c in kids {
                Self::svg_write_item(c, defs, uid, &mut inner);
            }
            if !inner.is_empty() {
                out.push_str(&format!("    <g{}{}>\n{}    </g>\n", head, clip, inner));
            }
            return;
        }
        let geos = crate::vector::shapes::local_paths(item);
        let d = Self::svg_path_d(&geos);
        if d.is_empty() {
            return; // text / image / degenerate geometry
        }
        let mut bb: Option<crate::vector::geom::Rect> = None;
        for g in &geos {
            if let Some(r) = crate::vector::geom::bounds(g) {
                bb = Some(crate::vector::geom::union(bb, r));
            }
        }
        // Always emit `fill` — SVG's default is black, which would flood open
        // work paths that only carry a stroke.
        let (fill, fill_a) = Self::svg_paint(&item.fill, bb, defs, uid);
        let mut attrs = format!(" fill=\"{}\"", fill);
        if fill != "none" && fill_a < 1.0 {
            attrs.push_str(&format!(" fill-opacity=\"{:.3}\"", fill_a));
        }
        if item.even_odd {
            attrs.push_str(" fill-rule=\"evenodd\"");
        }
        let st = &item.stroke;
        if st.width > 0.0 {
            let (paint, alpha) = Self::svg_paint(&st.paint, bb, defs, uid);
            if paint != "none" {
                // ponytail: `align` (inner/outer) has no SVG equivalent and
                // variable `width_profile` needs the stroke outliner — both
                // export as a plain centered stroke.
                attrs.push_str(&format!(
                    " stroke=\"{}\" stroke-width=\"{:.3}\"",
                    paint, st.width
                ));
                if alpha < 1.0 {
                    attrs.push_str(&format!(" stroke-opacity=\"{:.3}\"", alpha));
                }
                // Whitelisted: cap/join come straight from document JSON.
                if matches!(st.cap.as_str(), "round" | "square") {
                    attrs.push_str(&format!(" stroke-linecap=\"{}\"", st.cap));
                }
                if matches!(st.join.as_str(), "round" | "bevel") {
                    attrs.push_str(&format!(" stroke-linejoin=\"{}\"", st.join));
                }
                if st.miter_limit != 4.0 {
                    attrs.push_str(&format!(" stroke-miterlimit=\"{:.3}\"", st.miter_limit));
                }
                if !st.dash.is_empty() {
                    let dash: Vec<String> = st.dash.iter().map(|v| format!("{:.3}", v)).collect();
                    attrs.push_str(&format!(" stroke-dasharray=\"{}\"", dash.join(",")));
                    if st.dash_offset != 0.0 {
                        attrs.push_str(&format!(" stroke-dashoffset=\"{:.3}\"", st.dash_offset));
                    }
                }
            }
        }
        out.push_str(&format!("    <path{}{} d=\"{}\"/>\n", head, attrs, d));
    }

    // Layer ▸ Vector Mask ▸ Delete: drop the vector path AND its rasterized mask.
    pub fn delete_vector_mask(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            // A work path / shape outline also fills vector_path but does not
            // clip, and this function clears the RASTER mask too — so gating on
            // vector_path alone let Delete Vector Mask wipe a layer mask.
            if !self.has_vector_mask(id) {
                self.last_edit_error = "Could not delete the vector mask because this layer has none.".into();
                return;
            }
            if self.push_stack_undo("Delete Vector Mask") {
                return;
            }
            self.layers[i].vector_path.clear();
            self.layers[i].vector_subpath_lens.clear();
            self.layers[i].vector_anchors.clear();
            self.layers[i].vector_anchor_lens.clear();
            self.layers[i].mask = Arc::from(Vec::new());
            self.layers[i].psd_mask = None;
            self.composite();
        }
    }

    // Layer ▸ Rasterize ▸ Vector Mask: drop the vector path but KEEP the mask it
    // produced (the clip becomes a plain pixel mask).
    pub fn rasterize_vector_mask(&mut self, id: u32) -> bool {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].vector_path.is_empty() {
                return false;
            }
            if self.push_stack_undo("Rasterize Vector Mask") {
                return false;
            }
            self.layers[i].vector_path.clear();
            self.layers[i].vector_subpath_lens.clear();
            self.layers[i].vector_anchors.clear();
            self.layers[i].vector_anchor_lens.clear();
            return true;
        }
        false
    }

    // Layer ▸ Layer Mask ▸ Hide Selection: the inverse — hides (black) inside the
    // selection, reveals (white) outside. Requires an active selection.
    pub fn add_layer_mask_hide_selection(&mut self, id: u32) {
        if !self.sel.active {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            if !self.layers[i].mask.is_empty() {
                return;
            }
            if self.push_stack_undo("Hide Selection") {
                return;
            }
            let n = (self.w * self.h) as usize;
            let mut mask = vec![0u8; n];
            for k in 0..n {
                mask[k] = 255 - self.sel.mask[k];
            }
            self.layers[i].mask = mask.into();
            self.layers[i].psd_mask = None;
            self.composite();
        }
    }

    /// Masks panel ▸ Invert (⌘I on a mask): flip the active layer's mask.
    ///
    /// Distinct from `adjust_invert`, which inverts whatever the current edit
    /// target is — this always means the mask, so the Masks panel button does not
    /// depend on the brush's mask-edit toggle being on first. Returns false when
    /// the active layer has no mask to invert.
    pub fn invert_mask(&mut self) -> bool {
        let filter_masking = self.painting_filter_mask();
        let active = self.active;
        let n = (self.w as usize).saturating_mul(self.h as usize);
        let len = if filter_masking {
            self.layers[active].smart_mask.len()
        } else {
            self.layers[active].mask.len()
        };
        if n == 0 || len != n {
            return false;
        }
        if self.push_stack_undo("Invert Mask") {
            return false;
        }
        let layer = &mut self.layers[active];
        let mask = if filter_masking {
            &mut layer.smart_mask
        } else {
            Arc::make_mut(&mut layer.mask)
        };
        for coverage in mask.iter_mut() {
            *coverage = 255 - *coverage;
        }
        if !filter_masking {
            layer.psd_mask = None;
        }
        if filter_masking {
            self.render_smart(active);
        }
        self.composite();
        true
    }

    pub fn delete_layer_mask(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].mask.is_empty() {
                return;
            }
            if self.push_stack_undo("Delete Layer Mask") {
                return;
            }
            self.layers[i].mask = Vec::new().into();
            self.layers[i].psd_mask = None;
            self.reset_mask_properties(i);
            self.composite();
        }
    }
    // Density/Feather belong to the mask, so they go with it. A later mask on
    // this layer must not silently inherit the old one's Properties.
    fn reset_mask_properties(&mut self, i: usize) {
        self.layers[i].mask_density = 255;
        self.layers[i].mask_feather = 0.0;
        self.layers[i].mask_soft = Vec::new();
        self.layers[i].mask_soft_key = 0;
    }
    // Bake the mask into the layer's alpha, then remove the mask.
    pub fn apply_layer_mask(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].mask.is_empty() {
                return;
            }
            if self.refuse_mask_bake(i) {
                return;
            }
            // The mask is CANVAS-sized while the layer's pixels are its own PLANE, so
            // the two need different indices: `k` walks the canvas for mask coverage,
            // `pi` is that same point translated into the plane. Resolved before the
            // undo push so an unusable plane costs no history step. (#68)
            let Some(rect) = self.plane_rect(i) else {
                return;
            };
            if self.push_stack_undo("Apply Layer Mask") {
                return;
            }
            // Bake what the viewer sees — the mask AFTER Density and Feather,
            // not the raw bytes (Photoshop applies the effective mask too).
            self.ensure_mask_soft(i);
            let (cw, ch) = (self.w as i32, self.h as i32);
            for y in 0..ch {
                for x in 0..cw {
                    // Plane pixels outside the canvas are the crop reserve; the mask
                    // has no coverage there, so they keep their alpha untouched.
                    let Some(pi) = checked_plane_index(rect, x, y, 4) else {
                        continue;
                    };
                    let k = (y as usize) * (cw as usize) + (x as usize);
                    let m = self.layers[i].mask_cov_at(k);
                    if !self.layers[i].pixels_f32.is_empty() {
                        Arc::make_mut(&mut self.layers[i].pixels_f32)[pi + 3] *= m;
                        Arc::make_mut(&mut self.layers[i].pixels)[pi + 3] =
                            float_preview_u16(self.layers[i].pixels_f32[pi + 3]);
                    } else {
                        let a = self.layers[i].pixels[pi + 3] as f32 / 65535.0;
                        Arc::make_mut(&mut self.layers[i].pixels)[pi + 3] = color::to16(a * m);
                    }
                }
            }
            self.layers[i].mask = Vec::new().into();
            self.layers[i].psd_mask = None;
            self.reset_mask_properties(i);
            Self::rasterize_fill_metadata(&mut self.layers[i]);
            self.composite();
        }
    }
    // Bounding box [x, y, w, h] of the active layer's opaque content, or
    // [0,0,0,0] when the layer is empty. Used by View ▸ Show ▸ Layer Edges.
    // Smart Guides: content bbox of every visible non-group/non-adjustment layer
    // as flat [id, x, y, w, h, …]. The caller excludes the layer being dragged.
    pub fn all_layer_bounds(&self) -> Vec<i32> {
        let mut out = Vec::new();
        for (i, l) in self.layers.iter().enumerate() {
            if !l.visible || l.kind == 6 || l.kind == 1 {
                continue;
            }
            if let Some((minx, miny, maxx, maxy)) = self.layer_bbox(i) {
                out.extend_from_slice(&[l.id as i32, minx, miny, maxx - minx + 1, maxy - miny + 1]);
            }
        }
        out
    }

    pub fn active_layer_bounds(&self) -> Vec<i32> {
        match self.layer_bbox(self.active) {
            Some((minx, miny, maxx, maxy)) => {
                vec![minx, miny, maxx - minx + 1, maxy - miny + 1]
            }
            None => vec![0, 0, 0, 0],
        }
    }

    // Layer ▸ Layer Style ▸ Hide All Effects / Show All Effects (document-wide).
    pub fn set_effects_visible(&mut self, visible: bool) {
        if self.effects_visible == visible {
            return;
        }
        self.effects_visible = visible;
        self.fx_cache.clear(); // force the effect renders to rebuild (or drop)
        self.composite();
    }
    pub fn effects_visible(&self) -> bool {
        self.effects_visible
    }

    // Layer ▸ Isolate Layers: solo a set of layer ids (empty = show all). A
    // transient view filter — never undone or serialized.
    pub fn set_solo(&mut self, ids: &[u32]) {
        self.solo = ids.to_vec();
        self.composite();
    }
    pub fn is_soloed(&self) -> bool {
        !self.solo.is_empty()
    }

    pub fn layer_has_mask(&self, id: u32) -> bool {
        self.layer_index(id)
            .map(|i| !self.layers[i].mask.is_empty())
            .unwrap_or(false)
    }
    /// Any sample short of fully opaque. Save uses this to refuse a JPEG that
    /// would drop the layer's transparency. Float documents read `pixels_f32`;
    /// everything else reads the 16-bit plane.
    pub fn layer_has_transparency(&self, id: u32) -> bool {
        let Some(i) = self.layer_index(id) else {
            return false;
        };
        let layer = &self.layers[i];
        if !layer.pixels_f32.is_empty() {
            return layer
                .pixels_f32
                .chunks_exact(4)
                .any(|px| !px[3].is_finite() || px[3] < 1.0 - 1e-4);
        }
        layer.pixels.chunks_exact(4).any(|px| px[3] < 65535)
    }
    /// The mask as its own grayscale RGBA thumbnail (tw*th*4) for the Layers
    /// panel's second thumbnail. Empty when the layer has no mask. A *disabled*
    /// mask still renders — Photoshop keeps showing it under the red X. Reads
    /// the same effective coverage the compositor does (Feather + Density), so
    /// the thumbnail matches what the mask is doing.
    pub fn layer_mask_thumb(&self, id: u32, tw: u32, th: u32) -> Vec<u8> {
        let mut out = Vec::new();
        let (w, h) = (self.w, self.h);
        let Some(i) = self.layer_index(id) else {
            return out;
        };
        let layer = &self.layers[i];
        if tw == 0 || th == 0 || layer.mask.len() != (w * h) as usize {
            return out;
        }
        out = vec![0u8; (tw * th * 4) as usize];
        for ty in 0..th {
            for tx in 0..tw {
                let sx = (tx * w / tw).min(w - 1);
                let sy = (ty * h / th).min(h - 1);
                let v = (layer.mask_cov_at((sy * w + sx) as usize) * 255.0).round() as u8;
                let di = (ty * tw + tx) as usize * 4;
                out[di] = v;
                out[di + 1] = v;
                out[di + 2] = v;
                out[di + 3] = 255;
            }
        }
        out
    }

    /// The effective mask as a full-size grayscale plane (w*h, 255 = reveals)
    /// for the display-only mask previews: ⌥-click shows the mask alone,
    /// `\` paints it as a red rubylith over the image. Empty when the layer has
    /// no mask. Like Quick Mask, this never touches the composite, so export /
    /// pick_color / histogram stay untinted.
    /// ponytail: one copy per preview rebuild (toggle, doc swap, commit) — swap
    /// in a pointer view if the preview ever has to refresh per brush dab.
    pub fn layer_mask_gray(&self, id: u32) -> Vec<u8> {
        let (w, h) = (self.w, self.h);
        let Some(i) = self.layer_index(id) else {
            return Vec::new();
        };
        let layer = &self.layers[i];
        if layer.mask.len() != (w * h) as usize {
            return Vec::new();
        }
        (0..layer.mask.len())
            .map(|i| (layer.mask_cov_at(i) * 255.0).round() as u8)
            .collect()
    }

    /// ⌘-click a layer thumbnail: the layer's own transparency as document-sized
    /// coverage, so Load Selection can combine it exactly like a saved channel.
    /// Reads through `sample_layer` rather than indexing `pixels` directly, so a
    /// compact off-canvas plane, a Move offset and 32-bit float authority all
    /// stay correct — the canvas-stride-on-plane trap. Empty when the id is gone.
    pub fn layer_alpha_gray(&self, id: u32) -> Vec<u8> {
        let (w, h) = (self.w as i32, self.h as i32);
        let Some(i) = self.layer_index(id) else {
            return Vec::new();
        };
        let layer = &self.layers[i];
        let mut out = vec![0u8; (w as usize) * (h as usize)];
        for y in 0..h {
            for x in 0..w {
                let a = Self::sample_layer(layer, x, y, w, h).a;
                out[(y as usize) * (w as usize) + (x as usize)] =
                    (a.clamp(0.0, 1.0) * 255.0).round() as u8;
            }
        }
        out
    }

    /// One pixel of the ACTIVE layer, packed RGBA8 (0xRRGGBBAA) in layer-local
    /// straight alpha — not the composite `pick_color` reads. The Pencil's Auto
    /// Erase asks this at stroke start: does the pixel under the pointer already
    /// wear the foreground colour? Out of range reads transparent. (#432)
    pub fn active_layer_pixel(&self, x: i32, y: i32) -> u32 {
        let (w, h) = (self.w as i32, self.h as i32);
        if x < 0 || y < 0 || x >= w || y >= h {
            return 0;
        }
        let c = Self::sample_layer(&self.layers[self.active], x, y, w, h);
        let q = |v: f32| (v.clamp(0.0, 1.0) * 255.0).round() as u32;
        (q(c.r) << 24) | (q(c.g) << 16) | (q(c.b) << 8) | q(c.a)
    }

    // Layer ▸ Layer Mask ▸ Enable / Disable: toggle whether the mask is applied
    // (the mask data is kept either way). No-op if the layer has no mask.
    pub fn set_layer_mask_enabled(&mut self, id: u32, enabled: bool) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].mask.is_empty() || self.layers[i].mask_enabled == enabled {
                return;
            }
            if self.push_stack_undo(if enabled {
                "Enable Layer Mask"
            } else {
                "Disable Layer Mask"
            }) {
                return;
            }
            self.layers[i].mask_enabled = enabled;
            if let Some(mask) = &mut self.layers[i].psd_mask {
                mask.disabled = !enabled;
            }
            self.composite();
        }
    }
    pub fn layer_mask_enabled(&self, id: u32) -> bool {
        self.layer_index(id)
            .map(|i| self.layers[i].mask_enabled)
            .unwrap_or(true)
    }
    // Layer ▸ Layer Mask ▸ Unlink / Link: toggle whether the mask follows moves.
    pub fn set_layer_mask_linked(&mut self, id: u32, linked: bool) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].mask.is_empty() || self.layers[i].mask_linked == linked {
                return;
            }
            if self.push_stack_undo(if linked { "Link Mask" } else { "Unlink Mask" }) {
                return;
            }
            self.layers[i].mask_linked = linked;
            if let Some(mask) = &mut self.layers[i].psd_mask {
                mask.relative = linked;
            }
        }
    }
    pub fn layer_mask_linked(&self, id: u32) -> bool {
        self.layer_index(id)
            .map(|i| self.layers[i].mask_linked)
            .unwrap_or(true)
    }
    // Properties ▸ Density (0..1): non-destructively fade the mask toward fully
    // revealing. 1 = the mask at full strength, 0 = as if it weren't there.
    pub fn set_layer_mask_density(&mut self, id: u32, density: f32) {
        let density = if density.is_finite() {
            (density.clamp(0.0, 1.0) * 255.0).round() as u8
        } else {
            255
        };
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].mask.is_empty() || self.layers[i].mask_density == density {
                return;
            }
            if self.push_prop_undo(5, id, "Mask Density") {
                return;
            } // coalesce the slider drag
            self.layers[i].mask_density = density;
            self.composite();
        }
    }
    pub fn layer_mask_density(&self, id: u32) -> f32 {
        self.layer_index(id)
            .map(|i| f32::from(self.layers[i].mask_density) / 255.0)
            .unwrap_or(1.0)
    }
    // Properties ▸ Feather (px): live Gaussian softening of the mask edge. The
    // mask bytes are untouched — the blur is a cache, so it stays adjustable.
    pub fn set_layer_mask_feather(&mut self, id: u32, feather: f32) {
        // Cap at the canvas: a radius wider than the document adds no local
        // detail, and a hostile value would build an enormous kernel.
        let cap = self.w.max(self.h).max(1) as f32;
        let feather = if feather.is_finite() {
            feather.clamp(0.0, cap)
        } else {
            0.0
        };
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].mask.is_empty() || self.layers[i].mask_feather == feather {
                return;
            }
            if self.push_prop_undo(6, id, "Mask Feather") {
                return;
            } // coalesce the slider drag
            self.layers[i].mask_feather = feather;
            self.composite();
        }
    }
    pub fn layer_mask_feather(&self, id: u32) -> f32 {
        self.layer_index(id)
            .map(|i| self.layers[i].mask_feather)
            .unwrap_or(0.0)
    }
    // Keep the live-feather cache current before the mask is read. Layers at
    // feather 0 (the default) pay nothing; a feathered one pays one fingerprint
    // pass per composite and only re-blurs when the mask or radius changed.
    fn ensure_mask_soft(&mut self, i: usize) {
        let (w, h) = (self.w, self.h);
        let plane = (w as usize).saturating_mul(h as usize);
        let layer = &mut self.layers[i];
        if layer.mask_feather < 0.5 || layer.mask.len() != plane {
            layer.mask_soft = Vec::new();
            layer.mask_soft_key = 0;
            return;
        }
        let key = mask_soft_key(&layer.mask, layer.mask_feather);
        if key == layer.mask_soft_key && layer.mask_soft.len() == plane {
            return;
        }
        // Selection::feather is the engine's canonical coverage blur — the same
        // one behind Select ▸ Modify ▸ Feather and the PSD mask importer.
        let mut soft = Selection {
            w,
            h,
            active: true,
            mask: layer.mask.to_vec(),
            antialias: true,
        };
        soft.feather(layer.mask_feather);
        layer.mask_soft = soft.mask;
        layer.mask_soft_key = key;
    }
    // Layer ▸ Matting ▸ Defringe: bleed the interior colour into the active
    // layer's transparency-edge pixels, removing a contaminating fringe.
    pub fn defringe(&mut self, width: i32) {
        let (w, h) = self.active_pixel_plane_dimensions();
        self.apply16("Defringe", move |px, sel| {
            filters::defringe(px, w, h, sel, width)
        });
    }
    // Layer ▸ Matting ▸ Remove White/Black Matte: un-mix the matte colour from the
    // active layer's anti-aliased edge pixels (`white` true = white matte).
    pub fn remove_matte(&mut self, white: bool) {
        let label = if white {
            "Remove White Matte"
        } else {
            "Remove Black Matte"
        };
        self.apply16(label, move |px, sel| filters::remove_matte(px, sel, white));
    }
    // Image ▸ Apply Image: blend a source layer's pixels onto the active (target)
    // layer destructively, using `blend` mode + `opacity` (0..1), optionally
    // inverting the source first. RGB-only (no channel/mask options).
    pub fn apply_image(&mut self, src_id: u32, blend: u8, opacity: f32, invert: bool) {
        self.apply_image_channel(src_id, blend, opacity, invert, 255);
    }

    /// Apply Image with Photoshop's Channel picker. `channel` 255 = RGB
    /// composite (what `apply_image` does); otherwise the shared vocabulary —
    /// 0 Gray · 1 R · 2 G · 3 B · 4 Transparency · 5+ saved alpha channel — and
    /// the source contributes that channel as grey.
    pub fn apply_image_channel(
        &mut self,
        src_id: u32,
        blend: u8,
        opacity: f32,
        invert: bool,
        channel: u8,
    ) {
        let si = match self.layer_index(src_id) {
            Some(i) => i,
            None => return,
        };
        let active = self.active;
        if self.layers[active].locked
            || self.layers[active].kind == 7
            || self.layers[active].kind == 3
        {
            return;
        }
        if self.reject_float_edit_for_layer(active, "Apply Image Channel") {
            return;
        }
        // Source and destination are separate PLANES. Walk the destination's own
        // buffer and translate each pixel through canvas space to find the source
        // pixel; a canvas-linear index addresses neither correctly once crop or
        // Canvas Size has moved a plane. Resolved before the undo push. (#69)
        let (Some(srect), Some(drect)) = (self.plane_rect(si), self.plane_rect(active)) else {
            return;
        };
        if drect.w == 0 || drect.h == 0 {
            return;
        }
        if self.push_layer_undo("Apply Image") {
            return;
        }
        let src = self.layers[si].pixels.clone();
        let saved_channel: Option<Vec<u8>> = usize::from(channel)
            .checked_sub(5)
            .and_then(|k| self.saved_sels.get(k).map(|(_, m)| m.clone()));
        let saved_plane = saved_channel.as_deref();
        // Apply Image hand-rolls its loop instead of routing through apply16, so
        // nothing clipped it to the marquee — it rewrote the whole layer.
        let __before = self.layers[active].pixels.clone();
        let mode = BlendMode::from_u8(blend);
        let dw = drect.w as i32;
        let dst = Arc::make_mut(&mut self.layers[active].pixels);
        for k in 0..dst.len() / 4 {
            let p = k * 4;
            let cx = drect.x + (k as i32) % dw;
            let cy = drect.y + (k as i32) / dw;
            // No source pixel over this destination pixel: leave it untouched.
            let Some(sp) = checked_plane_index(srect, cx, cy, 4) else {
                continue;
            };
            let mut s = Rgba::from_u16(&src[sp..sp + 4]);
            if channel != 255 {
                // A single channel contributes as grey, keeping the source's own
                // alpha so a transparent source pixel still contributes nothing.
                let g = match channel {
                    1 => s.r,
                    2 => s.g,
                    3 => s.b,
                    4 => s.a,
                    0 => 0.299 * s.r + 0.587 * s.g + 0.114 * s.b,
                    _ => saved_plane
                        .and_then(|plane| plane.get((cy * self.w as i32 + cx) as usize))
                        .map_or(0.0, |v| *v as f32 / 255.0),
                };
                s.r = g;
                s.g = g;
                s.b = g;
            }
            if invert {
                s.r = 1.0 - s.r;
                s.g = 1.0 - s.g;
                s.b = 1.0 - s.b;
            }
            let base = Rgba::from_u16(&dst[p..p + 4]);
            composite_over(base, s, mode, opacity).to_u16(&mut dst[p..p + 4]);
        }
        self.restore_outside_selection(&__before);
        self.composite();
    }

    // Image ▸ Calculations: blend the greyscale of two source layers' channels
    // and write the result as a new selection. Each channel `ch`: 0 Gray
    // (luminosity) · 1 Red · 2 Green · 3 Blue, optionally inverted. `blend` mode
    // + `opacity` combine source 2 over source 1; the resulting grey is coverage.
    #[allow(clippy::too_many_arguments)]
    pub fn calculations(
        &mut self,
        s1_id: u32,
        ch1: u8,
        inv1: bool,
        s2_id: u32,
        ch2: u8,
        inv2: bool,
        blend: u8,
        opacity: f32,
    ) {
        let Some(mask) = self.calculations_plane(s1_id, ch1, inv1, s2_id, ch2, inv2, blend, opacity)
        else {
            return;
        };
        if self.push_sel_undo("Calculations") {
            return;
        }
        self.sel.set_mask(&mask);
        self.sel_dirty();
    }

    /// The same blend, handed back instead of written to the selection — the
    /// readback Result ▸ New Channel / New Document need. Pure: no undo, and the
    /// live selection is untouched. Empty when a source id is unknown.
    #[allow(clippy::too_many_arguments)]
    pub fn calculations_mask(
        &mut self,
        s1_id: u32,
        ch1: u8,
        inv1: bool,
        s2_id: u32,
        ch2: u8,
        inv2: bool,
        blend: u8,
        opacity: f32,
    ) -> Vec<u8> {
        self.calculations_plane(s1_id, ch1, inv1, s2_id, ch2, inv2, blend, opacity)
            .unwrap_or_default()
    }

    /// Grayscale PNG of an arbitrary canvas-sized coverage plane, so a computed
    /// result can open as its own document through the same path Split Channels
    /// already uses. Errors when the plane is not canvas-sized.
    pub fn encode_gray_png(&self, plane: &[u8]) -> Result<Vec<u8>, JsValue> {
        let n = (self.w * self.h) as usize;
        if plane.len() != n {
            return Err(JsValue::from_str("plane size mismatch"));
        }
        let mut rgba = vec![0u8; n * 4];
        for i in 0..n {
            let o = i * 4;
            rgba[o] = plane[i];
            rgba[o + 1] = plane[i];
            rgba[o + 2] = plane[i];
            rgba[o + 3] = 255;
        }
        let img = image::RgbaImage::from_raw(self.w, self.h, rgba)
            .ok_or_else(|| JsValue::from_str("buffer size mismatch"))?;
        let mut buf = Cursor::new(Vec::new());
        image::DynamicImage::ImageRgba8(img)
            .write_to(&mut buf, image::ImageFormat::Png)
            .map_err(|e| JsValue::from_str(&format!("encode failed: {e}")))?;
        Ok(buf.into_inner())
    }

    #[allow(clippy::too_many_arguments)]
    fn calculations_plane(
        &mut self,
        s1_id: u32,
        ch1: u8,
        inv1: bool,
        s2_id: u32,
        ch2: u8,
        inv2: bool,
        blend: u8,
        opacity: f32,
    ) -> Option<Vec<u8>> {
        let (i1, i2) = match (self.layer_index(s1_id), self.layer_index(s2_id)) {
            (Some(a), Some(b)) => (a, b),
            _ => return None,
        };
        // Both sources are PLANES; the selection this writes is canvas-sized. Resolve
        // a rect per source and read each through its own, before the undo push. (#70)
        let (Some(r1), Some(r2)) = (self.plane_rect(i1), self.plane_rect(i2)) else {
            return None;
        };
        let p1 = self.layers[i1].pixels.clone();
        let p2 = self.layers[i2].pixels.clone();
        let mode = BlendMode::from_u8(blend);
        let n = (self.w * self.h) as usize;
        // Channel vocabulary, shared with apply_image: 0 Gray · 1 R · 2 G · 3 B ·
        // 4 Transparency (the layer's own alpha) · 5+ the saved alpha channel at
        // index ch-5. Saved channels are canvas-sized coverage, so they are read
        // by canvas index rather than through a source plane.
        let saved: Vec<Vec<u8>> = self.saved_sels.iter().map(|(_, m)| m.clone()).collect();
        // `b` is a PLANE byte offset, not a canvas index.
        let chan = |p: &[u16], b: usize, ch: u8, inv: bool| -> f32 {
            let v = match ch {
                1 => p[b] as f32 / 65535.0,
                2 => p[b + 1] as f32 / 65535.0,
                3 => p[b + 2] as f32 / 65535.0,
                4 => p[b + 3] as f32 / 65535.0,
                0 => {
                    (p[b] as f32 * 0.299 + p[b + 1] as f32 * 0.587 + p[b + 2] as f32 * 0.114)
                        / 65535.0
                }
                _ => return 0.0, // saved channels are handled by canvas index below
            };
            if inv {
                1.0 - v
            } else {
                v
            }
        };
        let saved_at = |ch: u8, i: usize, inv: bool| -> Option<f32> {
            let plane = saved.get(usize::from(ch).checked_sub(5)?)?;
            let v = *plane.get(i)? as f32 / 255.0;
            Some(if inv { 1.0 - v } else { v })
        };
        let mut mask = vec![0u8; n];
        let cw = self.w as i32;
        for i in 0..n {
            let (cx, cy) = ((i as i32) % cw, (i as i32) / cw);
            // A source whose plane does not reach this canvas point reads as black,
            // which is the same thing an empty (fully transparent) source contributed
            // before planes could differ from the canvas.
            let g1 = saved_at(ch1, i, inv1)
                .unwrap_or_else(|| checked_plane_index(r1, cx, cy, 4).map_or(0.0, |b| chan(&p1, b, ch1, inv1)));
            let g2 = saved_at(ch2, i, inv2)
                .unwrap_or_else(|| checked_plane_index(r2, cx, cy, 4).map_or(0.0, |b| chan(&p2, b, ch2, inv2)));
            let res = composite_over(
                Rgba::new(g1, g1, g1, 1.0),
                Rgba::new(g2, g2, g2, 1.0),
                mode,
                opacity,
            );
            mask[i] = (res.r.clamp(0.0, 1.0) * 255.0).round() as u8;
        }
        Some(mask)
    }

    // Layer ▸ Layer Mask ▸ From Transparency: move the layer's alpha into a new
    // layer mask and make the layer itself fully opaque — the composite is
    // unchanged, but the transparency is now editable as a mask. No-op if the
    // layer already has a mask.
    pub fn layer_mask_from_transparency(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            if !self.layers[i].mask.is_empty() {
                return;
            }
            if self.reject_float_edit_for_layer(i, "Layer Mask From Transparency") {
                return;
            }
            // The mask is CANVAS-sized, the alpha it comes from is on the layer's own
            // PLANE. Walk the canvas and translate; plane pixels outside the canvas
            // (the crop reserve) have nowhere in the mask to go, so their alpha stays
            // as-is rather than being flattened to opaque. Resolved before the undo
            // push so an unusable plane costs no history step. (#71)
            let Some(rect) = self.plane_rect(i) else {
                return;
            };
            if self.push_stack_undo("Mask From Transparency") {
                return;
            }
            let (cw, ch) = (self.w as i32, self.h as i32);
            let mut mask = vec![0u8; (cw as usize) * (ch as usize)];
            for y in 0..ch {
                for x in 0..cw {
                    let Some(pi) = checked_plane_index(rect, x, y, 4) else {
                        continue;
                    };
                    let k = (y as usize) * (cw as usize) + (x as usize);
                    mask[k] = color::u16_to_8(self.layers[i].pixels[pi + 3]); // alpha → mask
                    Arc::make_mut(&mut self.layers[i].pixels)[pi + 3] = 65535; // layer becomes opaque
                }
            }
            self.layers[i].mask = mask.into();
            self.layers[i].psd_mask = None;
            self.composite();
        }
    }

    // ── Layer groups (pass-through folders) ────────────────────
    // Create a group folder above the active layer and place the active layer in it.

    // Fill layers cache rendered pixels for the compositor while `adj_kind` and
    // `adj_params` retain the editable source of truth:
    // 0 solid [r,g,b,a] · 1 gradient [pos,r,g,b,a]×N ·
    // 2 pattern [tile_w,tile_h,scale_percent] (`smart_src` stores the tile).
    // These fields already round-trip in MVSN, so no project-format bump is needed.
    fn map_fill_colors(layer: &mut Layer, mut map: impl FnMut(&mut [u16])) {
        if layer.kind != 4 {
            return;
        }
        let mut update = |rgba: &mut [f32]| {
            let mut pixel = [
                color::to16(rgba[0]),
                color::to16(rgba[1]),
                color::to16(rgba[2]),
                color::to16(rgba[3]),
            ];
            map(&mut pixel);
            for channel in 0..4 {
                rgba[channel] = pixel[channel] as f32 / 65535.0;
            }
        };
        match layer.adj_kind {
            0 if layer.adj_params.len() >= 3 => {
                if layer.adj_params.len() < 4 {
                    layer.adj_params.push(1.0);
                }
                update(&mut layer.adj_params[..4]);
            }
            1 => {
                for stop in layer.adj_params.chunks_exact_mut(5) {
                    update(&mut stop[1..5]);
                }
            }
            _ => {}
        }
    }

    fn rasterize_fill_metadata(layer: &mut Layer) {
        if layer.kind == 4 {
            layer.kind = 0;
            layer.adj_kind = 0;
            layer.adj_params.clear();
            layer.set_smart_src(Vec::new());
            layer.smart_src_f32 = Arc::from(Vec::new());
        }
    }

    fn render_fill_layer(&mut self, i: usize) {
        if i >= self.layers.len() || self.layers[i].kind != 4 {
            return;
        }
        let fill_kind = self.layers[i].adj_kind;
        let params = self.layers[i].adj_params.clone();
        let source = self.layers[i].smart_src.clone();
        let (w, h) = (self.w as usize, self.h as usize);
        let mut pixels = vec![0u16; w * h * 4];
        match fill_kind {
            0 if params.len() >= 3 => {
                let rgba = [
                    color::to16(params[0].clamp(0.0, 1.0)),
                    color::to16(params[1].clamp(0.0, 1.0)),
                    color::to16(params[2].clamp(0.0, 1.0)),
                    color::to16(params.get(3).copied().unwrap_or(1.0).clamp(0.0, 1.0)),
                ];
                for px in pixels.chunks_exact_mut(4) {
                    px.copy_from_slice(&rgba);
                }
            }
            1 if params.len() >= 10 => {
                let nstops = params.len() / 5;
                let sample = |t: f32| -> [f32; 4] {
                    let t = t.clamp(0.0, 1.0);
                    if t <= params[0] {
                        return [params[1], params[2], params[3], params[4]];
                    }
                    for k in 1..nstops {
                        let p1 = params[k * 5];
                        if t <= p1 {
                            let p0 = params[(k - 1) * 5];
                            let f = if p1 > p0 { (t - p0) / (p1 - p0) } else { 0.0 };
                            let mut out = [0f32; 4];
                            for (c, o) in out.iter_mut().enumerate() {
                                let a = params[(k - 1) * 5 + 1 + c];
                                let b = params[k * 5 + 1 + c];
                                *o = a + (b - a) * f;
                            }
                            return out;
                        }
                    }
                    let last = (nstops - 1) * 5;
                    [
                        params[last + 1],
                        params[last + 2],
                        params[last + 3],
                        params[last + 4],
                    ]
                };
                for y in 0..h {
                    let t = if h > 1 {
                        y as f32 / (h - 1) as f32
                    } else {
                        0.0
                    };
                    let c = sample(t);
                    let row = [
                        color::to16(c[0].clamp(0.0, 1.0)),
                        color::to16(c[1].clamp(0.0, 1.0)),
                        color::to16(c[2].clamp(0.0, 1.0)),
                        color::to16(c[3].clamp(0.0, 1.0)),
                    ];
                    for x in 0..w {
                        let o = (y * w + x) * 4;
                        pixels[o..o + 4].copy_from_slice(&row);
                    }
                }
            }
            2 if params.len() >= 2 => {
                let pw = params[0].round().max(1.0) as i32;
                let ph = params[1].round().max(1.0) as i32;
                let scale = params.get(2).copied().unwrap_or(100.0).clamp(1.0, 1000.0);
                if source.len() == (pw * ph * 4) as usize {
                    for y in 0..h as i32 {
                        for x in 0..w as i32 {
                            let sx = ((x as f32 * 100.0 / scale).floor() as i32).rem_euclid(pw);
                            let sy = ((y as f32 * 100.0 / scale).floor() as i32).rem_euclid(ph);
                            let si = (sy * pw + sx) as usize * 4;
                            let di = (y * w as i32 + x) as usize * 4;
                            pixels[di..di + 4].copy_from_slice(&source[si..si + 4]);
                        }
                    }
                }
            }
            _ => return,
        }
        self.layers[i].pixels = pixels.into();
        if self.depth == 32 {
            self.layers[i].pixels_f32 = self.layers[i]
                .pixels
                .iter()
                .map(|value| *value as f32 / 65_535.0)
                .collect();
        }
    }

    // Every Photoshop fill layer has a mask. An active selection seeds it and is
    // consumed; otherwise it starts fully revealing.
    fn seed_fill_mask(&mut self, layer: &mut Layer) {
        if self.sel.active {
            layer.mask = self.sel.mask.clone().into();
            self.sel.deselect();
            self.sel_dirty();
        } else {
            layer.mask = vec![255u8; (self.w * self.h) as usize].into();
        }
    }

    // Layer ▸ New Fill Layer ▸ Solid Color: editable, non-destructive colour fill.
    pub fn add_solid_fill_layer(&mut self, r: u8, g: u8, b: u8) -> u32 {
        if self.push_stack_undo("Solid Color Fill Layer") {
            return 0;
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut layer = Layer::transparent(id, "Color Fill", self.w, self.h);
        layer.kind = 4;
        layer.adj_kind = 0;
        layer.adj_params = vec![r as f32 / 255.0, g as f32 / 255.0, b as f32 / 255.0, 1.0];
        self.seed_fill_mask(&mut layer);
        let at = self.insert_layer_above_active(layer);
        self.render_fill_layer(at);
        self.composite();
        id
    }

    // Layer ▸ New Fill Layer ▸ Gradient: editable top-to-bottom gradient.
    pub fn add_gradient_fill_layer(&mut self, stops: &[f32]) -> u32 {
        let nstops = stops.len() / 5;
        if nstops < 2 {
            return 0;
        }
        if self.push_stack_undo("Gradient Fill Layer") {
            return 0;
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut layer = Layer::transparent(id, "Gradient Fill", self.w, self.h);
        layer.kind = 4;
        layer.adj_kind = 1;
        layer.adj_params = stops[..nstops * 5].to_vec();
        self.seed_fill_mask(&mut layer);
        let at = self.insert_layer_above_active(layer);
        self.render_fill_layer(at);
        self.composite();
        id
    }

    // Layer ▸ New Fill Layer ▸ Pattern: editable tile + scale, seeded from the
    // current Edit ▸ Define Pattern tile. No-op when no pattern is defined.
    pub fn add_pattern_fill_layer(&mut self) -> u32 {
        if self.pattern.is_empty() {
            return 0;
        }
        if self.push_stack_undo("Pattern Fill Layer") {
            return 0;
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut layer = Layer::transparent(id, "Pattern Fill", self.w, self.h);
        layer.kind = 4;
        layer.adj_kind = 2;
        layer.adj_params = vec![self.pattern_w as f32, self.pattern_h as f32, 100.0];
        layer.set_smart_src(self.pattern.clone());
        self.seed_fill_mask(&mut layer);
        let at = self.insert_layer_above_active(layer);
        self.render_fill_layer(at);
        self.composite();
        id
    }

    // Layer ▸ Layer Content Options: live-edit a fill layer. Repeated input ticks
    // coalesce into one undo step until `end_prop_edit` closes the transaction.
    pub fn set_fill_params(&mut self, id: u32, params: &[f32]) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].kind != 4 || self.layers[i].adj_params == params {
                return;
            }
            let valid = match self.layers[i].adj_kind {
                0 => params.len() >= 3,
                1 => params.len() >= 10,
                2 => params.len() >= 3,
                _ => false,
            };
            if !valid {
                return;
            }
            if self.push_prop_undo(3, id, "Fill Settings") {
                return;
            }
            self.layers[i].adj_params = params.to_vec();
            self.render_fill_layer(i);
            self.composite();
        }
    }

    // Pattern Fill options: replace the stored tile with the current defined
    // pattern while retaining this layer's scale.
    pub fn replace_pattern_fill(&mut self, id: u32) {
        if self.pattern.is_empty() {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].kind != 4 || self.layers[i].adj_kind != 2 {
                return;
            }
            if self.push_prop_undo(3, id, "Fill Settings") {
                return;
            }
            let scale = self.layers[i].adj_params.get(2).copied().unwrap_or(100.0);
            self.layers[i].adj_params = vec![self.pattern_w as f32, self.pattern_h as f32, scale];
            self.layers[i].set_smart_src(self.pattern.clone());
            if self.depth == 32 {
                self.layers[i].smart_src_f32 = self.layers[i]
                    .smart_src
                    .iter()
                    .map(|value| *value as f32 / 65_535.0)
                    .collect();
            }
            self.render_fill_layer(i);
            self.composite();
        }
    }

    // Layer ▸ Rasterize ▸ Fill Content: retain pixels/mask and drop editability.
    pub fn rasterize_fill_layer(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].kind != 4 {
                return;
            }
            if self.push_stack_undo("Rasterize Fill Layer") {
                return;
            }
            self.render_fill_layer(i);
            Self::rasterize_fill_metadata(&mut self.layers[i]);
            self.composite();
        }
    }

    pub fn create_group(&mut self, name: &str) -> u32 {
        if self.push_stack_undo("New Group") {
            return 0;
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut header = Layer::header(id, name);
        header.kind = 6;
        header.blend = BlendMode::PassThrough; // Photoshop's group default
        // ⌘G inside a group nests: the new group is a sibling of the wrapped layer.
        header.group = self.layers[self.active].group;
        let child = self.layers[self.active].id;
        let at = (self.active + 1).min(self.layers.len());
        self.layers.insert(at, header);
        if let Some(ci) = self.layer_index(child) {
            self.layers[ci].group = id;
        }
        self.active = self.layer_index(id).unwrap_or(self.active);
        self.composite();
        id
    }
    // Layer ▸ Group Layers / New ▸ Group from Layers: wrap the given layers or
    // groups (nested selections included) in a new group. Preserves their
    // relative order; the group lands at the bottom-most selected slot.
    pub fn group_layers(&mut self, ids: &[u32], name: &str) -> u32 {
        let idxs: Vec<usize> = (0..self.layers.len())
            .filter(|&i| ids.contains(&self.layers[i].id))
            .collect();
        if idxs.is_empty() {
            return 0;
        }
        // ⌘G inside a group nests: the new group becomes a sibling of the
        // bottom-most member. Walk that member's ancestor chain and land above
        // the highest SELECTED ancestor — a selected group is about to be
        // reparented into the new group, so parenting the new group to it (or
        // anything inside it) would create a cycle.
        let mut chain = Vec::new();
        let mut g = self.layers[idxs[0]].group;
        while g != 0 && !chain.contains(&g) {
            let Some(gi) = self.layer_index(g) else { break };
            chain.push(g);
            g = self.layers[gi].group;
        }
        let parent = match chain.iter().rposition(|gid| ids.contains(gid)) {
            Some(p) => chain.get(p + 1).copied().unwrap_or(0),
            None => chain.first().copied().unwrap_or(0),
        };
        if self.push_stack_undo("Group Layers") {
            return 0;
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut header = Layer::header(id, name);
        header.kind = 6;
        header.group = parent;
        // Photoshop's group default.
        header.blend = BlendMode::PassThrough;
        // Extract the members (descending so indices stay valid), tag their group.
        let mut members: Vec<Layer> = idxs
            .iter()
            .rev()
            .map(|&i| {
                let mut l = self.layers.remove(i);
                l.group = id;
                l
            })
            .collect();
        // Restore the original ascending order.
        members.reverse();
        // Insert [header, ...members] at the bottom-most former slot (clamped).
        let at = idxs[0].min(self.layers.len());
        self.layers.insert(at, header);
        for (k, l) in members.into_iter().enumerate() {
            self.layers.insert(at + 1 + k, l);
        }
        self.active = self.layer_index(id).unwrap_or(self.active);
        self.composite();
        id
    }
    // Layer ▸ New ▸ Artboard: a group whose header carries [x,y,w,h] bounds in
    // adj_params — the compositor clips its contents to those bounds and paints a
    // background inside them (white until `set_artboard_background` says other-
    // wise). Wraps the active layer as its first member.
    pub fn new_artboard(&mut self, x: i32, y: i32, aw: u32, ah: u32, name: &str) -> u32 {
        if self.push_stack_undo("New Artboard") {
            return 0;
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut header = Layer::header(id, name);
        header.kind = 6;
        header.blend = BlendMode::Normal; // isolate (bg + clip), not Pass Through
        header.adj_params = vec![x as f32, y as f32, aw as f32, ah as f32];
        let child = self.layers[self.active].id;
        let at = (self.active + 1).min(self.layers.len());
        self.layers.insert(at, header);
        if let Some(ci) = self.layer_index(child) {
            self.layers[ci].group = id;
        }
        self.active = self.layer_index(id).unwrap_or(self.active);
        self.composite();
        id
    }

    // Artboard tool: create an EMPTY white-backed artboard of the given bounds —
    // unlike `new_artboard`, which wraps the active layer, this leaves the
    // artboard childless so an interactive drag makes a standalone frame (layers
    // are dropped in later by reparenting). adj_params is the artboard's
    // [x, y, w, h] (len 4 → default white background + clip, exactly like
    // `new_artboard`; recolour it with `set_artboard_background`).
    pub fn new_artboard_rect(&mut self, x: i32, y: i32, w: u32, h: u32, name: &str) -> u32 {
        let (aw, ah) = (w.max(1), h.max(1));
        if self.push_stack_undo("New Artboard") {
            return 0;
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut header = Layer::header(id, name);
        header.kind = 6;
        header.blend = BlendMode::Normal; // isolate (white bg + clip)
        header.adj_params = vec![x as f32, y as f32, aw as f32, ah as f32];
        let at = (self.active + 1).min(self.layers.len());
        self.layers.insert(at, header);
        self.active = self.layer_index(id).unwrap_or(self.active);
        self.composite();
        id
    }

    // Artboard tool: move/resize an artboard (or any bounds-carrying kind=6
    // container) to [x, y, w, h]. A pure MOVE (size unchanged) drags the
    // artboard's child layers with it (Photoshop parity); a RESIZE only changes
    // the clip frame, revealing/hiding content without moving it. Extra adj_params
    // slots (a Frame's bg/shape flags) are preserved, so it is safe on frames too.
    // Returns false if `id` isn't a bounds-carrying container or nothing changed.
    pub fn set_artboard_bounds(&mut self, id: u32, x: i32, y: i32, w: u32, h: u32) -> bool {
        let i = match self.layer_index(id) {
            Some(i) => i,
            None => return false,
        };
        if self.layers[i].kind != 6 || self.layers[i].adj_params.len() < 4 {
            return false;
        }
        let (aw, ah) = (w.max(1) as i32, h.max(1) as i32);
        let p = &self.layers[i].adj_params;
        let (ox, oy, ow, oh) = (p[0] as i32, p[1] as i32, p[2] as i32, p[3] as i32);
        if ox == x && oy == y && ow == aw && oh == ah {
            return false; // no-op (a plain click-select)
        }
        let moved = ow == aw && oh == ah; // size kept → a body move, not a resize
        if self.push_stack_undo(if moved {
            "Move Artboard"
        } else {
            "Resize Artboard"
        }) {
            return false;
        }
        self.layers[i].adj_params[0] = x as f32;
        self.layers[i].adj_params[1] = y as f32;
        self.layers[i].adj_params[2] = aw as f32;
        self.layers[i].adj_params[3] = ah as f32;
        if moved {
            let (dx, dy) = (x - ox, y - oy);
            if dx != 0 || dy != 0 {
                for l in self.layers.iter_mut() {
                    if l.group == id {
                        l.ox += dx;
                        l.oy += dy;
                    }
                }
            }
        }
        self.composite();
        true
    }

    // Artboard Options ▸ Artboard Background Color: repaint the artboard's
    // background (0..255 straight-alpha RGBA; a = 0 is Photoshop's "Transparent",
    // which is how you export a UI asset with alpha). Writes slots 6..9 of the
    // kind=6 header — see `artboard_bg`. The artboard flag in slot 4 is left
    // alone, so a Transparent artboard stays an artboard (not a Frame) and keeps
    // showing up in `artboard_ids`. False when `id` isn't a bounds container or
    // the colour is unchanged.
    pub fn set_artboard_background(&mut self, id: u32, r: u8, g: u8, b: u8, a: u8) -> bool {
        let i = match self.layer_index(id) {
            Some(i) => i,
            None => return false,
        };
        if self.layers[i].kind != 6 || self.layers[i].adj_params.len() < 4 {
            return false;
        }
        let next = [
            r as f32 / 255.0,
            g as f32 / 255.0,
            b as f32 / 255.0,
            a as f32 / 255.0,
        ];
        let cur = |p: &Vec<f32>, k: usize| p.get(k).copied().unwrap_or(1.0);
        let p = &self.layers[i].adj_params;
        if (6..10).all(|k| (cur(p, k) - next[k - 6]).abs() < 1.0 / 512.0) {
            return false; // no-op (re-picking the colour it already has)
        }
        if self.push_stack_undo("Artboard Background") {
            return false;
        }
        let p = &mut self.layers[i].adj_params;
        // Fill the gap slots (frame bg flag + shape) an old 4-slot header lacks.
        while p.len() < 6 {
            p.push(if p.len() == 4 { 1.0 } else { 0.0 });
        }
        if p.len() < 10 {
            p.resize(10, 1.0);
        }
        p[6..10].copy_from_slice(&next);
        self.composite();
        true
    }

    // Artboard Options: the artboard's background colour as [r, g, b, a] (0..255),
    // for the options bar's swatch. Empty when `id` isn't a bounds container;
    // opaque white for a header saved before backgrounds were colourable.
    pub fn artboard_background(&self, id: u32) -> Vec<u8> {
        match self.layer_index(id) {
            Some(i) if self.layers[i].kind == 6 && self.layers[i].adj_params.len() >= 4 => {
                let p = &self.layers[i].adj_params;
                (6..10)
                    .map(|k| {
                        (p.get(k).copied().unwrap_or(1.0).clamp(0.0, 1.0) * 255.0 + 0.5) as u8
                    })
                    .collect()
            }
            _ => Vec::new(),
        }
    }

    // Artboard tool: the layer ids of the true artboards (kind=6 bounds
    // containers whose slot-4 artboard flag is set) — excludes Frame-tool frames
    // (flag 0) so the tool selects/edits only artboards. A Transparent artboard
    // keeps the flag and only zeroes its background alpha, so it stays listed.
    // The UI reads each one's bounds via `frame_bounds` and its label via
    // `layer_name`.
    pub fn artboard_ids(&self) -> Vec<u32> {
        self.layers
            .iter()
            .filter(|l| {
                l.kind == 6
                    && l.adj_params.len() >= 4
                    && l.adj_params.get(4).copied().unwrap_or(1.0) >= 0.5
            })
            .map(|l| l.id)
            .collect()
    }

    // Artboard tool: delete an artboard and its child layers in one step
    // (Photoshop deletes the artboard's contents along with it). No-op if `id`
    // isn't a bounds-carrying kind=6 container, or if it would empty the document.
    pub fn delete_artboard(&mut self, id: u32) {
        let is_artboard = matches!(
            self.layer_index(id),
            Some(i) if self.layers[i].kind == 6 && self.layers[i].adj_params.len() >= 4
        );
        if !is_artboard {
            return;
        }
        let removing = 1 + self.layers.iter().filter(|l| l.group == id).count();
        if removing >= self.layers.len() {
            return; // never leave the document with zero layers
        }
        if self.push_stack_undo("Delete Artboard") {
            return;
        }
        self.layers.retain(|l| l.id != id && l.group != id);
        if self.active >= self.layers.len() {
            self.active = self.layers.len().saturating_sub(1);
        }
        self.composite();
    }

    // File ▸ Export ▸ Color Lookup Tables: bake the document's adjustment-layer
    // colour transform into a 3D LUT (.cube text). An identity grid is pushed
    // through every visible adjustment layer (mask-independent, the global
    // transform). No adjustment layers → an identity LUT.
    pub fn export_color_lut(&self, size: u32) -> String {
        let n = size.clamp(2, 64) as usize;
        let adjs: Vec<(u8, Vec<f32>)> = self
            .layers
            .iter()
            .filter(|l| l.kind == 1 && l.visible)
            .map(|l| (l.adj_kind, l.adj_params.clone()))
            .collect();
        let mut s = format!("TITLE \"Monet Vision\"\nLUT_3D_SIZE {n}\n");
        let fm1 = (n - 1) as f32;
        // .cube convention: red varies fastest, then green, then blue.
        for bi in 0..n {
            for gi in 0..n {
                for ri in 0..n {
                    let (mut r, mut g, mut b) = (ri as f32 / fm1, gi as f32 / fm1, bi as f32 / fm1);
                    for (k, p) in &adjs {
                        let (nr, ng, nb) = pixel_adjust::apply_pixel(*k, p, r, g, b);
                        r = nr.clamp(0.0, 1.0);
                        g = ng.clamp(0.0, 1.0);
                        b = nb.clamp(0.0, 1.0);
                    }
                    s.push_str(&format!("{r:.6} {g:.6} {b:.6}\n"));
                }
            }
        }
        s
    }

    fn artboard_headers(&self) -> Vec<usize> {
        (0..self.layers.len())
            .filter(|&i| self.layers[i].kind == 6 && self.layers[i].adj_params.len() >= 4)
            .collect()
    }
    pub fn artboard_count(&self) -> usize {
        self.artboard_headers().len()
    }
    pub fn artboard_name(&self, idx: usize) -> String {
        self.artboard_headers()
            .get(idx)
            .map(|&i| self.layers[i].name.clone())
            .unwrap_or_default()
    }
    // File ▸ Export ▸ Artboards to Files: crop the idx-th artboard's bounds out of
    // the composite and encode it as a PNG. The artboard is composited in
    // ISOLATION (its own header + members, its own background) like Photoshop —
    // the document's Background layer and any canvas content behind the artboard
    // are not baked in, so an artboard set to a Transparent background exports
    // with real alpha instead of on white.
    pub fn export_artboard_png(&mut self, idx: usize) -> Result<Vec<u8>, JsValue> {
        let hs = self.artboard_headers();
        let i = match hs.get(idx) {
            Some(&i) => i,
            None => return Ok(Vec::new()),
        };
        let p = self.layers[i].adj_params.clone();
        let (ax, ay, aw, ah) = (p[0] as i32, p[1] as i32, p[2] as u32, p[3] as u32);
        if !dims_ok(aw, ah) {
            return Ok(Vec::new());
        }
        let id = self.layers[i].id;
        self.with_isolated_layer_export(id, move |engine| {
            engine.composite();
            let mut img = image::RgbaImage::new(aw, ah);
            let (cw, ch) = (engine.w as i32, engine.h as i32);
            for yy in 0..ah as i32 {
                for xx in 0..aw as i32 {
                    let (sx, sy) = (ax + xx, ay + yy);
                    if sx >= 0 && sy >= 0 && sx < cw && sy < ch {
                        let si = (sy * cw + sx) as usize * 4;
                        img.put_pixel(
                            xx as u32,
                            yy as u32,
                            image::Rgba([
                                engine.output[si],
                                engine.output[si + 1],
                                engine.output[si + 2],
                                engine.output[si + 3],
                            ]),
                        );
                    }
                }
            }
            let mut buf = Cursor::new(Vec::new());
            image::DynamicImage::ImageRgba8(img)
                .write_to(&mut buf, image::ImageFormat::Png)
                .map_err(|e| JsValue::from_str(&format!("encode failed: {e}")))?;
            Ok(buf.into_inner())
        })
    }

    // Layer ▸ New ▸ Frame: like an artboard but with a TRANSPARENT background
    // (adj_params[4]=0) — a rectangular clipping container. Sized to the active
    // selection, else a centred half-canvas rectangle.
    pub fn new_frame(&mut self, name: &str) -> u32 {
        let (fx, fy, fw, fh) = if self.sel.active {
            let b = self.sel.bounds(); // [x, y, w, h]
            (b[0], b[1], b[2].max(1) as u32, b[3].max(1) as u32)
        } else {
            let (w, h) = (self.w as i32, self.h as i32);
            (w / 4, h / 4, (w / 2).max(1) as u32, (h / 2).max(1) as u32)
        };
        if self.push_stack_undo("New Frame") {
            return 0;
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut header = Layer::header(id, name);
        header.kind = 6;
        header.blend = BlendMode::Normal;
        header.adj_params = vec![fx as f32, fy as f32, fw as f32, fh as f32, 0.0]; // bg=0 (transparent)
        let child = self.layers[self.active].id;
        let at = (self.active + 1).min(self.layers.len());
        self.layers.insert(at, header);
        if let Some(ci) = self.layer_index(child) {
            self.layers[ci].group = id;
        }
        self.active = self.layer_index(id).unwrap_or(self.active);
        self.composite();
        id
    }

    // Frame tool (K): create an EMPTY transparent clipping container of the given
    // bounds — unlike `new_frame`, which wraps the active layer, this leaves the
    // frame childless so the interactive drag-create makes a true placeholder. An
    // image is dropped in later as a clipped, centred member (`set_layer_group`).
    // adj_params = [x, y, w, h, bg, shape] with bg=0 (transparent, like new_frame)
    // and shape 0 = rectangular / 1 = elliptical clip.
    // Takes the name: every constructor used to hardcode "Frame 1", so the
    // Layers panel filled up with identically-named frames.
    fn make_frame(&mut self, x: i32, y: i32, w: u32, h: u32, ellipse: bool, name: &str) -> u32 {
        let (fw, fh) = (w.max(1), h.max(1));
        if self.push_stack_undo("New Frame") {
            return 0;
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut header = Layer::header(id, name);
        header.kind = 6;
        header.blend = BlendMode::Normal;
        header.adj_params = vec![
            x as f32,
            y as f32,
            fw as f32,
            fh as f32,
            0.0,                             // bg = transparent frame
            if ellipse { 1.0 } else { 0.0 }, // shape: 0 rect / 1 ellipse
        ];
        let at = (self.active + 1).min(self.layers.len());
        self.layers.insert(at, header);
        self.active = self.layer_index(id).unwrap_or(self.active);
        self.composite();
        id
    }
    // Frame tool: empty rectangular clipping frame at [x, y, w, h].
    pub fn new_frame_rect(&mut self, x: i32, y: i32, w: u32, h: u32, name: &str) -> u32 {
        self.make_frame(x, y, w, h, false, name)
    }
    // Frame tool: empty elliptical clipping frame inscribed in [x, y, w, h].
    pub fn new_frame_ellipse(&mut self, x: i32, y: i32, w: u32, h: u32, name: &str) -> u32 {
        self.make_frame(x, y, w, h, true, name)
    }
    // Frame tool: the [x, y, w, h] clip bounds of a frame/artboard container
    // (empty if `id` isn't a bounds-carrying group) — lets the UI centre a
    // dropped image inside the frame before clipping it as a member.
    pub fn frame_bounds(&self, id: u32) -> Vec<i32> {
        if let Some(i) = self.layer_index(id) {
            let l = &self.layers[i];
            if l.kind == 6 && l.adj_params.len() >= 4 {
                return vec![
                    l.adj_params[0] as i32,
                    l.adj_params[1] as i32,
                    l.adj_params[2] as i32,
                    l.adj_params[3] as i32,
                ];
            }
        }
        Vec::new()
    }

    // Layer ▸ New ▸ Artboard from Layers: an artboard sized to the active layer's
    // content bounds, wrapping it.
    // Layer ▸ New ▸ Artboard from Layers. Takes the name like `new_artboard`
    // does: hardcoding "Artboard 1" here gave every artboard made this way the
    // same name, and artboard export writes one file per NAME.
    pub fn artboard_from_layers(&mut self, name: &str) -> u32 {
        let b = self.active_layer_bounds(); // [x, y, w, h]
        if b[2] <= 0 || b[3] <= 0 {
            return self.new_artboard(0, 0, self.w, self.h, name);
        }
        self.new_artboard(b[0], b[1], b[2] as u32, b[3] as u32, name)
    }

    // Layer ▸ New ▸ Artboard from Group: tag the active group as a full-canvas
    // artboard (clip + white background).
    pub fn artboard_from_group(&mut self) {
        let i = self.active;
        if self.layers[i].kind != 6 || !self.layers[i].adj_params.is_empty() {
            return; // not a plain group
        }
        if self.push_stack_undo("Artboard from Group") {
            return;
        }
        self.layers[i].adj_params = vec![0.0, 0.0, self.w as f32, self.h as f32];
        self.layers[i].blend = BlendMode::Normal;
        self.composite();
    }

    pub fn set_layer_group(&mut self, id: u32, group_id: u32) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            self.layers[i].group = group_id;
            self.composite();
        }
    }
    // Move an existing layer INTO an artboard (or any bounds-carrying kind=6
    // container), or back to the document root with `artboard_id` 0 — the
    // missing half of `new_artboard_rect`'s "layers are dropped in later by
    // reparenting". Re-slots the layer directly below its new header so the
    // Layers panel reads it as a member; one undo step. Returns false when
    // nothing changed (bad ids, already a member, container-on-container).
    pub fn move_layer_to_artboard(&mut self, id: u32, artboard_id: u32) -> bool {
        let li = match self.layer_index(id) {
            Some(i) => i,
            None => return false,
        };
        // ponytail: containers stay top-level — no nested artboards; lift this
        // guard (plus the compositor's flat-group plan) if nesting ever matters.
        if self.layers[li].kind == 6 || self.layers[li].group == artboard_id {
            return false;
        }
        if artboard_id != 0 {
            match self.layer_index(artboard_id) {
                Some(ai) if self.layers[ai].kind == 6 && self.layers[ai].adj_params.len() >= 4 => {}
                _ => return false,
            }
        }
        if self.push_stack_undo(if artboard_id == 0 {
            "Remove from Artboard"
        } else {
            "Move to Artboard"
        }) {
            return false;
        }
        let active_id = self.layers[self.active].id;
        if artboard_id == 0 {
            self.layers[li].group = 0; // leaving: keep the stack position
        } else {
            let mut l = self.layers.remove(li);
            l.group = artboard_id;
            // Directly below the header in visual order = the header's own vec
            // slot (last in vec = top; the header shifts up by one).
            let at = self.layer_index(artboard_id).unwrap_or(self.layers.len());
            self.layers.insert(at, l);
        }
        self.active = self.layer_index(active_id).unwrap_or(0);
        self.composite();
        true
    }
    // Move tool (Photoshop parity): after a move commits, a layer is re-homed by
    // where its content landed — into the artboard under it, or out to the root
    // when it leaves its artboard. Members of plain groups and frames are left
    // alone (they travel with their container, not by canvas position).
    fn auto_adopt_artboard(&mut self, id: u32) {
        let i = match self.layer_index(id) {
            Some(i) => i,
            None => return,
        };
        if self.layers[i].kind == 6 {
            return;
        }
        let cur = self.layers[i].group;
        let artboards = self.artboard_ids();
        if cur != 0 && !artboards.contains(&cur) {
            return; // inside a plain group / frame — not artboard-managed
        }
        let (bx0, by0, bx1, by1) = match self.layer_bbox(i) {
            Some(b) => b,
            None => return, // no content to re-home by
        };
        // ponytail: membership keys off the content bbox CENTRE; Photoshop uses
        // a fuzzier majority-overlap rule — switch to overlap area if it misfires.
        let (cx, cy) = ((bx0 + bx1) / 2, (by0 + by1) / 2);
        let target = artboards
            .into_iter()
            .rev() // topmost artboard wins
            .find(|&aid| {
                matches!(self.layer_index(aid), Some(ai) if {
                    let p = &self.layers[ai].adj_params;
                    let (x, y) = (p[0] as i32, p[1] as i32);
                    cx >= x && cx < x + p[2] as i32 && cy >= y && cy < y + p[3] as i32
                })
            })
            .unwrap_or(0);
        if target != cur {
            self.move_layer_to_artboard(id, target);
        }
    }
    pub fn ungroup(&mut self, group_id: u32) {
        if let Some(gi) = self.layer_index(group_id) {
            if self.layers[gi].kind != 6 {
                return;
            }
            let parent = self.layers[gi].group;
            if self.push_stack_undo("Ungroup") {
                return;
            }
            for l in self.layers.iter_mut() {
                if l.group == group_id {
                    l.group = parent;
                }
            }
            self.layers.remove(gi);
            if self.active >= self.layers.len() {
                self.active = self.layers.len().saturating_sub(1);
            }
            self.composite();
        }
    }
    pub fn layer_group(&self, id: u32) -> u32 {
        self.layer_index(id)
            .map(|i| self.layers[i].group)
            .unwrap_or(0)
    }

    // ── Smart objects / smart filters (non-destructive) ────────
    /// Layer ▸ Smart Objects ▸ Convert to Smart Object for a GROUP or a
    /// multi-layer selection. The chosen layers are packed into a sub-document,
    /// serialized as MVSN into `smart_doc`, and their composite becomes the
    /// smart object's flat `smart_src` — so filters, placement and export keep
    /// working exactly as they do for a single-layer source, while Edit Contents
    /// can reopen the real layer stack. Passing a group header takes its members.
    /// Returns false (with `last_edit_error` set) when nothing was convertible.
    pub fn convert_layers_to_smart_object(&mut self, ids: &[u32]) -> bool {
        // A group header stands for its members; anything else is itself.
        let mut wanted: Vec<usize> = Vec::new();
        for id in ids {
            let Some(i) = self.layer_index(*id) else { continue };
            if self.layers[i].kind == 6 {
                let gid = self.layers[i].id;
                for (j, l) in self.layers.iter().enumerate() {
                    if l.group == gid && l.kind != 6 && !wanted.contains(&j) {
                        wanted.push(j);
                    }
                }
            } else if !wanted.contains(&i) {
                wanted.push(i);
            }
        }
        wanted.retain(|&i| matches!(self.layers[i].kind, 0 | 2 | 4));
        if wanted.is_empty() {
            self.last_edit_error =
                "Could not convert to a Smart Object because the selection holds no convertible layers.".into();
            return false;
        }
        // Keep document order, top-most first, so the sub-document stacks the
        // same way the parent did.
        wanted.sort_unstable();
        if wanted.iter().any(|&i| !self.canvas_home_plane(i)) {
            self.last_edit_error = "Could not convert this layer to a Smart Object.".into();
            return false;
        }
        // The sub-document is a real Engine, so it serializes and reloads through
        // the same MVSN path a top-level document does.
        let mut sub = Engine::new(self.w, self.h);
        sub.depth = self.depth;
        sub.layers.clear();
        for &i in &wanted {
            let mut copy = self.layers[i].clone();
            copy.group = 0;
            copy.clipping = false;
            sub.layers.push(copy);
        }
        sub.active = 0;
        // The contents blend as they did in the document (Color Settings ▸
        // Advanced), so converting does not change what the canvas shows.
        sub.blend_space = self.active_blend_space();
        sub.composite();
        // Composite into RGBA16 — and RGBA32 for a float document — instead of
        // reading the RGBA8 display buffer: that path quantises a 16-bit
        // document down to 8 bits and erases a 32-bit one's HDR range outright,
        // neither of which the single-layer sibling does. Everything that can
        // refuse runs before the undo push, so a refusal leaves no ghost step.
        let src_f32 = if self.depth == 32 {
            match sub.try_export_composite_rgba32() {
                Ok(samples) => samples,
                Err(message) => {
                    self.last_edit_error = message;
                    return false;
                }
            }
        } else {
            Vec::new()
        };
        let src = sub.export_composite_rgba16();
        let doc = sub.save_project();

        if self.push_stack_undo("Convert to Smart Object") {
            return false;
        }
        let host = wanted[0];
        let name = self.layers[host].name.clone();
        self.layers[host].kind = 7;
        self.layers[host].name = name;
        self.layers[host].pixels = src.clone().into();
        self.layers[host].pixels_f32 = src_f32.clone().into();
        self.layers[host].set_smart_src(src);
        self.layers[host].smart_src_f32 = src_f32.into();
        self.layers[host].smart_doc = doc;
        self.layers[host].smart_source_id = self.next_id;
        self.next_id += 1;
        self.layers[host].smart_filters.clear();
        self.layers[host].smart_filter_opts.clear();
        self.layers[host].smart_transform = SMART_IDENTITY;
        self.layers[host].smart_transform_ops.clear();
        // Everything else it absorbed goes away, deepest index first so the
        // remaining indices stay valid.
        let host_id = self.layers[host].id;
        for &i in wanted.iter().rev() {
            if self.layers[i].id != host_id {
                self.layers.remove(i);
            }
        }
        self.active = self.layer_index(host_id).unwrap_or(0);
        self.composite();
        true
    }

    /// The shared-source id of a smart object: layers duplicated from one
    /// another report the same non-zero value. 0 = standalone (or not a smart
    /// object at all), which is what the Layers panel badges on.
    pub fn smart_source_id(&self, id: u32) -> u32 {
        self.layer_index(id)
            .filter(|&i| self.layers[i].kind == 7)
            .map_or(0, |i| self.layers[i].smart_source_id)
    }

    /// Layer ▸ Smart Objects ▸ New Smart Object via Copy: break this layer out
    /// of its instance group so edits stop propagating to (and from) its former
    /// siblings. Its pixels, placement and filters are untouched — only the
    /// identity changes. Returns false when there was nothing to detach.
    pub fn detach_smart_object(&mut self, id: u32) -> bool {
        let Some(i) = self.layer_index(id) else {
            return false;
        };
        if self.layers[i].kind != 7 || self.layers[i].smart_source_id == 0 {
            return false;
        }
        // Already alone in its group: nothing is shared, so nothing to break.
        let source = self.layers[i].smart_source_id;
        if self.layers.iter().filter(|l| l.smart_source_id == source).count() < 2 {
            return false;
        }
        // A Photoshop source it shared becomes its own: decode the document it
        // has not been edited from yet, and let an export mint it a record,
        // since its descriptor still names the shared one.
        let document = match &self.layers[i].smart_link {
            Some(link) if self.layers[i].smart_doc.is_empty() => {
                self.embedded_photoshop_document(&link.id).ok().map(|sub| sub.save_project())
            }
            _ => None,
        };
        if self.push_stack_undo("New Smart Object via Copy") {
            return false;
        }
        self.layers[i].smart_source_id = self.next_id;
        self.next_id += 1;
        if self.layers[i].smart_link.is_some() {
            self.layers[i].psd_smart_blocks.clear();
            match document {
                Some(document) => self.layers[i].smart_doc = document,
                None if self.layers[i].smart_doc.is_empty() => self.layers[i].smart_link = None,
                None => {}
            }
            if let Some(link) = &mut self.layers[i].smart_link {
                link.id.clear();
            }
        }
        true
    }

    /// Push a smart object's freshly-decoded source onto every sibling that
    /// shares its id. Each sibling keeps its OWN placement, filters and mask —
    /// only the contents travel, which is what makes them instances rather than
    /// copies. `except` is the layer that already has the new source.
    fn propagate_smart_source(&mut self, except: usize) {
        let source = self.layers[except].smart_source_id;
        if source == 0 {
            return;
        }
        let src = self.layers[except].smart_src.clone();
        let src_f32 = self.layers[except].smart_src_f32.clone();
        let raw_headroom = self.layers[except].smart_raw_headroom.clone();
        let doc = self.layers[except].smart_doc.clone();
        let siblings: Vec<usize> = (0..self.layers.len())
            .filter(|&j| j != except && self.layers[j].smart_source_id == source)
            .collect();
        let flat = self.layers[except].smart_link.is_none();
        for j in siblings {
            self.layers[j].set_smart_src(src.clone());
            self.layers[j].smart_raw_headroom = raw_headroom.clone();
            self.layers[j].smart_src_f32 = src_f32.clone().into();
            self.layers[j].smart_doc = doc.clone();
            if flat {
                self.layers[j].smart_link = None;
            }
            self.render_smart(j);
        }
    }

    /// The serialized sub-document behind a layered smart object, for Edit
    /// Contents to open as its own tab. Empty when the smart object holds a flat
    /// source (which is what every pre-layered smart object holds).
    ///
    /// An imported Smart Object whose source is an embedded PSD/PSB is decoded
    /// here, on first Edit Contents rather than at import, so opening a file
    /// never pays for documents nobody edits (#460). One that cannot be read
    /// comes back empty, with the reason in `last_edit_error`.
    pub fn smart_object_document(&mut self, id: u32) -> Vec<u8> {
        let Some(i) = self.layer_index(id).filter(|&i| self.layers[i].kind == 7) else {
            return Vec::new();
        };
        let layer = &self.layers[i];
        let Some(link) = layer.smart_link.as_ref().filter(|_| layer.smart_doc.is_empty()) else {
            return layer.smart_doc.clone();
        };
        let embedded_mode = monet_format::import::psd_embedded_file(&self.psd_linked_blocks, &link.id)
            .and_then(photoshop_header)
            .map(|header| header.mode);
        match self.embedded_photoshop_document(&link.id) {
            Ok(sub) => {
                // The mode a Photoshop save writes these contents back in.
                let saved = match sub.mode {
                    1 => 1,
                    3 => 9,
                    4 => 7,
                    _ => 3,
                };
                if let Some(mode) = embedded_mode.filter(|&mode| mode != saved) {
                    self.last_edit_error = format!(
                        "The Smart Object's contents are a {} document. Vision edits them in {}, so once you update the Smart Object, a Photoshop save stores them as {}.",
                        photoshop_mode_name(mode),
                        photoshop_mode_name(saved),
                        photoshop_mode_name(saved),
                    );
                }
                sub.save_project()
            }
            Err(reason) => {
                self.last_edit_error = format!(
                    "The Smart Object's embedded Photoshop document could not be opened ({reason}), so Edit Contents shows its rendered pixels."
                );
                Vec::new()
            }
        }
    }

    /// Decode the PSD/PSB an imported Smart Object's file record `id` embeds.
    fn embedded_photoshop_document(&self, id: &str) -> Result<Engine, String> {
        let bytes = monet_format::import::psd_embedded_file(&self.psd_linked_blocks, id)
            .ok_or("the document no longer holds it")?;
        let doc = monet_format::import::parse(bytes).map_err(|error| error.to_string())?;
        if !dims_ok(doc.width, doc.height) {
            return Err("its dimensions are out of range".into());
        }
        let mut sub = format_import::from_doc(doc);
        // As a top-level open does: the modes Photoshop export keeps stay, any
        // other (CMYK, Indexed, Bitmap) is edited as RGB.
        if !matches!(sub.mode, 1 | 3 | 4) {
            sub.mode = 0;
        }
        Ok(sub)
    }

    /// Commit an edited sub-document back into its smart object: re-render the
    /// contents into the flat source and keep the new layer stack. Placement,
    /// filters and mask are untouched — this replaces contents only.
    pub fn replace_smart_object_document(&mut self, id: u32, bytes: &[u8]) -> bool {
        let Some(i) = self.layer_index(id) else {
            return false;
        };
        if self.layers[i].kind != 7 {
            return false;
        }
        let Ok(mut sub) = Engine::load_project(bytes) else {
            self.last_edit_error =
                "Could not update the Smart Object because its contents are not a readable document.".into();
            return false;
        };
        if self.layers[i].smart_link.is_some() {
            return self.replace_placed_smart_document(i, &mut sub, bytes);
        }
        if sub.w != self.w || sub.h != self.h {
            self.last_edit_error = "Could not update the Smart Object because its contents changed size; this Smart Object's contents must stay the document's size.".into();
            return false;
        }
        if self.push_stack_undo("Edit Contents") {
            return false;
        }
        sub.blend_space = self.active_blend_space(); // as the contents tab showed them
        sub.composite();
        let flat = sub.output.clone();
        let n = (self.w * self.h) as usize;
        let mut src = vec![0u16; n * 4];
        for k in 0..n * 4 {
            src[k] = (flat[k] as u16) * 257;
        }
        self.layers[i].set_smart_src(src);
        self.layers[i].smart_src_f32 = Vec::new().into();
        self.layers[i].smart_doc = bytes.to_vec();
        self.render_smart(i);
        self.propagate_smart_source(i);
        self.composite();
        true
    }

    /// Edit Contents commit for a Smart Object whose source is a Photoshop
    /// document: its composite is re-placed through each instance's own
    /// corners, so every layer sharing the source updates where it sits and
    /// re-renders through its own filters. A document that changed size keeps
    /// its placement's origin and scale.
    fn replace_placed_smart_document(&mut self, i: usize, sub: &mut Engine, bytes: &[u8]) -> bool {
        let composite = sub.export_composite_rgba16();
        let size = [sub.w, sub.h];
        let source = self.layers[i].smart_source_id;
        let mut placed = Vec::new();
        for j in 0..self.layers.len() {
            let layer = &self.layers[j];
            let instance = j == i || (source != 0 && layer.kind == 7 && layer.smart_source_id == source);
            let Some(link) = layer.smart_link.as_ref().filter(|_| instance) else {
                continue;
            };
            let placement = resized_smart_corners(link, size).and_then(|corners| {
                let src = placed_smart_source(&composite, size, corners, self.w, self.h)?;
                Some((corners, src))
            });
            let Some((corners, src)) = placement else {
                self.last_edit_error = format!(
                    "Could not update the Smart Object \"{}\" because its placement has no area.",
                    layer.name
                );
                return false;
            };
            let link = SmartLink { id: link.id.clone(), size, corners };
            placed.push((j, src, link));
        }
        if self.push_stack_undo("Edit Contents") {
            return false;
        }
        for (j, src, link) in placed {
            self.layers[j].set_smart_src(src);
            self.layers[j].smart_src_f32 = Vec::new().into();
            self.layers[j].pixels_f32 = Arc::from(Vec::new());
            self.layers[j].smart_doc = bytes.to_vec();
            self.layers[j].smart_link = Some(link);
            self.render_smart(j);
            if self.depth == 32 {
                Self::promote_layer_to_float(&mut self.layers[j]);
            }
        }
        self.composite();
        true
    }

    pub fn convert_to_smart_object(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].kind != 0 && self.layers[i].kind != 2 && self.layers[i].kind != 4 {
                // A bare return here read as "the menu item is broken": group
                // headers are the single most common target (group_layers leaves
                // the header active, so Cmd-G then Convert lands right here).
                self.last_edit_error = match self.layers[i].kind {
                    6 => "Could not convert to a Smart Object because grouping a group into one is not supported yet - convert the layers inside it instead.".into(),
                    1 => "Could not convert to a Smart Object because an adjustment layer holds no pixels.".into(),
                    3 => "Could not convert to a Smart Object because a vector layer must be rasterized first.".into(),
                    _ => "Could not convert this layer to a Smart Object.".into(),
                };
                return;
            }
            if self.push_stack_undo("Convert to Smart Object") {
                return;
            }
            // A cropped layer keeps an oversized plane, but the smart pipeline
            // requires a canvas-sized source — hand it an oversized one and the
            // whole smart-filter stack silently no-ops. (#76)
            if !self.canvas_home_plane(i) {
                self.last_edit_error = "Could not convert this layer to a Smart Object.".into();
                return;
            }
            let native_source = self.layers[i].pixels_f32.clone();
            // Open Object hands a RAW's highlight headroom to the Smart
            // Object, where Camera Raw (fid 17) reads it on every re-render.
            let matches = self.raw_headroom_for(i).is_some();
            let raw_headroom = self.raw_headroom.take().filter(|_| matches);
            let source = self.layers[i].pixels.clone();
            self.layers[i].set_smart_src(source);
            self.layers[i].smart_raw_headroom = raw_headroom.map(|(_, headroom)| headroom);
            self.layers[i].smart_src_f32 = native_source.into();
            self.layers[i].smart_source_id = self.next_id;
            self.next_id += 1;
            self.layers[i].smart_filters.clear();
            self.layers[i].smart_filter_opts.clear();
            self.layers[i].smart_transform = SMART_IDENTITY;
            self.layers[i].smart_transform_ops.clear();
            self.layers[i].kind = 7;
            self.layers[i].adj_kind = 0;
            self.layers[i].adj_params.clear();
        }
    }

    // File ▸ Place Embedded / Place Linked: decode directly into a NEW Smart
    // Object layer. Building the final layer in one mutation keeps placement a
    // single undo step instead of "New Layer" + "Convert to Smart Object".
    pub fn place_smart_object(&mut self, bytes: &[u8], name: &str) -> Result<u32, JsValue> {
        if photoshop_header(bytes).is_some() {
            return self
                .place_photoshop_document(bytes, name)
                .map_err(|message| JsValue::from_str(&message));
        }
        let source = self.decoded_placed_smart_source(bytes)?;
        if self.push_stack_undo("Place") {
            return Err(JsValue::from_str(IMPORTED_PHOTOSHOP_READ_ONLY));
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut layer = Layer::transparent(id, name, self.w, self.h);
        layer.kind = 7;
        layer.pixels = source.clone().into();
        layer.set_smart_src(source);
        self.insert_layer_above_active(layer);
        self.composite();
        Ok(id)
    }

    /// Place Embedded of a PSD/PSB: the Smart Object keeps the whole document,
    /// so Edit Contents reopens its layers, sized to fit and centred as an
    /// image places (#460).
    fn place_photoshop_document(&mut self, bytes: &[u8], name: &str) -> Result<u32, String> {
        let doc = monet_format::import::parse(bytes).map_err(|error| format!("import failed: {error}"))?;
        if !dims_ok(doc.width, doc.height) {
            return Err("document dimensions out of range".into());
        }
        let mut sub = format_import::from_doc(doc);
        let size = [sub.w, sub.h];
        let scale = (self.w as f64 / size[0] as f64)
            .min(self.h as f64 / size[1] as f64)
            .min(1.0);
        let pw = (size[0] as f64 * scale).round().max(1.0);
        let ph = (size[1] as f64 * scale).round().max(1.0);
        let ox = ((self.w as f64 - pw) / 2.0).floor();
        let oy = ((self.h as f64 - ph) / 2.0).floor();
        let corners = [ox, oy, ox + pw, oy, ox + pw, oy + ph, ox, oy + ph];
        let source = placed_smart_source(&sub.export_composite_rgba16(), size, corners, self.w, self.h)
            .ok_or("the document has no area to place")?;
        let document = sub.save_project();
        if self.push_stack_undo("Place") {
            return Err(IMPORTED_PHOTOSHOP_READ_ONLY.into());
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut layer = Layer::transparent(id, name, self.w, self.h);
        layer.kind = 7;
        layer.pixels = source.clone().into();
        layer.set_smart_src(source);
        layer.smart_doc = document;
        layer.smart_link = Some(SmartLink { id: String::new(), size, corners });
        // Duplicates are instances of the document, as Photoshop's are.
        layer.smart_source_id = self.next_id;
        self.next_id += 1;
        self.insert_layer_above_active(layer);
        self.composite();
        Ok(id)
    }

    // filter ids: 0 gaussian, 1 box, 2 sharpen, 3 unsharp, 4 median, 5 find-edges,
    // 6 emboss, 7 motion, 8 high-pass, 9 mosaic, 10 vignette,
    // 11 add-noise(amount, mono, seed), 12 oil/kuwahara, 13 spherize, 14 twirl,
    // 15 path blur, 16 pinch, 17 camera-raw develop recipe, 18..=116 the rest of
    // the Filter menu, 117 liquify mesh — the full id → kernel map is
    // `apply_smart_filter`, and the fid table the app passes lives in
    // apps/vision/src/state/app.ts.
    /// Smart-filter edits refused on a locked layer. The whole stack - adding,
    /// re-editing, reordering, disabling, and the filter mask - is layer
    /// content, and lock is the user's only protection for it. Sits after each
    /// op's validity checks and before its undo push, so a no-op stays a no-op
    /// and a refusal costs no history step.
    fn refuse_locked_smart(&mut self, id: u32) -> bool {
        if !self.layer_index(id).is_some_and(|i| self.layers[i].locked) {
            return false;
        }
        self.last_edit_error =
            "Could not edit the smart filters because the layer is locked.".into();
        true
    }

    pub fn smart_add_filter(&mut self, id: u32, filter_id: u8, params: &[f32]) {
        if filter_id == 118 && lens_profile::filter_params(params).is_none() {
            self.last_edit_error = "Could not apply Lens Profile: invalid calibration or controls.".into();
            return;
        }
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].kind != 7 {
                return;
            }
            if self.refuse_locked_smart(id) {
                return;
            }
            if self.reject_float_edit_for_layer(i, "Add Smart Filter") {
                return;
            }
            if self.push_stack_undo("Smart Filter") {
                return;
            }
            self.layers[i]
                .smart_filters
                .push((filter_id, params.to_vec()));
            // Photoshop gives a smart object its filter mask the moment it gets
            // a smart filter — there is no "Add Filter Mask" command, which is
            // why nothing here ever called `add_smart_filter_mask` and the mask
            // could not come into existence at all. Delete Filter Mask and
            // Disable Filter Mask were commands for a thing that never existed,
            // and the filter-mask paint path was unreachable with them.
            // Fully white is identity in the render (cov == 255 short-circuits),
            // so this changes no pixels; it rides the undo step just pushed.
            if self.layers[i].smart_mask.is_empty() {
                self.layers[i].smart_mask = vec![255u8; (self.w * self.h) as usize];
                self.layers[i].smart_mask_enabled = true;
            }
            self.layers[i].psd_smart_blocks.clear();
            self.render_smart(i);
            self.composite();
        }
    }
    // Read back a smart filter's params (e.g. to re-seed the Camera Raw workspace
    // sliders from a stored fid-17 entry). Empty vec when the layer or entry is absent.
    pub fn smart_filter_params(&self, id: u32, index: usize) -> Vec<f32> {
        self.layer_index(id)
            .and_then(|i| self.layers[i].smart_filters.get(index))
            .map(|(_fid, params)| params.clone())
            .unwrap_or_default()
    }
    // Read the filter identity independently of its parameter layout. `-1`
    // is unambiguous because stored ids are u8.
    pub fn smart_filter_id(&self, id: u32, index: usize) -> i32 {
        self.layer_index(id)
            .and_then(|i| self.layers[i].smart_filters.get(index))
            .map(|(filter_id, _)| *filter_id as i32)
            .unwrap_or(-1)
    }
    // Replace a smart filter's params in place (re-editing the Camera Raw recipe on
    // a smart object). Out-of-range index is a safe no-op that touches NO history,
    // so replaying a recorded update thunk against a layer without that entry
    // degrades gracefully instead of panicking or leaving a stray undo step.
    pub fn smart_update_filter(&mut self, id: u32, index: usize, params: &[f32]) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].kind != 7 || index >= self.layers[i].smart_filters.len() {
                return;
            }
            if self.layers[i].smart_filters[index].1.as_slice() == params {
                return;
            }
            if self.layers[i].smart_filters[index].0 == 118 && lens_profile::filter_params(params).is_none() {
                self.last_edit_error = "Could not apply Lens Profile: invalid calibration or controls.".into();
                return;
            }
            if self.refuse_locked_smart(id) {
                return;
            }
            if self.reject_float_edit_for_layer(i, "Edit Smart Filter") {
                return;
            }
            if self.push_stack_undo("Smart Filter") {
                return;
            }
            let fid = self.layers[i].smart_filters[index].0;
            self.layers[i].smart_filters[index] = (fid, params.to_vec());
            self.layers[i].psd_smart_blocks.clear();
            self.render_smart(i);
            self.composite();
        }
    }
    // ── Per-filter stack editing (a filter row in the Layers panel) ──
    // Every one of these is a no-op on a non-smart layer or an out-of-range
    // index — a stale row from a panel that has not re-read the stack must not
    // panic or leave a stray history step.
    fn smart_filter_row(&self, id: u32, index: usize) -> Option<usize> {
        let i = self.layer_index(id)?;
        (self.layers[i].kind == 7 && index < self.layers[i].smart_filters.len()).then_some(i)
    }
    // Layers panel: delete ONE filter (the row's trash target), leaving the rest
    // of the stack intact — unlike `smart_clear_filters`, which wipes it.
    pub fn smart_remove_filter(&mut self, id: u32, index: usize) {
        let Some(i) = self.smart_filter_row(id, index) else {
            return;
        };
        if self.refuse_locked_smart(id) {
            return;
        }
        if self.reject_float_edit_for_layer(i, "Delete Smart Filter") {
            return;
        }
        if self.push_stack_undo("Delete Smart Filter") {
            return;
        }
        self.layers[i].smart_filters.remove(index);
        if index < self.layers[i].smart_filter_opts.len() {
            self.layers[i].smart_filter_opts.remove(index);
        }
        self.layers[i].psd_smart_blocks.clear();
        self.render_smart(i);
        self.composite();
    }
    // Layers panel: drag a filter row to a new position. The stack is applied in
    // order, so this changes the rendered result.
    pub fn smart_move_filter(&mut self, id: u32, from: usize, to: usize) {
        let Some(i) = self.smart_filter_row(id, from) else {
            return;
        };
        if to >= self.layers[i].smart_filters.len() || to == from {
            return;
        }
        if self.refuse_locked_smart(id) {
            return;
        }
        if self.reject_float_edit_for_layer(i, "Smart Move Filter") {
            return;
        }
        if self.push_stack_undo("Move Smart Filter") {
            return;
        }
        let entry = self.layers[i].smart_filters.remove(from);
        self.layers[i].smart_filters.insert(to, entry);
        // Row state travels with its filter; materialize first so a partially
        // defaulted stack cannot desync from the reorder.
        let opts = self.layers[i].smart_filter_opts_mut();
        if from < opts.len() && to < opts.len() {
            let opt = opts.remove(from);
            opts.insert(to, opt);
        }
        self.layers[i].psd_smart_blocks.clear();
        self.render_smart(i);
        self.composite();
    }
    // The per-filter eye. Distinct from `set_smart_filters_enabled`, which
    // bypasses the whole stack.
    pub fn set_smart_filter_enabled(&mut self, id: u32, index: usize, enabled: bool) {
        let Some(i) = self.smart_filter_row(id, index) else {
            return;
        };
        if self.layers[i].smart_filter_opt(index).enabled == enabled {
            return;
        }
        if self.refuse_locked_smart(id) {
            return;
        }
        if self.reject_float_edit_for_layer(i, "Set Smart Filter Enabled") {
            return;
        }
        if self.push_stack_undo(if enabled {
            "Show Smart Filter"
        } else {
            "Hide Smart Filter"
        }) {
            return;
        }
        self.layers[i].smart_filter_opts_mut()[index].enabled = enabled;
        self.layers[i].psd_smart_blocks.clear();
        self.render_smart(i);
        self.composite();
    }
    // Smart Filter ▸ Blending Options: mode index + 0..1 opacity for one filter.
    pub fn set_smart_filter_blend(&mut self, id: u32, index: usize, mode: u8, opacity: f32) {
        let Some(i) = self.smart_filter_row(id, index) else {
            return;
        };
        let opacity = if opacity.is_finite() {
            opacity.clamp(0.0, 1.0)
        } else {
            1.0
        };
        let current = self.layers[i].smart_filter_opt(index);
        if current.blend == mode && current.opacity == opacity {
            return;
        }
        if self.refuse_locked_smart(id) {
            return;
        }
        if self.reject_float_edit_for_layer(i, "Smart Filter Blending Options") {
            return;
        }
        if self.push_stack_undo("Filter Blending Options") {
            return;
        }
        let opt = &mut self.layers[i].smart_filter_opts_mut()[index];
        opt.blend = mode;
        opt.opacity = opacity;
        self.layers[i].psd_smart_blocks.clear();
        self.render_smart(i);
        self.composite();
    }
    pub fn smart_filter_enabled(&self, id: u32, index: usize) -> bool {
        self.smart_filter_row(id, index)
            .is_none_or(|i| self.layers[i].smart_filter_opt(index).enabled)
    }
    pub fn smart_filter_blend_mode(&self, id: u32, index: usize) -> u8 {
        self.smart_filter_row(id, index)
            .map_or(0, |i| self.layers[i].smart_filter_opt(index).blend)
    }
    pub fn smart_filter_opacity(&self, id: u32, index: usize) -> f32 {
        self.smart_filter_row(id, index)
            .map_or(1.0, |i| self.layers[i].smart_filter_opt(index).opacity)
    }
    pub fn smart_clear_filters(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].kind != 7 || self.layers[i].smart_filters.is_empty() {
                return;
            }
            if self.reject_float_edit_for_layer(i, "Smart Clear Filters") {
                return;
            }
            if self.push_stack_undo("Clear Smart Filters") {
                return;
            }
            self.layers[i].smart_filters.clear();
            self.layers[i].smart_filter_opts.clear();
            self.layers[i].psd_smart_blocks.clear();
            self.render_smart(i);
            self.composite();
        }
    }
    /// Camera Raw ▸ Profile (#446): re-render the Smart Objects whose camera
    /// profile can be found now (develop.rs `refresh_develop_profile_layers`).
    /// Exported here, not there, so the plane sweep census below accounts for it.
    pub fn refresh_develop_profiles(&mut self, source_layer: Option<u32>, source: Option<Vec<f32>>) -> u32 {
        // The host has the saved RAW envelope even when this reopened engine
        // has no RawMetadata. Hydrate only its declared source-owning layer.
        if let (Some(i), Some(source)) = (source_layer.and_then(|id| self.layer_index(id)), dcp::DcpSource::from_words(source.as_deref().unwrap_or(&[]))) {
            for (fid, params) in &mut self.layers[i].smart_filters {
                if *fid == 17 { *params = develop::with_profile_source(params, Some(source)); }
            }
        }
        self.refresh_develop_profile_layers()
    }
    pub fn smart_filter_count(&self, id: u32) -> usize {
        self.layer_index(id)
            .map(|i| self.layers[i].smart_filters.len())
            .unwrap_or(0)
    }
    // Layer ▸ Smart Filter ▸ Enable / Disable: bypass or reinstate the whole
    // filter stack on a smart object (the stack is kept either way). No-op on a
    // non-smart layer or one with no filters.
    pub fn set_smart_filters_enabled(&mut self, id: u32, enabled: bool) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].kind != 7
                || self.layers[i].smart_filters.is_empty()
                || self.layers[i].smart_enabled == enabled
            {
                return;
            }
            if self.refuse_locked_smart(id) {
                return;
            }
            if self.reject_float_edit_for_layer(i, "Set Smart Filters Enabled") {
                return;
            }
            if self.push_stack_undo(if enabled {
                "Enable Smart Filters"
            } else {
                "Disable Smart Filters"
            }) {
                return;
            }
            self.layers[i].smart_enabled = enabled;
            self.layers[i].psd_smart_blocks.clear();
            self.render_smart(i);
            self.composite();
        }
    }
    // ── Smart Filter mask ───────────────────────────────────────────────
    // Photoshop's mask under the layer row. It gates the WHOLE stack: white
    // keeps the filtered result, black restores the raw source, grey lerps.
    // Add Filter Mask: the white plane Photoshop shows the moment a filter
    // lands. No-op unless the layer is a smart object with a filter stack.
    pub fn add_smart_filter_mask(&mut self, id: u32) -> bool {
        let Some(i) = self.layer_index(id) else {
            return false;
        };
        if self.layers[i].kind != 7
            || self.layers[i].smart_filters.is_empty()
            || !self.layers[i].smart_mask.is_empty()
        {
            return false;
        }
        // Masking re-runs the u16 stack, which a 32-bit layer's float authority
        // must not be overwritten by — same refusal as the rest of the stack ops.
        if self.refuse_locked_smart(id) {
            return false;
        }
        if self.reject_float_edit_for_layer(i, "Add Smart Filter Mask") {
            return false;
        }
        if self.push_stack_undo("Add Filter Mask") {
            return false;
        }
        self.layers[i].smart_mask = vec![255u8; (self.w * self.h) as usize];
        self.layers[i].smart_mask_enabled = true;
        true
    }
    // Layer ▸ Smart Filter ▸ Delete Filter Mask: drop the plane; the stack goes
    // back to covering the whole object.
    pub fn delete_smart_filter_mask(&mut self, id: u32) -> bool {
        let Some(i) = self.layer_index(id) else {
            return false;
        };
        if self.refuse_locked_smart(id) {
            return false;
        }
        if self.layers[i].smart_mask.is_empty() || self.reject_float_edit_for_layer(i, "Delete Smart Filter Mask") {
            return false;
        }
        if self.push_stack_undo("Delete Filter Mask") {
            return false;
        }
        self.layers[i].smart_mask = Vec::new();
        self.layers[i].smart_mask_enabled = true;
        self.render_smart(i);
        self.composite();
        true
    }
    // Layer ▸ Smart Filter ▸ Enable / Disable Filter Mask: the bytes are kept
    // either way (Photoshop's red X over the mask thumbnail).
    pub fn set_smart_filter_mask_enabled(&mut self, id: u32, enabled: bool) -> bool {
        let Some(i) = self.layer_index(id) else {
            return false;
        };
        if self.layers[i].smart_mask.is_empty() || self.layers[i].smart_mask_enabled == enabled {
            return false;
        }
        if self.refuse_locked_smart(id) || self.reject_float_edit_for_layer(i, "Set Smart Filter Mask Enabled") {
            return false;
        }
        if self.push_stack_undo(if enabled {
            "Enable Filter Mask"
        } else {
            "Disable Filter Mask"
        }) {
            return false;
        }
        self.layers[i].smart_mask_enabled = enabled;
        self.render_smart(i);
        self.composite();
        true
    }
    pub fn smart_filter_mask_enabled(&self, id: u32) -> bool {
        self.layer_index(id)
            .map(|i| self.layers[i].smart_mask_enabled)
            .unwrap_or(true)
    }
    pub fn has_smart_filter_mask(&self, id: u32) -> bool {
        self.layer_index(id)
            .map(|i| !self.layers[i].smart_mask.is_empty())
            .unwrap_or(false)
    }
    /// The filter mask as a full-size grayscale plane (w*h, 255 = filter at
    /// full strength) for the panel thumbnail and the ⌥-click mask preview.
    /// Empty when the layer has none. Like `layer_mask_gray`, display-only.
    pub fn smart_filter_mask_gray(&self, id: u32) -> Vec<u8> {
        self.layer_index(id)
            .map(|i| self.layers[i].smart_mask.clone())
            .unwrap_or_default()
    }
    // Direct the brush at the filter mask instead of the layer's pixels/mask.
    // Painting only lands once the plane exists (`add_smart_filter_mask`),
    // exactly like the layer mask.
    pub fn set_filter_mask_edit(&mut self, on: bool) {
        self.filter_mask_edit = on;
    }

    // Layer ▸ Smart Objects ▸ Reset Transform: regenerate the smart object's
    // pixels from its pristine embedded source through the filter stack,
    // discarding any baked transform.
    pub fn reset_smart_object(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].kind != 7 || self.layers[i].smart_src.is_empty() {
                return;
            }
            if self.reject_float_edit_for_layer(i, "Reset Smart Object") {
                return;
            }
            if self.push_stack_undo("Reset Smart Object") {
                return;
            }
            self.layers[i].smart_transform = SMART_IDENTITY;
            self.layers[i].smart_transform_ops.clear();
            self.layers[i].psd_smart_blocks.clear();
            self.render_smart(i);
            self.composite();
        }
    }

    pub fn smart_filters_enabled(&self, id: u32) -> bool {
        self.layer_index(id)
            .map(|i| self.layers[i].smart_enabled)
            .unwrap_or(true)
    }

    // ── Adjustment layers (non-destructive) ────────────────────
    pub fn add_adjustment_layer(&mut self, adj_kind: u8, params: &[f32], name: &str) -> u32 {
        if self.push_stack_undo("New Adjustment Layer") {
            return 0;
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut layer = Layer::header(id, name);
        layer.kind = 1;
        layer.adj_kind = adj_kind;
        layer.adj_params = params.to_vec();
        // Photoshop gives every adjustment layer a mask: seeded from the
        // active selection (which it consumes) so the adjustment applies only
        // to the selected region, else fully revealing.
        if self.sel.active {
            layer.mask = self.sel.mask.clone().into();
            self.sel.deselect();
            self.sel_dirty();
        } else {
            layer.mask = vec![255u8; (self.w * self.h) as usize].into();
        }
        self.insert_layer_above_active(layer);
        self.composite();
        id
    }
    pub fn set_adjustment_params(&mut self, id: u32, params: &[f32]) {
        if let Some(i) = self.layer_index(id) {
            // One undo step per continuous edit chain (slider drag), like the
            // opacity slider — not zero (history desync) and not one per tick.
            if self.push_prop_undo(2, id, "Adjustment Settings") {
                return;
            }
            self.layers[i].adj_params = params.to_vec();
            self.composite();
        }
    }

    /// Adjustment Brush: an adjustment layer whose mask starts fully HIDDEN
    /// (black), so the effect is invisible until the user brushes it in. Paired
    /// with `set_mask_reveal(true)` so brush strokes paint white into the mask.
    pub fn add_adjustment_layer_hidden(&mut self, adj_kind: u8, params: &[f32], name: &str) -> u32 {
        if self.push_stack_undo("Adjustment Brush") {
            return 0;
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut layer = Layer::header(id, name);
        layer.kind = 1;
        layer.adj_kind = adj_kind;
        layer.adj_params = params.to_vec();
        layer.mask = vec![0u8; (self.w * self.h) as usize].into(); // hidden; brushed in
        self.insert_layer_above_active(layer);
        self.composite();
        id
    }

    /// When on, mask-editing brush strokes paint white (reveal) regardless of the
    /// foreground color — used by the Adjustment Brush to paint the effect in.
    pub fn set_mask_reveal(&mut self, on: bool) {
        self.mask_reveal = on;
    }

    // ── Vector layers (kind 3) ──────────────────────────────────────────
    // A vector layer hosts an Artisan-style scene (paths/shapes/paint/stroke/
    // groups) rasterized on demand into the raster compositor (design doc §5).
    // Editing operates on the live scene; the layer's pixels are a derived cache.

    /// Create a vector layer from an Artisan-style scene JSON (a `.artisan`
    /// document or a `{format,version,document}` wrapper). Returns the layer id.
    pub fn add_vector_layer(&mut self, scene_json: &str, name: &str) -> u32 {
        if self.push_stack_undo("New Vector Layer") {
            return 0;
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut layer = Layer::transparent(id, name, self.w, self.h);
        layer.kind = 3;
        layer.vector_scene = Some(Box::new(
            crate::vector::model::Document::parse(scene_json).unwrap_or_default(),
        ));
        let at = self.insert_layer_above_active(layer);
        self.render_vector(at);
        self.composite();
        id
    }

    /// Provide a TrueType/OpenType font to the native vector text renderer.
    /// Bracket a bulk vector-font registration: registrations issued between
    /// `beginVectorFontBatch` and `endVectorFontBatch` skip their per-call
    /// vector-layer invalidation, so provisioning N faces triggers a single
    /// rerender at the end instead of one per face. Nesting is not supported;
    /// pair each begin with exactly one end.
    #[wasm_bindgen(js_name = beginVectorFontBatch)]
    pub fn begin_vector_font_batch(&mut self) {
        self.defer_vector_font_invalidation = true;
    }

    /// Close a `beginVectorFontBatch` and rerender existing vector layers once.
    #[wasm_bindgen(js_name = endVectorFontBatch)]
    pub fn end_vector_font_batch(&mut self) {
        self.defer_vector_font_invalidation = false;
        self.invalidate_vector_layers();
    }

    /// The engine cannot discover system fonts from WebAssembly, so hosts push
    /// bytes at runtime and vector text falls back to bitmap glyphs when no
    /// registered family matches.
    #[wasm_bindgen(js_name = registerVectorFont)]
    pub fn register_vector_font(
        &mut self,
        family: &str,
        bytes: &[u8],
        face_index: u32,
    ) -> Result<(), JsValue> {
        crate::vector::fonts::register_font(family, bytes, face_index)
            .map_err(|e| JsValue::from_str(&e))?;
        self.invalidate_vector_layers_unless_batched();
        Ok(())
    }

    /// Provide a styled TrueType/OpenType face for the native vector text renderer.
    /// Multiple faces can share the same family; vector text picks the closest
    /// registered face for its `fontWeight` and `fontStyle` before falling back.
    #[wasm_bindgen(js_name = registerVectorFontFace)]
    pub fn register_vector_font_face(
        &mut self,
        family: &str,
        bytes: &[u8],
        face_index: u32,
        weight: f32,
        italic: bool,
    ) -> Result<(), JsValue> {
        crate::vector::fonts::register_font_face(family, bytes, face_index, weight, italic)
            .map_err(|e| JsValue::from_str(&e))?;
        self.invalidate_vector_layers_unless_batched();
        Ok(())
    }

    /// Inspect TrueType/OpenType bytes and return face metadata as JSON. Hosts
    /// use this before registration so family/style metadata comes from the font
    /// itself instead of brittle filename heuristics.
    #[wasm_bindgen(js_name = inspectVectorFontFaces)]
    pub fn inspect_vector_font_faces(&self, bytes: &[u8]) -> Result<String, JsValue> {
        let faces =
            crate::vector::fonts::inspect_font_faces(bytes).map_err(|e| JsValue::from_str(&e))?;
        serde_json::to_string(&faces)
            .map_err(|e| JsValue::from_str(&format!("font face metadata encode failed: {e}")))
    }

    /// Rerender vector-layer caches after the host has changed the thread-local
    /// font registry through another Engine instance on the same thread. In the
    /// browser/WASM host every Engine lives on the main thread and shares one
    /// registry, which is what this refresh assumes; a native multi-threaded host
    /// would see per-thread registries and must register fonts on each thread.
    #[wasm_bindgen(js_name = refreshVectorFonts)]
    pub fn refresh_vector_fonts(&mut self) {
        self.invalidate_vector_layers();
    }

    #[wasm_bindgen(js_name = clearVectorFonts)]
    pub fn clear_vector_fonts(&mut self) {
        crate::vector::fonts::clear_fonts();
        self.invalidate_vector_layers();
    }

    /// Convert the active layer's id into a vector layer kind (scene starts empty
    /// unless one was already attached) — the host's entry to vector authoring.
    pub fn convert_to_vector(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            if self.reject_float_edit_for_layer(i, "Convert To Vector") {
                return;
            }
            if self.push_stack_undo("Convert to Vector Layer") {
                return;
            }
            self.layers[i].kind = 3;
            if self.layers[i].vector_scene.is_none() {
                self.layers[i].vector_scene =
                    Some(Box::new(crate::vector::model::Document::default()));
            }
            self.layers[i].vector_cache_key = None;
            self.render_vector(i);
            self.composite();
        }
    }

    /// Layer ▸ Rasterize ▸ Shape: keep the current rendered pixels while
    /// dropping the editable vector scene. Masks, blending, and effects remain
    /// attached to the resulting pixel layer.
    pub fn rasterize_vector_layer(&mut self, id: u32) -> bool {
        let Some(i) = self.layer_index(id) else {
            return false;
        };
        if self.layers[i].kind != 3 {
            return false;
        }
        if self.reject_imported_photoshop_edit() {
            return false;
        }
        self.render_vector(i);
        if self.push_stack_undo("Rasterize Shape") {
            return false;
        }
        self.layers[i].kind = 0;
        self.layers[i].vector_scene = None;
        self.layers[i].vector_cache_key = None;
        self.composite();
        true
    }

    /// Replace a vector layer's entire scene from JSON.
    /// Path edits refused on a locked layer. The Pen and Direct/Path Selection
    /// tools rewrite a vector layer's scene in place, and `create_work_path` and
    /// `vector_boolean` already checked the lock — the eight ops that actually
    /// move geometry did not, so locking a shape layer protected nothing.
    fn refuse_locked_vector(&mut self, id: u32) -> bool {
        if !self.layer_index(id).is_some_and(|i| self.layers[i].locked) {
            return false;
        }
        self.last_edit_error = "Could not edit the path because the layer is locked.".into();
        true
    }

    pub fn vector_set_scene(&mut self, id: u32, scene_json: &str) -> Result<(), JsValue> {
        let Some(i) = self.layer_index(id) else {
            return Ok(());
        };
        if self.layers[i].kind != 3 {
            return Ok(());
        }
        if self.refuse_locked_vector(id) {
            return Ok(());
        }
        let doc = crate::vector::model::Document::parse(scene_json)
            .map_err(|e| JsValue::from_str(&format!("vector scene parse: {e}")))?;
        if self.push_layer_undo("Edit Vector Layer") {
            return Err(JsValue::from_str(IMPORTED_PHOTOSHOP_READ_ONLY));
        }
        self.layers[i].vector_scene = Some(Box::new(doc));
        self.layers[i].vector_cache_key = None;
        self.render_vector(i);
        self.composite();
        Ok(())
    }

    /// Serialize a vector layer's scene back to canonical `.artisan` JSON.
    pub fn vector_scene_json(&self, id: u32) -> String {
        self.layer_index(id)
            .and_then(|i| self.layers[i].vector_scene.as_deref())
            .map(|d| serde_json::to_string(d).unwrap_or_default())
            .unwrap_or_default()
    }

    /// Set the scene's world→canvas view (pan/zoom/rotation). Triggers a
    /// re-raster at the new scale — the "raster-on-zoom" path (design doc §5.6).
    pub fn vector_set_view(&mut self, id: u32, tx: f32, ty: f32, zoom: f32, angle: f32) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].kind == 3 {
                self.layers[i].vector_view = [tx, ty, zoom, angle];
                self.layers[i].vector_cache_key = None;
                self.render_vector(i);
                self.composite();
            }
        }
    }

    /// Hit-test a vector layer's live scene in world space; returns the hit item
    /// id (empty = miss). Reads real geometry, so picking is exact at any zoom.
    pub fn vector_hit_test(&self, id: u32, x: f32, y: f32, tol: f32) -> String {
        self.layer_index(id)
            .and_then(|i| self.layers[i].vector_scene.as_deref())
            .and_then(|d| {
                crate::vector::query::hit_test(d, crate::vector::model::Point { x, y }, tol)
            })
            .unwrap_or_default()
    }

    /// Direct Selection tool ▸ hit an anchor point: the nearest path anchor to a
    /// world-space point within `tol`, as `{"item":"<id>","index":N}` (or "").
    /// Anchors are compared in world space (their item transform applied).
    pub fn vector_nearest_anchor(&self, id: u32, x: f32, y: f32, tol: f32) -> String {
        use crate::vector::geom;
        use crate::vector::model::{Item, Matrix, Point};
        fn walk(
            items: &[Item],
            world: Point,
            parent: Matrix,
            best: &mut Option<(String, usize, f32)>,
        ) {
            for it in items {
                let w = geom::m_mul(parent, it.transform);
                if let Some(children) = &it.children {
                    walk(children, world, w, best);
                }
                let mut flat = 0usize;
                for geo in it.outlines() {
                    for a in geo.anchors.iter() {
                        let d = geom::dist(geom::apply_point(w, a.point), world);
                        if best.as_ref().map_or(true, |b| d < b.2) {
                            *best = Some((it.id.clone(), flat, d));
                        }
                        flat += 1;
                    }
                }
            }
        }
        let Some(li) = self.layer_index(id) else {
            return String::new();
        };
        let Some(doc) = self.layers[li].vector_scene.as_deref() else {
            return String::new();
        };
        let world = Point { x, y };
        let mut best = None;
        for layer in &doc.layers {
            walk(&layer.items, world, geom::m_identity(), &mut best);
        }
        match best {
            Some((item, index, d)) if d <= tol => {
                format!("{{\"item\":\"{item}\",\"index\":{index}}}")
            }
            _ => String::new(),
        }
    }

    /// Direct Selection tool ▸ drag an anchor: move path `item_id`'s anchor at
    /// `index` to world point (x, y). The world point is converted to the item's
    /// local space, so transformed paths edit correctly. Returns whether it moved.
    pub fn vector_move_anchor(
        &mut self,
        id: u32,
        item_id: &str,
        index: usize,
        x: f32,
        y: f32,
    ) -> bool {
        if self.reject_imported_photoshop_edit() {
            return false;
        }
        if self.refuse_locked_vector(id) {
            return false;
        }
        use crate::vector::geom;
        use crate::vector::model::{Item, Matrix, Point};
        fn walk(
            items: &mut [Item],
            target: &str,
            index: usize,
            world: Point,
            parent: Matrix,
        ) -> bool {
            for it in items.iter_mut() {
                let w = geom::m_mul(parent, it.transform);
                if it.id == target {
                    if let Some((slot, local)) = it.outline_at(index) {
                        if let Some(a) = it
                            .outline_mut(slot)
                            .and_then(|geo| geo.anchors.get_mut(local))
                        {
                            if let Some(inv) = geom::m_invert(w) {
                                // handleIn/handleOut are offsets from the point, so
                                // moving the point alone carries the handles along.
                                a.point = geom::apply_point(inv, world);
                                return true;
                            }
                        }
                    }
                }
                if let Some(children) = &mut it.children {
                    if walk(children, target, index, world, w) {
                        return true;
                    }
                }
            }
            false
        }
        let Some(li) = self.layer_index(id) else {
            return false;
        };
        let world = Point { x, y };
        let mut moved = false;
        if let Some(doc) = self.layers[li].vector_scene.as_deref_mut() {
            for layer in doc.layers.iter_mut() {
                if walk(&mut layer.items, item_id, index, world, geom::m_identity()) {
                    moved = true;
                    break;
                }
            }
        }
        if moved {
            self.layers[li].vector_cache_key = None;
            self.render_vector(li);
            self.composite();
        }
        moved
    }

    /// Snapshot a vector layer before an interactive edit (e.g. an anchor drag)
    /// so the whole gesture collapses into one undo step.
    pub fn vector_begin_edit(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].kind == 3 {
                if self.refuse_locked_vector(id) {
                    return;
                }
                if self.push_layer_undo("Edit Path") {
                    return;
                }
            }
        }
    }

    /// Path Selection tool ▸ a component's world-space geometry bounds as
    /// `[x, y, w, h]` (empty = no such item / not a vector layer). What Align
    /// and Distribute line components up by (#456).
    pub fn vector_item_bounds(&self, id: u32, item_id: &str) -> Vec<f32> {
        self.layer_index(id)
            .and_then(|i| self.layers[i].vector_scene.as_deref())
            .and_then(|d| crate::vector::query::world_bounds(d, item_id))
            .map(|r| vec![r.x, r.y, r.w, r.h])
            .unwrap_or_default()
    }

    /// Path Selection tool ▸ move a whole path: translate item `item_id` by
    /// (dx, dy) world units (prepended to its transform). Returns whether it moved.
    pub fn vector_translate_item(&mut self, id: u32, item_id: &str, dx: f32, dy: f32) -> bool {
        if self.reject_imported_photoshop_edit() {
            return false;
        }
        if self.refuse_locked_vector(id) {
            return false;
        }
        let Some(li) = self.layer_index(id) else {
            return false;
        };
        let mut moved = false;
        if let Some(doc) = self.layers[li].vector_scene.as_deref_mut() {
            // (dx, dy) is a WORLD delta. Prepending it to the item's own
            // transform would let its ancestors' scale/rotation multiply it, so
            // a drag inside a 2x group moved twice as far. `translate_items`
            // conjugates by the parent world transform, which is the whole
            // reason it exists — use it rather than re-walking the tree here.
            if crate::vector::ops::find_mut(doc, item_id).is_some() {
                crate::vector::ops::translate_items(doc, &[item_id.to_string()], dx, dy);
                moved = true;
            }
        }
        if moved {
            self.layers[li].vector_cache_key = None;
            self.render_vector(li);
            self.composite();
        }
        moved
    }

    /// Direct Selection tool ▸ hit a bezier handle end: the nearest non-zero
    /// handle of any anchor to a world-space point within `tol`, as
    /// `{"item":"<id>","index":N,"end":"in"|"out"}` (or ""). Zero-length handles
    /// coincide with their anchor, so they are skipped — a click there keeps
    /// hitting the anchor, not a phantom handle.
    pub fn vector_nearest_handle(&self, id: u32, x: f32, y: f32, tol: f32) -> String {
        use crate::vector::geom;
        use crate::vector::model::{Item, Matrix, Point};
        fn walk(
            items: &[Item],
            world: Point,
            parent: Matrix,
            best: &mut Option<(String, usize, bool, f32)>,
        ) {
            for it in items {
                let w = geom::m_mul(parent, it.transform);
                if let Some(children) = &it.children {
                    walk(children, world, w, best);
                }
                let mut flat = 0usize;
                for geo in it.outlines() {
                    for a in geo.anchors.iter() {
                        let i = flat;
                        flat += 1;
                        let p = geom::apply_point(w, a.point);
                        for (is_in, h) in [(true, a.handle_in), (false, a.handle_out)] {
                            if h.x == 0.0 && h.y == 0.0 {
                                continue;
                            }
                            let v = geom::apply_vector(w, h);
                            let d = geom::dist(Point { x: p.x + v.x, y: p.y + v.y }, world);
                            if best.as_ref().map_or(true, |b| d < b.3) {
                                *best = Some((it.id.clone(), i, is_in, d));
                            }
                        }
                    }
                }
            }
        }
        let Some(li) = self.layer_index(id) else {
            return String::new();
        };
        let Some(doc) = self.layers[li].vector_scene.as_deref() else {
            return String::new();
        };
        let world = Point { x, y };
        let mut best = None;
        for layer in &doc.layers {
            walk(&layer.items, world, geom::m_identity(), &mut best);
        }
        match best {
            Some((item, index, is_in, d)) if d <= tol => {
                let end = if is_in { "in" } else { "out" };
                format!("{{\"item\":\"{item}\",\"index\":{index},\"end\":\"{end}\"}}")
            }
            _ => String::new(),
        }
    }

    /// Direct Selection tool ▸ drag a handle: place path `item_id`'s anchor-`index`
    /// handle END (`is_in` picks handleIn/handleOut) at world (x, y). `mirror`
    /// keeps the opposite handle symmetric (smooth point) — Alt-drag passes false
    /// to break the pair. Returns whether it moved.
    /// ponytail: mirror is exact negation (angle + length); Photoshop's
    /// keep-collinear-preserve-length variant would refine ops::set_handle.
    pub fn vector_move_handle(
        &mut self,
        id: u32,
        item_id: &str,
        index: usize,
        is_in: bool,
        x: f32,
        y: f32,
        mirror: bool,
    ) -> bool {
        if self.reject_imported_photoshop_edit() {
            return false;
        }
        if self.refuse_locked_vector(id) {
            return false;
        }
        use crate::vector::geom;
        use crate::vector::model::Point;
        let Some(li) = self.layer_index(id) else {
            return false;
        };
        let mut moved = false;
        if let Some(doc) = self.layers[li].vector_scene.as_deref_mut() {
            // Phase 1: resolve the world→local delta (ends the item borrow)…
            let mut delta = None;
            if let Some((item, pw)) = crate::vector::ops::find_mut(doc, item_id) {
                if item.kind == "path" || item.kind == "compound" {
                    let w = geom::m_mul(pw, item.transform);
                    let anchor = item
                        .outline_at(index)
                        .and_then(|(slot, local)| {
                            item.outlines().nth(slot).and_then(|g| g.anchors.get(local))
                        })
                        .cloned();
                    if let (Some(a), Some(inv)) = (anchor.as_ref(), geom::m_invert(w)) {
                        // Handles are LOCAL offsets from the anchor point.
                        let lp = geom::apply_point(inv, Point { x, y });
                        delta = Some((lp.x - a.point.x, lp.y - a.point.y));
                    }
                }
            }
            // …phase 2: write it through the shared op (mirror lives there).
            if let Some((vx, vy)) = delta {
                crate::vector::ops::set_handle(doc, item_id, index, is_in, vx, vy, mirror);
                moved = true;
            }
        }
        if moved {
            self.layers[li].vector_cache_key = None;
            self.render_vector(li);
            self.composite();
        }
        moved
    }

    /// Both point tools bail before pushing an undo step when the target anchor
    /// does not exist (bad id, bad index, or not a plain path).
    fn vector_anchor_exists(&mut self, li: usize, item_id: &str, index: usize) -> bool {
        self.layers[li].vector_scene.as_deref_mut().is_some_and(|doc| {
            crate::vector::ops::find_mut(doc, item_id)
                .filter(|(it, _)| it.kind == "path" || it.kind == "compound")
                .map(|(it, _)| it.outline_at(index).is_some())
                .unwrap_or(false)
        })
    }

    /// Add Anchor Point tool ▸ insert an anchor on the path segment under a
    /// world-space point (within `tol`), keeping the shape (de Casteljau split).
    /// A click on an existing anchor is a miss. One undo step; returns whether
    /// an anchor was added.
    pub fn vector_insert_anchor(&mut self, id: u32, x: f32, y: f32, tol: f32) -> bool {
        let Some(li) = self.layer_index(id) else {
            return false;
        };
        if self.refuse_locked_vector(id) {
            return false;
        }
        if !self.vector_nearest_anchor(id, x, y, tol).is_empty() {
            return false;
        }
        let Some((pid, slot, seg, t)) = self.layers[li]
            .vector_scene
            .as_deref()
            .and_then(|doc| crate::vector::ops::nearest_segment_point(doc, x, y, tol))
        else {
            return false;
        };
        if self.push_layer_undo("Add Anchor Point") {
            return false;
        }
        if let Some(doc) = self.layers[li].vector_scene.as_deref_mut() {
            if let Some((item, _)) = crate::vector::ops::find_mut(doc, &pid) {
                // The click named a contour as well as a segment, so the anchor
                // goes into THAT outline — a glyph's counter is not its outer.
                if let Some(g) = item.outline_mut(slot).map(|g| g.clone()) {
                    if let Some(target) = item.outline_mut(slot) {
                        *target = crate::vector::geom::insert_anchor(&g, seg, t);
                    }
                }
            }
        }
        self.layers[li].vector_cache_key = None;
        self.render_vector(li);
        self.composite();
        true
    }

    /// Delete Anchor Point tool ▸ remove anchor `index` from path `item_id` (the
    /// item itself goes when fewer than two anchors remain). One undo step.
    pub fn vector_delete_anchor(&mut self, id: u32, item_id: &str, index: usize) -> bool {
        let Some(li) = self.layer_index(id) else {
            return false;
        };
        if self.refuse_locked_vector(id) {
            return false;
        }
        if !self.vector_anchor_exists(li, item_id, index) {
            return false;
        }
        if self.push_layer_undo("Delete Anchor Point") {
            return false;
        }
        if let Some(doc) = self.layers[li].vector_scene.as_deref_mut() {
            crate::vector::ops::delete_anchors(doc, item_id, &[index]);
        }
        self.layers[li].vector_cache_key = None;
        self.render_vector(li);
        self.composite();
        true
    }

    /// Convert Point tool ▸ toggle anchor `index` of path `item_id` between
    /// corner (no handles) and smooth (tangent from neighbours). One undo step.
    pub fn vector_convert_anchor(&mut self, id: u32, item_id: &str, index: usize) -> bool {
        let Some(li) = self.layer_index(id) else {
            return false;
        };
        if self.refuse_locked_vector(id) {
            return false;
        }
        if !self.vector_anchor_exists(li, item_id, index) {
            return false;
        }
        if self.push_layer_undo("Convert Point") {
            return false;
        }
        if let Some(doc) = self.layers[li].vector_scene.as_deref_mut() {
            crate::vector::ops::toggle_anchor_smooth(doc, item_id, index);
        }
        self.layers[li].vector_cache_key = None;
        self.render_vector(li);
        self.composite();
        true
    }

    /// Boolean path op (unite/intersect/exclude/minus-front/minus-back/divide/…)
    /// over the given item ids in a vector layer's scene.
    pub fn vector_boolean(&mut self, id: u32, item_ids_json: &str, op: &str) {
        use crate::vector::model::Item;
        // Highest engine-minted id number ("c7", "p12", "g3") anywhere in a scene.
        fn minted_max(items: &[Item], seen: &mut u64) {
            for it in items {
                if let Some(n) = it
                    .id
                    .strip_prefix(&['c', 'p', 'g'][..])
                    .and_then(|digits| digits.parse::<u64>().ok())
                {
                    *seen = (*seen).max(n);
                }
                if let Some(children) = &it.children {
                    minted_max(children, seen);
                }
                if let Some(mask) = &it.mask {
                    minted_max(mask, seen);
                }
            }
        }
        let Some(i) = self.layer_index(id) else {
            return;
        };
        if self.layers[i].kind != 3 {
            return;
        }
        if self.refuse_locked_vector(id) {
            return;
        }
        let ids: Vec<String> = serde_json::from_str(item_ids_json).unwrap_or_default();
        if self.push_layer_undo("Vector Boolean") {
            return;
        }
        let mut counter = self.layers[i].vector_id_counter;
        if let Some(scene) = self.layers[i].vector_scene.as_deref_mut() {
            // The counter is not persisted, so a scene loaded from .monetgfx (or
            // imported from Artisan) restarts at 0 and the next op mints an id
            // the scene ALREADY uses — after which find_item/hit_test resolve the
            // wrong item and a later boolean's prune deletes both. Seed from what
            // the scene actually defines. (#122)
            let mut minted = 0u64;
            for layer in &scene.layers {
                minted_max(&layer.items, &mut minted);
            }
            counter = counter.max(minted);
            crate::vector::pathfinder::pathfinder(scene, &ids, op, &mut counter);
        }
        self.layers[i].vector_id_counter = counter;
        self.layers[i].vector_cache_key = None;
        self.render_vector(i);
        self.composite();
    }

    // ── Unified graphics document I/O (design doc §8) ───────────────────

    /// Load a unified graphics document (`.monetgfx` JSON), replacing the current
    /// document. Handles raster, adjustment, text, group, smart-object, and the
    /// new vector layer kinds. Returns Err on parse failure.
    pub fn load_graphics(&mut self, json: &str) -> Result<(), JsValue> {
        if self.reject_imported_photoshop_edit() {
            return Err(JsValue::from_str(IMPORTED_PHOTOSHOP_READ_ONLY));
        }
        let gfx =
            monet_format::graphics::GfxDocument::parse(json).map_err(|e| JsValue::from_str(&e))?;
        *self = format_import::from_gfx(gfx).map_err(|e| JsValue::from_str(&e))?;
        Ok(())
    }

    /// Serialize the current document to unified graphics JSON. Raster/text/smart
    /// layers export composited pixels; vector layers export their editable scene.
    pub fn try_save_graphics(&self) -> Result<String, String> {
        if self.imported_photoshop_source.is_some() {
            return Err(IMPORTED_PHOTOSHOP_EXPORT_BLOCKED.into());
        }
        format_import::validate_gfx_document_channels(self)?;
        Ok(format_import::to_gfx(self).to_json())
    }

    pub fn save_graphics(&self) -> String {
        // The retained Photoshop source is deliberately runtime-only. Returning
        // an ordinary GFX document here would look like a successful save while
        // silently discarding the native non-RGB authority.
        if self.imported_photoshop_source.is_some() {
            return String::new();
        }
        self.try_save_graphics().unwrap_or_default()
    }

    /// Assign the document's embedded ICC profile (raw bytes + display name),
    /// so a `.monetgfx` save carries the color space instead of leaving every
    /// other Monet app to guess sRGB. Empty bytes clear it. The engine stores
    /// it verbatim and never interprets it — the color transforms take profile
    /// bytes explicitly from the host (`convert_profile_with_icc`, `display_lut`).
    #[wasm_bindgen(js_name = setDocumentIcc)]
    pub fn set_document_icc(&mut self, bytes: &[u8], name: &str) {
        // The assigned RGB profile is what a separation's plates read the
        // pixels through; Assign Profile changes it.
        if self.mode_profile.as_deref().is_some_and(|p| p.source_icc != bytes) {
            self.rebuild_mode_profile(Some(bytes));
        }
        if bytes.is_empty() {
            self.gfx_envelope.icc_profile = None;
            self.gfx_envelope.icc_profile_name = None;
            return;
        }
        self.gfx_envelope.icc_profile = Some(monet_format::graphics::base64_encode(bytes));
        self.gfx_envelope.icc_profile_name = (!name.is_empty()).then(|| name.to_string());
    }

    /// The document's embedded ICC profile bytes, empty when none is assigned
    /// (or when the carried base64 is corrupt — the on-disk string is still
    /// re-emitted verbatim on save, so a bad profile is never silently dropped).
    #[wasm_bindgen(js_name = documentIcc)]
    pub fn document_icc(&self) -> Vec<u8> {
        self.gfx_envelope
            .icc_profile
            .as_deref()
            .and_then(monet_format::graphics::base64_decode)
            .unwrap_or_default()
    }

    #[wasm_bindgen(js_name = documentIccName)]
    pub fn document_icc_name(&self) -> String {
        self.gfx_envelope.icc_profile_name.clone().unwrap_or_default()
    }

    /// Save the current document as a unified graphics CONTAINER (a zip): a
    /// `manifest.json` (the GfxDocument) plus out-of-line pixel blobs —
    /// `pixels/<id>.png` for 8-bit layers, `pixels/<id>.raw16.z` (deflated
    /// little-endian u16) for >8-bit layers, and `masks/<id>.png` for masks.
    /// This keeps the manifest tiny and preserves full >8-bit precision. The zip
    /// is hand-rolled STORE-only (PNG/raw16 entries are already compressed).
    #[cfg(feature = "codecs-image")]
    #[wasm_bindgen(js_name = trySaveGraphicsContainer)]
    pub fn try_save_graphics_container(&self) -> Result<Vec<u8>, String> {
        if self.imported_photoshop_source.is_some() {
            return Err(IMPORTED_PHOTOSHOP_EXPORT_BLOCKED.into());
        }
        save_graphics_container_impl(self)
    }

    #[cfg(feature = "codecs-image")]
    #[wasm_bindgen(js_name = saveGraphicsContainer)]
    pub fn save_graphics_container(&self) -> Vec<u8> {
        if self.imported_photoshop_source.is_some() {
            return Vec::new();
        }
        save_graphics_container_impl(self).unwrap_or_default()
    }

    /// Load a unified graphics container produced by `save_graphics_container`,
    /// replacing the current document. Resolves out-of-line pixel refs back to
    /// inline blobs so the load funnels through the same placement code path as
    /// the JSON loader. Returns Err on a corrupt zip or missing entry.
    #[cfg(feature = "codecs-image")]
    #[wasm_bindgen(js_name = loadGraphicsContainer)]
    pub fn load_graphics_container(bytes: &[u8]) -> Result<Engine, JsValue> {
        #[cfg(target_arch = "wasm32")]
        console_error_panic_hook::set_once();
        // Errors flow as String (load_graphics_container_impl) and become a
        // JsValue only here at the wasm boundary — a JsValue's Drop aborts on
        // non-wasm targets, so the testable seam must never materialize one.
        load_graphics_container_impl(bytes).map_err(|e| JsValue::from_str(&e))
    }

    // ── Artisan compatibility surface (design doc §4.5 / §9 Phase 5) ────
    // Artisan drives a whole-canvas vector document, not a layer stack. These
    // thin shims model "a transparent document whose single layer is one vector
    // layer", so Artisan's render-only EngineClient (resize/set_document/set_view/
    // render/output_ptr/free) works against the merged engine unchanged.

    /// Resize the output surface to the viewport in device pixels (Artisan).
    pub fn resize(&mut self, w: u32, h: u32) {
        if w != self.w || h != self.h {
            self.resize_canvas(w, h, 0, 0);
        }
    }

    /// Replace the document with a single transparent vector layer holding the
    /// parsed `.artisan` scene (no white background — Artisan canvases are
    /// transparent). Render-only: owns no undo (the TS app owns the document).
    pub fn set_document(&mut self, json: &str) -> Result<(), JsValue> {
        if self.reject_imported_photoshop_edit() {
            return Err(JsValue::from_str(IMPORTED_PHOTOSHOP_READ_ONLY));
        }
        let doc = crate::vector::model::Document::parse(json)
            .map_err(|e| JsValue::from_str(&format!("artisan parse error: {e}")))?;
        let mut layer = Layer::transparent(1, "Artisan", self.w, self.h);
        layer.kind = 3;
        layer.vector_scene = Some(Box::new(doc));
        self.layers.clear();
        self.layers.push(layer);
        self.active = 0;
        self.next_id = 2;
        self.render_vector(0);
        self.composite();
        Ok(())
    }

    /// Set the world→screen view for the Artisan document (the single vector
    /// layer). Matches Artisan's `set_view(tx, ty, zoom, angle)`.
    ///
    /// An identical view is a no-op: the vector cache stays valid and the
    /// frame is not composited again. A real change updates the view, drops
    /// the cache, and composites once. The following `render` uploads that
    /// frame and does not composite again.
    pub fn set_view(&mut self, tx: f32, ty: f32, zoom: f32, angle: f32) {
        let Some(idx) = self.layers.iter().position(|l| l.kind == 3) else {
            self.composite();
            return;
        };
        let next = [tx, ty, zoom, angle];
        if self.layers[idx].vector_view == next {
            return;
        }
        self.layers[idx].vector_view = next;
        self.layers[idx].vector_cache_key = None;
        self.composite();
    }

    /// Upload the current frame. Composites only when `output` is not already
    /// the full frame for this canvas and vector view, so `set_view` plus
    /// `render` composites a changed view once.
    pub fn render(&mut self) {
        if !self.presented_frame_current() {
            self.composite();
        }
    }
    pub fn layer_adj_params(&self, id: u32) -> Vec<f32> {
        self.layer_index(id)
            .map(|i| self.layers[i].adj_params.clone())
            .unwrap_or_default()
    }
    pub fn layer_kind(&self, id: u32) -> u8 {
        self.layer_index(id)
            .map(|i| self.layers[i].kind)
            .unwrap_or(0)
    }
    pub fn layer_adj_kind(&self, id: u32) -> u8 {
        self.layer_index(id)
            .map(|i| self.layers[i].adj_kind)
            .unwrap_or(0)
    }

    // ── Text layers (re-editable; rasterized by the host) ──────
    pub fn set_text_layer(
        &mut self,
        id: u32,
        x: i32,
        y: i32,
        iw: u32,
        ih: u32,
        rgba: &[u8],
        text: &str,
        size: f32,
        r: u8,
        g: u8,
        b: u8,
        a: u8,
    ) {
        // Compute in u64 — `iw * ih * 4` would overflow u32 (and usize on
        // wasm32) for hostile sizes from the scripting API, defeating the check.
        if (rgba.len() as u64) < (iw as u64) * (ih as u64) * 4 {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            let Some(rect) = self.plane_rect(i) else {
                return;
            };
            if self.push_stack_undo("Type") {
                return;
            }
            for v in Arc::make_mut(&mut self.layers[i].pixels).iter_mut() {
                *v = 0;
            }
            let w = self.w as i32;
            let h = self.h as i32;
            for jy in 0..ih as i32 {
                for jx in 0..iw as i32 {
                    let dx = x + jx;
                    let dy = y + jy;
                    if dx < 0 || dy < 0 || dx >= w || dy >= h {
                        continue;
                    }
                    let Some(di) = checked_plane_index(rect, dx, dy, 4) else {
                        continue;
                    };
                    let pi = (jy * iw as i32 + jx) as usize * 4;
                    for k in 0..4 {
                        Arc::make_mut(&mut self.layers[i].pixels)[di + k] = color::u8_to_16(rgba[pi + k]);
                    }
                }
            }
            self.layers[i].kind = 2;
            self.layers[i].text = text.to_string();
            self.layers[i].text_size = size;
            self.layers[i].text_color = [r, g, b, a];
            self.layers[i].text_x = x;
            self.layers[i].text_y = y;
            if self.depth == 32 {
                self.layers[i].pixels_f32 = self.layers[i]
                    .pixels
                    .iter()
                    .map(|value| *value as f32 / 65_535.0)
                    .collect();
            }
            self.composite();
        }
    }
    pub fn layer_text(&self, id: u32) -> String {
        self.layer_index(id)
            .map(|i| self.layers[i].text.clone())
            .unwrap_or_default()
    }
    pub fn layer_text_size(&self, id: u32) -> f32 {
        self.layer_index(id)
            .map(|i| self.layers[i].text_size)
            .unwrap_or(48.0)
    }
    pub fn layer_text_color(&self, id: u32) -> u32 {
        self.layer_index(id)
            .map(|i| {
                let c = self.layers[i].text_color;
                ((c[0] as u32) << 24) | ((c[1] as u32) << 16) | ((c[2] as u32) << 8) | (c[3] as u32)
            })
            .unwrap_or(0xffff_ffff)
    }
    pub fn layer_text_pos(&self, id: u32) -> Vec<i32> {
        self.layer_index(id)
            .map(|i| vec![self.layers[i].text_x, self.layers[i].text_y])
            .unwrap_or(vec![0, 0])
    }

    // Rich re-editable type: the host rasterizes the spec to an RGBA bitmap and
    // hands it here with the opaque spec JSON for round-tripping. Mirrors
    // set_text_layer but carries the full model instead of just a string.
    pub fn set_text_layer_spec(
        &mut self,
        id: u32,
        x: i32,
        y: i32,
        iw: u32,
        ih: u32,
        rgba: &[u8],
        spec: &str,
    ) -> Vec<i32> {
        if self.reject_imported_photoshop_edit() {
            return Vec::new();
        }
        // This force-writes kind = 2. Without a guard, editing type on a layer
        // that was converted TO a smart object flips it back to a text layer
        // and orphans smart_src / smart_filters. Type ▸ Update All Text Layers
        // would do it to every such layer at once.
        if let Some(i) = self.layer_index(id) {
            if !matches!(self.layers[i].kind, 0 | 2) {
                self.last_edit_error =
                    "Could not edit type because this layer is no longer a Type layer.".into();
                return Vec::new();
            }
        }
        // Compute in u64 — `iw * ih * 4` would overflow u32 (and usize on
        // wasm32) for hostile sizes from the scripting API, defeating the check.
        if (rgba.len() as u64) < (iw as u64) * (ih as u64) * 4 {
            return Vec::new();
        }
        if let Some(i) = self.layer_index(id) {
            // During a live on-canvas edit session, coalesce the per-keystroke
            // re-applies into a single undo step (snapshot once, then keep redo
            // cleared) instead of one undo per character.
            // The glyph raster is placed at CANVAS coordinates but written into the
            // layer's own PLANE, so each texel is translated instead of strided by
            // self.w. Resolved before the undo push. (#75)
            let Some(rect) = self.plane_rect(i) else {
                return Vec::new();
            };
            let coalesced = self.text_session && self.text_pushed;
            if coalesced {
                self.redo.clear();
            } else {
                if self.push_stack_undo("Type") {
                    return Vec::new();
                }
                self.text_pushed = true;
            }
            // The previous footprint is only reusable when it is provably still
            // valid: same layer and same plane dims. A plane-dim change (crop,
            // canvas resize) invalidates it and falls back to the full clear.
            let prev = if coalesced {
                match self.text_raster_rect {
                    Some((pid, px, py, pw, ph, plane_w, plane_h))
                        if pid == id && plane_w == rect.w && plane_h == rect.h =>
                    {
                        Some((px, py, pw, ph))
                    }
                    _ => None,
                }
            } else {
                None
            };
            match prev {
                Some((px, py, pw, ph)) => {
                    for jy in 0..ph as i32 {
                        for jx in 0..pw as i32 {
                            let Some(di) = checked_plane_index(rect, px + jx, py + jy, 4) else {
                                continue;
                            };
                            for k in 0..4 {
                                Arc::make_mut(&mut self.layers[i].pixels)[di + k] = 0;
                            }
                        }
                    }
                }
                None => {
                    for v in Arc::make_mut(&mut self.layers[i].pixels).iter_mut() {
                        *v = 0;
                    }
                }
            }
            for jy in 0..ih as i32 {
                for jx in 0..iw as i32 {
                    let Some(di) = checked_plane_index(rect, x + jx, y + jy, 4) else {
                        continue;
                    };
                    let pi = (jy * iw as i32 + jx) as usize * 4;
                    for k in 0..4 {
                        Arc::make_mut(&mut self.layers[i].pixels)[di + k] = color::u8_to_16(rgba[pi + k]);
                    }
                }
            }
            self.layers[i].kind = 2;
            self.layers[i].text_spec = spec.to_string();
            self.layers[i].text_x = x;
            self.layers[i].text_y = y;
            self.text_raster_rect = Some((id, x, y, iw, ih, rect.w, rect.h));
            if self.depth == 32 {
                match prev {
                    Some((px, py, pw, ph)) => {
                        let x0 = px.min(x).max(0);
                        let y0 = py.min(y).max(0);
                        let x1 = (px + pw as i32).max(x + iw as i32).min(self.w as i32);
                        let y1 = (py + ph as i32).max(y + ih as i32).min(self.h as i32);
                        if x1 > x0 && y1 > y0 {
                            let layer = &mut self.layers[i];
                            let f32buf = Arc::make_mut(&mut layer.pixels_f32);
                            for cy in y0..y1 {
                                for cx in x0..x1 {
                                    let Some(di) = checked_plane_index(rect, cx, cy, 4) else {
                                        continue;
                                    };
                                    for k in 0..4 {
                                        f32buf[di + k] = layer.pixels[di + k] as f32 / 65_535.0;
                                    }
                                }
                            }
                        }
                    }
                    None => {
                        self.layers[i].pixels_f32 = self.layers[i]
                            .pixels
                            .iter()
                            .map(|value| *value as f32 / 65_535.0)
                            .collect();
                    }
                }
            }
            match prev {
                Some((px, py, pw, ph)) => {
                    let x0 = px.min(x).max(0);
                    let y0 = py.min(y).max(0);
                    let x1 = (px + pw as i32).max(x + iw as i32).min(self.w as i32);
                    let y1 = (py + ph as i32).max(y + ih as i32).min(self.h as i32);
                    if x1 > x0 && y1 > y0 {
                        self.composite_region(x0, y0, x1, y1);
                        return vec![x0, y0, x1 - x0, y1 - y0];
                    }
                    return Vec::new();
                }
                None => {
                    self.composite();
                    return Vec::new();
                }
            }
        }
        Vec::new()
    }
    pub fn layer_text_spec(&self, id: u32) -> String {
        self.layer_index(id)
            .map(|i| self.layers[i].text_spec.clone())
            .unwrap_or_default()
    }
    // Mark the start/end of a live on-canvas text edit. While active, the
    // per-keystroke `set_text_layer_spec` re-applies fold into one undo step.
    // Ending the session arms the next session to take a fresh snapshot.
    pub fn text_edit_session(&mut self, active: bool) {
        // Re-arm on close, and on opening a FRESH session — a session that was
        // never closed cleanly must not leak coalescing into the next one.
        // Re-opening an already-active session (create → begin edit) keeps the
        // current coalescing run intact.
        if !active || !self.text_session {
            self.text_pushed = false;
        }
        self.text_session = active;
    }
    // Rasterize Type: drop the live type model, keeping the rendered pixels as a
    // plain raster layer.
    pub fn rasterize_text_layer(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].kind == 2 {
                if self.push_stack_undo("Rasterize Type") {
                    return;
                }
                self.layers[i].kind = 0;
                self.layers[i].text_spec = String::new();
                self.layers[i].text = String::new();
                self.composite();
            }
        }
    }
    // Layer ▸ Smart Objects ▸ Rasterize: bake a smart object into an ordinary
    // pixel layer. Its current (filtered) pixels are kept; the embedded source
    // and filter stack are dropped, so the result is no longer re-editable.
    pub fn rasterize_smart_object(&mut self, id: u32) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].kind != 7 {
                return;
            }
            let has_native_pixels = !self.layers[i].pixels_f32.is_empty();
            if self.push_stack_undo("Rasterize Smart Object") {
                return;
            }
            if !has_native_pixels {
                self.render_smart(i); // make sure pixels reflect the full stack first
            }
            self.layers[i].kind = 0;
            self.layers[i].set_smart_src(Vec::new());
            self.layers[i].smart_src_f32 = Vec::new().into();
            self.layers[i].psd_smart_blocks.clear();
            self.layers[i].smart_link = None;
            self.layers[i].smart_filters.clear();
            self.layers[i].smart_filter_opts.clear();
            self.layers[i].smart_enabled = true;
            self.layers[i].smart_transform = SMART_IDENTITY;
            self.layers[i].smart_transform_ops.clear();
            self.composite();
        }
    }
    // Layer ▸ Smart Objects ▸ Replace Contents: swap the smart object's embedded
    // source with a freshly-decoded image (scaled to fill the document), then
    // re-run the non-destructive smart-filter stack over the new source. No-op
    // on a non-smart layer.
    pub fn replace_smart_object(&mut self, id: u32, bytes: &[u8]) -> Result<(), JsValue> {
        let i = match self.layer_index(id) {
            Some(i) => i,
            None => return Ok(()),
        };
        if self.layers[i].kind != 7 {
            return Ok(());
        }
        let source = self.decoded_smart_source(bytes)?;
        if self.push_stack_undo("Replace Contents") {
            return Err(JsValue::from_str(IMPORTED_PHOTOSHOP_READ_ONLY));
        }
        self.layers[i].set_smart_src(source);
        self.layers[i].smart_src_f32 = Arc::from(Vec::new());
        self.layers[i].pixels_f32 = Arc::from(Vec::new());
        self.layers[i].psd_smart_blocks.clear();
        // The new source is flat; Edit Contents must not reopen the old one.
        self.layers[i].smart_doc.clear();
        self.layers[i].smart_link = None;
        self.render_smart(i);
        if self.depth == 32 {
            Self::promote_layer_to_float(&mut self.layers[i]);
        }
        self.composite();
        Ok(())
    }

    // Edited Smart Object source save: update the raw embedded source, re-run
    // the smart-filter stack, then keep the currently placed layer footprint.
    // This is a transform-aware baseline for baked Vision transforms; Replace
    // Contents intentionally keeps its full-document replacement behavior.
    pub fn replace_smart_object_preserve_placement(
        &mut self,
        id: u32,
        bytes: &[u8],
    ) -> Result<(), JsValue> {
        let i = match self.layer_index(id) {
            Some(i) => i,
            None => return Ok(()),
        };
        if self.layers[i].kind != 7 {
            return Ok(());
        }
        let old_transform = self.layers[i].smart_transform;
        let old_source_bbox = self
            .smart_source_pixels(i)
            .and_then(|px| Engine::alpha_bbox(&px, self.w as i32, self.h as i32));
        let source = self.decoded_smart_source(bytes)?;

        if self.push_stack_undo("Update Smart Object Contents") {
            return Err(JsValue::from_str(IMPORTED_PHOTOSHOP_READ_ONLY));
        }
        self.layers[i].set_smart_src(source);
        self.layers[i].smart_src_f32 = Arc::from(Vec::new());
        self.layers[i].pixels_f32 = Arc::from(Vec::new());
        self.layers[i].psd_smart_blocks.clear();
        self.layers[i].smart_doc.clear();
        self.layers[i].smart_link = None;
        if let (Some(from), Some(to)) = (
            old_source_bbox,
            self.smart_source_pixels(i)
                .and_then(|px| Engine::alpha_bbox(&px, self.w as i32, self.h as i32)),
        ) {
            let retarget = Engine::bbox_remap_transform(from, to);
            self.layers[i].smart_transform =
                Engine::compose_smart_transform(retarget, old_transform);
        }
        self.render_smart(i);
        if self.depth == 32 {
            Self::promote_layer_to_float(&mut self.layers[i]);
        }
        // Instances share the source, so an Update Contents on one lands on all
        // of them — each re-rendered through its own placement and filters.
        self.propagate_smart_source(i);
        self.composite();
        Ok(())
    }

    // Layer ▸ Smart Objects ▸ Export Contents: encode the smart object's RAW
    // embedded source (before its filter stack) as a PNG. Empty on a non-smart
    // layer or one with no stored source.
    pub fn export_smart_object_png(&self, id: u32) -> Result<Vec<u8>, JsValue> {
        let i = match self.layer_index(id) {
            Some(i) => i,
            None => return Ok(Vec::new()),
        };
        let src = &self.layers[i].smart_src;
        if self.layers[i].kind != 7 || src.len() != (self.w * self.h * 4) as usize {
            return Ok(Vec::new());
        }
        // 16-bit source → 8-bit RGBA for the PNG.
        let rgba8: Vec<u8> = src.iter().map(|&v| (v >> 8) as u8).collect();
        let img = image::RgbaImage::from_raw(self.w, self.h, rgba8)
            .ok_or_else(|| JsValue::from_str("buffer size mismatch"))?;
        let mut buf = Cursor::new(Vec::new());
        image::DynamicImage::ImageRgba8(img)
            .write_to(&mut buf, image::ImageFormat::Png)
            .map_err(|e| JsValue::from_str(&format!("encode failed: {e}")))?;
        Ok(buf.into_inner())
    }

    // Layer ▸ Layer Style ▸ Create Layer(s): extract each enabled effect into its
    // own real layer (drop shadow / outer glow below the source; inner shadow /
    // glow / overlays / satin / bevel / stroke above), then clear the source's
    // effects — exactly Photoshop's "Create Layers". Reuses the effect renderer.
    pub fn create_layers_from_style(&mut self, id: u32) {
        let idx = match self.layer_index(id) {
            Some(i) => i,
            None => return,
        };
        if self.layers[idx].effects.is_empty() {
            return;
        }
        // The effect renderer works in CANVAS space, but the alpha it starts from
        // lives on the layer's own PLANE — sample it through the plane rect instead
        // of reading the plane with a canvas index. Off-plane canvas points have no
        // coverage, which is what a transparent pixel meant before planes could
        // differ from the canvas. (#73)
        let Some(rect) = self.plane_rect(idx) else {
            return;
        };
        let (cw, ch) = (self.w as i32, self.h as i32);
        let n = (cw as usize) * (ch as usize);
        let mut a = vec![0f32; n];
        {
            let px = &self.layers[idx].pixels;
            for y in 0..ch {
                for x in 0..cw {
                    if let Some(p) = checked_plane_index(rect, x, y, 4) {
                        a[(y as usize) * (cw as usize) + x as usize] =
                            px[p + 3] as f32 / 65535.0;
                    }
                }
            }
        }
        let library = self.style_pattern_tiles();
        let slots = effects::render_with_contours(
            &self.layers[idx].effects,
            &a,
            self.w as usize,
            self.h as usize,
            effects::Tiles { defined: self.pattern_tile(), library: &library },
            &self.contours,
        );
        if slots.is_empty() {
            return; // all effects disabled → nothing to extract
        }
        if self.push_stack_undo("Create Layers") {
            return;
        }
        let base = self.layers[idx].name.clone();
        let (w, h) = (self.w, self.h);
        let (ox, oy, group) = (
            self.layers[idx].ox,
            self.layers[idx].oy,
            self.layers[idx].group,
        );
        self.layers[idx].effects.clear();
        let mut above = Vec::new();
        let mut below = Vec::new();
        for s in slots {
            if s.below {
                below.push(s);
            } else {
                above.push(s);
            }
        }
        let mut k = 0u32;
        let mut mk = |s: effects::FxSlot, next_id: &mut u32| -> Layer {
            k += 1;
            let mut l = Layer::transparent(*next_id, &format!("{base}'s Effect {k}"), w, h);
            *next_id += 1;
            l.pixels = s.buf.into();
            l.blend = s.blend;
            l.opacity = s.opacity;
            l.ox = ox;
            l.oy = oy;
            l.group = group;
            l
        };
        let mut next_id = self.next_id;
        // Index 0 = bottom of the stack. Below-the-layer effects (drop shadow,
        // outer glow) go to LOWER indices (under the source); above-the-layer
        // effects go to HIGHER indices (over it).
        for s in below {
            let l = mk(s, &mut next_id);
            self.layers.insert(idx, l); // pushes the source up one
        }
        let sidx = self.layer_index(id).unwrap();
        for (j, s) in above.into_iter().enumerate() {
            let l = mk(s, &mut next_id);
            self.layers.insert(sidx + 1 + j, l);
        }
        self.next_id = next_id;
        self.active = self.layer_index(id).unwrap_or(self.active);
        self.fx_cache.clear();
        self.composite();
    }

    // Layer ▸ Rasterize ▸ Layer Style: bake the active layer's effects into its
    // pixels (the styled appearance becomes the layer content; effects cleared).
    // The mask is set aside during the bake so it isn't double-applied.
    pub fn rasterize_layer_style(&mut self, id: u32) {
        let i = match self.layer_index(id) {
            Some(i) => i,
            None => return,
        };
        if self.layers[i].effects.is_empty() {
            return;
        }
        // A group header has no pixel plane of its own, and bake_layer_style
        // isolates the layer — which hides the very members the group's style is
        // drawn around. Baking would therefore write nothing and silently drop a
        // real visual, so refuse loudly instead. (Before group styles rendered
        // at all this was a harmless no-op.)
        if self.layers[i].kind == 6 {
            self.last_edit_error = GROUP_STYLE_RASTERIZE_UNSUPPORTED.into();
            return;
        }
        if self.reject_float_edit_for_layer(i, "Rasterize Layer Style") {
            return;
        }
        if self.push_stack_undo("Rasterize Layer Style") {
            return;
        }
        self.bake_layer_style(i);
        self.composite();
    }

    // Bake layer `i`'s effects into its pixels (no undo, no final composite).
    fn bake_layer_style(&mut self, i: usize) {
        if self.layers[i].effects.is_empty() {
            return;
        }
        // Resolved up front: the composite below hides every other layer and must be
        // undone before any early return, so the plane check cannot live further
        // down. `self.output` is canvas-sized; this layer's pixels are its own plane.
        // (#72)
        let Some(rect) = self.plane_rect(i) else {
            return;
        };
        let id = self.layers[i].id;
        let saved_mask = std::mem::replace(&mut self.layers[i].mask, Arc::from(Vec::new()));
        // Bake the layer's own appearance, not its container's. Keeping an
        // ancestor visible would avoid the empty render but would also bake the
        // group's opacity/mask/effects into this member a second time.
        let saved_group = std::mem::replace(&mut self.layers[i].group, 0);
        let saved_clipping = std::mem::replace(&mut self.layers[i].clipping, false);
        let saved_solo = std::mem::take(&mut self.solo);
        let vis: Vec<bool> = self.layers.iter().map(|l| l.visible).collect();
        for l in self.layers.iter_mut() {
            l.visible = l.id == id;
        }
        self.fx_cache.clear();
        self.composite(); // layer + effects, isolated, no mask
        let out = self.output.clone();
        let (cw, ch) = (self.w as i32, self.h as i32);
        let px = Arc::make_mut(&mut self.layers[i].pixels);
        for y in 0..ch {
            for x in 0..cw {
                // Plane pixels outside the canvas were never composited, so the
                // baked style has nothing to say about them: leave the reserve alone.
                let Some(p) = checked_plane_index(rect, x, y, 4) else {
                    continue;
                };
                let k = ((y as usize) * (cw as usize) + x as usize) * 4;
                for c in 0..4 {
                    px[p + c] = out[k + c] as u16 * 257;
                }
            }
        }
        self.layers[i].effects.clear();
        self.layers[i].mask = saved_mask.into();
        self.layers[i].group = saved_group;
        self.layers[i].clipping = saved_clipping;
        self.solo = saved_solo;
        for (l, v) in self.layers.iter_mut().zip(vis) {
            l.visible = v;
        }
        self.fx_cache.clear();
    }

    // File ▸ Scripts ▸ Flatten All Layer Effects: bake every layer's style.
    pub fn flatten_all_layer_effects(&mut self) {
        let has_group_styles = self
            .layers
            .iter()
            .any(|layer| layer.kind == 6 && !layer.effects.is_empty());
        let ids: Vec<u32> = self
            .layers
            .iter()
            .filter(|layer| layer.kind != 6 && !layer.effects.is_empty())
            .map(|l| l.id)
            .collect();
        if ids.is_empty() {
            if has_group_styles {
                self.last_edit_error = GROUP_STYLE_RASTERIZE_UNSUPPORTED.into();
            }
            return;
        }
        if self.reject_document_float_edit("Flatten All Layer Effects") {
            return;
        }
        if self.push_stack_undo("Flatten All Layer Effects") {
            return;
        }
        for id in ids {
            if let Some(i) = self.layer_index(id) {
                self.bake_layer_style(i);
            }
        }
        self.composite();
        if has_group_styles {
            self.last_edit_error = GROUP_STYLE_RASTERIZE_UNSUPPORTED.into();
        }
    }

    pub fn set_layer_clipping(&mut self, id: u32, clip: bool) {
        if let Some(i) = self.layer_index(id) {
            if self.layers[i].clipping == clip {
                return;
            }
            if self.push_stack_undo("Clipping") {
                return;
            }
            self.layers[i].clipping = clip;
            self.composite();
        }
    }
    pub fn layer_clipping(&self, id: u32) -> bool {
        self.layer_index(id)
            .map(|i| self.layers[i].clipping)
            .unwrap_or(false)
    }

    // Hold one modal preview/compound edit outside the linear undo timeline.
    // A transaction is per Engine (therefore per document); nested begins are
    // refused so the saved redo branch can never be overwritten.
    pub fn begin_history_transaction(&mut self) -> bool {
        if self.history_transaction.is_some() {
            return false;
        }
        self.last_prop_undo = None;
        self.text_pushed = false;
        self.history_transaction = Some(HistoryTransaction {
            undo_depth: self.undo.len(),
            redo: std::mem::take(&mut self.redo),
            redo_before_last_push: std::mem::take(&mut self.redo_before_last_push),
        });
        true
    }

    pub fn history_transaction_active(&self) -> bool {
        self.history_transaction.is_some()
    }

    // Roll every edit made since begin back to the captured document state, but
    // keep the transaction open for the next preview frame. The user's real redo
    // branch remains parked in HistoryTransaction.
    pub fn reset_history_transaction(&mut self) -> bool {
        let Some(undo_depth) = self
            .history_transaction
            .as_ref()
            .map(|transaction| transaction.undo_depth)
        else {
            return false;
        };
        if self.undo.len() < undo_depth {
            return false;
        }
        let changed = self.undo.len() > undo_depth;
        while self.undo.len() > undo_depth {
            if let Some(entry) = self.undo.pop() {
                self.apply_snap(entry.snap);
            }
        }
        self.redo.clear();
        self.redo_before_last_push.clear();
        self.last_prop_undo = None;
        self.text_pushed = false;
        if changed {
            self.composite();
        }
        true
    }

    // Cancel is history-neutral: restore both the document and the exact redo
    // bookkeeping that existed before begin.
    pub fn cancel_history_transaction(&mut self) -> bool {
        if !self.reset_history_transaction() {
            return false;
        }
        let transaction = self.history_transaction.take().unwrap();
        self.redo = transaction.redo;
        self.redo_before_last_push = transaction.redo_before_last_push;
        self.trim_undo_to_history_states();
        true
    }

    // Keep the caller-built final history entry and end the old redo branch. No
    // label is pushed here: compound callers own their one labelled snapshot and
    // must drop any per-operation snapshots first. A no-change commit cancels.
    pub fn commit_history_transaction(&mut self) -> bool {
        let Some(undo_depth) = self
            .history_transaction
            .as_ref()
            .map(|transaction| transaction.undo_depth)
        else {
            return false;
        };
        if self.undo.len() < undo_depth {
            return false;
        }
        if self.undo.len() == undo_depth {
            self.cancel_history_transaction();
            return false;
        }
        self.history_transaction = None;
        self.redo.clear();
        self.redo_before_last_push.clear();
        self.last_prop_undo = None;
        self.text_pushed = false;
        self.trim_undo_to_history_states();
        true
    }

    // Push a single undo snapshot for a multi-edit UI transaction (e.g. opening
    // the Blending Options dialog), and drop it again if the dialog is cancelled
    // — so OK is one undoable step and Cancel leaves history clean.
    pub fn push_history(&mut self, label: &str) {
        if self.push_stack_undo(label) {
            return;
        }
    }
    pub fn drop_last_undo(&mut self) {
        self.last_prop_undo = None;
        self.undo.pop();
        // Undo the redo-clear the matching push performed: dropping a step must
        // leave history exactly as it was, redo branch included. (#83)
        self.redo = std::mem::take(&mut self.redo_before_last_push);
    }
    // End a continuous property edit (slider release), so the next drag of the
    // same property starts a fresh undo step instead of coalescing into this one.
    pub fn end_prop_edit(&mut self) {
        self.last_prop_undo = None;
    }
    pub fn set_layer_name(&mut self, id: u32, name: &str) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            // Layer.name rides inside the stack snapshot, so a rename that
            // pushes nothing is invisible going forward but fully captured
            // going backward — an unrelated Undo then silently reverts it.
            if self.layers[i].name == name {
                return;
            }
            if self.push_stack_undo("Rename Layer") {
                return;
            }
            let i = match self.layer_index(id) {
                Some(i) => i,
                None => return,
            };
            self.layers[i].name = name.to_string();
        }
    }

    /// Rename without pushing history. For compound transactions that own their
    /// surrounding snapshot (bulk Auto-Name), so one user action stays one undo
    /// step instead of N. Same contract as the raw Layer Style setters.
    pub fn set_layer_name_untracked(&mut self, id: u32, name: &str) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            self.layers[i].name = name.to_string();
        }
    }

    pub fn layer_name(&self, id: u32) -> String {
        self.layer_index(id)
            .map(|i| self.layers[i].name.clone())
            .unwrap_or_default()
    }
    pub fn set_layer_offset(&mut self, id: u32, ox: i32, oy: i32) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        if let Some(i) = self.layer_index(id) {
            self.layers[i].ox = ox;
            self.layers[i].oy = oy;
            self.composite();
        }
    }
    /// Current non-destructive layer offset `[ox, oy]` (empty if the id is gone).
    /// Lets the Timeline capture a layer's position into a keyframe.
    pub fn layer_offset(&self, id: u32) -> Vec<i32> {
        match self.layer_index(id) {
            Some(i) => vec![self.layers[i].ox, self.layers[i].oy],
            None => vec![],
        }
    }

    // Live Move-drag fast path: set the layer's offset and recomposite only the
    // union of its previous and new content footprints, then return that dirty
    // rect ([x, y, w, h]) for a region blit. A full `set_layer_offset` would
    // recomposite + reblit the entire canvas every pointer step (≈2 fps on a
    // large doc); scoping to the moved layer's bbox keeps dragging at 60 fps.
    //
    // The layer-local footprint is cached for the duration of one drag (the
    // pixels don't change while dragging); it is recomputed when a different
    // layer is moved and cleared on commit. An effects-bearing layer expands the
    // footprint by its rendered effect extent and freezes the fx cache during
    // the recomposite — the effect render is translation-invariant, so the drag
    // reuses the cached slots at the new offset instead of re-blurring per frame.
    pub fn move_layer_offset(&mut self, id: u32, ox: i32, oy: i32) -> Vec<i32> {
        if self.reject_imported_photoshop_edit() {
            return vec![0, 0, 0, 0];
        }
        let i = match self.layer_index(id) {
            // Lock Position refuses the move while leaving pixels editable,
            // which is the whole point of it being separate from Lock All.
            Some(i) if self.layers[i].lock_position || self.layers[i].locked => {
                self.last_edit_error =
                    "Could not move the layer because its position is locked.".into();
                return vec![0, 0, 0, 0];
            }
            Some(i) => i,
            None => return vec![0, 0, 0, 0],
        };
        let (pox, poy) = (self.layers[i].ox, self.layers[i].oy);
        self.layers[i].ox = ox;
        self.layers[i].oy = oy;
        self.text_raster_rect = None;

        let has_fx = !self.layers[i].effects.is_empty()
            && self.layers[i]
                .effects
                .iter()
                .any(|(_, p)| p.first().copied().unwrap_or(0.0) >= 0.5);
        let w = self.w as i32;
        let h = self.h as i32;

        // Cached layer-local footprint (recompute on layer change). For an fx
        // layer, union the content bbox with the rendered effect extent so the
        // shadow/glow that reaches beyond the pixels is recomposited too.
        let (lx0, ly0, lx1, ly1) = match self.move_bbox {
            Some((cid, a, b, c, d)) if cid == id => (a, b, c, d),
            _ => {
                let mut bb = self.layer_local_bbox(i);
                if has_fx {
                    self.ensure_fx(i); // refresh the cache for the layer's current shape
                    if let Some(r) = self.fx_cache.get(&id) {
                        let f = fx_local_bbox(&r.slots, w, h);
                        if f.2 >= f.0 {
                            bb = (bb.0.min(f.0), bb.1.min(f.1), bb.2.max(f.2), bb.3.max(f.3));
                        }
                    }
                }
                self.move_bbox = Some((id, bb.0, bb.1, bb.2, bb.3));
                bb
            }
        };
        if lx1 < lx0 {
            // No pixel content. A layer can still influence the composite
            // through its mask (adjustment layers, groups) — give those a full
            // recomposite so the drag previews; a truly inert layer repaints
            // nothing.
            if !self.layers[i].mask.is_empty() || self.layers[i].kind == 1 {
                self.composite();
                return vec![0, 0, w, h];
            }
            return vec![0, 0, 0, 0]; // empty layer: nothing to repaint
        }

        // Canvas-space footprints at the old and new offsets (exclusive maxima).
        let ax0 = (lx0 + pox).min(lx0 + ox).max(0);
        let ay0 = (ly0 + poy).min(ly0 + oy).max(0);
        let ax1 = (lx1 + pox).max(lx1 + ox).min(w - 1) + 1;
        let ay1 = (ly1 + poy).max(ly1 + oy).min(h - 1) + 1;
        if ax1 <= ax0 || ay1 <= ay0 {
            return vec![0, 0, 0, 0]; // moved entirely off-canvas
        }
        // Freeze the fx cache for an fx layer: its effect shape is unchanged
        // (only the offset moved), so reuse the cached slots instead of
        // rebuilding coverage + re-blurring inside the recomposite.
        self.fx_frozen = has_fx;
        self.composite_region(ax0, ay0, ax1, ay1);
        self.fx_frozen = false;
        vec![ax0, ay0, ax1 - ax0, ay1 - ay0]
    }
    // ── Layer ▸ Link Layers ────────────────────────────────────────
    // Linked layers share a non-zero `link_group` and move/nudge together.
    fn linked_siblings(&self, id: u32) -> Vec<u32> {
        let g = match self.layer_index(id) {
            Some(i) => self.layers[i].link_group,
            None => return Vec::new(),
        };
        if g == 0 {
            return Vec::new();
        }
        self.layers
            .iter()
            .filter(|l| l.id != id && l.link_group == g)
            .map(|l| l.id)
            .collect()
    }

    // Apply the committed (dx, dy) of layer `i`'s move plus the same shift to all
    // of its linked siblings, in one undo step. Used by both drag-commit and
    // nudge so linking behaves identically however the move was driven.
    fn apply_linked_move(&mut self, id: u32, i: usize, dx: i32, dy: i32) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        let siblings = self.linked_siblings(id);
        if siblings.is_empty() {
            if self.push_move_undo(i) {
                return;
            }
            self.layers[i].ox += dx;
            self.layers[i].oy += dy;
            self.bake_offset(i);
        } else {
            if self.push_stack_undo("Move") {
                return;
            }
            self.layers[i].ox += dx;
            self.layers[i].oy += dy;
            self.bake_offset(i);
            for sid in siblings {
                if let Some(si) = self.layer_index(sid) {
                    self.layers[si].ox += dx;
                    self.layers[si].oy += dy;
                    self.bake_offset(si);
                }
            }
        }
        self.composite();
    }

    // Layer ▸ Link Layers: put the given layers (≥2 valid) into a shared link set
    // so moving any one moves them all. Reuses an existing group among the set if
    // present (merging selections), else allocates a fresh group id.
    pub fn link_layers(&mut self, ids: &[u32]) {
        let valid: Vec<u32> = ids
            .iter()
            .copied()
            .filter(|&id| self.layer_index(id).is_some())
            .collect();
        if valid.len() < 2 {
            return;
        }
        let existing = valid
            .iter()
            .filter_map(|&id| self.layer_index(id))
            .map(|i| self.layers[i].link_group)
            .find(|&g| g != 0);
        let g = existing
            .unwrap_or_else(|| self.layers.iter().map(|l| l.link_group).max().unwrap_or(0) + 1);
        if self.push_stack_undo("Link Layers") {
            return;
        }
        for &id in &valid {
            if let Some(i) = self.layer_index(id) {
                self.layers[i].link_group = g;
            }
        }
    }

    // Layer ▸ Unlink Layers: drop the given layers out of any link set.
    pub fn unlink_layers(&mut self, ids: &[u32]) {
        let any = ids.iter().any(|&id| {
            self.layer_index(id)
                .map(|i| self.layers[i].link_group != 0)
                .unwrap_or(false)
        });
        if !any {
            return;
        }
        if self.push_stack_undo("Unlink Layers") {
            return;
        }
        for &id in ids {
            if let Some(i) = self.layer_index(id) {
                self.layers[i].link_group = 0;
            }
        }
    }

    // Select ▸ … / Layer ▸ Select Linked Layers: every layer in `id`'s link set
    // (just `[id]` when it is unlinked).
    pub fn linked_layers(&self, id: u32) -> Vec<u32> {
        let g = match self.layer_index(id) {
            Some(i) => self.layers[i].link_group,
            None => return Vec::new(),
        };
        if g == 0 {
            return vec![id];
        }
        self.layers
            .iter()
            .filter(|l| l.link_group == g)
            .map(|l| l.id)
            .collect()
    }

    pub fn is_linked(&self, id: u32) -> bool {
        self.layer_index(id)
            .map(|i| self.layers[i].link_group != 0)
            .unwrap_or(false)
    }

    pub fn nudge_layer(&mut self, id: u32, dx: i32, dy: i32) {
        if let Some(i) = self.layer_index(id) {
            self.apply_linked_move(id, i, dx, dy);
        }
    }
    // Move snapshots pixels+mask; smart objects also shift their embedded
    // source, and text layers their spec anchor — neither is carried by LayerPx,
    // so those take a full snapshot.
    fn push_move_undo(&mut self, i: usize) -> bool {
        if self.reject_imported_photoshop_edit() {
            return true;
        }
        if self.layers[i].smart_src.is_empty() && self.layers[i].kind != 2 {
            let snap = Snap::LayerPx {
                id: self.layers[i].id,
                pixel_bounds: self.layers[i].pixel_bounds,
                px: self.layers[i].pixels.clone(),
                px_f32: self.layers[i].pixels_f32.clone(),
                smart_src_f32: self.layers[i].smart_src_f32.clone(),
                mask: self.layers[i].mask.clone(),
                psd_mask: self.layers[i].psd_mask.clone(),
                vector_scene: self.layers[i].vector_scene.clone(),
            };
            self.push_undo(snap, "Move")
        } else {
            self.push_stack_undo("Move")
        }
    }
    // Bake an offset into the layer, resetting ox/oy. Pixel layers shift their
    // buffers; smart objects update inverse placement metadata so later smart
    // filter rerenders keep the move without moving the embedded source.
    // Mask cells exposed by the shift fill with 0, matching the live preview
    // (out-of-bounds mask = 0).
    // ── Source-aware geometry (#512) ───────────────────────────────
    // A kind-3 (vector) layer's `pixels` are a cache of `vector_scene`, and a
    // kind-2 (text) layer's are a cache of `text_spec`. Moving only the cache
    // loses the edit on the next re-render (vector cache miss, host re-raster,
    // save/reopen), so every geometry helper routes through here to move the
    // SOURCE too.

    /// The layer's world→canvas view as a vector matrix (mirrors
    /// `vector_view_transform`).
    fn vector_view_matrix(&self, view: [f32; 4]) -> crate::vector::model::Matrix {
        let t = self.vector_view_transform(view);
        crate::vector::model::Matrix {
            a: t.sx,
            b: t.ky,
            c: t.kx,
            d: t.sy,
            e: t.tx,
            f: t.ty,
        }
    }

    /// Shift/scale a text layer's anchor (`text_x`/`text_y`, `text_size` and the
    /// spec's `ax`/`ay`/`size`/`path`) by a canvas-space affine `m`. The caller
    /// moves the cached pixels separately.
    fn move_text_anchor(&mut self, i: usize, m: crate::vector::model::Matrix) {
        use crate::vector::geom;
        let p = geom::apply_point(
            m,
            crate::vector::model::Point {
                x: self.layers[i].text_x as f32,
                y: self.layers[i].text_y as f32,
            },
        );
        self.layers[i].text_x = p.x.round() as i32;
        self.layers[i].text_y = p.y.round() as i32;
        self.layers[i].text_size *= geom::mean_scale(m);
        if !self.layers[i].text_spec.is_empty() {
            if let Some(spec) = transform_text_spec_anchor(&self.layers[i].text_spec, m) {
                self.layers[i].text_spec = spec;
            }
        }
    }

    /// Apply a canvas-space affine `m` to a layer's SOURCE data. A vector scene
    /// is transformed in world space (conjugated by the layer's view); a text
    /// anchor moves in canvas space, and a text layer under a rotation or
    /// reflection is rasterized (its spec cannot express the turn). Returns true
    /// when the source changed.
    fn transform_layer_source(&mut self, i: usize, m: crate::vector::model::Matrix) -> bool {
        use crate::vector::geom;
        match self.layers[i].kind {
            3 => {
                let view = self.vector_view_matrix(self.layers[i].vector_view);
                let Some(inv) = geom::m_invert(view) else {
                    return false;
                };
                let world = geom::m_mul(inv, geom::m_mul(m, view));
                let Some(doc) = self.layers[i].vector_scene.as_deref_mut() else {
                    return false;
                };
                for layer in &mut doc.layers {
                    for item in &mut layer.items {
                        item.transform = geom::m_mul(world, item.transform);
                    }
                }
                self.layers[i].vector_cache_key = None;
                self.render_vector(i);
                true
            }
            2 => {
                let det = m.a * m.d - m.b * m.c;
                if m.b != 0.0 || m.c != 0.0 || det < 0.0 {
                    // Rotation/reflection: the spec has no rotation, so bake the
                    // rendered pixels and drop the live model (one undo step).
                    self.layers[i].kind = 0;
                    self.layers[i].text_spec.clear();
                    self.layers[i].text.clear();
                    return true;
                }
                self.move_text_anchor(i, m);
                true
            }
            _ => false,
        }
    }

    /// Transform every vector/text layer's SOURCE by a canvas-space affine `m`.
    /// The document resample/reframe/remap paths change the canvas under the
    /// layers; call this AFTER the new w/h are adopted so a vector re-render
    /// uses the new resolution.
    fn transform_document_sources(&mut self, m: crate::vector::model::Matrix) {
        for i in 0..self.layers.len() {
            if matches!(self.layers[i].kind, 2 | 3) {
                self.transform_layer_source(i, m);
            }
        }
    }

    fn bake_offset(&mut self, i: usize) {
        let (ox, oy) = (self.layers[i].ox, self.layers[i].oy);
        if ox == 0 && oy == 0 {
            return;
        }
        let w = self.w as i32;
        let h = self.h as i32;
        let map = move |nx: i32, ny: i32| (nx - ox, ny - oy);
        if self.layers[i].kind == 0 {
            let Some(bounds) = checked_translate_bounds(self.layers[i].pixel_bounds, ox, oy) else {
                return;
            };
            let layer = &mut self.layers[i];
            layer.pixel_bounds = bounds;
            if !layer.mask.is_empty() && layer.mask_linked {
                layer.mask = Engine::remap_buf(&layer.mask, 1, 0u8, w, h, w, h, move |nx, ny| {
                    (
                        nx.checked_sub(ox).unwrap_or(i32::MIN),
                        ny.checked_sub(oy).unwrap_or(i32::MIN),
                    )
                }).into();
                layer.psd_mask = None;
            }
            layer.ox = 0;
            layer.oy = 0;
        } else if self.layers[i].kind == 7 && !self.layers[i].smart_src.is_empty() {
            let moved = Engine::translation_inverse_transform(ox, oy);
            self.append_smart_matrix(i, moved);
            if !self.layers[i].mask.is_empty() && self.layers[i].mask_linked {
                self.layers[i].mask = Engine::remap_buf(&self.layers[i].mask, 1, 0u8, w, h, w, h, map).into();
                self.layers[i].psd_mask = None;
            }
            self.layers[i].ox = 0;
            self.layers[i].oy = 0;
            if self.layers[i].pixels_f32.is_empty() {
                self.render_smart(i);
            } else {
                self.layers[i].pixels_f32 = Engine::remap_buf(&self.layers[i].pixels_f32, 4, 0.0f32, w, h, w, h, map).into();
                self.layers[i].pixels = self.layers[i]
                    .pixels_f32
                    .iter()
                    .map(|value| float_preview_u16(*value))
                    .collect();
            }
        } else if self.layers[i].kind == 3 {
            // Vector: move the SCENE, not just the cached pixels, or the next
            // re-render snaps the layer back (#512).
            let m = crate::vector::geom::m_translation(ox as f32, oy as f32);
            self.transform_layer_source(i, m);
            if !self.layers[i].mask.is_empty() && self.layers[i].mask_linked {
                self.layers[i].mask = Engine::remap_buf(&self.layers[i].mask, 1, 0u8, w, h, w, h, map).into();
                self.layers[i].psd_mask = None;
            }
            self.layers[i].ox = 0;
            self.layers[i].oy = 0;
        } else {
            let layer = &mut self.layers[i];
            layer.pixels = Engine::remap_buf(&layer.pixels, 4, 0u16, w, h, w, h, map).into();
            if !layer.pixels_f32.is_empty() {
                layer.pixels_f32 = Engine::remap_buf(&layer.pixels_f32, 4, 0.0f32, w, h, w, h, map).into();
            }
            // A linked mask moves with the layer; an unlinked one stays put.
            if !layer.mask.is_empty() && layer.mask_linked {
                layer.mask = Engine::remap_buf(&layer.mask, 1, 0u8, w, h, w, h, map).into();
                layer.psd_mask = None;
            }
            layer.ox = 0;
            layer.oy = 0;
        }
        // Text: the cached pixels moved above; move the spec anchor too so a
        // host re-render keeps the move (#512).
        if self.layers[i].kind == 2 {
            self.move_text_anchor(i, crate::vector::geom::m_translation(ox as f32, oy as f32));
        }
    }
    // Commit the active layer's live offset (called when the Move tool releases).
    pub fn commit_offset(&mut self, id: u32) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        self.move_bbox = None; // end of drag — drop the cached footprint
        if let Some(i) = self.layer_index(id) {
            let (dx, dy) = (self.layers[i].ox, self.layers[i].oy);
            if dx == 0 && dy == 0 {
                return;
            }
            // The live drag already set this layer's offset; clear it so
            // apply_linked_move re-adds the delta uniformly across the link set
            // (siblings start at 0 and follow on release).
            self.layers[i].ox = 0;
            self.layers[i].oy = 0;
            self.apply_linked_move(id, i, dx, dy);
            // Landing inside/outside an artboard re-homes the layer. Its own
            // undo step — the bare move may be a pixels-only snapshot that
            // cannot restore grouping/stack order.
            self.auto_adopt_artboard(id);
        }
    }

    // Move the active layer's SELECTED pixels by (dx, dy) — Photoshop's Move tool
    // with an active selection "floats" the selection: the selected content
    // relocates, the marquee moves with it, and the vacated area becomes a hole —
    // transparent on a normal layer, filled with the background colour on a locked
    // Background layer. (With no selection the caller moves the whole layer.)
    pub fn move_selection(&mut self, dx: i32, dy: i32, bg_r: u8, bg_g: u8, bg_b: u8) {
        if !self.sel.active || (dx == 0 && dy == 0) {
            return;
        }
        if self.reject_legacy_float_edit("Move Selection") {
            return;
        }
        let w = self.w as i32;
        let h = self.h as i32;
        let n = (w * h) as usize;
        if !self.sel.mask.iter().any(|&v| v > 0) {
            return; // empty selection — don't burn an undo step
        }
        let Some(rect) = self.plane_rect(self.active) else {
            return;
        };
        let Some(local) = self.plane_local_selection() else {
            return;
        };
        // Full-doc snapshot so undo restores both the moved pixels and the marquee.
        if self.push_stack_undo("Move Selection") {
            return;
        }
        let a = self.active;
        let locked = self.layers[a].locked;
        let src = self.layers[a].pixels.clone();
        let mask = self.sel.mask.clone();

        // 1. Vacate the source: transparent (normal) or bg-filled (locked), per
        //    selection coverage so a soft (anti-aliased) edge leaves a soft hole.
        let bg = Rgba::new(
            bg_r as f32 / 255.0,
            bg_g as f32 / 255.0,
            bg_b as f32 / 255.0,
            1.0,
        );
        for i in 0..self.layers[a].pixels.len() / 4 {
            let cov = local.coverage(i);
            if cov <= 0.0 {
                continue;
            }
            let p = i * 4;
            let base = Rgba::from_u16(&self.layers[a].pixels[p..p + 4]);
            let hole = if locked {
                bg
            } else {
                Rgba::new(base.r, base.g, base.b, 0.0)
            };
            let res = Rgba::new(
                base.r + (hole.r - base.r) * cov,
                base.g + (hole.g - base.g) * cov,
                base.b + (hole.b - base.b) * cov,
                base.a + (hole.a - base.a) * cov,
            );
            res.to_u16(&mut Arc::make_mut(&mut self.layers[a].pixels)[p..p + 4]);
        }

        // 2. Stamp the snapshot over the destination, offset by (dx, dy).
        for y in 0..h {
            for x in 0..w {
                let si = (y * w + x) as usize;
                let cov = mask[si] as f32 / 255.0;
                if cov <= 0.0 {
                    continue;
                }
                let (nx, ny) = (x + dx, y + dy);
                if nx < 0 || ny < 0 || nx >= w || ny >= h {
                    continue;
                }
                let (Some(sp), Some(dp)) = (
                    checked_plane_index(rect, x, y, 4),
                    checked_plane_index(rect, nx, ny, 4),
                ) else {
                    continue;
                };
                let s = Rgba::from_u16(&src[sp..sp + 4]);
                let src_px = Rgba::new(s.r, s.g, s.b, s.a * cov);
                let base = Rgba::from_u16(&self.layers[a].pixels[dp..dp + 4]);
                let res = composite_over(base, src_px, BlendMode::Normal, 1.0);
                res.to_u16(&mut Arc::make_mut(&mut self.layers[a].pixels)[dp..dp + 4]);
            }
        }

        // 3. Move the marquee with the content.
        let mut nm = vec![0u8; n];
        for y in 0..h {
            for x in 0..w {
                let si = (y * w + x) as usize;
                if mask[si] == 0 {
                    continue;
                }
                let (nx, ny) = (x + dx, y + dy);
                if nx >= 0 && ny >= 0 && nx < w && ny < h {
                    nm[(ny * w + nx) as usize] = mask[si];
                }
            }
        }
        self.sel.mask = nm;

        self.composite();
        self.sel_dirty();
    }

    // Produce a downscaled RGBA thumbnail of a layer (tw*th*4).
    pub fn layer_thumb(&self, id: u32, tw: u32, th: u32) -> Vec<u8> {
        let mut out = vec![0u8; (tw * th * 4) as usize];
        if let Some(idx) = self.layer_index(id) {
            let layer = &self.layers[idx];
            let (w, h) = (self.w, self.h);
            for ty in 0..th {
                for tx in 0..tw {
                    let sx = (tx * w / tw).min(w - 1);
                    let sy = (ty * h / th).min(h - 1);
                    let di = (ty * tw + tx) as usize * 4;
                    Engine::sample_layer(layer, sx as i32, sy as i32, w as i32, h as i32)
                        .to_u8(&mut out[di..di + 4]);
                }
            }
        }
        out
    }

    // ── Brush engine ───────────────────────────────────────────
    pub fn set_brush(
        &mut self,
        size: f32,
        hardness: f32,
        flow: f32,
        opacity: f32,
        spacing: f32,
        r: u8,
        g: u8,
        b: u8,
        a: u8,
        erase: bool,
    ) {
        self.brush.size = size.max(1.0);
        self.brush.hardness = hardness.clamp(0.0, 1.0);
        self.brush.flow = flow.clamp(0.0, 1.0);
        self.brush.opacity = opacity.clamp(0.0, 1.0);
        self.brush.spacing = spacing.clamp(0.01, 2.0);
        self.brush.color = [r, g, b, a];
        self.brush.erase = erase;
        self.brush.mode = if erase { 1 } else { 0 };
    }
    // Eraser ▸ Block mode: paint/erase the dab as a hard, aliased SQUARE at the
    // brush size instead of the round falloff. ponytail: brush-sized square, not
    // Photoshop's fixed ~16px screen-space block.
    pub fn set_block(&mut self, block: bool) {
        self.brush.block = block;
    }
    pub fn set_brush_dynamics(&mut self, size_pressure: bool, flow_pressure: bool) {
        self.brush.size_pressure = size_pressure;
        self.brush.flow_pressure = flow_pressure;
    }
    // Brush Tip Shape (Photoshop): `angle_deg` rotates the tip; `roundness` 0..1
    // squashes the round disc into an ellipse (1 = round). Applies to the
    // procedural round brush footprint across the brush-based tools.
    pub fn set_brush_shape(&mut self, angle_deg: f32, roundness: f32) {
        self.brush.angle = angle_deg.to_radians();
        self.brush.roundness = roundness.clamp(0.05, 1.0);
    }
    // Brush Settings ▸ Transfer (Photoshop): randomize each dab's opacity and
    // flow. `*_jitter` 0..1 is how far below the set value a dab may fall;
    // `min_*` 0..1 floors that multiplier. All zero = constant per stroke.
    pub fn set_brush_transfer(
        &mut self,
        opacity_jitter: f32,
        min_opacity: f32,
        flow_jitter: f32,
        min_flow: f32,
    ) {
        self.brush.opacity_jitter = opacity_jitter.clamp(0.0, 1.0);
        self.brush.min_opacity = min_opacity.clamp(0.0, 1.0);
        self.brush.flow_jitter = flow_jitter.clamp(0.0, 1.0);
        self.brush.min_flow = min_flow.clamp(0.0, 1.0);
    }
    /// Brush Settings ▸ Scattering. `scatter` 0..1 is Photoshop's percentage as a
    /// fraction of the dab size (1000% there ≈ 1.0 here scaled by 10 in the UI);
    /// `count` is dabs per step (1 = the plain stroke), jittered downward by
    /// `count_jitter`.
    pub fn set_brush_scatter(
        &mut self,
        scatter: f32,
        both_axes: bool,
        count: u32,
        count_jitter: f32,
    ) {
        self.brush.scatter = scatter.max(0.0).min(10.0);
        self.brush.scatter_both_axes = both_axes;
        self.brush.scatter_count = count.clamp(1, 16);
        self.brush.scatter_count_jitter = count_jitter.clamp(0.0, 1.0);
    }

    /// Brush Settings ▸ Shape Dynamics. Jitters are 0..1 (0 = off); the minimums
    /// floor what the jitter — and the pressure ramp — may shrink a dab to.
    pub fn set_brush_shape_dynamics(
        &mut self,
        size_jitter: f32,
        min_diameter: f32,
        angle_jitter: f32,
        roundness_jitter: f32,
        min_roundness: f32,
    ) {
        self.brush.size_jitter = size_jitter.clamp(0.0, 1.0);
        self.brush.min_diameter = min_diameter.clamp(0.0, 1.0);
        self.brush.angle_jitter = angle_jitter.clamp(0.0, 1.0);
        self.brush.roundness_jitter = roundness_jitter.clamp(0.0, 1.0);
        self.brush.min_roundness = min_roundness.clamp(0.0, 1.0);
    }

    // Override the brush mode: 0 paint · 1 erase · 2 dodge · 3 burn · 4 smudge ·
    // 5 heal · 6 colorreplace · 7 background_eraser · 8 sponge · 9 blur ·
    // 10 sharpen · 11 mixer.
    pub fn set_brush_mode(&mut self, mode: u8) {
        self.brush.mode = mode;
        self.brush.erase = mode == 1;
    }
    // Brush Mode (Photoshop's blend dropdown): how each paint dab composites onto
    // the layer. `mode` is a BlendMode index (0 = Normal). Applies to the paint /
    // pencil path only; Heal, History Brush and Eraser keep their own compositing.
    pub fn set_brush_blend(&mut self, mode: u8) {
        self.brush.blend = BlendMode::from_u8(mode);
    }
    // Brush Mode special composites that aren't layer blends: 0 = use the blend,
    // 1 = Behind (paint only the transparent parts), 2 = Clear (erase by coverage).
    // Paint / pencil path only.
    pub fn set_brush_paint_mode(&mut self, kind: u8) {
        self.brush.behind = kind == 1;
        self.brush.clear = kind == 2;
    }
    // Color Replacement Mode: 0 Hue, 1 Saturation, 2 Color (default), 3 Luminosity —
    // mapped to the matching non-separable blend (Hue 21 … Luminosity 24).
    pub fn set_color_replace_mode(&mut self, m: u8) {
        self.color_replace_blend = BlendMode::from_u8(21 + m.min(3));
    }

    // Dodge/Burn tool options. `range`: 0 shadows, 1 midtones, 2 highlights;
    // `exposure`: 0..1 strength; `protect`: preserve hue/saturation & avoid
    // clipping. Mirrors Photoshop's Dodge/Burn options bar.
    pub fn set_dodge_options(&mut self, range: u8, exposure: f32, protect: bool) {
        self.dodge_range = range.min(2);
        self.dodge_exposure = exposure.clamp(0.0, 1.0);
        self.protect_tones = protect;
    }

    // Sponge (brush mode 8): `mode` 0 saturate / 1 desaturate; `rate` 0..1
    // strength; `vibrance` protects pixels already near the target extreme
    // (Photoshop's Vibrance option, default on — minimises clipping).
    pub fn set_sponge_options(&mut self, mode: u8, rate: f32, vibrance: bool) {
        self.sponge_mode = mode.min(1);
        self.sponge_rate = rate.clamp(0.0, 1.0);
        self.sponge_vibrance = vibrance;
    }
    // Blur (brush mode 9): `rate` 0..1 strength per dab.
    pub fn set_blur_options(&mut self, rate: f32) {
        self.blur_rate = rate.clamp(0.0, 1.0);
    }
    // Sharpen (brush mode 10): `rate` 0..1 strength; `protect` limits boost in shadows.
    pub fn set_sharpen_options(&mut self, rate: f32, protect: bool) {
        self.sharpen_rate = rate.clamp(0.0, 1.0);
        self.sharpen_protect = protect;
    }
    // Background Eraser (brush mode 7): colour-match `tolerance` 0..1 + Protect Foreground.
    pub fn set_background_eraser_options(&mut self, tolerance: f32, protect_fg: bool) {
        self.bg_tolerance = tolerance.clamp(0.0, 1.0);
        self.bg_protect_fg = protect_fg;
    }
    // Background Eraser ▸ Sampling (0 Continuous / 1 Once / 2 Background Swatch)
    // and Limits (0 Discontiguous / 1 Contiguous / 2 Find Edges); see the fields.
    pub fn set_background_eraser_sampling(&mut self, sampling: u8, limits: u8) {
        self.bg_sampling = sampling.min(2);
        self.bg_limits = limits.min(2);
    }
    // Sample All Layers for Smudge / Blur / Sharpen / Mixer: the dab reads the
    // merged image beneath the brush instead of the active layer alone.
    pub fn set_retouch_sample_all(&mut self, on: bool) {
        self.retouch_sample_all = on;
    }
    // Mixer Brush ▸ Load the brush after each stroke / Clean the brush after each stroke.
    pub fn set_mixer_auto(&mut self, load: bool, clean: bool) {
        self.mixer_auto_load = load;
        self.mixer_auto_clean = clean;
    }

    // Smudge (brush mode 4) ▸ Finger Painting: seed each stroke's carried colour
    // from the foreground colour instead of the canvas under the stamp center.
    pub fn set_smudge_finger(&mut self, finger: bool) {
        self.smudge_finger = finger;
    }

    // Mixer Brush (brush mode 11) options. `wet` 0..1 — how much canvas colour the
    // reservoir picks up per dab (the smear rate); `load` 0..1 — how much foreground
    // paint the reservoir starts with vs the canvas at stroke start; `mix` 0..1 —
    // fraction of reservoir paint vs sampled canvas in each deposit (high mix →
    // reservoir dominates). Mirrors Photoshop's Mixer Brush options bar.
    pub fn set_mixer_params(&mut self, wet: f32, load: f32, mix: f32) {
        self.mixer_wet = wet.clamp(0.0, 1.0);
        self.mixer_load = load.clamp(0.0, 1.0);
        self.mixer_mix = mix.clamp(0.0, 1.0);
    }

    // Enable clone-stamp sampling: each dab samples the (composited) image at the
    // stamp position offset by (dx, dy) instead of using the brush color.
    pub fn set_clone(&mut self, enabled: bool, dx: i32, dy: i32) {
        self.clone_enabled = enabled;
        self.clone_dx = dx;
        self.clone_dy = dy;
        self.clone_persp = false;
        self.clone_affine = None;
        self.clone_du = 0.0;
        self.clone_dv = 0.0;
    }

    // Vanishing Point clone sampling: map destination pixels through a perspective
    // plane, offset in plane space from the destination anchor to the source
    // anchor, then project back to canvas coordinates before sampling clone_src.
    #[allow(clippy::too_many_arguments)]
    pub fn set_clone_perspective(
        &mut self,
        enabled: bool,
        x0: f32,
        y0: f32,
        x1: f32,
        y1: f32,
        x2: f32,
        y2: f32,
        x3: f32,
        y3: f32,
        src_x: f32,
        src_y: f32,
        dst_x: f32,
        dst_y: f32,
    ) -> bool {
        self.clone_affine = None;
        if !enabled {
            self.clone_persp = false;
            self.clone_enabled = false;
            self.clone_du = 0.0;
            self.clone_dv = 0.0;
            return true;
        }
        let (h, ok) = square_to_quad(x0, y0, x1, y1, x2, y2, x3, y3);
        if !ok {
            self.clone_persp = false;
            return false;
        }
        let inv = mat3_inv(h);
        let Some((su, sv)) = mat3_project(inv, src_x, src_y) else {
            self.clone_persp = false;
            return false;
        };
        let Some((du, dv)) = mat3_project(inv, dst_x, dst_y) else {
            self.clone_persp = false;
            return false;
        };
        if !su.is_finite() || !sv.is_finite() || !du.is_finite() || !dv.is_finite() {
            self.clone_persp = false;
            return false;
        }
        self.clone_enabled = true;
        self.clone_persp = true;
        self.clone_h = h;
        self.clone_h_inv = inv;
        self.clone_du = su - du;
        self.clone_dv = sv - dv;
        self.clone_dx = 0;
        self.clone_dy = 0;
        true
    }

    // Clone Source panel (#427): sample through the source slot's transform.
    // The source point (src_x, src_y) lands on the destination anchor, and the
    // source is scaled by W/H percent, flipped, then rotated by `angle_deg`
    // about it — so each dest pixel reads s = S + M·(d − D), M = (R·diag)⁻¹.
    // Invalid input refuses and leaves the current clone state untouched.
    #[allow(clippy::too_many_arguments)]
    pub fn set_clone_transform(
        &mut self,
        src_x: f32,
        src_y: f32,
        dst_x: f32,
        dst_y: f32,
        w_pct: f32,
        h_pct: f32,
        angle_deg: f32,
        flip_h: bool,
        flip_v: bool,
    ) -> bool {
        let finite = [src_x, src_y, dst_x, dst_y, angle_deg].iter().all(|v| v.is_finite());
        if !finite || !(1.0..=1000.0).contains(&w_pct) || !(1.0..=1000.0).contains(&h_pct) {
            return false;
        }
        let (sin, cos) = angle_deg.to_radians().sin_cos();
        let kx = if flip_h { -100.0 } else { 100.0 } / w_pct;
        let ky = if flip_v { -100.0 } else { 100.0 } / h_pct;
        let (a, b, c, d) = (kx * cos, kx * sin, -ky * sin, ky * cos);
        self.clone_affine = Some([
            a,
            b,
            c,
            d,
            src_x - (a * dst_x + b * dst_y),
            src_y - (c * dst_x + d * dst_y),
        ]);
        self.clone_enabled = true;
        self.clone_persp = false;
        self.clone_dx = 0;
        self.clone_dy = 0;
        true
    }

    // Clone Source panel: a slot's source can live in another open document.
    // The frontend pushes that document's source pixels here, and the next
    // stroke_begin samples them instead of capturing this engine — for that one
    // stroke only (stroke_begin consumes the flag even when it refuses).
    pub fn set_clone_source(&mut self, w: u32, h: u32, px: &[u8]) -> bool {
        let len = (w as usize).checked_mul(h as usize).and_then(|n| n.checked_mul(4));
        if w == 0 || h == 0 || len != Some(px.len()) {
            return false;
        }
        self.clone_src = px.to_vec();
        self.clone_src_w = w as i32;
        self.clone_src_h = h as i32;
        self.clone_external = true;
        true
    }

    // The RGBA8 clone source this engine would capture under the current Sample
    // mode — what another document's stroke and the overlay sample. A live
    // stroke's own source is swapped back, so this is safe mid-stroke.
    pub fn clone_source_rgba8(&mut self) -> Vec<u8> {
        let saved = std::mem::take(&mut self.clone_src);
        let (sw, sh) = (self.clone_src_w, self.clone_src_h);
        self.capture_clone_src();
        (self.clone_src_w, self.clone_src_h) = (sw, sh);
        std::mem::replace(&mut self.clone_src, saved)
    }

    // Clone Stamp / Healing Brush "Sample": 0 current layer, 1 current & below,
    // 2 all layers. Picks which layers the clone/heal source is captured from.
    pub fn set_clone_sample(&mut self, mode: u8) {
        self.clone_sample = mode;
    }

    // Capture the clone/heal source buffer (RGBA8) per the Sample mode.
    /// The 8-bit canvas-space composite of the layers below index `from`, made by
    /// transiently hiding `from..` and recompositing (the live composite is restored
    /// before returning). `from == active` is "everything beneath the active layer".
    fn composite_hiding_from(&mut self, from: usize) -> Vec<u8> {
        let hidden: Vec<usize> = (from..self.layers.len())
            .filter(|&i| self.layers[i].visible)
            .collect();
        for &i in &hidden {
            self.layers[i].visible = false;
        }
        self.composite();
        let out = self.output.clone();
        for &i in &hidden {
            self.layers[i].visible = true;
        }
        self.composite();
        out
    }

    fn capture_clone_src(&mut self) {
        (self.clone_src_w, self.clone_src_h) = (self.w as i32, self.h as i32);
        match self.clone_sample {
            0 => {
                // Clone sampling is canvas-space, so lift the active plane first.
                self.clone_src = self.selection_sample_buffer(false).unwrap_or_default();
            }
            1 => {
                // Current & Below: the active layer + everything beneath it.
                self.clone_src = self.composite_hiding_from(self.active + 1);
            }
            _ => {
                // All Layers: the full composite.
                self.composite();
                self.clone_src = self.output.clone();
            }
        }
    }

    // Healing Brush ▸ Diffusion (Photoshop 1..7): how quickly the healed patch
    // adapts to its surroundings. Low keeps the transplanted grain/detail right
    // out to the rim; high ramps it in gradually, which is what smooth areas
    // (skin, sky) want. Clamped, so an out-of-range value can't kill a stroke.
    pub fn set_heal_diffusion(&mut self, diffusion: u8) {
        self.heal_diffusion = diffusion.clamp(1, 7);
    }

    // Pattern Stamp tool: when on, a clone stroke samples the currently defined
    // pattern (tiled, canvas-aligned) instead of a captured canvas region. The
    // Healing Brush's "Source: Pattern" rides the same flag — the dab then heals
    // the pattern tile into place through the boundary solve.
    pub fn set_pattern_stamp(&mut self, on: bool) {
        self.pattern_stamp = on;
        if on {
            self.clone_persp = false;
        }
    }

    // Pattern Stamp ▸ Aligned: the tiling origin. Aligned (Photoshop default) tiles
    // to the canvas origin (0,0) across every stroke; Aligned off re-anchors the
    // pattern to each stroke's start point, which the frontend passes here.
    pub fn set_pattern_anchor(&mut self, ax: i32, ay: i32) {
        self.pattern_ox = ax;
        self.pattern_oy = ay;
    }

    // Fill the clone source with the defined pattern tiled across the whole canvas,
    // so the existing clone dab stamps the pattern. The tiling origin is (pattern_ox,
    // pattern_oy): (0,0) canvas-aligned by default, or the stroke start when Aligned
    // is off (Pattern Stamp re-anchors each stroke).
    fn fill_clone_from_pattern(&mut self) {
        // Defensive guard only: stroke_begin already early-returns when Pattern Stamp
        // is active with no pattern, so this is never reached in the normal stroke flow
        // — but it keeps the rem_euclid(pw/ph) tiling below panic-free if called directly.
        if self.pattern.is_empty() {
            self.clone_enabled = false;
            return;
        }
        let (w, h) = (self.w as i32, self.h as i32);
        let (pw, ph) = (self.pattern_w as i32, self.pattern_h as i32);
        let (ox, oy) = (self.pattern_ox, self.pattern_oy);
        let mut src = vec![0u8; (w * h * 4) as usize];
        for y in 0..h {
            for x in 0..w {
                let pi = ((y - oy).rem_euclid(ph) * pw + (x - ox).rem_euclid(pw)) as usize * 4;
                let o = (y * w + x) as usize * 4;
                for k in 0..4 {
                    src[o + k] = (self.pattern[pi + k] >> 8) as u8;
                }
            }
        }
        self.clone_src = src;
        (self.clone_src_w, self.clone_src_h) = (w, h);
        self.clone_dx = 0;
        self.clone_dy = 0;
    }

    // Direct the brush to paint into the active layer's mask instead of pixels.
    pub fn set_mask_edit(&mut self, on: bool) {
        self.mask_edit = on;
    }

    // Single definition of "this stroke writes the Smart Filter mask", shared by
    // stroke_begin, the dab loop and stroke_end.
    // A float-authority layer is excluded: the stroke would land, but the
    // re-render that makes it visible cannot touch a 32-bit layer.
    fn painting_filter_mask(&self) -> bool {
        self.filter_mask_edit
            && !self.layers[self.active].smart_mask.is_empty()
            && !(self.depth == 32 && Self::layer_has_float_authority(&self.layers[self.active]))
    }

    /// Whether a stroke writes into the layer's MASK rather than its pixels.
    ///
    /// `stroke_begin` and `stamp` used to derive this separately and DISAGREED:
    /// stroke_begin counted an adjustment/fill layer as mask painting, stamp did
    /// not. So stroke_begin took the masking branch and never populated
    /// `stroke_base`, and stamp then took the pixel branch and indexed that
    /// empty buffer — a panic mid-`&mut self`. Under wasm that never releases
    /// wasm-bindgen's borrow flag, so every later engine call throws and the
    /// unsaved document cannot even be saved. Both sites now ask this.
    fn painting_mask(&self) -> bool {
        let l = &self.layers[self.active];
        self.painting_filter_mask()
            || ((self.mask_edit || l.kind == 1 || l.kind == 4) && !l.mask.is_empty())
    }

    pub fn stroke_begin(&mut self) -> bool {
        // Every stroke's dynamics start from the same seed: dabs vary along the
        // stroke, but the same gesture always paints the same thing.
        self.stroke_rng = STROKE_RNG_SEED;
        // A pushed clone source is good for this stroke only, begun or refused.
        let external_clone = std::mem::take(&mut self.clone_external);
        if self.reject_imported_photoshop_edit() {
            return false;
        }
        // Quick Mask painting edits the dedicated `quick_mask` buffer directly,
        // bypassing the layer-mask / lock / smart-object gating below (the buffer
        // isn't a layer). In-mode undo is deferred — the round-trip Sel undo is
        // pushed by exit_quick_mask. The base buffer rides in `stroke_base_mask`
        // (cleared by stroke_end), mirroring the layer-mask paint path.
        if self.qm_on {
            if self.quick_mask.len() != (self.w * self.h) as usize {
                self.quick_mask = vec![255u8; (self.w * self.h) as usize];
            }
            self.smudge_init = false;
            self.bg_eraser_init = false;
            self.mixer_init = false;
            self.stroke_base_mask = self.quick_mask.clone();
            self.begin_stroke_acc();
            self.stroking = true;
            self.have_last = false;
            return true;
        }
        // Painting an adjustment layer targets its MASK (Photoshop's default
        // channel for adjustment layers); pixel painting is gated on lock and
        // smart objects (Photoshop requires rasterizing first — a baked
        // stroke would be wiped by the next smart-filter re-render).
        let filter_masking = self.painting_filter_mask();
        let masking = self.painting_mask();
        if !masking && self.refuse_destructive_edit() {
            return false;
        }
        if !masking && self.reject_legacy_float_edit("Brush Stroke") {
            return false;
        }
        // Pattern Stamp with no defined pattern: nothing to paint (no stroke, no undo).
        if self.pattern_stamp && self.pattern.is_empty() {
            self.last_edit_error =
                "Could not use the Pattern Stamp because no pattern is defined. Choose Edit ▸ Define Pattern first."
                    .into();
            return false;
        }
        // History Brush (mode 12) needs a captured source that still matches the
        // layer size — an empty source (never set) or a crop in between misaligns
        // the snapshot, so the stroke is a no-op (no undo step pushed).
        if self.brush.mode == 12 && !self.history_source_matches_active_layer() {
            self.last_edit_error = "Could not use the History Brush because the history source no longer matches this canvas. Choose Set Source in the History panel to recapture it.".into();
            return false;
        }
        let label = if masking {
            "Paint Mask"
        } else {
            match self.brush.mode {
                1 => "Erase",
                2 => "Dodge",
                3 => "Burn",
                4 => "Smudge",
                5 => "Heal",
                6 => "Color Replacement",
                7 => "Background Eraser",
                8 => "Sponge",
                9 => "Blur",
                10 => "Sharpen",
                11 => "Mixer Brush",
                12 => "History Brush",
                _ => {
                    if self.pattern_stamp {
                        "Pattern Stamp"
                    } else if self.clone_enabled {
                        "Clone Stamp"
                    } else {
                        "Brush"
                    }
                }
            }
        };
        self.smudge_init = false;
        self.bg_eraser_init = false;
        // Load after each stroke: fresh paint now; off, the reservoir carries over.
        if self.mixer_auto_load {
            self.mixer_init = false;
            self.mixer_empty = false;
        }
        if masking {
            if self.push_stack_undo(label) {
                return false;
            }
            self.stroke_base_mask = if filter_masking {
                self.layers[self.active].smart_mask.clone()
            } else {
self.layers[self.active].mask.to_vec()
            };
        } else {
            if self.push_layer_undo(label) {
                return false;
            }
            if self.clone_enabled {
                if self.pattern_stamp {
                    self.fill_clone_from_pattern();
                } else if !external_clone {
                    self.capture_clone_src();
                }
            }
            // Sample All Layers: freeze the stack beneath the active layer once per
            // stroke; the dab composites the live layer pixel over it.
            // ponytail: layers ABOVE the active one are left out (their pixels would
            // sit under the deposit); include them via composite_hiding_from(len)
            // + a second over() if a retouch under an overlay ever matters.
            if self.retouch_sample_all && matches!(self.brush.mode, 4 | 9 | 10 | 11) {
                self.retouch_src = self.composite_hiding_from(self.active);
            }
            self.stroke_base = Arc::clone(&self.layers[self.active].pixels);
        }
        self.begin_stroke_acc();
        self.stroking = true;
        self.have_last = false;
        true
    }

    // Add a segment to the current stroke; returns dirty rect [x,y,w,h].
    /// Paint Symmetry modes follow Photoshop's preset order. `axis_x`/`axis_y`
    /// are the default path centre in document space.
    pub fn set_paint_symmetry(&mut self, mode: u8, axis_x: f32, axis_y: f32) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        self.paint_symmetry = mode.min(10);
        self.paint_symmetry_segments = match self.paint_symmetry {
            10 => self.paint_symmetry_segments.clamp(3, 10),
            _ => self.paint_symmetry_segments.clamp(2, 12),
        };
        self.sym_axis_x = if axis_x.is_finite() {
            axis_x
        } else {
            self.w as f32 * 0.5
        };
        self.sym_axis_y = if axis_y.is_finite() {
            axis_y
        } else {
            self.h as f32 * 0.5
        };
    }
    pub fn commit_paint_symmetry(
        &mut self,
        mode: u8,
        segments: u8,
        axis_x: f32,
        axis_y: f32,
        angle_deg: f32,
        scale: f32,
    ) -> bool {
        let mode = mode.min(10);
        let segments = match mode {
            10 => segments.clamp(3, 10),
            _ => segments.clamp(2, 12),
        };
        let axis_x = if axis_x.is_finite() {
            axis_x
        } else {
            self.w as f32 * 0.5
        };
        let axis_y = if axis_y.is_finite() {
            axis_y
        } else {
            self.h as f32 * 0.5
        };
        let angle_deg = if angle_deg.is_finite() {
            (angle_deg + 180.0).rem_euclid(360.0) - 180.0
        } else {
            0.0
        };
        let scale = if scale.is_finite() {
            scale.clamp(MIN_PAINT_SYMMETRY_SCALE, MAX_PAINT_SYMMETRY_SCALE)
        } else {
            1.0
        };
        if self.paint_symmetry == mode
            && self.paint_symmetry_segments == segments
            && self.sym_axis_x == axis_x
            && self.sym_axis_y == axis_y
            && self.sym_angle_deg == angle_deg
            && self.sym_scale == scale
        {
            return false;
        }
        if self.push_paint_symmetry_undo() {
            return false;
        }
        self.paint_symmetry = mode;
        self.paint_symmetry_segments = segments;
        self.sym_axis_x = axis_x;
        self.sym_axis_y = axis_y;
        self.sym_angle_deg = angle_deg;
        self.sym_scale = scale;
        true
    }
    pub fn paint_symmetry_mode(&self) -> u8 {
        self.paint_symmetry
    }
    pub fn set_paint_symmetry_segments(&mut self, segments: u8) {
        if self.reject_imported_photoshop_edit() {
            return;
        }
        self.paint_symmetry_segments = match self.paint_symmetry {
            10 => segments.clamp(3, 10),
            _ => segments.clamp(2, 12),
        };
    }
    pub fn paint_symmetry_segment_count(&self) -> u8 {
        self.paint_symmetry_segments
    }
    pub fn paint_symmetry_axis_x(&self) -> f32 {
        self.sym_axis_x
    }
    pub fn paint_symmetry_axis_y(&self) -> f32 {
        self.sym_axis_y
    }
    pub fn paint_symmetry_angle(&self) -> f32 {
        self.sym_angle_deg
    }
    pub fn paint_symmetry_scale(&self) -> f32 {
        self.sym_scale
    }
    pub fn stroke_to(&mut self, x: f32, y: f32, pressure: f32) -> Vec<i32> {
        if !self.stroking {
            return vec![0, 0, 0, 0];
        }
        let p = pressure.clamp(0.0, 1.0);
        // Minimum Diameter is what the pressure ramp bottoms out at — it was a
        // hard-coded 0.25 before Shape Dynamics made it a setting.
        let min_d = self.brush.min_diameter;
        let mut eff_size = if self.brush.size_pressure {
            (self.brush.size * (min_d + (1.0 - min_d) * p)).max(1.0)
        } else {
            self.brush.size
        };
        if self.brush.size_jitter > 0.0 {
            eff_size = (eff_size * self.transfer_factor(self.brush.size_jitter, min_d)).max(1.0);
        }
        let spacing_px = (eff_size * self.brush.spacing).max(1.0);

        let sym = self.paint_symmetry;
        let segments = self.paint_symmetry_segments;
        let (ax, ay) = (self.sym_axis_x, self.sym_axis_y);
        let symmetry_scale = self
            .sym_scale
            .clamp(MIN_PAINT_SYMMETRY_SCALE, MAX_PAINT_SYMMETRY_SCALE);
        let (angle_sin, angle_cos) = self.sym_angle_deg.to_radians().sin_cos();
        let mut dirty = [i32::MAX, i32::MAX, i32::MIN, i32::MIN];
        let mut centers = Vec::new();
        let grow = |dirty: &mut [i32; 4], b: &[i32]| {
            if b[0] < dirty[0] {
                dirty[0] = b[0];
            }
            if b[1] < dirty[1] {
                dirty[1] = b[1];
            }
            if b[2] > dirty[2] {
                dirty[2] = b[2];
            }
            if b[3] > dirty[3] {
                dirty[3] = b[3];
            }
        };
        // Paint Symmetry echoes each dab across an axis or around the centre.
        let mut stamp_at = |e: &mut Engine, sx: f32, sy: f32| {
            let world_dx = sx - ax;
            let world_dy = sy - ay;
            let sx = (world_dx * angle_cos + world_dy * angle_sin) / symmetry_scale;
            let sy = (-world_dx * angle_sin + world_dy * angle_cos) / symmetry_scale;
            let mut painted = [(0.0f32, 0.0f32); 20];
            let mut painted_len = 0usize;
            let mut paint = |local_x: f32, local_y: f32| {
                if painted[..painted_len]
                    .iter()
                    .any(|&(x, y)| (x - local_x).abs() + (y - local_y).abs() <= 0.0001)
                {
                    return;
                }
                painted[painted_len] = (local_x, local_y);
                painted_len += 1;
                let x = ax + (local_x * angle_cos - local_y * angle_sin) * symmetry_scale;
                let y = ay + (local_x * angle_sin + local_y * angle_cos) * symmetry_scale;
                centers.push((x, y));
            };
            match sym {
                1 => {
                    paint(sx, sy);
                    paint(-sx, sy);
                }
                2 => {
                    paint(sx, sy);
                    paint(sx, -sy);
                }
                3 => {
                    paint(sx, sy);
                    paint(-sx, sy);
                    paint(sx, -sy);
                    paint(-sx, -sy);
                }
                4 => {
                    paint(sx, sy);
                    let (mx, my) = (sy, sx);
                    if (mx - sx).abs() + (my - sy).abs() > 0.0001 {
                        paint(mx, my);
                    }
                }
                5 => {
                    paint(sx, sy);
                    let amplitude = e.w.min(e.h) as f32 * 0.1;
                    let path_x = amplitude * (std::f32::consts::TAU * sy / e.h as f32).sin();
                    let mx = 2.0 * path_x - sx;
                    if (mx - sx).abs() > 0.0001 {
                        paint(mx, sy);
                    }
                }
                6 | 7 => {
                    let (dx, dy) = (sx, sy);
                    let radius = (dx * dx + dy * dy).sqrt();
                    paint(sx, sy);
                    if radius < 0.0001 {
                        return;
                    }
                    let guide_radius = if sym == 6 {
                        e.w.min(e.h) as f32 * 0.25
                    } else {
                        let spacing = e.w.min(e.h) as f32 * 0.45 / 2.0;
                        let phase =
                            dy.atan2(dx).rem_euclid(std::f32::consts::TAU) / std::f32::consts::TAU;
                        let turn = (radius / spacing - phase).round().clamp(0.0, 2.0);
                        (turn + phase) * spacing
                    };
                    let mirror_scale = (2.0 * guide_radius - radius) / radius;
                    let (mx, my) = (dx * mirror_scale, dy * mirror_scale);
                    if (mx - sx).abs() + (my - sy).abs() > 0.0001 {
                        paint(mx, my);
                    }
                }
                8 => {
                    paint(sx, sy);
                    let offset = e.w as f32 / 6.0;
                    for line_x in [-offset, offset] {
                        let mx = 2.0 * line_x - sx;
                        if (mx - sx).abs() > 0.0001 {
                            paint(mx, sy);
                        }
                    }
                }
                9 | 10 => {
                    let (dx, dy) = (sx, sy);
                    if dx.abs() + dy.abs() < 0.0001 {
                        paint(sx, sy);
                        return;
                    }
                    let count = if sym == 10 {
                        segments.clamp(3, 10)
                    } else {
                        segments.clamp(2, 12)
                    };
                    for i in 0..count {
                        let angle = std::f32::consts::TAU * i as f32 / count as f32;
                        let (sin, cos) = angle.sin_cos();
                        let (x, y) = (dx * cos - dy * sin, dx * sin + dy * cos);
                        paint(x, y);
                        if sym == 10 {
                            let (mx, my) = (dx * cos + dy * sin, dx * sin - dy * cos);
                            if (mx - x).abs() + (my - y).abs() > 0.0001 {
                                paint(mx, my);
                            }
                        }
                    }
                }
                _ => paint(sx, sy),
            }
        };

        if !self.have_last {
            stamp_at(self, x, y);
            self.last_x = x;
            self.last_y = y;
            self.have_last = true;
        } else {
            let dx = x - self.last_x;
            let dy = y - self.last_y;
            let dist = (dx * dx + dy * dy).sqrt();
            let steps = (dist / spacing_px).floor() as i32;
            for s in 1..=steps {
                let t = s as f32 * spacing_px / dist;
                stamp_at(self, self.last_x + dx * t, self.last_y + dy * t);
            }
            if steps >= 1 {
                let t = steps as f32 * spacing_px / dist;
                self.last_x += dx * t;
                self.last_y += dy * t;
            }
        }
        drop(stamp_at);

        let mode = self.brush.mode;
        // Scattering: spray each dab off the path and optionally lay down several
        // per step. Applied here, after symmetry has built the dab list and
        // before plane growth measures it, so a sprayed dab can still grow the
        // plane it lands on. Draws from the stroke RNG, so a stroke repeats.
        if self.brush.scatter > 0.0 || self.brush.scatter_count > 1 {
            let reach = self.brush.scatter * eff_size;
            let both = self.brush.scatter_both_axes;
            // Count jitter takes dabs away from the set count, never adds.
            let count = if self.brush.scatter_count_jitter > 0.0 {
                let f = self.transfer_factor(self.brush.scatter_count_jitter, 0.0);
                ((self.brush.scatter_count as f32 * f).round() as u32).max(1)
            } else {
                self.brush.scatter_count
            };
            // The stroke direction, so a one-axis scatter throws ACROSS it.
            let (sdx, sdy) = (x - self.last_x, y - self.last_y);
            let len = (sdx * sdx + sdy * sdy).sqrt();
            let (ux, uy) = if len > 1e-4 { (sdx / len, sdy / len) } else { (1.0, 0.0) };
            let (nx, ny) = (-uy, ux);
            let base: Vec<(f32, f32)> = centers.clone();
            centers.clear();
            for (bx, by) in base {
                for _ in 0..count {
                    if reach <= 0.0 {
                        centers.push((bx, by));
                        continue;
                    }
                    let across = (self.next_rand() * 2.0 - 1.0) * reach;
                    let along = if both { (self.next_rand() * 2.0 - 1.0) * reach } else { 0.0 };
                    centers.push((bx + nx * across + ux * along, by + ny * across + uy * along));
                }
            }
        }

        let can_grow_plane = match mode {
            0 => !self.brush.clear,
            1 | 2 | 3 | 7 | 8 | 9 | 10 | 11 | 12 => false,
            _ => true,
        };
        let flow_can_paint = self.brush.flow > 0.0 && (!self.brush.flow_pressure || p > 0.0);
        let opacity_can_paint = mode == 4 || self.brush.opacity > 0.0;
        if !self.qm_on
            && !self.painting_mask()
            && can_grow_plane
            && flow_can_paint
            && opacity_can_paint
        {
            let mut target = None;
            if let Some(plane) = self.plane_rect(self.active) {
                for &(cx, cy) in &centers {
                    let Some((bounds, _, _, _)) = self.stamp_geometry(cx, cy, eff_size) else {
                        continue;
                    };
                    let bounds_x1 = i64::from(bounds.x) + i64::from(bounds.w);
                    let bounds_y1 = i64::from(bounds.y) + i64::from(bounds.h);
                    let plane_x1 = i64::from(plane.x) + i64::from(plane.w);
                    let plane_y1 = i64::from(plane.y) + i64::from(plane.h);
                    if bounds.x >= plane.x
                        && bounds.y >= plane.y
                        && bounds_x1 <= plane_x1
                        && bounds_y1 <= plane_y1
                    {
                        continue;
                    }
                    let growth = if self.sel.active {
                        let mut selected = [i32::MAX, i32::MAX, i32::MIN, i32::MIN];
                        for y in bounds.y..bounds.y + bounds.h as i32 {
                            for x in bounds.x..bounds.x + bounds.w as i32 {
                                let i = (y * self.w as i32 + x) as usize;
                                if self.sel.mask[i] == 0
                                    || checked_plane_index(plane, x, y, 4).is_some()
                                {
                                    continue;
                                }
                                selected[0] = selected[0].min(x);
                                selected[1] = selected[1].min(y);
                                selected[2] = selected[2].max(x);
                                selected[3] = selected[3].max(y);
                            }
                        }
                        if selected[0] <= selected[2] {
                            Some(Bounds {
                                x: selected[0],
                                y: selected[1],
                                w: (selected[2] - selected[0] + 1) as u32,
                                h: (selected[3] - selected[1] + 1) as u32,
                            })
                        } else {
                            None
                        }
                    } else {
                        Some(bounds)
                    };
                    let Some(growth) = growth else {
                        continue;
                    };
                    target = match target {
                        Some(current) => checked_union_bounds(current, growth),
                        None => Some(growth),
                    };
                    if target.is_none() {
                        break;
                    }
                }
            }
            if let Some(target) = target {
                self.expand_active_stroke_plane(target);
            }
        }

        for (cx, cy) in centers {
            let bounds = self.stamp(cx, cy, p, eff_size);
            grow(&mut dirty, &bounds);
        }
        // Quick Mask edits the buffer, not a layer — bump its revision so the
        // overlay's full-rebuild path stays in sync (the live dirty-rect redraw
        // uses the returned rect directly).
        if self.qm_on {
            self.qm_gen = self.qm_gen.wrapping_add(1);
        }
        if dirty[2] < dirty[0] {
            return vec![0, 0, 0, 0];
        }
        vec![
            dirty[0],
            dirty[1],
            dirty[2] - dirty[0] + 1,
            dirty[3] - dirty[1] + 1,
        ]
    }

    // Airbrush / Build-up: stamp one dab AT the point regardless of travelled
    // distance, so a held-still pointer keeps depositing at the Flow rate.
    // `stroke_to` only stamps once `dist >= spacing_px` (spacing floored at 1px),
    // so dropping `have_last` re-enters its first-dab path — same stamp, same
    // `stroke_acc` accumulation toward the opacity cap, no undo step and no layer
    // clone (both belong to stroke_begin/stroke_end).
    pub fn stroke_dab(&mut self, x: f32, y: f32, pressure: f32) -> Vec<i32> {
        self.have_last = false;
        self.stroke_to(x, y, pressure)
    }

    pub fn stroke_end(&mut self) {
        if self.qm_on {
            self.qm_gen = self.qm_gen.wrapping_add(1);
        }
        // A filter-mask stroke changed coverage, not pixels — the stack has to
        // re-run for it to reach the canvas.
        // ponytail: once per stroke, so there is no live preview while dragging.
        // Cache the un-masked filtered plane at stroke_begin and lerp per dab if
        // that matters.
        if self.stroking && self.painting_filter_mask() {
            let active = self.active;
            self.render_smart(active);
            self.composite();
        }
        // Clean after each stroke: the reservoir is emptied, so the next stroke
        // (unless it reloads) picks up canvas colour only.
        if self.mixer_auto_clean {
            self.mixer_init = false;
            self.mixer_empty = true;
        }
        self.stroking = false;
        self.stroke_base = Arc::from(Vec::new());
        self.stroke_acc_w = 0;
        self.clone_src = Vec::new();
        self.retouch_src = Vec::new();
        self.stroke_base_mask = Vec::new();
        self.have_last = false;
    }

    // ── Liquify forward-warp session ────────────────────────────
    // Can this smart object take a Liquify session? The filter stack renders in
    // SOURCE space (before the placement transform), so a scaled/rotated/warped
    // smart object would commit a mesh that no longer matches the live preview —
    // refuse those rather than lie. A source that doesn't match the canvas can't
    // reach the stack at all (see smart_source_pixels_with_replacement), so the
    // warp would silently vanish on the next re-render.
    // ponytail: identity-placement ceiling. Lift it by running the stack after
    // the placement transform (Photoshop's order) if a transformed smart object
    // ever needs Liquify.
    fn smart_liquify_ready(&self, idx: usize) -> bool {
        let l = &self.layers[idx];
        l.smart_src.len() == (self.w * self.h * 4) as usize
            && l.smart_transform_ops.is_empty()
            && Engine::smart_transform_is_identity(l.smart_transform)
    }

    // Begin a Liquify session: freeze the active layer's pixels, allocate a
    // zeroed forward-displacement field, and open ONE undo transaction
    // ("Liquify").
    // Gated like a brush stroke — a locked, adjustment, text, group or vector
    // layer refuses (returns false; no undo step, no session). A smart object is
    // allowed and commits non-destructively: liquify_end turns the session mesh
    // into a re-editable fid-117 smart filter.
    pub fn liquify_begin(&mut self) -> bool {
        if self.reject_imported_photoshop_edit() {
            return false;
        }
        let l = &self.layers[self.active];
        if l.locked || l.kind == 1 || l.kind == 2 || l.kind == 3 || l.kind == 4 || l.kind == 6 {
            return false;
        }
        if l.kind == 7 && !self.smart_liquify_ready(self.active) {
            return false;
        }
        if self.reject_legacy_float_edit("Liquify") {
            return false;
        }
        if !self.begin_history_transaction() {
            return false;
        }
        // A smart-object session ends by mutating the filter stack, so it needs a
        // doc snapshot; a pixel layer keeps the cheaper layer-pixel snapshot.
        let smart = self.layers[self.active].kind == 7;
        let refused = if smart {
            self.push_stack_undo("Liquify")
        } else {
            self.push_layer_undo("Liquify")
        };
        if refused {
            self.cancel_history_transaction();
            return false;
        }
        self.liquify_base = self.layers[self.active].pixels.to_vec();
        let n = (self.w * self.h) as usize;
        self.liquify_fx = vec![0.0; n];
        self.liquify_fy = vec![0.0; n];
        self.liquify_mask = if self.sel.active {
            self.sel.mask.clone()
        } else {
            Vec::new()
        };
        self.liquify_freeze_mask = Vec::new();
        self.liquify_mask_gen = self.liquify_mask_gen.wrapping_add(1);
        self.liquify_active = true;
        self.liquify_pin_edges = false;
        true
    }

    // Liquify workspace Pin Edges: while on, the outer 1px canvas border never
    // displaces, so warps near the edge can't tear the image away from its
    // boundary. Session-wide (not per-dab) since the option is a toggle, not a
    // brush parameter — this keeps liquify_dab's ABI stable for every caller.
    pub fn liquify_set_pin_edges(&mut self, on: bool) -> bool {
        if !self.liquify_active {
            return false;
        }
        self.liquify_pin_edges = on;
        true
    }

    // Apply one dab: accumulate the mode's contribution into the field over the
    // footprint, re-render the dirty rect from the frozen base, and return the
    // [x, y, w, h] dirty rect (the caller composites + blits it). Only D within
    // the footprint changes, and the smoothstep falloff eases D to 0 at the edge,
    // so re-rendering just the footprint is exact and joins the unwarped surround
    // seamlessly. No undo is pushed here — the one step from liquify_begin stands.
    #[allow(clippy::too_many_arguments)]
    pub fn liquify_dab(
        &mut self,
        cx: f32,
        cy: f32,
        radius: f32,
        hardness: f32,
        mode: u8,
        strength: f32,
        gx: f32,
        gy: f32,
    ) -> Vec<i32> {
        if !self.liquify_active {
            return vec![0, 0, 0, 0];
        }
        let w = self.w;
        let h = self.h;
        liquify_accumulate(
            &mut self.liquify_fx,
            &mut self.liquify_fy,
            w,
            h,
            cx,
            cy,
            radius,
            hardness.clamp(0.0, 1.0),
            mode,
            strength,
            gx,
            gy,
            if self.liquify_mask.is_empty() {
                None
            } else {
                Some(&self.liquify_mask)
            },
            if self.liquify_freeze_mask.is_empty() {
                None
            } else {
                Some(&self.liquify_freeze_mask)
            },
            self.liquify_pin_edges,
        );
        let r = radius.max(1.0);
        let x0 = ((cx - r).floor() as i32).max(0);
        let y0 = ((cy - r).floor() as i32).max(0);
        let x1 = ((cx + r).ceil() as i32 + 1).min(w as i32);
        let y1 = ((cy + r).ceil() as i32 + 1).min(h as i32);
        let rw = (x1 - x0).max(0);
        let rh = (y1 - y0).max(0);
        if rw == 0 || rh == 0 {
            return vec![0, 0, 0, 0];
        }
        let a = self.active;
        let bounds = self.layers[a].pixel_bounds;
        let origin = (bounds.x + self.layers[a].ox, bounds.y + self.layers[a].oy);
        liquify_render(
            &self.liquify_base,
            bounds.w,
            bounds.h,
            origin,
            w,
            h,
            &self.liquify_fx,
            &self.liquify_fy,
            Arc::make_mut(&mut self.layers[a].pixels),
            [x0, y0, rw, rh],
        );
        vec![x0, y0, rw, rh]
    }

    // Freeze/Thaw Mask inside the Liquify workspace. This paints a session-local
    // protection overlay only; it never edits document pixels and never pushes a
    // separate history step. Future warp dabs scale by (editable coverage) ×
    // (1 − frozen coverage), so frozen pixels keep their current distortion state.
    pub fn liquify_mask_dab(
        &mut self,
        cx: f32,
        cy: f32,
        radius: f32,
        hardness: f32,
        freeze: bool,
        strength: f32,
    ) -> Vec<i32> {
        if !self.liquify_active {
            return vec![0, 0, 0, 0];
        }
        let w = self.w;
        let h = self.h;
        if self.liquify_freeze_mask.is_empty() {
            if !freeze {
                return vec![0, 0, 0, 0];
            }
            self.liquify_freeze_mask = vec![0u8; (w * h) as usize];
        }
        let changed = liquify_paint_freeze_mask(
            &mut self.liquify_freeze_mask,
            w,
            h,
            cx,
            cy,
            radius,
            hardness.clamp(0.0, 1.0),
            freeze,
            strength.clamp(0.0, 1.0),
            if self.liquify_mask.is_empty() {
                None
            } else {
                Some(&self.liquify_mask)
            },
        );
        if !changed {
            return vec![0, 0, 0, 0];
        }
        if self.liquify_freeze_mask.iter().all(|&v| v == 0) {
            self.liquify_freeze_mask = Vec::new();
        }
        self.liquify_mask_gen = self.liquify_mask_gen.wrapping_add(1);
        let r = radius.max(1.0);
        let x0 = ((cx - r).floor() as i32).max(0);
        let y0 = ((cy - r).floor() as i32).max(0);
        let x1 = ((cx + r).ceil() as i32 + 1).min(w as i32);
        let y1 = ((cy + r).ceil() as i32 + 1).min(h as i32);
        vec![x0, y0, (x1 - x0).max(0), (y1 - y0).max(0)]
    }

    // Photoshop-style Liquify mask actions. These mutate only the session-local
    // Freeze Mask overlay and never touch document pixels or add history steps.
    pub fn liquify_mask_clear(&mut self) -> bool {
        if !self.liquify_active || self.liquify_freeze_mask.is_empty() {
            return false;
        }
        self.liquify_freeze_mask = Vec::new();
        self.liquify_mask_gen = self.liquify_mask_gen.wrapping_add(1);
        true
    }

    pub fn liquify_mask_all(&mut self) -> bool {
        if !self.liquify_active {
            return false;
        }
        let n = (self.w * self.h) as usize;
        let next = if self.liquify_mask.is_empty() {
            vec![255u8; n]
        } else {
            self.liquify_mask.clone()
        };
        if self.liquify_freeze_mask == next {
            return false;
        }
        self.liquify_freeze_mask = next;
        self.liquify_mask_gen = self.liquify_mask_gen.wrapping_add(1);
        true
    }

    pub fn liquify_mask_invert(&mut self) -> bool {
        if !self.liquify_active {
            return false;
        }
        let n = (self.w * self.h) as usize;
        let mut next = vec![0u8; n];
        if self.liquify_mask.is_empty() {
            for (i, out) in next.iter_mut().enumerate() {
                let cur = self.liquify_freeze_mask.get(i).copied().unwrap_or(0);
                *out = 255u8.saturating_sub(cur);
            }
        } else {
            for (i, out) in next.iter_mut().enumerate() {
                let editable = self.liquify_mask[i];
                let cur = self.liquify_freeze_mask.get(i).copied().unwrap_or(0);
                *out = editable.saturating_sub(cur.min(editable));
            }
        }
        if next.iter().all(|&v| v == 0) {
            next = Vec::new();
        }
        if self.liquify_freeze_mask == next {
            return false;
        }
        self.liquify_freeze_mask = next;
        self.liquify_mask_gen = self.liquify_mask_gen.wrapping_add(1);
        true
    }

    // Combine a sourced channel into the Freeze Mask overlay. op follows the same
    // convention as the selection combine modes used elsewhere in the engine:
    // 0 Replace · 1 Add · 2 Subtract · 3 Intersect.
    fn liquify_mask_combine(&mut self, source: &[u8], op: u8) -> bool {
        if !self.liquify_active {
            return false;
        }
        let n = (self.w * self.h) as usize;
        let mut next = vec![0u8; n];
        for i in 0..n {
            let s = source.get(i).copied().unwrap_or(0);
            let c = self.liquify_freeze_mask.get(i).copied().unwrap_or(0);
            next[i] = match op {
                1 => c.max(s),
                2 => c.saturating_sub(s),
                3 => c.min(s),
                _ => s, // Replace
            };
        }
        if next.iter().all(|&v| v == 0) {
            next = Vec::new();
        }
        if self.liquify_freeze_mask == next {
            return false;
        }
        self.liquify_freeze_mask = next;
        self.liquify_mask_gen = self.liquify_mask_gen.wrapping_add(1);
        true
    }

    // Load the active layer's alpha channel as the Freeze Mask source (opaque
    // pixels protect fully, transparent pixels don't protect at all), then
    // combine it into the current overlay. Confined to the editable area
    // captured at session start, like the other mask actions.
    pub fn liquify_mask_from_transparency(&mut self, op: u8) -> bool {
        if !self.liquify_active {
            return false;
        }
        let Some(rect) = self.plane_rect(self.active) else {
            return false;
        };
        let (w, h) = (self.w as i32, self.h as i32);
        let n = (w * h) as usize;
        let px = &self.layers[self.active].pixels;
        let mut source = vec![0u8; n];
        for y in 0..h {
            for x in 0..w {
                let i = (y * w + x) as usize;
                let a = checked_plane_index(rect, x, y, 4)
                    .map(|p| (px[p + 3] >> 8) as u8)
                    .unwrap_or(0);
                source[i] = match self.liquify_mask.get(i) {
                    Some(&edit) => a.min(edit),
                    None => a,
                };
            }
        }
        self.liquify_mask_combine(&source, op)
    }

    // Load the active layer's own layer mask as the Freeze Mask source (a layer
    // with no layer mask is fully revealed, i.e. protects everywhere), then
    // combine it into the current overlay. Confined to the editable area
    // captured at session start, like the other mask actions.
    pub fn liquify_mask_from_layer_mask(&mut self, op: u8) -> bool {
        if !self.liquify_active {
            return false;
        }
        let n = (self.w * self.h) as usize;
        let mask = &self.layers[self.active].mask;
        let mut source = vec![0u8; n];
        for i in 0..n {
            let m = mask.get(i).copied().unwrap_or(255);
            source[i] = match self.liquify_mask.get(i) {
                Some(&edit) => m.min(edit),
                None => m,
            };
        }
        self.liquify_mask_combine(&source, op)
    }

    // Commit the Liquify session: drop the working buffers. The transaction's
    // single undo step stands as the one history entry for the session — unless
    // nothing was warped, in which case the transaction is cancelled: Apply with
    // no strokes (or after Restore All) changed nothing, and a no-op must not burn
    // a history step, exactly as liquify_cancel does. (#87)
    // On a smart object the accumulated mesh is handed to the filter stack as a
    // re-editable fid-117 entry instead of being left baked into the rendered
    // pixels (which the next stack change would discard).
    pub fn liquify_end(&mut self) {
        let warped = self.liquify_fx.iter().any(|d| *d != 0.0)
            || self.liquify_fy.iter().any(|d| *d != 0.0);
        if self.liquify_active && self.layers[self.active].kind == 7 && warped {
            let params = pack_liquify_mesh(&self.liquify_fx, &self.liquify_fy, self.w, self.h);
            let a = self.active;
            self.layers[a].smart_filters.push((LIQUIFY_SMART_FID, params));
            self.layers[a].psd_smart_blocks.clear();
            self.render_smart(a);
            self.composite();
        }
        if self.liquify_active {
            if warped {
                self.commit_history_transaction();
            } else {
                self.cancel_history_transaction();
            }
        }
        self.liquify_active = false;
        self.liquify_base = Vec::new();
        self.liquify_fx = Vec::new();
        self.liquify_fy = Vec::new();
        self.liquify_mask = Vec::new();
        self.liquify_freeze_mask = Vec::new();
        self.liquify_mask_gen = self.liquify_mask_gen.wrapping_add(1);
    }

    // Restore All inside the Liquify workspace: clear the accumulated
    // displacement field and repaint the active layer from the frozen base while
    // keeping the session open. The one undo step from liquify_begin remains.
    pub fn liquify_restore_all(&mut self) -> bool {
        if !self.liquify_active {
            return false;
        }
        let a = self.active;
        Arc::make_mut(&mut self.layers[a].pixels).copy_from_slice(&self.liquify_base);
        self.liquify_fx.fill(0.0);
        self.liquify_fy.fill(0.0);
        self.composite();
        true
    }

    pub fn liquify_mesh_fx(&self) -> Vec<f32> {
        if self.liquify_active {
            self.liquify_fx.clone()
        } else {
            Vec::new()
        }
    }

    pub fn liquify_mesh_fy(&self) -> Vec<f32> {
        if self.liquify_active {
            self.liquify_fy.clone()
        } else {
            Vec::new()
        }
    }

    // Load a saved Liquify displacement mesh into the current session and render
    // the active layer from the frozen base. No undo is pushed here: loading a
    // mesh is part of the open Liquify workspace session.
    pub fn liquify_load_mesh(&mut self, fx: &[f32], fy: &[f32]) -> bool {
        if !self.liquify_active {
            return false;
        }
        let n = (self.w * self.h) as usize;
        if fx.len() != n || fy.len() != n {
            return false;
        }
        self.liquify_fx.clone_from_slice(fx);
        self.liquify_fy.clone_from_slice(fy);
        let a = self.active;
        let bounds = self.layers[a].pixel_bounds;
        let origin = (bounds.x + self.layers[a].ox, bounds.y + self.layers[a].oy);
        liquify_render(
            &self.liquify_base,
            bounds.w,
            bounds.h,
            origin,
            self.w,
            self.h,
            &self.liquify_fx,
            &self.liquify_fy,
            Arc::make_mut(&mut self.layers[a].pixels),
            [0, 0, self.w as i32, self.h as i32],
        );
        self.composite();
        true
    }

    // Cancel the Liquify session: restore the frozen base and exact history branch
    // captured at begin, leaving the document as it was before.
    pub fn liquify_cancel(&mut self) {
        if !self.liquify_active {
            return;
        }
        self.cancel_history_transaction();
        self.liquify_active = false;
        self.liquify_base = Vec::new();
        self.liquify_fx = Vec::new();
        self.liquify_fy = Vec::new();
        self.liquify_mask = Vec::new();
        self.liquify_freeze_mask = Vec::new();
        self.liquify_mask_gen = self.liquify_mask_gen.wrapping_add(1);
    }

    pub fn liquify_freeze_mask_on(&self) -> bool {
        self.liquify_active && self.liquify_freeze_mask.iter().any(|&v| v > 0)
    }

    pub fn liquify_freeze_mask_generation(&self) -> u32 {
        self.liquify_mask_gen
    }

    pub fn liquify_freeze_mask_ptr(&self) -> *const u8 {
        self.liquify_freeze_mask.as_ptr()
    }

    // History panel "Set Source": freeze the active layer's current pixels as the
    // History Brush / Edit ▸ Fill ▸ History source. The user can seek to any
    // timeline state, set the source there, then seek back — the snapshot persists.
    // Runtime-only (not serialized); auto-captured on Engine::new / open / load.
    pub fn set_history_source(&mut self) {
        let layer = &self.layers[self.active];
        let Some(bounds) = checked_translate_bounds(layer.pixel_bounds, layer.ox, layer.oy) else {
            self.history_source.clear();
            self.history_source_bounds = None;
            self.history_source_document = None;
            return;
        };
        self.history_source = layer.pixels.to_vec();
        self.history_source_bounds = Some(bounds);
        self.history_source_document = Some((self.w, self.h));
    }

    // Whether the captured History source still fits the active layer (gates the
    // History Brush + Fill; canvas geometry changes invalidate the old source).
    pub fn has_history_source(&self) -> bool {
        !self.history_source.is_empty() && self.history_source_matches_active_layer()
    }

    fn history_source_matches_active_layer(&self) -> bool {
        let layer = &self.layers[self.active];
        let effective_bounds = checked_translate_bounds(layer.pixel_bounds, layer.ox, layer.oy);
        self.history_source_document == Some((self.w, self.h))
            && self.history_source_bounds == effective_bounds
            && self.history_source.len() == layer.pixels.len()
    }

    // Composite an RGBA image buffer onto the active layer at (x, y), respecting
    // the selection. Used by the text tool and paste.
    pub fn stamp_image(&mut self, x: i32, y: i32, iw: u32, ih: u32, rgba: &[u8]) {
        if self.active_layer().locked || rgba.len() < (iw * ih * 4) as usize {
            return;
        }
        if self.reject_legacy_float_edit("Stamp Image") {
            return;
        }
        let Some(rect) = self.plane_rect(self.active) else {
            return;
        };
        if self.push_layer_undo("Paste") {
            return;
        }
        let w = self.w as i32;
        let h = self.h as i32;
        for j in 0..ih as i32 {
            for i in 0..iw as i32 {
                let dx = x + i;
                let dy = y + j;
                if dx < 0 || dy < 0 || dx >= w || dy >= h {
                    continue;
                }
                let di = (dy * w + dx) as usize;
                let sel = self.sel.coverage(di);
                if sel <= 0.0 {
                    continue;
                }
                let Some(bp) = checked_plane_index(rect, dx, dy, 4) else {
                    continue;
                };
                let pi = (j * iw as i32 + i) as usize * 4;
                let base = Rgba::from_u16(&self.layers[self.active].pixels[bp..bp + 4]);
                let s = Rgba::new(
                    rgba[pi] as f32 / 255.0,
                    rgba[pi + 1] as f32 / 255.0,
                    rgba[pi + 2] as f32 / 255.0,
                    (rgba[pi + 3] as f32 / 255.0) * sel,
                );
                let res = composite_over(base, s, BlendMode::Normal, 1.0);
                res.to_u16(&mut Arc::make_mut(&mut self.layers[self.active].pixels)[bp..bp + 4]);
            }
        }
        self.composite();
    }

    /// `stamp_image` for the document's own 16-bit samples. A 3D LUT graded from
    /// `export_composite_rgba16` lands here so a 16-bit layer is not rounded
    /// through an 8-bit canvas first. (#550)
    pub fn stamp_image_rgba16(&mut self, x: i32, y: i32, iw: u32, ih: u32, rgba: &[u16]) {
        if self.active_layer().locked || rgba.len() < (iw * ih * 4) as usize {
            return;
        }
        if self.reject_legacy_float_edit("Stamp Image") {
            return;
        }
        let Some(rect) = self.plane_rect(self.active) else {
            return;
        };
        if self.push_layer_undo("Paste") {
            return;
        }
        let w = self.w as i32;
        let h = self.h as i32;
        for j in 0..ih as i32 {
            for i in 0..iw as i32 {
                let dx = x + i;
                let dy = y + j;
                if dx < 0 || dy < 0 || dx >= w || dy >= h {
                    continue;
                }
                let di = (dy * w + dx) as usize;
                let sel = self.sel.coverage(di);
                if sel <= 0.0 {
                    continue;
                }
                let Some(bp) = checked_plane_index(rect, dx, dy, 4) else {
                    continue;
                };
                let pi = (j * iw as i32 + i) as usize * 4;
                let base = Rgba::from_u16(&self.layers[self.active].pixels[bp..bp + 4]);
                let s = Rgba::new(
                    rgba[pi] as f32 / 65535.0,
                    rgba[pi + 1] as f32 / 65535.0,
                    rgba[pi + 2] as f32 / 65535.0,
                    (rgba[pi + 3] as f32 / 65535.0) * sel,
                );
                let res = composite_over(base, s, BlendMode::Normal, 1.0);
                res.to_u16(&mut Arc::make_mut(&mut self.layers[self.active].pixels)[bp..bp + 4]);
            }
        }
        self.composite();
    }

    // Stamp a single dab; returns its pixel bbox [minx,miny,maxx,maxy].
    // xorshift32 over the stroke RNG → the next 0..1 sample for the brush
    // dynamics. Deterministic per stroke (stroke_begin reseeds it).
    fn next_rand(&mut self) -> f32 {
        let mut s = self.stroke_rng;
        s ^= s << 13;
        s ^= s >> 17;
        s ^= s << 5;
        self.stroke_rng = s;
        (s >> 8) as f32 / 16_777_216.0
    }

    // Transfer dynamics: a per-dab multiplier in [min, 1]. `jitter` 0 disables
    // the dynamic entirely (identity, and no RNG draw, so an unused dynamic
    // never shifts another one's sequence).
    fn transfer_factor(&mut self, jitter: f32, min: f32) -> f32 {
        if jitter <= 0.0 {
            return 1.0;
        }
        let r = self.next_rand();
        (1.0 - jitter * r).max(min.clamp(0.0, 1.0))
    }

    /// What a retouch dab reads at canvas (x, y) / plane index `pi`: the active
    /// layer's pixel alone or, with Sample All Layers, that pixel over the frozen
    /// composite of the layers beneath it (`retouch_src`, canvas stride).
    fn retouch_pixel(&self, sample_all: bool, x: i32, y: i32, pi: usize) -> Rgba {
        let top = Rgba::from_u16(&self.layers[self.active].pixels[pi..pi + 4]);
        if !sample_all {
            return top;
        }
        let i = ((y * self.w as i32 + x) as usize) * 4;
        let s = &self.retouch_src[i..i + 4];
        let under = Rgba::new(
            s[0] as f32 / 255.0,
            s[1] as f32 / 255.0,
            s[2] as f32 / 255.0,
            s[3] as f32 / 255.0,
        );
        composite_over(under, top, BlendMode::Normal, 1.0)
    }

    /// Drop live coverage without releasing the accumulator allocation.
    fn begin_stroke_acc(&mut self) {
        self.stroke_acc_w = 0;
    }

    /// Grow the opacity accumulator to the dab's canvas bounds, once per dab.
    /// Newly covered pixels start at zero. A later dab reuses the allocation
    /// when it fits.
    fn ensure_stroke_acc(&mut self, x0: i32, y0: i32, x1: i32, y1: i32) {
        if x1 < x0 || y1 < y0 {
            return;
        }
        let (nx0, ny0, nx1, ny1) = if self.stroke_acc_w <= 0 {
            (x0, y0, x1, y1)
        } else {
            (
                self.stroke_acc_x.min(x0),
                self.stroke_acc_y.min(y0),
                (self.stroke_acc_x + self.stroke_acc_w - 1).max(x1),
                (self.stroke_acc_y + self.stroke_acc_h - 1).max(y1),
            )
        };
        let nw = nx1 - nx0 + 1;
        let nh = ny1 - ny0 + 1;
        if self.stroke_acc_w == nw && self.stroke_acc_h == nh && self.stroke_acc_x == nx0 && self.stroke_acc_y == ny0
        {
            return;
        }
        let need = (nw as usize).saturating_mul(nh as usize);
        if self.stroke_acc_w <= 0 {
            if self.stroke_acc.len() < need {
                self.stroke_acc.resize(need, 0.0);
            }
            self.stroke_acc[..need].fill(0.0);
        } else {
            let mut next = vec![0.0f32; need];
            for y in 0..self.stroke_acc_h {
                for x in 0..self.stroke_acc_w {
                    let src = (y * self.stroke_acc_w + x) as usize;
                    let dx = self.stroke_acc_x + x - nx0;
                    let dy = self.stroke_acc_y + y - ny0;
                    next[(dy * nw + dx) as usize] = self.stroke_acc[src];
                }
            }
            self.stroke_acc = next;
        }
        self.stroke_acc_x = nx0;
        self.stroke_acc_y = ny0;
        self.stroke_acc_w = nw;
        self.stroke_acc_h = nh;
    }

    /// Opacity/flow accumulation at one canvas pixel. Same recurrence the
    /// full-canvas buffer used: `acc + (1 - acc) * dab`, capped.
    fn bump_stroke_acc(&mut self, x: i32, y: i32, dab: f32, cap: f32) -> f32 {
        let lx = x - self.stroke_acc_x;
        let ly = y - self.stroke_acc_y;
        if lx < 0 || ly < 0 || lx >= self.stroke_acc_w || ly >= self.stroke_acc_h {
            return 0.0;
        }
        let i = (ly * self.stroke_acc_w + lx) as usize;
        let acc = &mut self.stroke_acc[i];
        *acc = (*acc + (1.0 - *acc) * dab).min(cap);
        *acc
    }

    fn stamp(&mut self, cx: f32, cy: f32, pressure: f32, eff_size: f32) -> [i32; 4] {
        // The layer's pixel plane in canvas space; every write below translates
        // through it. A stroke on a layer whose plane is unusable is a no-op. (#43)
        let Some(plane) = self.plane_rect(self.active) else {
            return [0, 0, 0, 0];
        };
        let w = self.w as i32;
        let h = self.h as i32;
        let radius = (eff_size * 0.5).max(0.5);
        // Custom brush tip (Define Brush Preset): the active tip's alpha REPLACES
        // the procedural round falloff on paint/erase paths (modes 0/1, not clone
        // or pattern-stamp). Scale the tip's longest side to eff_size with
        // aspect preserved; the bbox then frames the scaled tip and the per-pixel
        // tip alpha drives the same dab/cap/accumulator + spacing + opacity/flow/
        // selection downstream, so the painted footprint matches the tip bitmap.
        let Some((bounds, use_tip, scaled_w, scaled_h)) =
            self.stamp_geometry(cx, cy, eff_size)
        else {
            return [0, 0, 0, 0];
        };
        let (x0, y0) = (bounds.x, bounds.y);
        let (x1, y1) = (
            bounds.x + bounds.w as i32 - 1,
            bounds.y + bounds.h as i32 - 1,
        );
        let hardness = self.brush.hardness;
        let block = self.brush.block;
        // Brush Tip Shape: rotate the dab by `angle` and squash its minor axis by
        // `roundness` (identity at angle 0 / roundness 1). sin/cos once per dab.
        // Shape Dynamics jitters both per dab, on the same seeded RNG as
        // Transfer — and draws no random number when a jitter is 0, so an
        // existing stroke's RNG sequence is unchanged.
        let roundness = if self.brush.roundness_jitter > 0.0 {
            let f = self.transfer_factor(self.brush.roundness_jitter, self.brush.min_roundness);
            (self.brush.roundness * f).clamp(0.05, 1.0)
        } else {
            self.brush.roundness.clamp(0.05, 1.0)
        };
        let angle = if self.brush.angle_jitter > 0.0 {
            // Photoshop's Angle Jitter spans the full circle at 100%.
            let r = self.next_rand() * 2.0 - 1.0;
            self.brush.angle + r * self.brush.angle_jitter * std::f32::consts::PI
        } else {
            self.brush.angle
        };
        let (sin_a, cos_a) = angle.sin_cos();
        // Transfer dynamics: each dab draws its own opacity/flow multiplier from
        // the stroke RNG (identity, and no RNG draw, when the jitter is 0).
        let flow = self.brush.flow
            * if self.brush.flow_pressure {
                pressure
            } else {
                1.0
            }
            * self.transfer_factor(self.brush.flow_jitter, self.brush.min_flow);
        let opacity =
            self.brush.opacity * self.transfer_factor(self.brush.opacity_jitter, self.brush.min_opacity);
        let color = self.brush.color;
        let mode = self.brush.mode;
        let paint_blend = self.brush.blend;
        // Color Settings ▸ Advanced ▸ Blend RGB Colors Using Gamma also covers
        // painting in Normal mode (Photoshop: "blend or paint layers").
        let paint_space = self.active_blend_space();
        let paint_gamma = paint_space.rgb.as_deref().filter(|_| paint_blend == BlendMode::Normal);
        let (paint_behind, paint_clear) = (self.brush.behind, self.brush.clear);
        let (sponge_mode, sponge_rate, sponge_vibrance, blur_rate, sharpen_rate, sharpen_protect) = (
            self.sponge_mode,
            self.sponge_rate,
            self.sponge_vibrance,
            self.blur_rate,
            self.sharpen_rate,
            self.sharpen_protect,
        );
        let (bg_tol, bg_protect_fg) = (self.bg_tolerance, self.bg_protect_fg);
        let bg_limits = self.bg_limits;
        let (mixer_wet, mixer_load, mixer_mix) = (self.mixer_wet, self.mixer_load, self.mixer_mix);
        // Sample All Layers (stroke_begin froze the stack beneath this layer): the
        // retouch brushes read the merged colour and deposit through source-over.
        let sample_all = matches!(mode, 4 | 9 | 10 | 11)
            && self.retouch_src.len() == (w * h * 4) as usize;
        let cr_blend = self.color_replace_blend;
        let clone = self.clone_enabled;
        // History Brush (mode 12): source each pixel from the frozen `history_source`
        // snapshot at the SAME index (no offset), so it falls through the default
        // composite_over path → bit-exact revert at full opacity/flow/hardness. The
        // size check guards a crop that changed the layer between Set Source and now.
        let history = mode == 12;
        let history_ok = self.history_source_matches_active_layer();
        let history_bounds = self.history_source_bounds;
        let filter_masking = self.painting_filter_mask();
        let masking = self.painting_mask();
        let (cdx, cdy) = (self.clone_dx, self.clone_dy);
        let (clone_sw, clone_sh, clone_affine) =
            (self.clone_src_w, self.clone_src_h, self.clone_affine);
        let (clone_persp, clone_h, clone_h_inv, clone_du, clone_dv) = (
            self.clone_persp,
            self.clone_h,
            self.clone_h_inv,
            self.clone_du,
            self.clone_dv,
        );
        let br = color[0] as f32 / 255.0;
        let bg = color[1] as f32 / 255.0;
        let bb = color[2] as f32 / 255.0;
        let ba = color[3] as f32 / 255.0;
        let (dodge_range, dodge_exposure, protect_tones) =
            (self.dodge_range, self.dodge_exposure, self.protect_tones);

        // Heal (mode 5): blend the sampled patch in through a gradient-domain
        // boundary solve — the SAME `HealMembrane` Camera Raw's spot tool uses.
        // The membrane is the harmonic function that equals the residual
        // (destination − source) on the dab's rim and decays inward, so the
        // patch keeps its own texture while its tone bends to meet whatever it
        // landed on. The old constant mean offset over the footprint was this
        // membrane's n = 0 term alone, which left a hard edge across a gradient.
        //
        // ponytail: solved on the dab's bounding disc, so a roundness < 1 tip
        // probes outside its own footprint. Map the ellipse conformally if
        // anyone ever heals with a squashed tip.
        let heal_membrane = (mode == 5 && clone).then(|| {
            let dest = &self.layers[self.active].pixels;
            let clone_src = &self.clone_src;
            HealMembrane::from_boundary(radius, |ox, oy| {
                // Probes are clamped into the plane rather than dropped: the
                // closed form needs every one of them. A probe whose SOURCE
                // falls off canvas contributes a zero residual, which only
                // damps the correction toward the old no-op.
                let px = ((cx + ox).round() as i32).clamp(plane.x, plane.x + plane.w as i32 - 1);
                let py = ((cy + oy).round() as i32).clamp(plane.y, plane.y + plane.h as i32 - 1);
                let (Some(di), Some(patch)) = (
                    checked_plane_index(plane, px, py, 4),
                    sample_clone_src(
                        clone_src, clone_sw, clone_sh, clone_persp, clone_h, clone_h_inv,
                        clone_du, clone_dv, cdx, cdy, clone_affine, px, py,
                    ),
                ) else {
                    return [0.0; 3];
                };
                [
                    dest[di] as f32 / 65535.0 - patch[0],
                    dest[di + 1] as f32 / 65535.0 - patch[1],
                    dest[di + 2] as f32 / 65535.0 - patch[2],
                ]
            })
        });
        // Healing Brush ▸ Diffusion (Photoshop 1..7): how fast the patch falls
        // off into its surroundings. 1 carries the transplant at full strength
        // to the rim (grain / fine detail, and the exponent is 0 so the tip's
        // own falloff is untouched); 7 ramps it in gradually (smooth skin, sky).
        let heal_diffusion_exp = if mode == 5 && clone {
            (self.heal_diffusion.clamp(1, 7) - 1) as f32 * 0.5
        } else {
            0.0
        };

        // Smudge (mode 4): initialize the carried color once per stroke. Finger
        // Painting seeds it from the foreground colour (as if the finger were dipped
        // in paint); otherwise from the canvas pixel under the stamp center.
        if mode == 4 && !self.smudge_init {
            if self.smudge_finger {
                // The brush colour carries the current foreground (pushBrush loads it
                // via set_brush every stroke), the same colour the paint brush deposits.
                self.smudge_color = [
                    self.brush.color[0] as f32 / 255.0,
                    self.brush.color[1] as f32 / 255.0,
                    self.brush.color[2] as f32 / 255.0,
                    self.brush.color[3] as f32 / 255.0,
                ];
            } else {
                let cj = (cx as i32).clamp(0, w - 1);
                let ci = (cy as i32).clamp(0, h - 1);
                if let Some(p) = checked_plane_index(plane, cj, ci, 4) {
                    let c = self.retouch_pixel(sample_all, cj, ci, p);
                    self.smudge_color = [c.r, c.g, c.b, c.a];
                }
            }
            self.smudge_init = true;
        }
        let smudge = self.smudge_color;

        // Background Eraser (mode 7): the key colour by Sampling mode — Continuous
        // reads under the brush center every dab, Once on the stroke's first dab,
        // Background Swatch takes the swatch. Dabs erase only pixels matching it.
        if mode == 7 {
            if self.bg_sampling == 2 {
                self.bg_eraser_color = [
                    self.bg[0] as f32 / 255.0,
                    self.bg[1] as f32 / 255.0,
                    self.bg[2] as f32 / 255.0,
                ];
            } else if self.bg_sampling == 0 || !self.bg_eraser_init {
                let cj = (cx as i32).clamp(0, w - 1);
                let ci = (cy as i32).clamp(0, h - 1);
                if let Some(p) = checked_plane_index(plane, cj, ci, 4) {
                    let px = &self.layers[self.active].pixels;
                    self.bg_eraser_color = [
                        px[p] as f32 / 65535.0,
                        px[p + 1] as f32 / 65535.0,
                        px[p + 2] as f32 / 65535.0,
                    ];
                }
            }
            self.bg_eraser_init = true;
        }
        let bg_col = self.bg_eraser_color;
        let bg_key_match = |base: &[u16], scale: f32| -> bool {
            let dr = base[0] as f32 / 65535.0 - bg_col[0];
            let dg = base[1] as f32 / 65535.0 - bg_col[1];
            let db = base[2] as f32 / 65535.0 - bg_col[2];
            (dr * dr + dg * dg + db * db).sqrt() <= bg_tol * 1.732 * scale
        };
        // Limits: which matching pixels of this dab may erase. Contiguous keeps the
        // 4-connected region around the hotspot (a flood over the footprint bbox);
        // Find Edges adds the 1px ring of not-quite-matching pixels touching that
        // region (within twice the tolerance), taking the anti-aliased fringe with
        // the background so the object's edge stays crisp instead of haloed.
        // ponytail: one-pixel dilation stands in for edge detection; grow it into
        // a gradient-snapped boundary if hair-fine edges ever need it.
        //
        // Only for a dab that actually reaches the eraser branch below. A mask or
        // Quick Mask stroke never does — and `stroke_begin` takes its own branch
        // for those and leaves `stroke_base` EMPTY, so flooding it here indexed an
        // empty buffer and panicked mid-`&mut self`: the exact trap documented on
        // `painting_mask`. The same flag then picks the branch below, so the two
        // can no longer disagree. `bg_reach` is a dab-local bbox buffer on stride
        // `bw` (= bounds.w); the canvas-stride selection read stays where it was.
        let bg_flood = mode == 7 && bg_limits > 0 && !masking && !self.qm_on;
        let bw = (x1 - x0 + 1) as usize;
        let mut bg_reach: Vec<bool> = Vec::new();
        if bg_flood {
            bg_reach = vec![false; bw * (y1 - y0 + 1) as usize];
            let local = |xx: i32, yy: i32| ((yy - y0) as usize) * bw + (xx - x0) as usize;
            let matches_at = |xx: i32, yy: i32, scale: f32| {
                checked_plane_index(plane, xx, yy, 4)
                    .is_some_and(|p| bg_key_match(&self.stroke_base[p..p + 4], scale))
            };
            let (hx, hy) = ((cx as i32).clamp(x0, x1), (cy as i32).clamp(y0, y1));
            let mut stack = Vec::new();
            if matches_at(hx, hy, 1.0) {
                bg_reach[local(hx, hy)] = true;
                stack.push((hx, hy));
            }
            while let Some((xx, yy)) = stack.pop() {
                for (nx, ny) in [(xx - 1, yy), (xx + 1, yy), (xx, yy - 1), (xx, yy + 1)] {
                    if nx < x0 || nx > x1 || ny < y0 || ny > y1 || bg_reach[local(nx, ny)] {
                        continue;
                    }
                    if matches_at(nx, ny, 1.0) {
                        bg_reach[local(nx, ny)] = true;
                        stack.push((nx, ny));
                    }
                }
            }
            if bg_limits == 2 {
                let core = bg_reach.clone();
                for yy in y0..=y1 {
                    for xx in x0..=x1 {
                        let touches = [(xx - 1, yy), (xx + 1, yy), (xx, yy - 1), (xx, yy + 1)]
                            .into_iter()
                            .any(|(nx, ny)| {
                                nx >= x0 && nx <= x1 && ny >= y0 && ny <= y1 && core[local(nx, ny)]
                            });
                        if !core[local(xx, yy)] && touches && matches_at(xx, yy, 2.0) {
                            bg_reach[local(xx, yy)] = true;
                        }
                    }
                }
            }
        }

        // Blur (9) / Sharpen (10) / Mixer (11): the brush-footprint mean RGB. Blur
        // blends each pixel toward it, Sharpen away from it, and the Mixer samples
        // it as the canvas colour it picks up + deposits. Computed once per dab from
        // the live pixels (skipping fully-transparent ones).
        let mut focus_mean = [0f32; 3];
        if mode == 9 || mode == 10 || mode == 11 {
            let (mut sm, mut cnt) = ([0f32; 3], 0f32);
            for yy in y0..=y1 {
                for xx in x0..=x1 {
                    let ndx = (xx as f32 + 0.5 - cx) / radius;
                    let ndy = (yy as f32 + 0.5 - cy) / radius;
                    if ndx * ndx + ndy * ndy > 1.0 {
                        continue;
                    }
                    let Some(p) = checked_plane_index(plane, xx, yy, 4) else {
                        continue;
                    };
                    let c = self.retouch_pixel(sample_all, xx, yy, p);
                    if c.a <= 0.0 {
                        continue;
                    }
                    sm[0] += c.r;
                    sm[1] += c.g;
                    sm[2] += c.b;
                    cnt += 1.0;
                }
            }
            if cnt > 0.0 {
                for k in 0..3 {
                    focus_mean[k] = sm[k] / cnt;
                }
            }
        }

        // Mixer (mode 11): load the reservoir on the first dab — blend the
        // foreground paint with the canvas colour under the brush by Load
        // (load=1 → pure foreground, load=0 → straight canvas, no paint). A
        // cleaned, not reloaded brush takes canvas colour only.
        if mode == 11 && !self.mixer_init {
            let load = if self.mixer_empty { 0.0 } else { mixer_load };
            self.mixer_reservoir = [
                focus_mean[0] + (br - focus_mean[0]) * load,
                focus_mean[1] + (bg - focus_mean[1]) * load,
                focus_mean[2] + (bb - focus_mean[2]) * load,
            ];
            self.mixer_init = true;
            self.mixer_empty = false;
        }
        let reservoir = self.mixer_reservoir;
        self.ensure_stroke_acc(x0, y0, x1, y1);

        for y in y0..=y1 {
            for x in x0..=x1 {
                // Custom tip alpha REPLACES the round falloff; otherwise the radial
                // distance + procedural falloff. Both cull the dab via falloff<=0
                // (the tip returns 0 outside the scaled bitmap, the disc when d>1).
                let falloff = if use_tip {
                    sample_tip_alpha(
                        &self.brush_tip,
                        self.brush_tip_w,
                        self.brush_tip_h,
                        x,
                        y,
                        cx,
                        cy,
                        scaled_w,
                        scaled_h,
                    )
                } else if block {
                    // Block eraser: a hard, aliased square at the brush size —
                    // full coverage inside, nothing outside (Chebyshev cutoff).
                    let dx = (x as f32 + 0.5 - cx).abs();
                    let dy = (y as f32 + 0.5 - cy).abs();
                    if dx > radius || dy > radius {
                        continue;
                    }
                    1.0
                } else {
                    let dx = (x as f32 + 0.5 - cx) / radius;
                    let dy = (y as f32 + 0.5 - cy) / radius;
                    // Rotate into the tip's frame, then stretch the minor axis so a
                    // roundness < 1 disc becomes an ellipse (major axis = radius).
                    let rx = dx * cos_a + dy * sin_a;
                    let ry = (-dx * sin_a + dy * cos_a) / roundness;
                    let d = (rx * rx + ry * ry).sqrt();
                    if d > 1.0 {
                        continue;
                    }
                    brush_falloff(d, hardness)
                };
                if falloff <= 0.0 {
                    continue;
                }
                // Diffusion ramp (heal only; exponent 0 everywhere else).
                let falloff = if heal_diffusion_exp > 0.0 {
                    let ndx = (x as f32 + 0.5 - cx) / radius;
                    let ndy = (y as f32 + 0.5 - cy) / radius;
                    let d = (ndx * ndx + ndy * ndy).sqrt().min(1.0);
                    let ramp = (1.0 - d).powf(heal_diffusion_exp);
                    if ramp <= 0.0 {
                        continue;
                    }
                    falloff * ramp
                } else {
                    falloff
                };
                // `i` is the CANVAS index — it addresses sel, stroke_acc, quick_mask,
                // stroke_base_mask and the layer mask, all of which are canvas-sized.
                // `pi` is the same point translated into the layer's own PLANE, and it
                // is the only correct index for `pixels` and `stroke_base` (a clone of
                // `pixels`). Conflating the two painted at the wrong offset after a
                // layer Move and ran off the buffer after a Canvas Size enlarge. (#43)
                let i = (y * w + x) as usize;
                let sel_cov = self.sel.coverage(i);
                if sel_cov <= 0.0 {
                    continue;
                }
                let history_index = if history {
                    if !history_ok {
                        continue;
                    }
                    let Some(bounds) = history_bounds else {
                        continue;
                    };
                    let Some(index) = checked_plane_index(bounds, x, y, 4) else {
                        continue;
                    };
                    Some(index)
                } else {
                    None
                };

                // Quick Mask: write the brush coverage into the quick_mask buffer
                // (255 = selected). The foreground luminance is the paint target —
                // black → 0 (adds rubylith / removes from selection), white → 255
                // (clears it). Bypasses every brush-mode behaviour and the layer.
                if self.qm_on {
                    let dab = (flow * falloff * sel_cov).clamp(0.0, 1.0);
                    let cap = opacity * sel_cov;
                    let cov = self.bump_stroke_acc(x, y, dab, cap);
                    let pv = 0.299 * br + 0.587 * bg + 0.114 * bb;
                    let base_qm = self.stroke_base_mask[i] as f32 / 255.0;
                    self.quick_mask[i] = color::to8(base_qm + (pv - base_qm) * cov);
                    continue;
                }

                // Mask editing: paint the brush-color luminance into the mask.
                // The Adjustment Brush forces white (reveal) via `mask_reveal`.
                // Runs before the pixel branches: a masked non-pixel layer has no
                // plane to index, and the mask is the stroke's target regardless
                // of brush mode.
                if masking {
                    let dab = (flow * falloff * sel_cov).clamp(0.0, 1.0);
                    let cap = opacity * sel_cov;
                    let cov = self.bump_stroke_acc(x, y, dab, cap);
                    let pv = if self.mask_reveal {
                        1.0
                    } else {
                        0.299 * br + 0.587 * bg + 0.114 * bb
                    };
                    let base_m = self.stroke_base_mask[i] as f32 / 255.0;
                    let next = color::to8(base_m + (pv - base_m) * cov);
                    if filter_masking {
                        // The composite only changes once the stack re-runs, so
                        // the smart layer is re-rendered at stroke_end.
                        self.layers[self.active].smart_mask[i] = next;
                        continue;
                    }
                    if self.layers[self.active].mask[i] != next {
                        Arc::make_mut(&mut self.layers[self.active].mask)[i] = next;
                        self.layers[self.active].psd_mask = None;
                    }
                    continue;
                }
                let Some(pi) = checked_plane_index(plane, x, y, 4) else {
                    continue;
                };

                // Smudge: drag the carried color into the live pixels.
                if mode == 4 {
                    let amount = (flow * falloff * sel_cov).clamp(0.0, 1.0);
                    let bp = pi;
                    if sample_all {
                        // Deposit the carried colour at the dab's strength over the
                        // layer pixel (the in-place lerp below on an opaque layer),
                        // so an empty layer above the stack receives the smear.
                        let base = Rgba::from_u16(&self.layers[self.active].pixels[bp..bp + 4]);
                        let dab = Rgba::new(smudge[0], smudge[1], smudge[2], smudge[3] * amount);
                        composite_over(base, dab, BlendMode::Normal, 1.0)
                            .to_u16(&mut Arc::make_mut(&mut self.layers[self.active].pixels)[bp..bp + 4]);
                        continue;
                    }
                    let p = &mut Arc::make_mut(&mut self.layers[self.active].pixels)[bp..bp + 4];
                    for k in 0..4 {
                        let cur = p[k] as f32 / 65535.0;
                        p[k] = color::to16(cur + (smudge[k] - cur) * amount);
                    }
                    continue;
                }

                // Sponge (8) / Blur (9) / Sharpen (10): mutate the live RGB directly
                // (alpha preserved), scaled by the per-tool rate. Like Smudge, these
                // do not use the stroke accumulator — overlapping dabs intensify.
                if mode == 8 || mode == 9 || mode == 10 {
                    let rate = match mode {
                        8 => sponge_rate,
                        9 => blur_rate,
                        _ => sharpen_rate,
                    };
                    let amount = (flow * falloff * sel_cov * rate).clamp(0.0, 1.0);
                    let bp = pi;
                    if sample_all {
                        // Blur / Sharpen over the merged colour: the full-strength
                        // result (rate folded into the target) deposited at the dab's
                        // coverage — the in-place lerp below on an opaque layer, and
                        // the retouch itself landing on an empty one.
                        let cur = self.retouch_pixel(true, x, y, bp);
                        let cov = (flow * falloff * sel_cov).clamp(0.0, 1.0) * cur.a;
                        let (c, m) = ([cur.r, cur.g, cur.b], focus_mean);
                        let target = if mode == 9 {
                            [0, 1, 2].map(|k| c[k] + (m[k] - c[k]) * rate)
                        } else {
                            let r2 = if sharpen_protect {
                                rate * color::lum(cur.r, cur.g, cur.b)
                            } else {
                                rate
                            };
                            [0, 1, 2].map(|k| (c[k] + (c[k] - m[k]) * r2).clamp(0.0, 1.0))
                        };
                        let base = Rgba::from_u16(&self.layers[self.active].pixels[bp..bp + 4]);
                        let dab = Rgba::new(target[0], target[1], target[2], cov);
                        composite_over(base, dab, BlendMode::Normal, 1.0)
                            .to_u16(&mut Arc::make_mut(&mut self.layers[self.active].pixels)[bp..bp + 4]);
                        continue;
                    }
                    let p = &mut Arc::make_mut(&mut self.layers[self.active].pixels)[bp..bp + 4];
                    let (r0, g0, b0) = (
                        p[0] as f32 / 65535.0,
                        p[1] as f32 / 65535.0,
                        p[2] as f32 / 65535.0,
                    );
                    let (nr, ng, nb) = if mode == 8 {
                        let (hh, ss, vv) = color::rgb_to_hsv(r0, g0, b0);
                        let target = if sponge_mode == 1 { 0.0 } else { 1.0 };
                        // Vibrance (Photoshop default): weight the move by how far
                        // the pixel still is from the target extreme, so already
                        // saturated/desaturated pixels are protected from clipping.
                        // Same (1-s)-style shape as the Vibrance adjustment.
                        let w = if sponge_vibrance {
                            (target - ss).abs()
                        } else {
                            1.0
                        };
                        let ns = (ss + (target - ss) * amount * w).clamp(0.0, 1.0);
                        color::hsv_to_rgb(hh, ns, vv)
                    } else if mode == 9 {
                        (
                            r0 + (focus_mean[0] - r0) * amount,
                            g0 + (focus_mean[1] - g0) * amount,
                            b0 + (focus_mean[2] - b0) * amount,
                        )
                    } else {
                        // Sharpen: push away from the local mean; Protect dampens the
                        // boost in shadows (scaled by luminance).
                        let a2 = if sharpen_protect {
                            amount * color::lum(r0, g0, b0)
                        } else {
                            amount
                        };
                        (
                            (r0 + (r0 - focus_mean[0]) * a2).clamp(0.0, 1.0),
                            (g0 + (g0 - focus_mean[1]) * a2).clamp(0.0, 1.0),
                            (b0 + (b0 - focus_mean[2]) * a2).clamp(0.0, 1.0),
                        )
                    };
                    p[0] = color::to16(nr);
                    p[1] = color::to16(ng);
                    p[2] = color::to16(nb);
                    continue;
                }

                // Mixer Brush (11): deposit a blend of the carried reservoir paint
                // and the sampled canvas colour (Mix = reservoir fraction → high mix
                // favours the reservoir), weighted by Wet·flow·falloff·coverage.
                // Like Smudge, this mutates the live RGB in place (alpha preserved)
                // so colours smear/build along the stroke; the reservoir is pulled
                // toward the canvas by Wet once per dab (below) to carry colour forward.
                if mode == 11 {
                    // Wet is the deposit strength, exactly as it always was: every
                    // wet > 0 deposits bit-for-bit what it did before this option
                    // group existed. Wet 0 alone used to be a total no-op (amount
                    // 0, nothing written), and that is where PS's Dry preset lands,
                    // so a dry brush now lays its reservoir share instead.
                    // ponytail: the dry share is Mix, ignoring Load's dilution;
                    // fold Load in if a half-loaded dry brush ever needs to be paler.
                    let strength = if mixer_wet > 0.0 { mixer_wet } else { mixer_mix };
                    let amount = (strength * flow * falloff * sel_cov).clamp(0.0, 1.0);
                    let bp = pi;
                    let dep = [0, 1, 2].map(|k| focus_mean[k] + (reservoir[k] - focus_mean[k]) * mixer_mix);
                    if sample_all {
                        // The deposit's opacity: reservoir paint is opaque, the sampled
                        // canvas share only as opaque as the merged image there.
                        let cur = self.retouch_pixel(true, x, y, bp);
                        let a = amount * (mixer_mix + (1.0 - mixer_mix) * cur.a);
                        let base = Rgba::from_u16(&self.layers[self.active].pixels[bp..bp + 4]);
                        composite_over(base, Rgba::new(dep[0], dep[1], dep[2], a), BlendMode::Normal, 1.0)
                            .to_u16(&mut Arc::make_mut(&mut self.layers[self.active].pixels)[bp..bp + 4]);
                        continue;
                    }
                    let p = &mut Arc::make_mut(&mut self.layers[self.active].pixels)[bp..bp + 4];
                    for k in 0..3 {
                        let cur = p[k] as f32 / 65535.0;
                        p[k] = color::to16(cur + (dep[k] - cur) * amount);
                    }
                    continue;
                }

                let dab = (flow * falloff * sel_cov).clamp(0.0, 1.0);
                let cap = opacity * sel_cov;
                let cov = self.bump_stroke_acc(x, y, dab, cap);

                // Per-pixel paint color: History snapshot, clone-source sample, or
                // the brush color. History sources at the same index (no offset).
                let (cr, cg, cb, ca) = if history {
                    let sp = history_index.expect("history index was checked");
                    (
                        self.history_source[sp] as f32 / 65535.0,
                        self.history_source[sp + 1] as f32 / 65535.0,
                        self.history_source[sp + 2] as f32 / 65535.0,
                        self.history_source[sp + 3] as f32 / 65535.0,
                    )
                } else if clone {
                    let Some(src) = sample_clone_src(
                        &self.clone_src,
                        clone_sw,
                        clone_sh,
                        clone_persp,
                        clone_h,
                        clone_h_inv,
                        clone_du,
                        clone_dv,
                        cdx,
                        cdy,
                        clone_affine,
                        x,
                        y,
                    ) else {
                        continue;
                    };
                    let heal = heal_membrane.as_ref().map_or([0.0; 3], |m| {
                        m.correction(x as f32 + 0.5 - cx, y as f32 + 0.5 - cy)
                    });
                    (
                        (src[0] + heal[0]).clamp(0.0, 1.0),
                        (src[1] + heal[1]).clamp(0.0, 1.0),
                        (src[2] + heal[2]).clamp(0.0, 1.0),
                        src[3],
                    )
                } else {
                    (br, bg, bb, ba)
                };

                let bp = pi;
                let base = Rgba::from_u16(&self.stroke_base[bp..bp + 4]);
                let outp = &mut Arc::make_mut(&mut self.layers[self.active].pixels)[bp..bp + 4];
                match mode {
                    1 => {
                        // erase: reduce base alpha by coverage
                        let na = base.a * (1.0 - cov);
                        outp[0] = color::to16(base.r);
                        outp[1] = color::to16(base.g);
                        outp[2] = color::to16(base.b);
                        outp[3] = color::to16(na);
                    }
                    2 | 3 => {
                        // Dodge (2 lighten) / Burn (3 darken), Photoshop-style.
                        // The adjustment is weighted by how much the pixel's
                        // luminance falls in the selected tonal Range (Adobe:
                        // shadows 0–85, midtones 85–170, highlights 170–255),
                        // scaled by Exposure. Protect Tones keeps hue/saturation
                        // by scaling chroma toward the target luminance instead
                        // of pushing channels toward white/black.
                        let l = color::lum(base.r, base.g, base.b);
                        let w = match dodge_range {
                            0 => (1.0 - l) * (1.0 - l), // shadows: peak at black
                            2 => l * l,                 // highlights: peak at white
                            _ => 4.0 * l * (1.0 - l),   // midtones: peak at mid-gray
                        };
                        let s = (dodge_exposure * cov * w).clamp(0.0, 1.0);
                        let dodge = mode == 2;
                        if protect_tones {
                            // Scale every channel by the same gain toward the new
                            // luminance — preserving hue/saturation — and cap the
                            // gain at 1/max-channel so the brightest channel never
                            // clips (Protect Tones "prevent clipping in highlights").
                            let l2 = if dodge {
                                l + (1.0 - l) * s
                            } else {
                                l * (1.0 - s)
                            };
                            let maxc = base.r.max(base.g).max(base.b).max(1e-4);
                            let k = if l > 1e-4 {
                                (l2 / l).min(1.0 / maxc)
                            } else {
                                1.0
                            };
                            outp[0] = color::to16((base.r * k).clamp(0.0, 1.0));
                            outp[1] = color::to16((base.g * k).clamp(0.0, 1.0));
                            outp[2] = color::to16((base.b * k).clamp(0.0, 1.0));
                        } else if dodge {
                            outp[0] = color::to16(base.r + (1.0 - base.r) * s);
                            outp[1] = color::to16(base.g + (1.0 - base.g) * s);
                            outp[2] = color::to16(base.b + (1.0 - base.b) * s);
                        } else {
                            outp[0] = color::to16(base.r * (1.0 - s));
                            outp[1] = color::to16(base.g * (1.0 - s));
                            outp[2] = color::to16(base.b * (1.0 - s));
                        }
                        outp[3] = color::to16(base.a);
                    }
                    6 => {
                        // Color Replacement: apply the foreground via `cr_blend` (the
                        // Mode — Hue / Saturation / Color / Luminosity) — the selected
                        // component(s) come from the brush, the rest from the pixel.
                        let src = Rgba::new(cr, cg, cb, ca * cov);
                        let res = composite_over(base, src, cr_blend, 1.0);
                        res.to_u16(outp);
                    }
                    7 => {
                        // Background Eraser: erase (reduce alpha) only where the base
                        // colour matches the sampled background within tolerance —
                        // Limits narrow that to the flood computed above.
                        // Protect Foreground keeps pixels close to the brush colour.
                        let matches = if bg_flood {
                            bg_reach[((y - y0) as usize) * bw + (x - x0) as usize]
                        } else {
                            bg_key_match(&self.stroke_base[bp..bp + 4], 1.0)
                        };
                        let protect = bg_protect_fg && {
                            let fr = br - base.r;
                            let fg2 = bg - base.g;
                            let fb = bb - base.b;
                            (fr * fr + fg2 * fg2 + fb * fb).sqrt() < 0.10
                        };
                        // A pixel this dab doesn't reach is left as it is: an earlier
                        // dab may have erased it under another key (Continuous) or
                        // flood (Limits), and rewriting base.a would restore it.
                        if !matches || protect {
                            continue;
                        }
                        outp[0] = color::to16(base.r);
                        outp[1] = color::to16(base.g);
                        outp[2] = color::to16(base.b);
                        outp[3] = color::to16(base.a * (1.0 - cov));
                    }
                    _ => {
                        let src = Rgba::new(cr, cg, cb, ca * cov);
                        // Paint / pencil (mode 0) honour the Brush Mode; Heal (5) and
                        // History Brush (12) fall through here too but must revert /
                        // transplant through Normal.
                        let res = if mode == 0 && paint_clear {
                            // Clear: erase this pixel's alpha by the dab coverage.
                            Rgba::new(base.r, base.g, base.b, base.a * (1.0 - ca * cov))
                        } else if mode == 0 && paint_behind {
                            // Behind: paint sits under the layer — it shows only where
                            // the pixel is (partly) transparent.
                            composite_over(src, base, BlendMode::Normal, 1.0)
                        } else if mode == 0 && paint_gamma.is_some() {
                            let decoded = composite_over(
                                gamma_decode(paint_gamma, base),
                                gamma_decode(paint_gamma, src),
                                BlendMode::Normal,
                                1.0,
                            );
                            gamma_encode(paint_gamma, decoded)
                        } else {
                            let blend = if mode == 0 { paint_blend } else { BlendMode::Normal };
                            composite_over(base, src, blend, 1.0)
                        };
                        res.to_u16(outp);
                    }
                }
            }
        }

        // Smudge: carry the color forward by sampling the (now-smeared) center.
        if mode == 4 {
            let cj = (cx as i32).clamp(0, w - 1);
            let ci = (cy as i32).clamp(0, h - 1);
            if let Some(p) = checked_plane_index(plane, cj, ci, 4) {
                let c = self.retouch_pixel(sample_all, cj, ci, p);
                let center = [c.r, c.g, c.b, c.a];
                for k in 0..4 {
                    self.smudge_color[k] += (center[k] - self.smudge_color[k]) * 0.25;
                }
            }
        }

        // Mixer: carry colour along the stroke — pull the reservoir toward the
        // canvas colour just sampled (pre-dab footprint mean) by Wet, so colours
        // smear/blend across a boundary as the brush drags through them.
        if mode == 11 {
            for k in 0..3 {
                self.mixer_reservoir[k] += (focus_mean[k] - self.mixer_reservoir[k]) * mixer_wet;
            }
        }

        [x0, y0, x1, y1]
    }

    // ── Fills ──────────────────────────────────────────────────
    pub fn fill_selection(&mut self, r: u8, g: u8, b: u8, a: u8) {
        self.fill_blend(r, g, b, a, 0);
    }

    // Edit ▸ Fill: fill the selection (or whole layer if none) with a colour,
    // using the given blend `mode` (index into BlendMode). `a` carries the
    // Opacity (a = opacity × 255). Mode 0 = Normal (the plain fill).
    pub fn fill_blend(&mut self, r: u8, g: u8, b: u8, a: u8, mode: u8) {
        self.fill_blend_inner(r, g, b, a, mode, false);
    }

    // Edit ▸ Fill with "Preserve Transparency": like fill_blend but locks the
    // layer's alpha — transparent pixels (base.a == 0) are left untouched and every
    // painted pixel keeps its original alpha (only the colour changes).
    pub fn fill_blend_preserve(&mut self, r: u8, g: u8, b: u8, a: u8, mode: u8) {
        self.fill_blend_inner(r, g, b, a, mode, true);
    }

    /// Lock Transparent Pixels is Preserve Transparency made persistent, so
    /// every path that already honours the per-invocation flag honours the lock
    /// by OR-ing it in here rather than growing a second code path.
    fn preserve_for_active(&self, requested: bool) -> bool {
        requested || self.layers[self.active].lock_transparent
    }

    /// Lock Transparent Pixels for an op whose core rewrote the active layer
    /// without knowing the lock: a pixel that was transparent goes back to
    /// exactly what it was, and every other pixel keeps its old alpha.
    fn restore_locked_transparency(&mut self, before: &[u16]) {
        let px = Arc::make_mut(&mut self.layers[self.active].pixels);
        if px.len() != before.len() {
            return;
        }
        for (p, b) in px.chunks_exact_mut(4).zip(before.chunks_exact(4)) {
            if b[3] == 0 {
                p.copy_from_slice(b);
            } else {
                p[3] = b[3];
            }
        }
    }

    /// The content-aware ops synthesize colour pixels, and with the mask
    /// targeted they rewrote the pixels behind it. Photoshop runs them on layer
    /// pixels only, so refuse and say what to target.
    fn refuse_mask_target(&mut self, label: &str) -> bool {
        if !self.painting_mask() {
            return false;
        }
        self.last_edit_error = format!("{label} writes layer pixels: target the layer, not its mask.");
        true
    }

    fn fill_blend_inner(&mut self, r: u8, g: u8, b: u8, a: u8, mode: u8, preserve: bool) {
        let preserve = self.preserve_for_active(preserve);
        if self.refuse_destructive_edit() {
            return;
        }
        if self.reject_legacy_float_edit("Fill") {
            return;
        }
        if self.push_layer_undo("Fill") {
            return;
        }
        let src = Rgba::new(
            r as f32 / 255.0,
            g as f32 / 255.0,
            b as f32 / 255.0,
            a as f32 / 255.0,
        );
        let blend = BlendMode::from_u8(mode);
        // Plane-space count and selection — see clear_selection.
        let Some(local) = self.plane_local_selection() else {
            return;
        };
        let px = Arc::make_mut(&mut self.layers[self.active].pixels);
        for i in 0..px.len() / 4 {
            let cov = local.coverage(i);
            if cov <= 0.0 {
                continue;
            }
            let bp = i * 4;
            let base = Rgba::from_u16(&px[bp..bp + 4]);
            if preserve && base.a <= 0.0 {
                continue; // Preserve Transparency: don't paint transparent pixels
            }
            let s = Rgba::new(src.r, src.g, src.b, src.a * cov);
            let mut res = composite_over(base, s, blend, 1.0);
            if preserve {
                res.a = base.a; // lock the layer's alpha
            }
            res.to_u16(&mut px[bp..bp + 4]);
        }
        self.composite();
    }

    // Edit ▸ Fill ▸ History: fill the selection (or whole layer if none) from the
    // History Brush source — the frozen snapshot captured via the History panel.
    // `opacity` is 0..255 (opacity × 255), `mode` indexes BlendMode. No-op without
    // a captured source or after a crop changed the layer size (the snapshot would
    // misalign). One undoable "Fill" step. Mirrors fill_blend_inner.
    pub fn fill_history(&mut self, opacity: u8, mode: u8) {
        if self.refuse_destructive_edit() {
            return;
        }
        if !self.history_source_matches_active_layer() {
            self.last_edit_error = "Could not fill from History because the history source no longer matches this canvas. Choose Set Source in the History panel to recapture it.".into();
            return;
        }
        if self.reject_legacy_float_edit("Fill") {
            return;
        }
        if self.push_layer_undo("Fill") {
            return;
        }
        let blend = BlendMode::from_u8(mode);
        let op = opacity as f32 / 255.0;
        let bounds = self.history_source_bounds.expect("history bounds were checked");
        let document_w = self.w as i32;
        let document_h = self.h as i32;
        let selection = &self.sel;
        let src = &self.history_source;
        let px = Arc::make_mut(&mut self.layers[self.active].pixels);
        for local_y in 0..bounds.h {
            for local_x in 0..bounds.w {
                let cov = if selection.active {
                    let x = i64::from(bounds.x) + i64::from(local_x);
                    let y = i64::from(bounds.y) + i64::from(local_y);
                    if x < 0
                        || y < 0
                        || x >= i64::from(document_w)
                        || y >= i64::from(document_h)
                    {
                        continue;
                    }
                    selection.coverage((y as i32 * document_w + x as i32) as usize)
                } else {
                    1.0
                };
                if cov <= 0.0 {
                    continue;
                }
                let bp = (local_y as usize * bounds.w as usize + local_x as usize) * 4;
                let base = Rgba::from_u16(&px[bp..bp + 4]);
                let s_full = Rgba::from_u16(&src[bp..bp + 4]);
                let s = Rgba::new(s_full.r, s_full.g, s_full.b, s_full.a * op * cov);
                let res = composite_over(base, s, blend, 1.0);
                res.to_u16(&mut px[bp..bp + 4]);
            }
        }
        self.composite();
    }

    // Red Eye tool (heal group): neutralize red-eye inside the given rectangle.
    // For each pixel `redness = r / ((g+b)/2 + eps)`; a pixel is red-eye when it is
    // bright-red enough (`r >= 0.35`) AND `redness >= 2.2 - pupil*1.2` — a higher
    // Pupil Size lowers the bar so a larger area is corrected. Caught pixels are
    // replaced with the green/blue-derived neutral (the eye's true luminance without
    // the flash) darkened by Darken Amount: `v = ((g+b)/2) * (1 - darken)`, r=g=b=v,
    // alpha unchanged. Non-red pixels are left byte-identical. One undoable op.
    // `pupil` / `darken` are 0..255 (Pupil Size / Darken Amount × 255).
    pub fn remove_red_eye(&mut self, x: i32, y: i32, w: i32, h: i32, pupil: u8, darken: u8) {
        if self.active_layer().locked || self.active_layer().kind == 4 || w <= 0 || h <= 0 {
            return;
        }
        if self.reject_legacy_float_edit("Remove Red Eye") {
            return;
        }
        if self.push_layer_undo("Red Eye") {
            return;
        }
        let pupil_f = pupil as f32 / 255.0;
        let darken_f = darken as f32 / 255.0;
        let thresh = 2.2 - pupil_f * 1.2;
        // The rect arrives in CANVAS coordinates while the buffer is the layer's
        // PLANE, which crop leaves larger than the canvas. Using the canvas stride
        // and canvas clamps walked the wrong pixels, so Red Eye did nothing on a
        // cropped document: shift the rect into plane space and stride by the plane.
        let Some((plane_w, plane_h)) = self.active_plane_dims() else {
            return;
        };
        let (dw, dh) = (plane_w as i32, plane_h as i32);
        let (org_x, org_y) = {
            let layer = &self.layers[self.active];
            (
                layer.pixel_bounds.x + layer.ox,
                layer.pixel_bounds.y + layer.oy,
            )
        };
        let x0 = (x - org_x).max(0);
        let y0 = (y - org_y).max(0);
        let x1 = (x + w - org_x).min(dw);
        let y1 = (y + h - org_y).min(dh);
        let px = Arc::make_mut(&mut self.layers[self.active].pixels);
        for py in y0..y1 {
            for px_x in x0..x1 {
                let bp = ((py * dw + px_x) as usize) * 4;
                let base = Rgba::from_u16(&px[bp..bp + 4]);
                let gb = (base.g + base.b) * 0.5;
                let redness = base.r / (gb + 1e-3);
                if base.r >= 0.35 && redness >= thresh {
                    let v = gb * (1.0 - darken_f);
                    Rgba::new(v, v, v, base.a).to_u16(&mut px[bp..bp + 4]);
                }
            }
        }
        self.composite();
    }

    // Edit ▸ Define Pattern: capture the active selection's bounding box (or the
    // whole active layer if nothing is selected) as the current pattern tile.
    // Does not modify the document.
    pub fn define_pattern(&mut self) {
        let (x, y, pw, ph) = if self.sel.active {
            let b = self.sel.bounds();
            (b[0], b[1], b[2], b[3])
        } else {
            (0, 0, self.w as i32, self.h as i32)
        };
        if pw <= 0 || ph <= 0 {
            return;
        }
        // The capture rect is in CANVAS coordinates while the buffer is the layer's
        // PLANE — translate each texel instead of striding by self.w. Texels the
        // plane does not cover stay transparent rather than reading a wrong row. (#1)
        let Some(rect) = self.plane_rect(self.active) else {
            return;
        };
        let src = &self.layers[self.active].pixels;
        let mut pat = vec![0u16; (pw * ph * 4) as usize];
        for j in 0..ph {
            for i in 0..pw {
                let Some(s) = checked_plane_index(rect, x + i, y + j, 4) else {
                    continue;
                };
                let d = (j * pw + i) as usize * 4;
                pat[d..d + 4].copy_from_slice(&src[s..s + 4]);
            }
        }
        self.pattern = pat;
        self.pattern_w = pw as u32;
        self.pattern_h = ph as u32;
        // Layer styles sample this tile (pattern kind "Defined"), and the fx
        // signature only covers the effect params — so redefining has to drop
        // the cached renders and recomposite.
        self.fx_cache.clear();
        self.composite();
    }

    pub fn has_pattern(&self) -> bool {
        !self.pattern.is_empty()
    }

    pub fn pattern_w(&self) -> u32 {
        self.pattern_w
    }

    pub fn pattern_h(&self) -> u32 {
        self.pattern_h
    }

    // The captured tile's RGBA16 texels — the TS store reads these into its named
    // pattern library after define_pattern. Mirrors brush_tip_bytes.
    pub fn pattern_bytes(&self) -> Vec<u16> {
        self.pattern.clone()
    }

    // Push a library pattern back into the slot (the TS store calls this when the
    // user picks one from the Patterns picker). Every consumer — Edit ▸ Fill ▸
    // Pattern, the Pattern Stamp, add/replace_pattern_fill, the Pattern Overlay
    // style — reads this one slot, so selecting is all any of them needs. A
    // buffer that isn't the size its dimensions claim is ignored.
    pub fn set_pattern(&mut self, w: u32, h: u32, px: &[u16]) {
        if w == 0 || h == 0 || (w as usize) * (h as usize) * 4 != px.len() {
            return;
        }
        self.pattern = px.to_vec();
        self.pattern_w = w;
        self.pattern_h = h;
        // Same reason define_pattern drops the cache: layer styles set to the
        // "Defined" pattern sample this tile, and the fx signature only covers
        // the effect params.
        self.fx_cache.clear();
        self.composite();
    }

    // The defined tile as a layer-effect pattern source, if one is captured and
    // its buffer is the size its dimensions claim.
    fn pattern_tile(&self) -> Option<effects::Tile<'_>> {
        let (w, h) = (self.pattern_w as usize, self.pattern_h as usize);
        (w > 0 && h > 0 && self.pattern.len() >= w * h * 4).then_some(effects::Tile {
            px: &self.pattern,
            w,
            h,
        })
    }

    // Edit ▸ Define Brush Preset: capture the active layer's selection bounds (or
    // the whole layer if no selection) as a custom brush TIP — a grayscale alpha
    // bitmap where alpha = (1 - lum)·src_a with Rec.601 luma. White paints
    // transparent, black fully opaque, and transparent source stays transparent
    // (the Photoshop convention). Mirrors define_pattern. Runtime-only (the TS
    // store reads the bytes back via brush_tip_bytes into its tip library).
    pub fn define_brush_from_selection(&mut self) {
        let (x, y, pw, ph) = if self.sel.active {
            let b = self.sel.bounds();
            (b[0], b[1], b[2], b[3])
        } else {
            (0, 0, self.w as i32, self.h as i32)
        };
        if pw <= 0 || ph <= 0 {
            return;
        }
        // Same canvas-rect-over-plane-buffer translation as define_pattern; texels the
        // plane does not cover stay 0 (fully transparent tip). (#2)
        let Some(rect) = self.plane_rect(self.active) else {
            return;
        };
        let src = &self.layers[self.active].pixels;
        let mut tip = vec![0u8; (pw * ph) as usize];
        for j in 0..ph {
            for i in 0..pw {
                let Some(s) = checked_plane_index(rect, x + i, y + j, 4) else {
                    continue;
                };
                let r = src[s] as f32 / 65535.0;
                let g = src[s + 1] as f32 / 65535.0;
                let b = src[s + 2] as f32 / 65535.0;
                let a = src[s + 3] as f32 / 65535.0;
                let lum = 0.299 * r + 0.587 * g + 0.114 * b; // Rec.601
                tip[(j * pw + i) as usize] = color::to8((1.0 - lum) * a);
            }
        }
        self.brush_tip = tip;
        self.brush_tip_w = pw as u32;
        self.brush_tip_h = ph as u32;
    }

    // Whether a custom brush tip has been captured (gates the tip paint path).
    pub fn has_brush_tip(&self) -> bool {
        !self.brush_tip.is_empty()
    }

    pub fn brush_tip_w(&self) -> u32 {
        self.brush_tip_w
    }

    pub fn brush_tip_h(&self) -> u32 {
        self.brush_tip_h
    }

    // The captured tip's alpha bytes (one u8 per texel) — the TS store reads these
    // into its tip library after define_brush_from_selection.
    pub fn brush_tip_bytes(&self) -> Vec<u8> {
        self.brush_tip.clone()
    }

    // Push a saved tip back into the engine (the TS store calls this when the user
    // selects a tip from the Brushes panel). A length mismatch is ignored.
    pub fn set_brush_tip(&mut self, w: u32, h: u32, alpha: &[u8]) {
        if (w as usize) * (h as usize) != alpha.len() {
            return;
        }
        self.brush_tip = alpha.to_vec();
        self.brush_tip_w = w;
        self.brush_tip_h = h;
    }

    // Toggle whether the active tip REPLACES the round falloff on the normal paint
    // path (false → the procedural round brush).
    pub fn set_brush_tip_active(&mut self, on: bool) {
        self.brush_tip_active = on;
    }

    // Edit ▸ Fill ▸ Pattern: tile the defined pattern across the active layer
    // (within the selection), aligned to the document origin, with a blend
    // Mode + Opacity. No-op without a defined pattern.
    pub fn fill_pattern(&mut self, opacity: u8, mode: u8) {
        self.fill_pattern_inner(opacity, mode, false);
    }

    // Edit ▸ Fill (Pattern) with "Preserve Transparency": as fill_pattern but locks
    // the layer's alpha (transparent pixels untouched; alpha kept). See fill_blend_preserve.
    pub fn fill_pattern_preserve(&mut self, opacity: u8, mode: u8) {
        self.fill_pattern_inner(opacity, mode, true);
    }

    fn fill_pattern_inner(&mut self, opacity: u8, mode: u8, preserve: bool) {
        let preserve = self.preserve_for_active(preserve);
        if self.pattern.is_empty() || self.refuse_destructive_edit() {
            return;
        }
        if self.reject_legacy_float_edit("Pattern Fill") {
            return;
        }
        let Some(rect) = self.plane_rect(self.active) else {
            return;
        };
        let Some(local) = self.plane_local_selection() else {
            return;
        };
        if self.push_layer_undo("Fill Pattern") {
            return;
        }
        let (pw, ph) = (self.pattern_w as i32, self.pattern_h as i32);
        let (w, h) = (rect.w as i32, rect.h as i32);
        let blend = BlendMode::from_u8(mode);
        let alpha = opacity as f32 / 255.0;
        let pat = self.pattern.clone();
        let px = Arc::make_mut(&mut self.layers[self.active].pixels);
        for y in 0..h {
            for x in 0..w {
                let i = (y * w + x) as usize;
                let cov = local.coverage(i);
                if cov <= 0.0 {
                    continue;
                }
                let bp = i * 4;
                let base = Rgba::from_u16(&px[bp..bp + 4]);
                if preserve && base.a <= 0.0 {
                    continue; // Preserve Transparency: don't paint transparent pixels
                }
                let (Some(cx), Some(cy)) = (rect.x.checked_add(x), rect.y.checked_add(y)) else {
                    continue;
                };
                let pi = (cy.rem_euclid(ph) * pw + cx.rem_euclid(pw)) as usize * 4;
                let mut s = Rgba::from_u16(&pat[pi..pi + 4]);
                s.a *= alpha * cov;
                let mut res = composite_over(base, s, blend, 1.0);
                if preserve {
                    res.a = base.a; // lock the layer's alpha
                }
                res.to_u16(&mut px[bp..bp + 4]);
            }
        }
        self.composite();
    }

    // Edit ▸ Fade: blend the active layer's last pixel edit back toward the
    // state before it, at `opacity` (0..1) with a blend `mode`. Reads the
    // pre-op pixels from the top undo snapshot, so it must immediately follow a
    // fadeable op on the active layer (no-op otherwise). Photoshop parity.
    pub fn fade_last(&mut self, opacity: f32, mode: u8) {
        if self.reject_legacy_float_edit("Fade Last") {
            return;
        }
        let active_id = self.active_layer().id;
        let before = match self.undo.last() {
            Some(UndoEntry {
                snap: Snap::LayerPx { id, px, .. },
                ..
            }) if *id == active_id => px.clone(),
            _ => return,
        };
        if before.len() != self.layers[self.active].pixels.len() {
            return;
        }
        if self.push_layer_undo("Fade") {
            return;
        }
        let blend = BlendMode::from_u8(mode);
        let opacity = opacity.clamp(0.0, 1.0);
        let cur = self.layers[self.active].pixels.clone();
        let n = before.len() / 4;
        let px = Arc::make_mut(&mut self.layers[self.active].pixels);
        for i in 0..n {
            let bp = i * 4;
            let base = Rgba::from_u16(&before[bp..bp + 4]); // before the op
            let src = Rgba::from_u16(&cur[bp..bp + 4]); // the applied (full-strength) result
            let res = composite_over(base, src, blend, opacity);
            res.to_u16(&mut px[bp..bp + 4]);
        }
        self.composite();
    }

    // Whether Edit ▸ Fade is available (the last op was a fadeable pixel edit on
    // the active layer).
    pub fn can_fade(&self) -> bool {
        matches!(self.undo.last(),
            Some(UndoEntry { label, snap: Snap::LayerPx { id, .. }, .. })
                if *id == self.active_layer().id && label != "Fade")
    }

    // Edit ▸ Clear / plain Delete in Photoshop: the selected pixels become
    // transparent. A no-op without a selection (Photoshop disables Clear).
    pub fn clear_selection(&mut self) {
        if !self.sel.active {
            return;
        }
        if self.refuse_destructive_edit() {
            return;
        }
        if self.reject_legacy_float_edit("Clear Selection") {
            return;
        }
        if self.push_layer_undo("Clear") {
            return;
        }
        // Both the count and the selection lookup are PLANE-space: the canvas count
        // touched only the first w*h pixels of a larger plane, and a canvas-indexed
        // selection cleared the wrong ones.
        let Some(local) = self.plane_local_selection() else {
            return;
        };
        let px = Arc::make_mut(&mut self.layers[self.active].pixels);
        for i in 0..px.len() / 4 {
            let cov = local.coverage(i);
            if cov <= 0.0 {
                continue;
            }
            let a = &mut px[i * 4 + 3];
            *a = (*a as f32 * (1.0 - cov)).round() as u16;
        }
        self.composite();
    }

    // Content-Aware Fill — harmonic (diffusion) inpaint of the selection on the
    // active layer, propagating surrounding color inward. Good for smooth regions.
    // Generative / Content-Aware Synthesis fill — exemplar-based inpainting
    // (the classical, non-ML analog of Generative Fill): peel the selection from
    // its boundary inward, and for each pixel copy the center of the best-matching
    // patch sampled from the known region (texture synthesis).
    pub fn generative_fill(&mut self) {
        if !self.sel.active || self.active_layer().locked || self.active_layer().kind == 4 {
            return;
        }
        if self.reject_legacy_float_edit("Generative Fill") {
            return;
        }
        if self.plane_local_selection().is_none() {
            return;
        }
        if self.push_layer_undo("Generative Fill") {
            return;
        }
        self.ai_generated = true; // synthesized pixels — Content Credentials must say so
        self.exemplar_fill_active_selection(false);
        self.composite();
    }

    /// Exemplar-based inpaint of the active selection, in place — the shared core
    /// behind Generative Fill and the Spot Healing Brush's Content-Aware / Create
    /// Texture types. Peels the hole from its boundary inward, filling each
    /// frontier pixel from a donor patch in the known region. `randomize` picks
    /// that donor at random instead of by best patch match: structure stops being
    /// continued and the hole is rebuilt as texture, which is exactly Photoshop's
    /// "Create Texture". Pushes no undo and does not composite; the caller owns
    /// the history step and the repaint.
    fn exemplar_fill_active_selection(&mut self, randomize: bool) {
        self.exemplar_fill_with(randomize, None, 0, 0, false, false);
    }

    /// The exemplar core. `donor` (plane-sized) limits the candidate patches to
    /// the Content-Aware Fill workspace's Sampling Area; `None` samples every
    /// known pixel exactly as before the workspace existed. Each candidate gets
    /// one random transform from the adaptations — `rotation` 0..4 (None / Low /
    /// Medium / High / Full), `scale` (0.8–1.25×) and `mirror` — and `color` 0..3
    /// (None / Default / High / Very High) shifts the copied pixel by that share
    /// of the gap between the target's and the donor's patch means. With every
    /// adaptation off no extra random number is drawn, so the result is the
    /// untransformed search. Returns whether anything was written.
    // ponytail: one random transform per candidate keeps cost flat; PatchMatch if quality demands
    fn exemplar_fill_with(
        &mut self,
        randomize: bool,
        donor: Option<&[bool]>,
        color: u32,
        rotation: u32,
        scale: bool,
        mirror: bool,
    ) -> bool {
        let Some(local) = self.plane_local_selection() else {
            return false;
        };
        let (w, h) = (local.w as i32, local.h as i32);
        let n = (w * h) as usize;
        let mut known = vec![true; n];
        let mut hole = 0;
        for i in 0..n {
            if local.coverage(i) > 0.5 {
                known[i] = false;
                hole += 1;
            }
        }
        if hole == 0 {
            return false;
        }
        let mut px = self.layers[self.active].pixels.to_vec();
        // candidate source pixels: a random subset of known interior pixels
        let pr = EXEMPLAR_PATCH_RADIUS;
        let interior = |x: i32, y: i32| x >= pr && y >= pr && x < w - pr && y < h - pr;
        let mut cands: Vec<(i32, i32)> = Vec::new();
        let mut rng = self.rng | 1;
        let mut next = || {
            rng ^= rng << 13;
            rng ^= rng >> 17;
            rng ^= rng << 5;
            rng
        };
        if let Some(d) = donor {
            // Drawn from the enumerated Sampling Area: random probes would miss
            // a small painted patch in a large plane and find nothing.
            let pool: Vec<(i32, i32)> = (0..h)
                .flat_map(|y| (0..w).map(move |x| (x, y)))
                .filter(|&(x, y)| interior(x, y) && d[(y * w + x) as usize] && known[(y * w + x) as usize])
                .collect();
            while cands.len() < 400.min(pool.len()) {
                cands.push(pool[next() as usize % pool.len()]);
            }
        } else {
            let want = 400.min(n);
            let mut tries = 0;
            while cands.len() < want && tries < want * 8 {
                tries += 1;
                let x = (next() % w as u32) as i32;
                let y = (next() % h as u32) as i32;
                if interior(x, y) && known[(y * w + x) as usize] {
                    cands.push((x, y));
                }
            }
        }
        if cands.is_empty() {
            return false;
        }
        // Where each patch offset lands in each candidate's transformed donor
        // patch, `patch` entries per candidate. At identity that is (dx, dy).
        let patch = ((2 * pr + 1) * (2 * pr + 1)) as usize;
        let max_angle = [0.0, 15f32, 30.0, 45.0, 180.0][rotation.min(4) as usize].to_radians();
        let unit = |r: u32| r as f32 / u32::MAX as f32;
        let mut offs: Vec<(i32, i32)> = Vec::with_capacity(cands.len() * patch);
        for _ in 0..cands.len() {
            let angle = if max_angle > 0.0 { (unit(next()) * 2.0 - 1.0) * max_angle } else { 0.0 };
            let s = if scale { 0.8 + unit(next()) * 0.45 } else { 1.0 };
            let flip = mirror && next() & 1 == 1;
            let (sin, cos) = angle.sin_cos();
            for dy in -pr..=pr {
                for dx in -pr..=pr {
                    let (mx, my) = ((if flip { -dx } else { dx }) as f32, dy as f32);
                    offs.push((
                        ((cos * mx - sin * my) * s).round() as i32,
                        ((sin * mx + cos * my) * s).round() as i32,
                    ));
                }
            }
        }
        let gain = [0.0, 0.5, 0.8, 1.0][color.min(3) as usize];
        // peel inward: repeatedly fill hole pixels that touch the known region.
        loop {
            let mut frontier: Vec<i32> = Vec::new();
            for y in 0..h {
                for x in 0..w {
                    let i = (y * w + x) as usize;
                    if known[i] {
                        continue;
                    }
                    let near = (x > 0 && known[i - 1])
                        || (x < w - 1 && known[i + 1])
                        || (y > 0 && known[i - w as usize])
                        || (y < h - 1 && known[i + w as usize]);
                    if near {
                        frontier.push(i as i32);
                    }
                }
            }
            if frontier.is_empty() {
                break;
            }
            for &fi in &frontier {
                let x = fi % w;
                let y = fi / w;
                // Create Texture takes a random donor; Content-Aware searches
                // for the patch that best continues what surrounds the hole.
                let mut bq = if randomize {
                    cands[next() as usize % cands.len()]
                } else {
                    cands[0]
                };
                // Mean of (target − donor) over the best patch, for Color.
                let mut gap = [0f32; 3];
                if !randomize {
                    let mut best = f32::MAX;
                    for (ci, &(qx, qy)) in cands.iter().enumerate() {
                        let off = &offs[ci * patch..(ci + 1) * patch];
                        let mut d = 0.0f32;
                        let mut g = [0f32; 3];
                        let mut cnt = 0u32;
                        let mut o = 0;
                        for dy in -pr..=pr {
                            for dx in -pr..=pr {
                                let (ox, oy) = off[o];
                                o += 1;
                                let nx = x + dx;
                                let ny = y + dy;
                                if nx < 0 || ny < 0 || nx >= w || ny >= h {
                                    continue;
                                }
                                let ni = (ny * w + nx) as usize;
                                if !known[ni] {
                                    continue;
                                }
                                let (sx, sy) = (qx + ox, qy + oy);
                                if sx < 0 || sy < 0 || sx >= w || sy >= h {
                                    continue;
                                }
                                let si = (sy * w + sx) as usize;
                                for k in 0..3 {
                                    let diff = px[ni * 4 + k] as f32 - px[si * 4 + k] as f32;
                                    d += diff * diff;
                                    g[k] += diff;
                                }
                                cnt += 1;
                            }
                        }
                        if cnt > 0 {
                            d /= cnt as f32;
                            if d < best {
                                best = d;
                                bq = (qx, qy);
                                gap = g.map(|v| v / cnt as f32);
                            }
                        }
                    }
                }
                let si = (bq.1 * w + bq.0) as usize;
                let di = (y * w + x) as usize;
                for k in 0..4 {
                    px[di * 4 + k] = px[si * 4 + k];
                }
                if gain > 0.0 {
                    for k in 0..3 {
                        let v = px[di * 4 + k] as f32 + gain * gap[k];
                        px[di * 4 + k] = v.round().clamp(0.0, 65535.0) as u16;
                    }
                }
                known[di] = true;
            }
        }
        self.rng = rng;
        self.layers[self.active].pixels = px.into();
        true
    }

    /// Spot Healing Brush ▸ Type (Photoshop), applied to the painted footprint the
    /// store has already turned into the active selection:
    ///   0 Content-Aware   — exemplar synthesis, the best-matching donor patch from
    ///                       the surroundings, so structure carries through;
    ///   1 Proximity Match — diffuse the boundary colour inward (the Content-Aware
    ///                       Fill membrane), which is what "uses the pixels around
    ///                       the edge of the selection" means;
    ///   2 Create Texture  — the same exemplar peel with a random donor, so the
    ///                       hole comes back as texture rather than structure.
    /// `sample_all` (Photoshop's Sample All Layers) heals from the flattened
    /// composite instead of the active layer alone; only the active layer is
    /// written, so the layers underneath are untouched.
    pub fn spot_heal_selection(&mut self, kind: u8, sample_all: bool) {
        if !self.sel.active || self.active_layer().locked || self.active_layer().kind == 4 {
            return;
        }
        if self.reject_legacy_float_edit("Spot Heal Selection") {
            return;
        }
        let Some(rect) = self.plane_rect(self.active) else {
            return;
        };
        let Some(local) = self.plane_local_selection() else {
            return;
        };
        if self.push_layer_undo("Spot Healing Brush") {
            return;
        }
        // Sample All Layers: let the fill READ the composite by blitting it over
        // the plane, then put every pixel the heal did not touch back afterwards.
        // ponytail: the composite is 8-bit, so a 16-bit layer's surroundings are
        // read at 8-bit precision for the duration of the fill (the pixels
        // themselves are restored bit-exact). Composite to 16-bit if that shows.
        let restore = sample_all.then(|| {
            let hole: Vec<bool> = (0..(rect.w * rect.h) as usize)
                .map(|i| local.coverage(i) > 0.5)
                .collect();
            let before = self.layers[self.active].pixels.clone();
            self.composite();
            let (cw, ch) = (self.w as i32, self.h as i32);
            let out = std::mem::take(&mut self.output);
            let px = Arc::make_mut(&mut self.layers[self.active].pixels);
            for y in 0..rect.h as i32 {
                for x in 0..rect.w as i32 {
                    let (cx, cy) = (rect.x + x, rect.y + y);
                    if cx < 0 || cy < 0 || cx >= cw || cy >= ch {
                        continue;
                    }
                    let si = (cy as usize * cw as usize + cx as usize) * 4;
                    let di = (y as usize * rect.w as usize + x as usize) * 4;
                    for k in 0..4 {
                        px[di + k] = out[si + k] as u16 * 257;
                    }
                }
            }
            self.output = out;
            (before, hole)
        });
        match kind {
            1 => self.content_aware_fill_active_selection(),
            2 => self.exemplar_fill_active_selection(true),
            _ => self.exemplar_fill_active_selection(false),
        }
        if let Some((before, hole)) = restore {
            let px = Arc::make_mut(&mut self.layers[self.active].pixels);
            for (i, &in_hole) in hole.iter().enumerate() {
                if in_hole {
                    continue;
                }
                px[i * 4..i * 4 + 4].copy_from_slice(&before[i * 4..i * 4 + 4]);
            }
        }
        self.composite();
    }

    pub fn content_aware_fill(&mut self) {
        if !self.sel.active {
            return;
        }
        // Same guards as its sibling Patch, which shares this engine core: the
        // layers whose pixels are regenerated, and both pixel locks.
        if self.refuse_destructive_edit() || self.refuse_mask_target("Content-Aware Fill") {
            return;
        }
        let bounds = self.sel.bounds();
        if bounds[2] <= 0 || bounds[3] <= 0 {
            return;
        }
        if self.reject_legacy_float_edit("Content Aware Fill") {
            return;
        }
        if self.plane_local_selection().is_none() {
            return;
        }
        if self.push_layer_undo("Content-Aware Fill") {
            return;
        }
        let before = self
            .preserve_for_active(false)
            .then(|| self.layers[self.active].pixels.clone());
        self.content_aware_fill_active_selection();
        if let Some(before) = before {
            self.restore_locked_transparency(&before);
        }
        self.composite();
    }

    /// Edit ▸ Content-Aware Fill… — the workspace's fill: exemplar synthesis of
    /// the selection that copies only from the Sampling Area `sample` (document
    /// sized, above 127 = sample), with the adaptations `exemplar_fill_with`
    /// describes. `output` 0 fills the layer in place; 1 (New Layer) and 2
    /// (Duplicate Layer) leave the source bit for bit and put the result on a
    /// layer above it, keeping the source active. Every refusal happens before
    /// the single history step and names what to change. Returns whether it
    /// filled.
    pub fn content_aware_fill_workspace(
        &mut self,
        sample: &[u8],
        color: u32,
        rotation: u32,
        scale: bool,
        mirror: bool,
        output: u32,
    ) -> bool {
        let bounds = self.sel.bounds();
        if !self.sel.active || bounds[2] <= 0 || bounds[3] <= 0 {
            self.last_edit_error = "Content-Aware Fill needs a selection: select the area to fill first.".into();
            return false;
        }
        // u32 so an out-of-range value from JS reaches this check instead of wrapping.
        if sample.len() != (self.w * self.h) as usize || color > 3 || rotation > 4 || output > 2 {
            self.last_edit_error = "Content-Aware Fill settings are out of range.".into();
            return false;
        }
        if self.refuse_destructive_edit()
            || self.refuse_mask_target("Content-Aware Fill")
            || self.reject_legacy_float_edit("Content-Aware Fill")
        {
            return false;
        }
        let (Some(rect), Some(local)) = (self.plane_rect(self.active), self.plane_local_selection()) else {
            return false;
        };
        let hole: Vec<bool> = (0..(rect.w * rect.h) as usize).map(|i| local.coverage(i) > 0.5).collect();
        if !hole.contains(&true) {
            self.last_edit_error = "The selection does not cover any of this layer's pixels.".into();
            return false;
        }
        let mut sampling = Selection::new(self.w, self.h);
        sampling.set_mask(sample);
        let sampling = project_selection_to_bounds(&sampling, rect);
        let donor: Vec<bool> = (0..hole.len()).map(|i| sampling.coverage(i) > 0.5 && !hole[i]).collect();
        // The core only takes donor patches that fit inside the plane.
        let (w, h, pr) = (rect.w as i32, rect.h as i32, EXEMPLAR_PATCH_RADIUS);
        if !(pr..h - pr).any(|y| (pr..w - pr).any(|x| donor[(y * w + x) as usize])) {
            self.last_edit_error = "The sampling area is empty: paint a sampling area outside the selection.".into();
            return false;
        }
        let refused = if output == 0 {
            self.push_layer_undo("Content-Aware Fill")
        } else {
            self.push_stack_undo("Content-Aware Fill")
        };
        if refused {
            return false;
        }
        let src = self.active;
        let before = self.layers[src].pixels.clone();
        self.exemplar_fill_with(false, Some(&donor), color, rotation, scale, mirror);
        // A New Layer is not the locked layer; a duplicate carries its locks.
        if output != 1 && self.preserve_for_active(false) {
            self.restore_locked_transparency(&before);
        }
        if output > 0 {
            let result = std::mem::replace(&mut self.layers[src].pixels, before.into());
            let layer = if output == 1 {
                let source = &self.layers[src];
                let mut layer = Layer::transparent(self.next_id, "Content-Aware Fill", rect.w, rect.h);
                layer.pixel_bounds = source.pixel_bounds;
                (layer.ox, layer.oy) = (source.ox, source.oy);
                for i in (0..hole.len()).filter(|&i| hole[i]) {
                    Arc::make_mut(&mut layer.pixels)[i * 4..i * 4 + 4].copy_from_slice(&result[i * 4..i * 4 + 4]);
                }
                layer
            } else {
                // refuse_destructive_edit refused groups, so one clone is the
                // whole duplicate.
                let mut layer = self.layers[src].clone();
                layer.id = self.next_id;
                layer.name = format!("{} copy", layer.name);
                layer.pixels = result.into();
                layer
            };
            self.next_id += 1;
            self.insert_layer_above_active(layer);
            // The workspace's preview is pinned to the source layer.
            self.active = src;
        }
        self.composite();
        true
    }

    /// Diffuse-fill (Content-Aware) the active selection on the active layer, in
    /// place — the shared core behind Content-Aware Fill and Content-Aware Move.
    /// Solves a Laplace relaxation over the selection bbox, seeded with the mean
    /// of the known pixels. Pushes no undo and does not composite; the caller
    /// owns the history step and the repaint.
    fn content_aware_fill_active_selection(&mut self) {
        let Some(local) = self.plane_local_selection() else {
            return;
        };
        let w = local.w as usize;
        let h = local.h as usize;
        let n = w * h;
        let bounds = local.bounds();
        let mut unknown = vec![false; n];
        for i in 0..n {
            if local.coverage(i) > 0.5 {
                unknown[i] = true;
            }
        }
        let mut r = vec![0f32; n];
        let mut g = vec![0f32; n];
        let mut b = vec![0f32; n];
        {
            let px = &self.layers[self.active].pixels;
            for i in 0..n {
                r[i] = px[i * 4] as f32;
                g[i] = px[i * 4 + 1] as f32;
                b[i] = px[i * 4 + 2] as f32;
            }
        }
        // seed unknowns with the mean of known pixels for faster convergence
        let (mut sr, mut sg, mut sb, mut c) = (0f32, 0f32, 0f32, 0f32);
        for i in 0..n {
            if !unknown[i] {
                sr += r[i];
                sg += g[i];
                sb += b[i];
                c += 1.0;
            }
        }
        if c > 0.0 {
            let (mr, mg, mb) = (sr / c, sg / c, sb / c);
            for i in 0..n {
                if unknown[i] {
                    r[i] = mr;
                    g[i] = mg;
                    b[i] = mb;
                }
            }
        }
        // Gauss-Seidel relaxation over the selection bbox (+1px margin).
        let x0 = (bounds[0] - 1).max(0) as usize;
        let y0 = (bounds[1] - 1).max(0) as usize;
        let x1 = ((bounds[0] + bounds[2] + 1).max(0) as usize).min(w);
        let y1 = ((bounds[1] + bounds[3] + 1).max(0) as usize).min(h);
        for _ in 0..160 {
            for y in y0..y1 {
                for x in x0..x1 {
                    let i = y * w + x;
                    if !unknown[i] {
                        continue;
                    }
                    let (mut ar, mut ag, mut ab, mut k) = (0f32, 0f32, 0f32, 0f32);
                    if x > 0 {
                        let j = i - 1;
                        ar += r[j];
                        ag += g[j];
                        ab += b[j];
                        k += 1.0;
                    }
                    if x + 1 < w {
                        let j = i + 1;
                        ar += r[j];
                        ag += g[j];
                        ab += b[j];
                        k += 1.0;
                    }
                    if y > 0 {
                        let j = i - w;
                        ar += r[j];
                        ag += g[j];
                        ab += b[j];
                        k += 1.0;
                    }
                    if y + 1 < h {
                        let j = i + w;
                        ar += r[j];
                        ag += g[j];
                        ab += b[j];
                        k += 1.0;
                    }
                    if k > 0.0 {
                        r[i] = ar / k;
                        g[i] = ag / k;
                        b[i] = ab / k;
                    }
                }
            }
        }
        let px = Arc::make_mut(&mut self.layers[self.active].pixels);
        for i in 0..n {
            if unknown[i] {
                px[i * 4] = r[i].clamp(0.0, 65535.0) as u16;
                px[i * 4 + 1] = g[i].clamp(0.0, 65535.0) as u16;
                px[i * 4 + 2] = b[i].clamp(0.0, 65535.0) as u16;
                if px[i * 4 + 3] == 0 {
                    px[i * 4 + 3] = 65535;
                }
            }
        }
    }

    /// Content-Aware Move (Photoshop): relocate the active selection's CONTENTS
    /// by (dx,dy) and content-aware-fill the hole they leave behind — one undo
    /// step. Distinct from Patch (which heals the selection in place from an
    /// offset source); here the object moves and the vacated source is rebuilt.
    /// `extend` duplicates instead: the source is left as it was. `structure`
    /// 1..7 and `color` 0..10 are Patch's Content-Aware controls applied to the
    /// dropped object — how much of its own texture survives, and how far its
    /// tone is pulled toward the destination's surroundings (7 / 0 is a plain
    /// stamp). `sx`/`sy`/`deg` are Transform On Drop's scale and rotation about
    /// the dropped object's centre.
    #[allow(clippy::too_many_arguments)]
    pub fn content_aware_move(
        &mut self,
        dx: i32,
        dy: i32,
        extend: bool,
        structure: u32,
        color: u32,
        sx: f32,
        sy: f32,
        deg: f32,
    ) {
        if !self.sel.active {
            return;
        }
        // u32 so an out-of-range value from JS (or a hand-edited action) reaches
        // this check instead of wrapping into range.
        if !(1..=7).contains(&structure)
            || color > 10
            || !(sx.is_finite() && sy.is_finite() && deg.is_finite())
            || sx.abs() < 1e-3
            || sy.abs() < 1e-3
        {
            self.last_edit_error =
                "Content-Aware Move needs Structure 1–7, Color 0–10 and a finite, non-zero scale.".into();
            return;
        }
        if dx == 0 && dy == 0 && sx == 1.0 && sy == 1.0 && deg == 0.0 {
            return;
        }
        // As for Patch and Content-Aware Fill: kind 4 was already refused here,
        // but silently and alone — refuse_destructive_edit covers it, the other
        // regenerated kinds, and both pixel locks, and says why.
        if self.refuse_destructive_edit() || self.refuse_mask_target("Content-Aware Move") {
            return;
        }
        if self.reject_legacy_float_edit("Content Aware Move") {
            return;
        }
        let w = self.w as i32;
        let h = self.h as i32;
        let n = (w * h) as usize;
        if !self.sel.mask.iter().any(|&v| v > 0) {
            return; // empty selection — don't burn an undo step
        }
        let Some(rect) = self.plane_rect(self.active) else {
            return;
        };
        // Full-doc snapshot: undo restores the moved pixels, the filled hole and
        // the relocated marquee together (a single history step).
        if self.push_stack_undo("Content-Aware Move") {
            return;
        }
        // Snapshot the source pixels + marquee BEFORE we disturb either.
        let src = self.layers[self.active].pixels.clone();
        let mask = self.sel.mask.clone();
        let b = self.sel.bounds();

        // 1. Move only: reconstruct the region the object vacates (content-aware
        //    fill the source selection, which is still where the marquee is).
        if !extend {
            self.content_aware_fill_active_selection();
        }

        // 2. Carry the object and its marquee to the drop point: the drag, plus
        //    the similarity pivoted on the selection centre. The shared inverse
        //    pivots on the canvas centre, so the pivot shift (I − L)·u folds into
        //    its translation (as layerTransformArgs does). Exact at identity with
        //    an integer offset: every sample lands on one texel with weight 1.
        let (ux, uy) = (
            (b[0] as f32 + b[2] as f32 / 2.0) - w as f32 / 2.0,
            (b[1] as f32 + b[3] as f32 / 2.0) - h as f32 / 2.0,
        );
        let (sn, cs) = deg.to_radians().sin_cos();
        let (ax, ay) = (sx.abs(), sy.abs());
        let tx = dx as f32 + ux - (cs * ax * ux - sn * ay * uy);
        let ty = dy as f32 + uy - (sn * ax * ux + cs * ay * uy);
        let inv = Engine::layer_transform_inverse_matrix(w, h, sx, sy, deg, tx, ty);
        let obj = Engine::transform_plane_with_inverse(&src, rect.w as i32, rect.h as i32, (rect.x, rect.y), inv);
        self.sel.mask = Engine::rotate_buf(
            &mask,
            1,
            0u8,
            w,
            h,
            w,
            h,
            |x, y| mat3_project(inv, x as f32, y as f32).unwrap_or((-2.0, -2.0)),
            |v| v as f32,
            |f| f.round().clamp(0.0, 255.0) as u8,
        );

        // 3. Patch's Content-Aware math at the destination. The diffuse fill of
        //    the new marquee is only a tone reference for Color, never an edit.
        let fill = (color > 0).then(|| {
            let base = self.layers[self.active].pixels.to_vec();
            self.content_aware_fill_active_selection();
            std::mem::replace(&mut self.layers[self.active].pixels, base.into())
        });
        // The object's tone: its alpha-weighted mean, so the transparent margin of
        // a loose marquee does not drag the tone toward black.
        let mut mean = [0f64; 3];
        let mut weight = 0f64;
        for i in 0..n {
            if self.sel.mask[i] == 0 {
                continue;
            }
            let Some(di) = checked_plane_index(rect, i as i32 % w, i as i32 / w, 4) else {
                continue;
            };
            let a = obj[di + 3] as f64;
            for k in 0..3 {
                mean[k] += obj[di + k] as f64 * a;
            }
            weight += a;
        }
        if weight > 0.0 {
            for m in &mut mean {
                *m /= weight;
            }
        }
        let (g, c) = (structure as f64 / 7.0, color as f64 / 10.0);
        let mut written = 0usize;
        for y in 0..h {
            for x in 0..w {
                let cov = self.sel.coverage((y * w + x) as usize);
                if cov <= 0.0 {
                    continue;
                }
                let Some(di) = checked_plane_index(rect, x, y, 4) else {
                    continue;
                };
                // tone + texture·g, written as obj + … so Structure 7 / Color 0
                // is the object bit-for-bit. RGB only: the object's own alpha is
                // composited over, so transparent pixels never erase what they
                // are dropped onto.
                let mut p = [0u16, 0, 0, obj[di + 3]];
                for k in 0..3 {
                    let o = obj[di + k] as f64;
                    let tone = fill.as_ref().map_or(0.0, |f| (f[di + k] as f64 - mean[k]) * c);
                    p[k] = (o + tone + (o - mean[k]) * (g - 1.0)).round().clamp(0.0, 65535.0) as u16;
                }
                let s = Rgba::from_u16(&p);
                let out = &mut Arc::make_mut(&mut self.layers[self.active].pixels)[di..di + 4];
                composite_over(Rgba::from_u16(out), Rgba::new(s.r, s.g, s.b, s.a * cov), BlendMode::Normal, 1.0)
                    .to_u16(out);
                written += 1;
            }
        }
        // Extend dropped entirely off the layer changed nothing; the undo step
        // was pushed before that was knowable, so take it back.
        if extend && written == 0 {
            self.sel.mask = mask;
            self.drop_last_undo();
            return;
        }
        if self.preserve_for_active(false) {
            self.restore_locked_transparency(&src);
        }

        self.composite();
        self.sel_dirty();
    }

    // Flood-fill (paint bucket) from (sx,sy) on the active layer.
    // Flood-fill from (sx,sy). `all_layers`: determine the fill region from the
    // merged image (Photoshop's bucket "All Layers"); default off → sample only
    // the active layer. The fill is always painted onto the active layer.
    // Flood region for the Paint Bucket: the pixels reachable from the seed
    // through colour-matching neighbours (contiguous) or every matching pixel
    // (global), by `tol` tolerance. The caller intersects it with the active
    // selection when painting. Shared by the solid and pattern bucket fills.
    fn bucket_region(
        &mut self,
        sx: i32,
        sy: i32,
        tol: f32,
        contiguous: bool,
        all_layers: bool,
    ) -> Vec<bool> {
        let w = self.w as i32;
        let h = self.h as i32;
        // Region-matching buffer (16-bit): the merged image or the active layer.
        let px: Vec<u16> = if all_layers {
            self.composite();
            self.output.iter().map(|&v| (v as u16) * 257).collect() // 8-bit → 16-bit
        } else {
            // The active layer's pixels are its own PLANE, but the flood below walks
            // CANVAS space (and so does the region it returns), so lift the plane into
            // a canvas-sized buffer first — the same shape lens_flare uses. Off-plane
            // canvas points stay zero and simply never match the seed. (#45)
            let Some(rect) = self.plane_rect(self.active) else {
                return vec![false; (w as usize) * (h as usize)];
            };
            let src = &self.layers[self.active].pixels;
            let mut buf = vec![0u16; (w as usize) * (h as usize) * 4];
            for y in 0..h {
                for x in 0..w {
                    if let Some(p) = checked_plane_index(rect, x, y, 4) {
                        let d = ((y * w + x) as usize) * 4;
                        buf[d..d + 4].copy_from_slice(&src[p..p + 4]);
                    }
                }
            }
            buf
        };
        let seed = (sy * w + sx) as usize * 4;
        let (sr, sg, sb, sa) = (
            px[seed] as f32,
            px[seed + 1] as f32,
            px[seed + 2] as f32,
            px[seed + 3] as f32,
        );
        let t = tol * 65535.0;
        let matches = |i: usize| {
            let p = i * 4;
            (px[p] as f32 - sr).abs() <= t
                && (px[p + 1] as f32 - sg).abs() <= t
                && (px[p + 2] as f32 - sb).abs() <= t
                && (px[p + 3] as f32 - sa).abs() <= t
        };
        let mut region = vec![false; (w * h) as usize];
        if contiguous {
            let mut stack = vec![(sx, sy)];
            let mut seen = vec![false; (w * h) as usize];
            seen[(sy * w + sx) as usize] = true;
            while let Some((cx, cy)) = stack.pop() {
                let i = (cy * w + cx) as usize;
                if !matches(i) {
                    continue;
                }
                region[i] = true;
                for (nx, ny) in [(cx - 1, cy), (cx + 1, cy), (cx, cy - 1), (cx, cy + 1)] {
                    if nx >= 0 && ny >= 0 && nx < w && ny < h {
                        let ni = (ny * w + nx) as usize;
                        if !seen[ni] {
                            seen[ni] = true;
                            stack.push((nx, ny));
                        }
                    }
                }
            }
        } else {
            for i in 0..(w * h) as usize {
                if matches(i) {
                    region[i] = true;
                }
            }
        }
        region
    }

    pub fn bucket_fill(
        &mut self,
        sx: i32,
        sy: i32,
        r: u8,
        g: u8,
        b: u8,
        a: u8,
        tol: f32,
        contiguous: bool,
        all_layers: bool,
        blend: u8,
        opacity: f32,
    ) {
        if self.refuse_destructive_edit() {
            return;
        }
        if sx < 0 || sy < 0 || sx >= self.w as i32 || sy >= self.h as i32 {
            return;
        }
        if self.reject_legacy_float_edit("Bucket Fill") {
            return;
        }
        // The flood region and the selection are CANVAS-indexed; the pixels written
        // are on the layer's own PLANE. Translate each canvas point instead of using
        // its index as a plane offset. Resolved before the undo push. (#45)
        let Some(rect) = self.plane_rect(self.active) else {
            return;
        };
        if self.push_layer_undo("Bucket Fill") {
            return;
        }
        let region = self.bucket_region(sx, sy, tol, contiguous, all_layers);
        let mode = BlendMode::from_u8(blend);
        let op = opacity.clamp(0.0, 1.0);
        let cw = self.w as i32;
        let src = Rgba::new(
            r as f32 / 255.0,
            g as f32 / 255.0,
            b as f32 / 255.0,
            a as f32 / 255.0,
        );
        for i in 0..region.len() {
            if !region[i] {
                continue;
            }
            let cov = self.sel.coverage(i);
            if cov <= 0.0 {
                continue;
            }
            let Some(bp) = checked_plane_index(rect, (i as i32) % cw, (i as i32) / cw, 4)
            else {
                continue;
            };
            let base = Rgba::from_u16(&self.layers[self.active].pixels[bp..bp + 4]);
            let s = Rgba::new(src.r, src.g, src.b, src.a * cov);
            let res = composite_over(base, s, mode, op);
            res.to_u16(&mut Arc::make_mut(&mut self.layers[self.active].pixels)[bp..bp + 4]);
        }
        self.composite();
    }

    /// Paint Bucket ▸ Fill: Pattern — flood the same region as `bucket_fill` but
    /// stamp the defined pattern (tiled, canvas-aligned) instead of a solid
    /// colour. No-op if no pattern is defined. `blend`/`opacity` match the solid
    /// bucket's Mode + Opacity options.
    pub fn bucket_fill_pattern(
        &mut self,
        sx: i32,
        sy: i32,
        tol: f32,
        contiguous: bool,
        all_layers: bool,
        blend: u8,
        opacity: f32,
    ) {
        if self.pattern.is_empty() || self.refuse_destructive_edit() {
            return;
        }
        if sx < 0 || sy < 0 || sx >= self.w as i32 || sy >= self.h as i32 {
            return;
        }
        if self.reject_legacy_float_edit("Bucket Fill Pattern") {
            return;
        }
        // Canvas-indexed region/selection, plane-resident pixels — translate. The
        // pattern stays canvas-aligned (that is the documented behaviour), so its own
        // lookup keeps using the canvas coordinates. (#45)
        let Some(rect) = self.plane_rect(self.active) else {
            return;
        };
        if self.push_layer_undo("Bucket Fill") {
            return;
        }
        let region = self.bucket_region(sx, sy, tol, contiguous, all_layers);
        let mode = BlendMode::from_u8(blend);
        let op = opacity.clamp(0.0, 1.0);
        let w = self.w as i32;
        let (pw, ph) = (self.pattern_w as i32, self.pattern_h as i32);
        let pat = self.pattern.clone();
        for i in 0..region.len() {
            if !region[i] {
                continue;
            }
            let cov = self.sel.coverage(i);
            if cov <= 0.0 {
                continue;
            }
            let (x, y) = ((i as i32) % w, (i as i32) / w);
            let Some(bp) = checked_plane_index(rect, x, y, 4) else {
                continue;
            };
            let base = Rgba::from_u16(&self.layers[self.active].pixels[bp..bp + 4]);
            let pi = (y.rem_euclid(ph) * pw + x.rem_euclid(pw)) as usize * 4;
            let mut s = Rgba::from_u16(&pat[pi..pi + 4]);
            s.a *= cov;
            let res = composite_over(base, s, mode, op);
            res.to_u16(&mut Arc::make_mut(&mut self.layers[self.active].pixels)[bp..bp + 4]);
        }
        self.composite();
    }

    // Gradient fill on the active layer within the selection.
    // `stops` is a flat [offset, r, g, b, a, …] array (0..1 each).
    // Draw a gradient from (x0,y0) to (x1,y1). `kind`: 0 linear · 1 radial ·
    // 2 angle · 3 reflected · 4 diamond (the five Photoshop gradient styles).
    pub fn gradient_fill(
        &mut self,
        x0: f32,
        y0: f32,
        x1: f32,
        y1: f32,
        kind: u8,
        reverse: bool,
        stops: &[f32],
        dither: bool,
        transparency: bool,
        method: u8,
        blend: u8,
        opacity: f32,
    ) {
        if stops.len() < 5 || self.refuse_destructive_edit() {
            return;
        }
        if self.reject_legacy_float_edit("Gradient Fill") {
            return;
        }
        let blend_mode = BlendMode::from_u8(blend);
        let op = opacity.clamp(0.0, 1.0);
        // 4x4 ordered (Bayer) dither: deterministic, no crawl between recomposites.
        const BAYER4: [u8; 16] = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
        let Some(rect) = self.plane_rect(self.active) else {
            return;
        };
        if self.push_layer_undo("Gradient") {
            return;
        }
        let w = self.w as i32;
        let h = self.h as i32;
        let dx = x1 - x0;
        let dy = y1 - y0;
        let len2 = (dx * dx + dy * dy).max(1e-4);
        let len = len2.sqrt();
        let (ux, uy) = (dx / len, dy / len); // unit vector along the gradient
        let dir = dy.atan2(dx); // gradient direction angle (for the angle style)
        let nstops = stops.len() / 5;
        let sample = |t: f32| -> Rgba {
            let t = t.clamp(0.0, 1.0);
            let mut i = 0;
            while i + 1 < nstops && stops[(i + 1) * 5] < t {
                i += 1;
            }
            let a0 = stops[i * 5];
            let j = (i + 1).min(nstops - 1);
            let a1 = stops[j * 5];
            // Clamped: below the first stop (offset dragged off 0) an unclamped
            // factor goes negative and EXTRAPOLATES past the stop instead of
            // holding it — Photoshop, and this app's own GradientBar preview,
            // hold the endpoint colour. (#46)
            let f = if (a1 - a0).abs() < 1e-5 {
                0.0
            } else {
                ((t - a0) / (a1 - a0)).clamp(0.0, 1.0)
            };
            let c0 = [stops[i * 5 + 1], stops[i * 5 + 2], stops[i * 5 + 3]];
            let c1 = [stops[j * 5 + 1], stops[j * 5 + 2], stops[j * 5 + 3]];
            // Alpha (transparency stops) always blends linearly; the "Method"
            // only changes the colour blend space.
            let al = stops[i * 5 + 4] + (stops[j * 5 + 4] - stops[i * 5 + 4]) * f;
            let rgb = match method {
                1 => mix_oklab(c0, c1, f),  // Perceptual (Oklab)
                2 => mix_linear(c0, c1, f), // Linear (light)
                _ => [
                    c0[0] + (c1[0] - c0[0]) * f,
                    c0[1] + (c1[1] - c0[1]) * f,
                    c0[2] + (c1[2] - c0[2]) * f,
                ], // Classic (straight gamma-space RGB)
            };
            Rgba::new(rgb[0], rgb[1], rgb[2], al)
        };
        for y in 0..h {
            for x in 0..w {
                let i = (y * w + x) as usize;
                let cov = self.sel.coverage(i);
                if cov <= 0.0 {
                    continue;
                }
                let px = x as f32 + 0.5 - x0;
                let py = y as f32 + 0.5 - y0;
                let proj = px * ux + py * uy; // signed distance along the gradient (px)
                let t = match kind {
                    1 => ((px * px + py * py).sqrt() / len).clamp(0.0, 1.0), // radial
                    2 => {
                        // angle: sweep 360° around the start, 0 at the gradient direction
                        let mut a = (py.atan2(px) - dir) / std::f32::consts::TAU;
                        a -= a.floor();
                        a
                    }
                    3 => (proj.abs() / len).clamp(0.0, 1.0), // reflected (mirror at the start)
                    4 => {
                        let perp = -px * uy + py * ux; // perpendicular distance (px)
                        ((proj.abs() + perp.abs()) / len).clamp(0.0, 1.0) // diamond (L1)
                    }
                    _ => (proj / len).clamp(0.0, 1.0), // linear
                };
                // "Reverse" flips the colour ramp (end colour at the start).
                let t = if reverse { 1.0 - t } else { t };
                let mut s = sample(t);
                if dither {
                    // Ordered offset of ~±half an 8-bit step to break banding.
                    let off =
                        (BAYER4[((y & 3) * 4 + (x & 3)) as usize] as f32 / 16.0 - 0.5) / 255.0;
                    s = Rgba::new(
                        (s.r + off).clamp(0.0, 1.0),
                        (s.g + off).clamp(0.0, 1.0),
                        (s.b + off).clamp(0.0, 1.0),
                        s.a,
                    );
                }
                // Gradient geometry is CANVAS-space (the user drags across the
                // document); the pixels live on the layer's PLANE. (#45)
                let Some(bp) = checked_plane_index(rect, x, y, 4) else {
                    continue;
                };
                let base = Rgba::from_u16(&self.layers[self.active].pixels[bp..bp + 4]);
                // Transparency off (Photoshop's toggle) ignores the stops' alpha
                // and fills fully opaque; `cov` still carries edge/selection AA.
                let sa = if transparency { s.a } else { 1.0 };
                let src = Rgba::new(s.r, s.g, s.b, sa * cov);
                let res = composite_over(base, src, blend_mode, op);
                res.to_u16(&mut Arc::make_mut(&mut self.layers[self.active].pixels)[bp..bp + 4]);
            }
        }
        self.composite();
    }

    // ── Selection ──────────────────────────────────────────────
    fn sel_dirty(&mut self) {
        // An ACTIVE mask with no coverage anywhere is an invisible trap: there is
        // no edge, so no marching ants explain it, but `coverage()` is 0 for every
        // pixel, so every later brush stroke, fill, filter and adjustment is masked
        // to nothing until the user happens to run Deselect. Alt-clicking the wand
        // (subtract) or intersecting with nothing selected lands there in one
        // click. Photoshop drops the selection instead ("no pixels are more than
        // 50% selected"), so normalize the empty result to deselected here — the
        // one place every selection op passes through. (#53)
        if self.sel.active && self.sel.mask.iter().all(|&v| v == 0) {
            self.sel.active = false;
        }
        self.sel_gen = self.sel_gen.wrapping_add(1);
    }
    // Keep the runtime Quick Mask buffer matched to the document size. Called next
    // to every output reallocation (size-changing ops). Only acts while Quick Mask
    // is on; the minimal cut resets the buffer to all-selected (255) rather than
    // resampling it, then bumps qm_gen so the overlay rebuilds.
    fn resize_quick_mask(&mut self) {
        if !self.qm_on {
            return;
        }
        self.quick_mask = vec![255u8; (self.w * self.h) as usize];
        self.qm_gen = self.qm_gen.wrapping_add(1);
    }
    // Monotonic revision of the selection mask (see `sel_gen`).
    pub fn selection_generation(&self) -> u32 {
        self.sel_gen
    }
    pub fn select_rect(&mut self, x: i32, y: i32, w: i32, h: i32, mode: u8) {
        if self.push_sel_undo("Marquee") {
            return;
        }
        self.sel.rect(x, y, w, h, SelMode::from_u8(mode));
        self.sel_dirty();
    }
    pub fn select_ellipse(&mut self, x: i32, y: i32, w: i32, h: i32, mode: u8) {
        if self.push_sel_undo("Ellipse Marquee") {
            return;
        }
        self.sel.ellipse(x, y, w, h, SelMode::from_u8(mode));
        self.sel_dirty();
    }
    // Toggle anti-aliased selection edges (Photoshop's "Anti-alias" option for
    // the elliptical marquee / lasso). Applies to subsequent marquee ops.
    pub fn set_selection_antialias(&mut self, on: bool) {
        self.sel.antialias = on;
    }
    pub fn select_polygon(&mut self, xs: &[f32], ys: &[f32], mode: u8) {
        if self.push_sel_undo("Lasso") {
            return;
        }
        self.sel.polygon(xs, ys, SelMode::from_u8(mode));
        self.sel_dirty();
    }
    pub fn select_all(&mut self) {
        if self.push_sel_undo("Select All") {
            return;
        }
        self.sel.select_all();
        self.sel_dirty();
    }
    pub fn select_none(&mut self) {
        // Photoshop disables Deselect when nothing is selected — a habit ⌘D
        // must not burn an undo step (and the redo chain) as a no-op.
        if !self.sel.active {
            return;
        }
        if self.push_sel_undo("Deselect") {
            return;
        }
        self.last_sel = Some(self.sel.mask.clone()); // remember it for Reselect
        self.sel.deselect();
        self.sel_dirty();
    }

    // Select ▸ Reselect (⇧⌘D): restore the most recently deselected selection.
    // No-op if nothing was deselected (or the canvas size changed since). Returns
    // true when it restored a selection.
    pub fn reselect(&mut self) -> bool {
        let n = (self.w * self.h) as usize;
        let mask = match &self.last_sel {
            Some(m) if m.len() == n => m.clone(),
            _ => return false,
        };
        if self.push_sel_undo("Reselect") {
            return false;
        }
        self.sel.active = true;
        self.sel.mask = mask;
        self.sel_dirty();
        true
    }

    // Whether Select ▸ Reselect has a stored selection to restore (for UI enablement).
    pub fn can_reselect(&self) -> bool {
        matches!(&self.last_sel, Some(m) if m.len() == (self.w * self.h) as usize)
    }
    pub fn select_invert(&mut self) {
        if self.push_sel_undo("Inverse") {
            return;
        }
        self.sel.invert();
        self.sel_dirty();
    }

    // Select ▸ Transform Selection: scale (around the selection's bbox centre)
    // and move the marquee itself — the PIXELS are untouched, only the selection
    // mask is reshaped. No-op without an active selection.
    pub fn transform_selection(&mut self, scale_x: f32, scale_y: f32, tx: f32, ty: f32) {
        if !self.sel.active {
            return;
        }
        let b = self.sel.bounds();
        let cx = b[0] as f32 + b[2] as f32 / 2.0;
        let cy = b[1] as f32 + b[3] as f32 / 2.0;
        let sx = scale_x.abs().max(1e-3);
        let sy = scale_y.abs().max(1e-3);
        if sx == 1.0 && sy == 1.0 && tx == 0.0 && ty == 0.0 {
            return;
        }
        if self.push_sel_undo("Transform Selection") {
            return;
        }
        let w = self.w as i32;
        let h = self.h as i32;
        let old = self.sel.mask.clone();
        for y in 0..h {
            for x in 0..w {
                // inverse-map the output pixel back to the source mask
                let fx = (x as f32 + 0.5 - cx - tx) / sx + cx;
                let fy = (y as f32 + 0.5 - cy - ty) / sy + cy;
                let sxi = fx.floor() as i32;
                let syi = fy.floor() as i32;
                let v = if sxi >= 0 && syi >= 0 && sxi < w && syi < h {
                    old[(syi * w + sxi) as usize]
                } else {
                    0
                };
                self.sel.mask[(y * w + x) as usize] = v;
            }
        }
        self.sel_dirty();
    }
    // Select ▸ Transform Selection with rotation/skew: warp the coverage mask
    // through the affine [a,b,c,d,e,f] (canvas order: x' = a·x + c·y + e,
    // y' = b·x + d·y + f), inverse-mapped with bilinear sampling so a rotated
    // marquee keeps a clean antialiased edge — same algorithm as the JS
    // warpSelectionMask this replaces. Own undo label: the pure scale/move
    // path above and this one are the same menu command, so they share it.
    pub fn transform_selection_affine(&mut self, a: f32, b: f32, c: f32, d: f32, e: f32, f: f32) {
        if !self.sel.active {
            return;
        }
        if a == 1.0 && b == 0.0 && c == 0.0 && d == 1.0 && e == 0.0 && f == 0.0 {
            return;
        }
        if self.push_sel_undo("Transform Selection") {
            return;
        }
        let w = self.w as i32;
        let h = self.h as i32;
        let old = self.sel.mask.clone();
        let det = a * d - b * c;
        if !det.is_finite() || det.abs() < 1e-9 {
            // Collapsed frame -> empty selection (matches warpSelectionMask's fallback).
            self.sel.mask.iter_mut().for_each(|v| *v = 0);
            self.sel_dirty();
            return;
        }
        let ia = d / det;
        let ib = -b / det;
        let ic = -c / det;
        let id = a / det;
        let itx = -(ia * e + ic * f);
        let ity = -(ib * e + id * f);
        let at = |x: i32, y: i32| -> f32 {
            if x < 0 || y < 0 || x >= w || y >= h {
                0.0
            } else {
                old[(y * w + x) as usize] as f32
            }
        };
        for y in 0..h {
            for x in 0..w {
                let px = x as f32 + 0.5;
                let py = y as f32 + 0.5;
                let fx = ia * px + ic * py + itx - 0.5;
                let fy = ib * px + id * py + ity - 0.5;
                let x0 = fx.floor();
                let y0 = fy.floor();
                let tx = fx - x0;
                let ty = fy - y0;
                let x0i = x0 as i32;
                let y0i = y0 as i32;
                let v = at(x0i, y0i) * (1.0 - tx) * (1.0 - ty)
                    + at(x0i + 1, y0i) * tx * (1.0 - ty)
                    + at(x0i, y0i + 1) * (1.0 - tx) * ty
                    + at(x0i + 1, y0i + 1) * tx * ty;
                self.sel.mask[(y * w + x) as usize] = v.round().clamp(0.0, 255.0) as u8;
            }
        }
        self.sel_dirty();
    }
    // Select ▸ Modify ▸ Expand: grow the selection by `n` pixels (circular kernel).
    pub fn expand_selection(&mut self, n: u32) {
        if !self.sel.active || n == 0 {
            return;
        }
        if self.push_sel_undo("Expand Selection") {
            return;
        }
        self.sel.morph(n as i32);
        self.sel_dirty();
    }
    // Select ▸ Modify ▸ Contract: shrink the selection by `n` pixels.
    pub fn contract_selection(&mut self, n: u32) {
        if !self.sel.active || n == 0 {
            return;
        }
        if self.push_sel_undo("Contract Selection") {
            return;
        }
        self.sel.morph(-(n as i32));
        self.sel_dirty();
    }
    // Select ▸ Modify ▸ Feather: soften the selection edge by `radius` pixels.
    pub fn feather_selection(&mut self, radius: f32) {
        if !self.sel.active || radius < 0.5 {
            return;
        }
        if self.push_sel_undo("Feather Selection") {
            return;
        }
        self.sel.feather(radius);
        self.sel_dirty();
    }
    // Select ▸ Modify ▸ Border: turn the selection into a band of half-width `n`
    // pixels straddling its edge (≈ 2n wide total).
    pub fn border_selection(&mut self, n: u32) {
        if !self.sel.active || n == 0 {
            return;
        }
        if self.push_sel_undo("Border Selection") {
            return;
        }
        self.sel.border(n as i32);
        self.sel_dirty();
    }
    // Select ▸ Modify ▸ Smooth: round corners/spikes with a `radius`-px majority filter.
    pub fn smooth_selection(&mut self, radius: u32) {
        if !self.sel.active || radius == 0 {
            return;
        }
        if self.push_sel_undo("Smooth Selection") {
            return;
        }
        self.sel.smooth(radius as i32);
        self.sel_dirty();
    }
    /// The Select and Mask refine pipeline over any Selection — Refine Edge
    /// (global band + Refine-Edge-Brush `stroke` region, Smart Radius), then the
    /// Global Refinements in panel order: Smooth, Feather, Contrast, Shift Edge
    /// (`shift` > 0 expands). Shared by the committed apply and the workspace's
    /// live preview so the two always agree.
    #[allow(clippy::too_many_arguments)]
    fn sam_refine(
        sel: &mut Selection,
        guide: Option<&[u8]>,
        radius: i32,
        smart: bool,
        smooth: u32,
        feather: f32,
        contrast: f32,
        shift: i32,
        stroke: Option<&[u8]>,
    ) {
        if let Some(g) = guide {
            sel.refine_edge(g, radius, smart, stroke);
        }
        if smooth > 0 {
            sel.smooth(smooth as i32);
        }
        if feather >= 0.5 {
            sel.feather(feather);
        }
        if contrast > 0.0 {
            sel.contrast(contrast);
        }
        if shift != 0 {
            sel.morph(shift);
        }
    }
    /// Select ▸ Select and Mask: commit the workspace's refinements to the
    /// current selection in one undo step. `stroke` is the Refine Edge Brush's
    /// painted region (doc-sized coverage; empty slice = none).
    #[allow(clippy::too_many_arguments)]
    pub fn select_and_mask(
        &mut self,
        radius: i32,
        smart: bool,
        smooth: u32,
        feather: f32,
        contrast: f32,
        shift: i32,
        stroke: &[u8],
    ) {
        if !self.sel.active {
            return;
        }
        let has_stroke =
            stroke.len() == (self.w * self.h) as usize && stroke.iter().any(|&v| v > 0);
        // Refine Edge needs the composite as guidance; grab it before the undo push
        // (read-only) so the mask edit stays a single reversible step.
        let guide = if radius > 0 || has_stroke {
            self.composite();
            Some(self.output.clone())
        } else {
            None
        };
        if self.push_sel_undo("Select and Mask") {
            return;
        }
        Self::sam_refine(
            &mut self.sel,
            guide.as_deref(),
            radius,
            smart,
            smooth,
            feather,
            contrast,
            shift,
            has_stroke.then_some(stroke),
        );
        self.sel_dirty();
    }
    /// Select and Mask workspace live preview: the coverage the current
    /// parameters would produce, computed on a scratch copy of the selection —
    /// the live selection, undo history and canvas stay untouched. Empty when no
    /// selection is active.
    #[allow(clippy::too_many_arguments)]
    pub fn select_and_mask_preview(
        &mut self,
        radius: i32,
        smart: bool,
        smooth: u32,
        feather: f32,
        contrast: f32,
        shift: i32,
        stroke: &[u8],
    ) -> Vec<u8> {
        if !self.sel.active {
            return Vec::new();
        }
        let has_stroke =
            stroke.len() == (self.w * self.h) as usize && stroke.iter().any(|&v| v > 0);
        let guide = if radius > 0 || has_stroke {
            self.composite();
            Some(self.output.clone())
        } else {
            None
        };
        let mut scratch = Selection {
            w: self.w,
            h: self.h,
            active: true,
            mask: self.sel.mask.clone(),
            antialias: self.sel.antialias,
        };
        Self::sam_refine(
            &mut scratch,
            guide.as_deref(),
            radius,
            smart,
            smooth,
            feather,
            contrast,
            shift,
            has_stroke.then_some(stroke),
        );
        scratch.mask
    }
    /// Select and Mask ▸ Decontaminate Colors + "New Layer with Layer Mask": for
    /// partial-alpha edge pixels, unmix the background colour that bled into the
    /// composite (`F = (C − (1−α)·B) / α`, with `B` a local average of nearby
    /// unselected composite pixels), blend toward it by `amount` (0..1), and emit
    /// the merged-visible result as a new opaque layer masked by the selection —
    /// so the fringe is clean once the layer is later moved or recomposited.
    pub fn decontaminate_colors(&mut self, amount: f32) {
        if !self.sel.active {
            return;
        }
        let amt = amount.clamp(0.0, 1.0);
        self.composite();
        let out = self.output.clone(); // merged visible, RGBA8
        let w = self.w as i32;
        let h = self.h as i32;
        let n = (w * h) as usize;
        if out.len() != n * 4 {
            return;
        }
        let cov: Vec<f32> = (0..n).map(|i| self.sel.coverage(i)).collect();
        // Local background radius. ponytail: O(n·r²) but only over the thin edge
        // band (0.03<α<0.97); interior/exterior skip the scan. Widen r if the
        // background sampled per edge pixel is too sparse for clean unmixing.
        let br = 8i32;
        let mut buf = vec![0u16; n * 4];
        for y in 0..h {
            for x in 0..w {
                let i = (y * w + x) as usize;
                let p = i * 4;
                let c = [out[p] as f32, out[p + 1] as f32, out[p + 2] as f32];
                let a = cov[i];
                let mut color = c;
                if a > 0.03 && a < 0.97 {
                    let (mut acc, mut wsum) = ([0f32; 3], 0f32);
                    for dy in -br..=br {
                        for dx in -br..=br {
                            let (nx, ny) = (x + dx, y + dy);
                            if nx < 0 || ny < 0 || nx >= w || ny >= h {
                                continue;
                            }
                            let ni = (ny * w + nx) as usize;
                            if cov[ni] < 0.1 {
                                let np = ni * 4;
                                acc[0] += out[np] as f32;
                                acc[1] += out[np + 1] as f32;
                                acc[2] += out[np + 2] as f32;
                                wsum += 1.0;
                            }
                        }
                    }
                    if wsum > 0.0 {
                        let b = [acc[0] / wsum, acc[1] / wsum, acc[2] / wsum];
                        let f = [
                            ((c[0] - (1.0 - a) * b[0]) / a).clamp(0.0, 255.0),
                            ((c[1] - (1.0 - a) * b[1]) / a).clamp(0.0, 255.0),
                            ((c[2] - (1.0 - a) * b[2]) / a).clamp(0.0, 255.0),
                        ];
                        color = [
                            c[0] + (f[0] - c[0]) * amt,
                            c[1] + (f[1] - c[1]) * amt,
                            c[2] + (f[2] - c[2]) * amt,
                        ];
                    }
                }
                Rgba::new(color[0] / 255.0, color[1] / 255.0, color[2] / 255.0, 1.0)
                    .to_u16(&mut buf[p..p + 4]);
            }
        }
        // One undo step: build the opaque decontaminated layer + selection mask.
        if self.push_stack_undo("Decontaminate Colors") {
            return;
        }
        let id = self.next_id;
        self.next_id += 1;
        let mut layer = Layer::transparent(id, "Decontaminated", self.w, self.h);
        layer.pixels = buf.into();
        layer.mask = self.sel.mask[..n].to_vec().into(); // selection coverage reveals
        self.insert_layer_above_active(layer);
        self.composite();
    }
    /// Object Selection tool: within a box, flood the background inward from the
    /// box border and select the distinct interior object. Border colours grow as
    /// background (region-growing with colour tolerance `tol` 0..1); whatever the
    /// flood can't reach — the object — becomes the selection. `mode` is the
    /// options-bar/modifier combine mode (SelMode) and the result honours the
    /// Anti-alias setting, exactly like the Magic Wand.
    pub fn select_object(&mut self, bx: i32, by: i32, bw: i32, bh: i32, tol: f32, mode: u8) {
        let w = self.w as i32;
        let h = self.h as i32;
        let x0 = bx.clamp(0, w);
        let y0 = by.clamp(0, h);
        let x1 = (bx + bw).clamp(0, w);
        let y1 = (by + bh).clamp(0, h);
        self.select_object_in_hint(x0, y0, x1, y1, None, tol, mode);
    }

    /// Object Selection ▸ Lasso hint mode: the same background flood, but the
    /// user's freehand polygon is the hint instead of a box. `pts` is a flat
    /// [x0,y0,x1,y1,…] closed polygon in document pixels. A tighter hint isolates
    /// better than a box because everything inside the bounding rect but outside
    /// the polygon is known background and seeds the flood directly.
    pub fn select_object_lasso(&mut self, pts: &[f32], tol: f32, mode: u8) {
        if pts.len() < 6 || pts.len() % 2 != 0 || !pts.iter().all(|v| v.is_finite()) {
            return;
        }
        let xs: Vec<f32> = pts.iter().step_by(2).copied().collect();
        let ys: Vec<f32> = pts.iter().skip(1).step_by(2).copied().collect();
        let w = self.w as i32;
        let h = self.h as i32;
        let x0 = xs.iter().cloned().fold(f32::INFINITY, f32::min).floor() as i32;
        let y0 = ys.iter().cloned().fold(f32::INFINITY, f32::min).floor() as i32;
        let x1 = xs.iter().cloned().fold(f32::NEG_INFINITY, f32::max).ceil() as i32 + 1;
        let y1 = ys.iter().cloned().fold(f32::NEG_INFINITY, f32::max).ceil() as i32 + 1;
        let (x0, y0) = (x0.clamp(0, w), y0.clamp(0, h));
        let (x1, y1) = (x1.clamp(0, w), y1.clamp(0, h));
        if x1 - x0 < 2 || y1 - y0 < 2 {
            return;
        }
        let rw = (x1 - x0) as usize;
        let mut hint = vec![false; rw * (y1 - y0) as usize];
        for y in y0..y1 {
            for x in x0..x1 {
                // Pixel centres, matching the anti-aliased lasso fill.
                if crate::raster::selection::point_in_poly(x as f32 + 0.5, y as f32 + 0.5, &xs, &ys) {
                    hint[(y - y0) as usize * rw + (x - x0) as usize] = true;
                }
            }
        }
        if !hint.iter().any(|&v| v) {
            return;
        }
        self.select_object_in_hint(x0, y0, x1, y1, Some(&hint), tol, mode);
    }

    /// Shared core of the Object Selection tool. The background is grown inward
    /// from the hint's border with colour tolerance `tol`; whatever the flood
    /// cannot reach is the object. `hint` (in the rect's own row-stride space)
    /// marks the pixels the user drew around — `None` means the whole rect, as a
    /// box drag does. Everything inside the rect but outside the hint is known
    /// background, so it seeds the flood too.
    fn select_object_in_hint(
        &mut self,
        x0: i32,
        y0: i32,
        x1: i32,
        y1: i32,
        hint: Option<&[bool]>,
        tol: f32,
        mode: u8,
    ) {
        let w = self.w as i32;
        if x1 - x0 < 2 || y1 - y0 < 2 {
            return;
        }
        self.composite();
        let out = self.output.clone();
        let color = |x: i32, y: i32| -> [f32; 3] {
            let i = (y * w + x) as usize * 4;
            [out[i] as f32, out[i + 1] as f32, out[i + 2] as f32]
        };
        let thr = (tol.clamp(0.0, 1.0) * 255.0).powi(2) * 3.0;
        let rw = (x1 - x0) as usize;
        let ridx = |x: i32, y: i32| (y - y0) as usize * rw + (x - x0) as usize;
        let inside = |k: usize| hint.map_or(true, |m| m[k]);
        let mut bg = vec![false; rw * (y1 - y0) as usize];
        let mut queue = std::collections::VecDeque::new();
        let mut seed = |bg: &mut Vec<bool>, queue: &mut std::collections::VecDeque<(i32, i32)>, x: i32, y: i32| {
            let k = ridx(x, y);
            if !bg[k] {
                bg[k] = true;
                queue.push_back((x, y));
            }
        };
        for x in x0..x1 {
            for y in [y0, y1 - 1] {
                seed(&mut bg, &mut queue, x, y);
            }
        }
        for y in y0..y1 {
            for x in [x0, x1 - 1] {
                seed(&mut bg, &mut queue, x, y);
            }
        }
        // Outside the drawn hint is background by construction, not by colour.
        if hint.is_some() {
            for y in y0..y1 {
                for x in x0..x1 {
                    if !inside(ridx(x, y)) {
                        seed(&mut bg, &mut queue, x, y);
                    }
                }
            }
        }
        while let Some((cx, cy)) = queue.pop_front() {
            let c = color(cx, cy);
            for (dx, dy) in [(-1, 0), (1, 0), (0, -1), (0, 1)] {
                let (nx, ny) = (cx + dx, cy + dy);
                if nx < x0 || ny < y0 || nx >= x1 || ny >= y1 {
                    continue;
                }
                let k = ridx(nx, ny);
                if bg[k] {
                    continue;
                }
                let n = color(nx, ny);
                let dd = (n[0] - c[0]).powi(2) + (n[1] - c[1]).powi(2) + (n[2] - c[2]).powi(2);
                if dd <= thr {
                    bg[k] = true;
                    queue.push_back((nx, ny));
                }
            }
        }
        if self.push_sel_undo("Select Object") {
            return;
        }
        let h = self.h as i32;
        let mut matched = vec![false; (w * h) as usize];
        for y in y0..y1 {
            for x in x0..x1 {
                let k = ridx(x, y);
                if !bg[k] && inside(k) {
                    matched[(y * w + x) as usize] = true;
                }
            }
        }
        self.sel.apply_matched(&matched, SelMode::from_u8(mode));
        self.sel_dirty();
    }
    // Select ▸ Grow: extend the selection to contiguous pixels within `tol` of its colours.
    pub fn grow_selection(&mut self, tol: f32) {
        if !self.sel.active || !self.sel.mask.iter().any(|&v| v >= 128) {
            return;
        }
        if self.push_sel_undo("Grow") {
            return;
        }
        self.composite();
        let out = self.output.clone();
        self.sel.grow(&out, tol);
        self.sel_dirty();
    }
    // Select ▸ Similar: select every pixel within `tol` of the selection's colours.
    pub fn similar_selection(&mut self, tol: f32) {
        if !self.sel.active || !self.sel.mask.iter().any(|&v| v >= 128) {
            return;
        }
        if self.push_sel_undo("Similar") {
            return;
        }
        self.composite();
        let out = self.output.clone();
        self.sel.similar(&out, tol);
        self.sel_dirty();
    }
    // Edit ▸ Stroke: paint a `width`-px band along the selection edge onto the
    // active layer with the given colour. `location`: 0 inside, 1 center, 2 outside.
    pub fn stroke_selection(&mut self, width: u32, r: u8, g: u8, b: u8, a: u8, location: u8) {
        if !self.sel.active || width == 0 || self.refuse_destructive_edit() {
            return;
        }
        if !self.sel.mask.iter().any(|&v| v >= 128) {
            return;
        }
        if self.reject_legacy_float_edit("Stroke Selection") {
            return;
        }
        let Some(rect) = self.plane_rect(self.active) else {
            return;
        };
        if self.push_layer_undo("Stroke") {
            return;
        }
        let band = self.sel.stroke_band(width as i32, location);
        let src = Rgba::new(
            r as f32 / 255.0,
            g as f32 / 255.0,
            b as f32 / 255.0,
            a as f32 / 255.0,
        );
        let active = self.active;
        let w = self.w as usize;
        for (i, &on) in band.iter().enumerate() {
            if on {
                let Some(bp) = checked_plane_index(rect, (i % w) as i32, (i / w) as i32, 4)
                else {
                    continue;
                };
                let base = Rgba::from_u16(&self.layers[active].pixels[bp..bp + 4]);
                let res = composite_over(base, src, BlendMode::Normal, 1.0);
                res.to_u16(&mut Arc::make_mut(&mut self.layers[active].pixels)[bp..bp + 4]);
            }
        }
        self.composite();
    }
    // Load a full-document coverage mask (e.g. an ML "Select Subject" result).
    pub fn set_selection_mask(&mut self, mask: &[u8]) {
        if mask.len() != (self.w * self.h) as usize {
            return;
        }
        if self.push_sel_undo("Select Subject") {
            return;
        }
        self.sel.set_mask(mask);
        self.sel_dirty();
    }

    // Select ▸ Focus Area: select the in-focus (sharp / textured) regions by
    // local luminance variance. `threshold` 0..1 is the In-Focus Range — higher
    // demands sharper detail; `noise` 0..1 is Advanced ▸ Image Noise Level and
    // `soften` is Soften Edge in px. A 3×3 majority pass de-speckles the result.
    pub fn select_focus_area(&mut self, threshold: f32, noise: f32, soften: f32) {
        let mask = self.focus_area_preview(threshold, noise, soften);
        if self.push_sel_undo("Focus Area") {
            return;
        }
        self.sel.set_mask(&mask);
        self.sel_dirty();
    }
    /// Focus Area ▸ Auto: the In-Focus Range (slider units, 0..1) that best
    /// splits this image's sharpness map into blurred vs in-focus, by Otsu's
    /// method over the same noise-corrected measure the preview thresholds.
    pub fn focus_area_auto_range(&mut self, noise: f32) -> f32 {
        let (sharp, maxs) = self.focus_sharpness(noise);
        // 256-bin histogram of normalised sharpness, then Otsu's between-class
        // variance maximum.
        let mut hist = [0u32; 256];
        for &s in &sharp {
            hist[((s / maxs) * 255.0).clamp(0.0, 255.0) as usize] += 1;
        }
        let total: f32 = sharp.len() as f32;
        let sum: f32 = (0..256).map(|i| i as f32 * hist[i] as f32).sum();
        let (mut wb, mut sb, mut best, mut best_bin) = (0f32, 0f32, -1f32, 0usize);
        for bin in 0..256 {
            wb += hist[bin] as f32;
            if wb == 0.0 {
                continue;
            }
            let wf = total - wb;
            if wf == 0.0 {
                break;
            }
            sb += bin as f32 * hist[bin] as f32;
            let diff = sb / wb - (sum - sb) / wf;
            let between = wb * wf * diff * diff;
            if between > best {
                best = between;
                best_bin = bin;
            }
        }
        // Invert the cutoff formula below back into slider units.
        ((best_bin as f32 / 255.0) - 0.02).max(0.0) / 0.5
    }
    /// Focus Area dialog live preview — also the commit's core: the coverage the
    /// given In-Focus Range / Image Noise Level / Soften Edge selects. Pure: the
    /// live selection, undo history and canvas stay untouched.
    pub fn focus_area_preview(&mut self, threshold: f32, noise: f32, soften: f32) -> Vec<u8> {
        let w = self.w as i32;
        let h = self.h as i32;
        let n = (w * h) as usize;
        let (sharp, maxs) = self.focus_sharpness(noise);
        let cutoff = threshold.clamp(0.0, 1.0) * maxs * 0.5 + maxs * 0.02;
        let raw: Vec<u8> = sharp
            .iter()
            .map(|&s| if s >= cutoff { 255 } else { 0 })
            .collect();
        // 3×3 majority de-speckle.
        let mut mask = vec![0u8; n];
        for y in 0..h {
            for x in 0..w {
                let (mut on, mut tot) = (0i32, 0i32);
                for dy in -1..=1 {
                    for dx in -1..=1 {
                        let (xx, yy) = (x + dx, y + dy);
                        if xx >= 0 && yy >= 0 && xx < w && yy < h {
                            tot += 1;
                            if raw[(yy * w + xx) as usize] > 0 {
                                on += 1;
                            }
                        }
                    }
                }
                mask[(y * w + x) as usize] = if on * 2 > tot { 255 } else { 0 };
            }
        }
        if soften >= 0.5 {
            // Soften Edge = the same blur Select ▸ Modify ▸ Feather uses, on a
            // scratch selection so nothing live is touched.
            let mut scratch = Selection {
                w: self.w,
                h: self.h,
                active: true,
                mask,
                antialias: self.sel.antialias,
            };
            scratch.feather(soften);
            return scratch.mask;
        }
        mask
    }
    // Local std-dev of luminance in a 3×3 window = a sharpness/focus measure,
    // with `noise` (0..1 of full scale) removed in quadrature — sensor grain
    // raises every window's variance, so subtracting it as variance rather than
    // shifting the threshold keeps genuinely sharp detail where it is. Returns
    // the map and its (non-zero) maximum.
    fn focus_sharpness(&mut self, noise: f32) -> (Vec<f32>, f32) {
        self.composite();
        let w = self.w as i32;
        let h = self.h as i32;
        let n = (w * h) as usize;
        let out = &self.output;
        let mut lum = vec![0f32; n];
        for i in 0..n {
            lum[i] = 0.299 * out[i * 4] as f32
                + 0.587 * out[i * 4 + 1] as f32
                + 0.114 * out[i * 4 + 2] as f32;
        }
        let floor = noise.clamp(0.0, 1.0) * 255.0 * 0.25; // 0.25 = a heavy-grain std-dev
        let mut sharp = vec![0f32; n];
        let mut maxs = 1e-6f32;
        for y in 0..h {
            for x in 0..w {
                let (mut sum, mut sum2, mut cnt) = (0f32, 0f32, 0f32);
                for dy in -1..=1 {
                    for dx in -1..=1 {
                        let (xx, yy) = (x + dx, y + dy);
                        if xx >= 0 && yy >= 0 && xx < w && yy < h {
                            let v = lum[(yy * w + xx) as usize];
                            sum += v;
                            sum2 += v * v;
                            cnt += 1.0;
                        }
                    }
                }
                let mean = sum / cnt;
                let var = (sum2 / cnt - mean * mean).max(0.0);
                let s = (var - floor * floor).max(0.0).sqrt();
                sharp[(y * w + x) as usize] = s;
                if s > maxs {
                    maxs = s;
                }
            }
        }
        (sharp, maxs)
    }

    // Select the likely sky region by flooding from sky-like pixels on the top
    // edge of the composited image. This is deliberately conservative: only
    // connected bright/blue/pale pixels above the horizon band are selected, so
    // blue foreground objects below the skyline do not get replaced.
    pub fn select_sky(&mut self, horizon: f32, tolerance: f32) -> bool {
        self.composite();
        let w = self.w as i32;
        let h = self.h as i32;
        if w <= 0 || h <= 0 {
            return false;
        }
        let tol = tolerance.clamp(0.0, 1.0);
        let horizon_y = (h as f32 * horizon.clamp(0.05, 0.95)).round() as i32;
        let limit_y = (horizon_y + (h as f32 * (0.08 + 0.08 * tol)).round() as i32).clamp(0, h - 1);
        let seed_rows = ((h as f32 * 0.06).round() as i32).clamp(1, (horizon_y + 1).max(1));
        let n = (w * h) as usize;
        let mut mask = vec![0u8; n];
        let mut queue = Vec::<usize>::new();

        for y in 0..seed_rows.min(h) {
            for x in 0..w {
                let idx = (y * w + x) as usize;
                if sky_candidate(&self.output, w, h, x, y, limit_y, tol) {
                    mask[idx] = 255;
                    queue.push(idx);
                }
            }
        }

        let mut head = 0usize;
        while head < queue.len() {
            let idx = queue[head];
            head += 1;
            let x = idx as i32 % w;
            let y = idx as i32 / w;
            for (nx, ny) in [(x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)] {
                if nx < 0 || ny < 0 || nx >= w || ny > limit_y {
                    continue;
                }
                let ni = (ny * w + nx) as usize;
                if mask[ni] != 0 || !sky_candidate(&self.output, w, h, nx, ny, limit_y, tol) {
                    continue;
                }
                mask[ni] = 255;
                queue.push(ni);
            }
        }

        if !mask.iter().any(|&v| v != 0) {
            return false;
        }
        if self.push_sel_undo("Select Sky") {
            return false;
        }
        self.sel.set_mask(&mask);
        self.sel_dirty();
        true
    }

    // Doc-sized selection coverage (0..255); 255 everywhere when inactive.
    // Used by ML generative fill to locate the region to synthesize.
    pub fn get_selection_mask(&self) -> Vec<u8> {
        if !self.sel.active {
            return vec![255u8; (self.w * self.h) as usize];
        }
        self.sel.mask.clone()
    }
    // Magic wand. `all_layers`: sample the merged (composited) image when true;
    // otherwise sample only the active layer (Photoshop's "Sample All Layers" —
    // default off).
    pub fn magic_wand(
        &mut self,
        x: i32,
        y: i32,
        tol: f32,
        contiguous: bool,
        mode: u8,
        all_layers: bool,
    ) {
        // Bounds-check before the undo push so an off-canvas click is a true
        // no-op instead of a phantom history state.
        if x < 0 || y < 0 || x >= self.w as i32 || y >= self.h as i32 {
            return;
        }
        // Canvas-space sample buffer, resolved before the undo push. (#51)
        let Some(pixels) = self.selection_sample_buffer(all_layers) else {
            return;
        };
        if self.push_sel_undo("Magic Wand") {
            return;
        }
        self.sel
            .magic_wand(&pixels, x, y, tol, contiguous, SelMode::from_u8(mode));
        self.sel_dirty();
    }
    // Quick Selection: a brush-drag region grow. One dab per call; `first` pushes
    // the single undo step at the start of a stroke (subsequent dabs don't). The
    // caller passes the tool mode on the first dab, then Add (or Subtract) as it
    // drags. `all_layers` samples the merged image instead of the active layer;
    // `enhance` is the options bar's Auto-Enhance — a Refine Edge matte over the
    // dab so the stroke's boundary snaps to image structure.
    #[allow(clippy::too_many_arguments)]
    pub fn quick_selection(
        &mut self,
        x: i32,
        y: i32,
        radius: i32,
        tol: f32,
        mode: u8,
        first: bool,
        all_layers: bool,
        enhance: bool,
    ) {
        if x < 0 || y < 0 || x >= self.w as i32 || y >= self.h as i32 {
            return;
        }
        if first {
            if self.push_sel_undo("Quick Selection") {
                return;
            }
        }
        let Some(p) = self.selection_sample_buffer(all_layers) else {
            return;
        };
        self.sel
            .quick_selection_paint(&p, x, y, radius.max(1), tol, SelMode::from_u8(mode));
        if enhance {
            self.sel.auto_enhance_dab(&p, x, y, radius.max(1));
        }
        self.sel_dirty();
    }
    // Magnetic Lasso: snap the freehand points to nearby edges, then select the
    // resulting polygon. Samples the active layer; honours the anti-alias flag.
    pub fn magnetic_lasso(
        &mut self,
        xs: &[f32],
        ys: &[f32],
        edge_radius: i32,
        threshold: f32,
        mode: u8,
    ) {
        if xs.len() < 3 {
            return;
        }
        // Magnetic Lasso always samples the active layer, so it needs the same
        // canvas-space lift the wand does. Resolved before the undo push. (#51)
        let Some(p) = self.selection_sample_buffer(false) else {
            return;
        };
        if self.push_sel_undo("Magnetic Lasso") {
            return;
        }
        self.sel
            .magnetic_lasso_apply(&p, xs, ys, edge_radius, threshold, SelMode::from_u8(mode));
        self.sel_dirty();
    }
    // Type Mask: turn a rasterized alpha buffer (glyphs) placed at (px,py) into a
    // selection — coverage follows the alpha, so the marquee is anti-aliased.
    pub fn select_from_alpha(
        &mut self,
        px: i32,
        py: i32,
        aw: u32,
        ah: u32,
        alpha: &[u8],
        mode: u8,
    ) {
        if self.push_sel_undo("Type Mask") {
            return;
        }
        self.sel
            .from_alpha(px, py, aw as i32, ah as i32, alpha, SelMode::from_u8(mode));
        self.sel_dirty();
    }
    // Magic Eraser (eraser group): one click erases all pixels similar to the
    // clicked pixel — to transparency on the active layer. Reuses the Magic Wand's
    // similarity flood, but into a TEMP Selection so the user's real selection is
    // untouched and NO marquee is left behind (Photoshop's Magic Eraser does not
    // leave a selection). `opacity` (0..1) scales the erase (1 = fully transparent).
    pub fn magic_eraser(
        &mut self,
        x: i32,
        y: i32,
        tol: f32,
        contiguous: bool,
        all_layers: bool,
        opacity: f32,
    ) {
        if x < 0 || y < 0 || x >= self.w as i32 || y >= self.h as i32 {
            return;
        }
        // Refuse non-pixel layers (adjustment / vector / smart object) like the rest
        // of the brush/eraser family: their pixels re-render, so a baked erase would
        // be silently discarded by the next composite.
        {
            let l = self.active_layer();
            if l.locked || l.kind == 1 || l.kind == 3 || l.kind == 4 || l.kind == 7 {
                return;
            }
        }
        if self.reject_legacy_float_edit("Magic Eraser") {
            return;
        }
        // The erase is applied to the layer's PLANE, which crop leaves larger than
        // the canvas, so the wand mask has to end up in plane space. The two sample
        // sources live in different spaces, so each branch reaches that differently:
        // All Layers samples the canvas-sized composite and its mask is projected,
        // while the single-layer path samples the plane itself and wands there
        // directly. Building one canvas-sized mask for both walked the wrong pixels
        // and Magic Eraser erased nothing on a cropped document.
        let Some((plane_w, plane_h)) = self.active_plane_dims() else {
            return;
        };
        let effective = {
            let layer = &self.layers[self.active];
            match checked_translate_bounds(layer.pixel_bounds, layer.ox, layer.oy) {
                Some(bounds) => bounds,
                None => return,
            }
        };
        let mask = if all_layers {
            self.composite();
            let canvas_pixels = self.output.clone();
            let mut canvas_mask = Selection::new(self.w, self.h);
            canvas_mask.magic_wand(&canvas_pixels, x, y, tol, contiguous, SelMode::Replace);
            project_selection_to_bounds(&canvas_mask, effective)
        } else {
            let (local_x, local_y) = (x - effective.x, y - effective.y);
            if local_x < 0 || local_y < 0 || local_x >= plane_w as i32 || local_y >= plane_h as i32 {
                return; // the click is not over this layer's plane
            }
            let src = &self.layers[self.active].pixels;
            let mut plane_pixels = vec![0u8; src.len()];
            for (o, &v) in plane_pixels.iter_mut().zip(src.iter()) {
                *o = (v >> 8) as u8;
            }
            let mut plane_mask = Selection::new(plane_w, plane_h);
            plane_mask.magic_wand(
                &plane_pixels,
                local_x,
                local_y,
                tol,
                contiguous,
                SelMode::Replace,
            );
            plane_mask
        };
        if self.push_layer_undo("Magic Eraser") {
            return;
        }
        let op = opacity.clamp(0.0, 1.0);
        let px = Arc::make_mut(&mut self.layers[self.active].pixels);
        for i in 0..px.len() / 4 {
            let cov = mask.coverage(i);
            if cov <= 0.0 {
                continue;
            }
            let a = &mut px[i * 4 + 3];
            *a = (*a as f32 * (1.0 - op * cov)).round() as u16;
        }
        self.composite();
    }
    // Select ▸ Color Range: select by similarity to an explicit colour (graded by
    // `fuzziness` 0..200), globally over the active layer or the composite.
    pub fn select_color_range(
        &mut self,
        r: u8,
        g: u8,
        b: u8,
        fuzziness: f32,
        mode: u8,
        all_layers: bool,
    ) {
        let Some(pixels) = self.selection_sample_buffer(all_layers) else {
            return;
        };
        if self.push_sel_undo("Color Range") {
            return;
        }
        self.sel
            .color_range(&pixels, [r, g, b], fuzziness, SelMode::from_u8(mode));
        self.sel_dirty();
    }
    // Batched Color Range used by the dialog: build its include/subtract cluster,
    // optional inverse, and final selection combine behind one undo snapshot.
    // Colours are packed RGB triples.
    /// Color Range ▸ Highlights / Midtones / Shadows. A luminance band, not an
    /// RGB cluster — the one preset family the sampled-colour path cannot fake.
    /// `kind` 0 shadows / 1 midtones / 2 highlights, `range` 0..1 is the dialog's
    /// Range slider.
    pub fn select_tonal_range(
        &mut self,
        kind: u8,
        range: f32,
        mode: u8,
        invert: bool,
        all_layers: bool,
    ) {
        if !range.is_finite() {
            return;
        }
        let Some(pixels) = self.selection_sample_buffer(all_layers) else {
            return;
        };
        if self.push_sel_undo("Color Range") {
            return;
        }
        self.sel.tonal_range(&pixels, kind, range, SelMode::from_u8(mode));
        if invert {
            self.sel.invert();
        }
        self.sel_dirty();
    }

    /// Color Range ▸ Localized Color Clusters: the sampled-colour match, faded by
    /// distance from each sample's own point so the same colour elsewhere in the
    /// frame stays unselected. `points` is a flat [x,y,…] list matching `samples`
    /// pairwise; `radius` 0 falls back to the unlocalized match.
    pub fn select_color_range_localized(
        &mut self,
        samples: &[u8],
        points: &[f32],
        fuzziness: f32,
        radius: f32,
        mode: u8,
        invert: bool,
        all_layers: bool,
    ) {
        if samples.len() < 3
            || !samples.len().is_multiple_of(3)
            || points.len() * 3 != samples.len() * 2
            || !points.iter().all(|v| v.is_finite())
            || !radius.is_finite()
        {
            return;
        }
        let Some(pixels) = self.selection_sample_buffer(all_layers) else {
            return;
        };
        if self.push_sel_undo("Color Range") {
            return;
        }
        let mode = SelMode::from_u8(mode);
        for (index, sample) in samples.chunks_exact(3).enumerate() {
            // Every sample after the first unions into the same pass, exactly as
            // the batch path does.
            let step = if index == 0 { mode } else { SelMode::Add };
            self.sel.color_range_localized(
                &pixels,
                [sample[0], sample[1], sample[2]],
                fuzziness,
                points[index * 2],
                points[index * 2 + 1],
                radius,
                step,
            );
        }
        if invert {
            self.sel.invert();
        }
        self.sel_dirty();
    }

    pub fn select_color_range_batch(
        &mut self,
        samples: &[u8],
        subtract_samples: &[u8],
        fuzziness: f32,
        mode: u8,
        invert: bool,
        all_layers: bool,
    ) {
        if samples.len() < 3
            || !samples.len().is_multiple_of(3)
            || !subtract_samples.len().is_multiple_of(3)
        {
            return;
        }
        let Some(pixels) = self.selection_sample_buffer(all_layers) else {
            return;
        };
        if self.push_sel_undo("Color Range") {
            return;
        }
        let mode = SelMode::from_u8(mode);
        let previous = match mode {
            SelMode::Add if self.sel.active => Some(self.sel.mask.clone()),
            SelMode::Subtract | SelMode::Intersect => Some(self.sel.mask.clone()),
            _ => None,
        };
        for (index, sample) in samples.chunks_exact(3).enumerate() {
            self.sel.color_range(
                &pixels,
                [sample[0], sample[1], sample[2]],
                fuzziness,
                if index == 0 {
                    SelMode::Replace
                } else {
                    SelMode::Add
                },
            );
        }
        for sample in subtract_samples.chunks_exact(3) {
            self.sel.color_range(
                &pixels,
                [sample[0], sample[1], sample[2]],
                fuzziness,
                SelMode::Subtract,
            );
        }
        if invert {
            self.sel.invert();
        }
        if let Some(previous) = previous {
            if mode == SelMode::Subtract {
                self.sel.invert();
            }
            self.sel.apply_saved(
                &previous,
                if mode == SelMode::Add {
                    SelMode::Add
                } else {
                    SelMode::Intersect
                },
            );
        }
        self.sel_dirty();
    }
    // Select ▸ Save Selection: store the current selection (or the whole canvas
    // if nothing is selected) as a named channel, replacing any of the same name.
    pub fn save_selection(&mut self, name: String) {
        if self.push_stack_undo("Save Selection") {
            return;
        }
        self.write_saved_selection(name);
    }

    /// Save explicit document-sized coverage without changing the live selection.
    pub fn save_selection_mask(&mut self, name: String, mask: &[u8]) {
        if mask.len() != (self.w * self.h) as usize || self.push_stack_undo("Save Selection") {
            return;
        }
        self.write_saved_selection_mask(name, mask.to_vec());
    }

    /// Write a saved-selection channel WITHOUT taking a history step.
    ///
    /// The store exchanges selections between documents through a scratch channel:
    /// it sets a mask (one undo step), saves it to a channel, then undoes to restore
    /// the destination's own live selection. With the tracked `save_selection` that
    /// `undo()` popped the SAVE step instead of the mask step — so the channel was
    /// thrown away, the foreign mask stayed on screen, and Add/Subtract/Intersect
    /// silently degraded to Replace. The channel write is the intended edit here, so
    /// it must not be an undo step of its own. (#81)
    pub fn save_selection_untracked(&mut self, name: String) {
        self.write_saved_selection(name);
    }

    fn write_saved_selection(&mut self, name: String) {
        let mask = if self.sel.active {
            self.sel.mask.clone()
        } else {
            vec![255u8; (self.w * self.h) as usize]
        };
        self.write_saved_selection_mask(name, mask);
    }

    fn write_saved_selection_mask(&mut self, name: String, mask: Vec<u8>) {
        if let Some(slot) = self.saved_sels.iter_mut().find(|(n, _)| *n == name) {
            slot.1 = mask;
        } else {
            self.saved_sels.push((name, mask));
        }
    }
    // Select ▸ Load Selection: combine a saved channel into the active selection.
    /// A saved-selection channel's coverage bytes — a PURE READ.
    ///
    /// Reading a channel out of another document used to mean `load_selection` +
    /// `undo()`, which pushed a Sel entry on that document and left its counterpart
    /// sitting on its REDO stack: the source document then reported canRedo and
    /// Ctrl+Shift+Z there re-applied a selection load the user never performed.
    /// Empty when the channel does not exist. (#88)
    pub fn saved_selection_mask(&self, name: String) -> Vec<u8> {
        self.saved_sels
            .iter()
            .find(|(n, _)| *n == name)
            .map(|(_, m)| m.clone())
            .unwrap_or_default()
    }

    pub fn load_selection(&mut self, name: String, mode: u8) {
        let mask = match self.saved_sels.iter().find(|(n, _)| *n == name) {
            Some((_, m)) => m.clone(),
            None => return,
        };
        self.apply_selection_mask(&mask, mode);
    }

    /// Combine explicit document-sized coverage into the live selection as one step.
    pub fn apply_selection_mask(&mut self, mask: &[u8], mode: u8) {
        if mask.len() != (self.w * self.h) as usize || self.push_sel_undo("Load Selection") {
            return;
        }
        self.sel.apply_saved(mask, SelMode::from_u8(mode));
        self.sel_dirty();
    }
    pub fn saved_selection_names(&self) -> Vec<String> {
        self.saved_sels.iter().map(|(n, _)| n.clone()).collect()
    }
    pub fn delete_saved_selection(&mut self, name: String) {
        // The read-only refusal must speak even when the op would be a no-op, so
        // it stays ahead of the validity check. push_stack_undo re-checks it.
        if self.reject_imported_photoshop_edit() {
            return;
        }
        if !self.saved_sels.iter().any(|(n, _)| *n == name) {
            return;
        }
        if self.push_stack_undo("Delete Channel") {
            return;
        }
        self.saved_sels.retain(|(n, _)| *n != name);
    }
    /// Channels panel ▸ New Spot Channel: add a named ink plate whose coverage is
    /// the current selection (or the whole canvas if nothing is selected).
    pub fn add_spot_channel(&mut self, name: String, r: u8, g: u8, b: u8, solidity: f32) {
        // The read-only refusal must speak even when the op would be a no-op, so
        // it stays ahead of the validity check. push_stack_undo re-checks it.
        if self.reject_imported_photoshop_edit() {
            return;
        }
        if self.spot_channels.len() >= MAX_SPOT_CHANNELS || !solidity.is_finite() {
            return;
        }
        if self.push_stack_undo("New Spot Channel") {
            return;
        }
        let coverage = if self.sel.active {
            self.sel.mask.clone()
        } else {
            vec![255u8; (self.w * self.h) as usize]
        };
        self.spot_channels.push(SpotChannel {
            name,
            ink: [r, g, b],
            solidity: solidity.clamp(0.0, 1.0),
            coverage,
            visible: true,
        });
    }
    pub fn document_channel_count(&self) -> usize {
        self.document_channels.len()
    }
    pub fn spot_channel_count(&self) -> usize {
        self.spot_channels.len()
    }
    pub fn spot_channel_name(&self, i: usize) -> String {
        self.spot_channels
            .get(i)
            .map(|s| s.name.clone())
            .unwrap_or_default()
    }
    pub fn remove_spot_channel(&mut self, i: usize) {
        // The read-only refusal must speak even when the op would be a no-op, so
        // it stays ahead of the validity check. push_stack_undo re-checks it.
        if self.reject_imported_photoshop_edit() {
            return;
        }
        if i >= self.spot_channels.len() {
            return;
        }
        if self.push_stack_undo("Delete Spot Channel") {
            return;
        }
        self.spot_channels.remove(i);
    }
    /// The plate's ink as 0xRRGGBB, so the panel can show the real swatch.
    /// The spot plate's ink coverage (w*h, 255 = full ink), for the Channels
    /// panel thumbnail. Empty for an unknown index. Read-only, like the plate's
    /// other getters beside it.
    pub fn spot_channel_coverage(&self, i: usize) -> Vec<u8> {
        self.spot_channels
            .get(i)
            .map(|c| c.coverage.clone())
            .unwrap_or_default()
    }
    pub fn spot_channel_ink(&self, i: usize) -> u32 {
        self.spot_channels
            .get(i)
            .map(|s| {
                (u32::from(s.ink[0]) << 16) | (u32::from(s.ink[1]) << 8) | u32::from(s.ink[2])
            })
            .unwrap_or_default()
    }
    pub fn spot_channel_solidity(&self, i: usize) -> f32 {
        self.spot_channels.get(i).map(|s| s.solidity).unwrap_or(1.0)
    }
    pub fn spot_channel_visible(&self, i: usize) -> bool {
        self.spot_channels.get(i).is_some_and(|s| s.visible)
    }
    /// Channels panel ▸ the plate's eye. Display state, so it neither dirties
    /// history nor touches the coverage — it only stops the ink printing.
    pub fn set_spot_channel_visible(&mut self, i: usize, on: bool) {
        if let Some(spot) = self.spot_channels.get_mut(i) {
            if spot.visible == on {
                return;
            }
            spot.visible = on;
            self.composite();
        }
    }
    /// Channels panel ▸ Spot Channel Options: Photoshop edits the plate's name,
    /// ink and solidity in one dialog, so this takes all three at once.
    pub fn set_spot_channel_options(
        &mut self,
        i: usize,
        name: String,
        r: u8,
        g: u8,
        b: u8,
        solidity: f32,
    ) {
        if i >= self.spot_channels.len() || !solidity.is_finite() {
            return;
        }
        if self.push_stack_undo("Spot Channel Options") {
            return;
        }
        let spot = &mut self.spot_channels[i];
        spot.name = name;
        spot.ink = [r, g, b];
        spot.solidity = solidity.clamp(0.0, 1.0);
        self.composite();
    }
    /// Channels panel ▸ target a spot plate: its coverage becomes the selection,
    /// which is what Quick Mask paints. The write-back half is
    /// `save_selection_to_spot_channel`, exactly the round-trip an alpha channel
    /// is targeted through.
    pub fn load_spot_channel_as_selection(&mut self, i: usize, mode: u8) {
        let mask = match self.spot_channels.get(i) {
            Some(spot) => spot.coverage.clone(),
            None => return,
        };
        if self.push_sel_undo("Load Spot Channel") {
            return;
        }
        self.sel.apply_saved(&mask, SelMode::from_u8(mode));
        self.sel_dirty();
    }
    /// The painted buffer becomes the plate's coverage — the edit half of a spot
    /// channel. No selection means full coverage, matching `save_selection`.
    pub fn save_selection_to_spot_channel(&mut self, i: usize) {
        if i >= self.spot_channels.len() {
            return;
        }
        if self.push_stack_undo("Edit Spot Channel") {
            return;
        }
        let mask = if self.sel.active {
            self.sel.mask.clone()
        } else {
            vec![255u8; (self.w * self.h) as usize]
        };
        self.spot_channels[i].coverage = mask;
        self.composite();
    }
    /// Channels panel ▸ Merge Spot Channel: flatten the image and print this ink
    /// into the pixels, then drop the plate. The other plates stay live, so they
    /// are muted for the flatten instead of being baked in with it.
    pub fn merge_spot_channel(&mut self, i: usize) {
        if i >= self.spot_channels.len() {
            return;
        }
        if self.reject_document_float_edit("Merge Spot Channel") {
            return;
        }
        if self.push_stack_undo("Merge Spot Channel") {
            return;
        }
        let visibility: Vec<bool> = self.spot_channels.iter().map(|s| s.visible).collect();
        for (index, spot) in self.spot_channels.iter_mut().enumerate() {
            spot.visible = index == i;
        }
        self.flatten_into_background();
        self.spot_channels.remove(i);
        for (index, spot) in self.spot_channels.iter_mut().enumerate() {
            // `visibility` still has the merged plate in it, so indices at or
            // past the removed one shift by one.
            spot.visible = visibility[index + usize::from(index >= i)];
        }
        self.composite();
    }
    // Overprint every spot channel's ink onto the composite in the region.
    // Empty spot list is a no-op, so ordinary documents pay nothing.
    fn overprint_spot_channels(&mut self, x0: i32, y0: i32, x1: i32, y1: i32) {
        if self.spot_channels.is_empty() {
            return;
        }
        let spots = std::mem::take(&mut self.spot_channels);
        let w = self.w as i32;
        for sc in spots.iter().filter(|sc| sc.visible) {
            for y in y0..y1 {
                for x in x0..x1 {
                    let idx = (y * w + x) as usize;
                    let cov = sc.coverage.get(idx).copied().unwrap_or(0);
                    if cov == 0 {
                        continue;
                    }
                    let t = (cov as f32 / 255.0) * sc.solidity;
                    let o = idx * 4;
                    for k in 0..3 {
                        let base = self.output[o + k] as f32;
                        self.output[o + k] = (base * (1.0 - t) + sc.ink[k] as f32 * t)
                            .round()
                            .clamp(0.0, 255.0) as u8;
                    }
                }
            }
        }
        self.spot_channels = spots;
    }
    fn overprint_spot_channels_u8(&self, output: &mut [u8], x0: i32, y0: i32, x1: i32, y1: i32) {
        if self.spot_channels.is_empty() {
            return;
        }
        let w = self.w as i32;
        for spot in self.spot_channels.iter().filter(|spot| spot.visible) {
            for y in y0..y1 {
                for x in x0..x1 {
                    let index = (y * w + x) as usize;
                    let coverage = spot.coverage.get(index).copied().unwrap_or(0);
                    if coverage == 0 {
                        continue;
                    }
                    let amount = (coverage as f32 / 255.0) * spot.solidity;
                    let offset = index * 4;
                    for channel in 0..3 {
                        let base = output[offset + channel] as f32;
                        let ink = spot.ink[channel] as f32;
                        output[offset + channel] = (base * (1.0 - amount) + ink * amount)
                            .round()
                            .clamp(0.0, 255.0) as u8;
                    }
                }
            }
        }
    }
    fn overprint_spot_channels_u16(&self, output: &mut [u16], x0: i32, y0: i32, x1: i32, y1: i32) {
        if self.spot_channels.is_empty() {
            return;
        }
        let w = self.w as i32;
        for spot in self.spot_channels.iter().filter(|spot| spot.visible) {
            for y in y0..y1 {
                for x in x0..x1 {
                    let index = (y * w + x) as usize;
                    let coverage = spot.coverage.get(index).copied().unwrap_or(0);
                    if coverage == 0 {
                        continue;
                    }
                    let amount = (coverage as f32 / 255.0) * spot.solidity;
                    let offset = index * 4;
                    for channel in 0..3 {
                        let base = output[offset + channel] as f32;
                        let ink = spot.ink[channel] as f32 * 257.0;
                        output[offset + channel] = (base * (1.0 - amount) + ink * amount)
                            .round()
                            .clamp(0.0, 65535.0)
                            as u16;
                    }
                }
            }
        }
    }
    fn overprint_spot_channels_f32(&self, output: &mut [f32], x0: i32, y0: i32, x1: i32, y1: i32) {
        let w = self.w as i32;
        for spot in self.spot_channels.iter().filter(|spot| spot.visible) {
            for y in y0..y1 {
                for x in x0..x1 {
                    let index = (y * w + x) as usize;
                    let coverage = spot.coverage.get(index).copied().unwrap_or(0);
                    if coverage == 0 {
                        continue;
                    }
                    let amount = (coverage as f32 / 255.0) * spot.solidity;
                    let offset = index * 4;
                    for channel in 0..3 {
                        let ink = spot.ink[channel] as f32 / 255.0;
                        output[offset + channel] =
                            output[offset + channel] * (1.0 - amount) + ink * amount;
                    }
                }
            }
        }
    }
    /// Channels panel ▸ Duplicate Channel: copy a document plate's grayscale
    /// into a new named alpha channel. `channel` is 1-based within the CURRENT
    /// mode's plate set — R,G,B · Gray · C,M,Y,K · L,a,b — and 0 (or an index
    /// past the set) means the composite luminance. CMYK/Lab plates are
    /// separated on demand through the shared ink model, so every mode has real
    /// pixel channels here. Reuses the alpha-channel store, so — like Save
    /// Selection — it is not part of the pixel undo snapshot.
    pub fn duplicate_channel(&mut self, channel: u8, name: String) {
        // The read-only refusal must speak even when the op would be a no-op, so
        // it stays ahead of the validity check. push_stack_undo re-checks it.
        if self.reject_imported_photoshop_edit() {
            return;
        }
        let n = (self.w * self.h) as usize;
        if self.output.len() < n * 4 {
            return;
        }
        if self.push_stack_undo("Duplicate Channel") {
            return;
        }
        let plate = (channel as usize)
            .checked_sub(1)
            .filter(|p| *p < Self::plate_count(self.mode));
        let profile = self.mode_profile.as_deref();
        let mut mask = vec![0u8; n];
        for (i, m) in mask.iter_mut().enumerate() {
            let o = i * 4;
            let r = self.output[o] as f32;
            let g = self.output[o + 1] as f32;
            let b = self.output[o + 2] as f32;
            // ponytail: one ICC call per pixel for a profiled document; batch
            // through `separate` if a very large Duplicate Channel drags.
            *m = match plate {
                Some(p) => color::to8(
                    Self::doc_plates_of(profile, self.mode, [r / 255.0, g / 255.0, b / 255.0])[p],
                ),
                None => (0.299 * r + 0.587 * g + 0.114 * b)
                    .round()
                    .clamp(0.0, 255.0) as u8,
            };
        }
        if let Some(slot) = self.saved_sels.iter_mut().find(|(nm, _)| *nm == name) {
            slot.1 = mask;
        } else {
            self.saved_sels.push((name, mask));
        }
    }

    /// Channels panel ▸ Apply to Channel: write a saved alpha channel back into
    /// a document plate — the inverse of Duplicate Channel, and what makes a
    /// CMYK/Lab plate editable (paint or adjust an alpha channel, then push it
    /// into the Cyan or the a plate). `channel` is 1-based within the current
    /// mode's plate set; 0 or an out-of-range index is refused. Writes the
    /// ACTIVE layer through the shared ink model as one undo step, honouring the
    /// selection.
    pub fn apply_alpha_to_channel(&mut self, name: String, channel: u8) {
        let Some(plate) = (channel as usize)
            .checked_sub(1)
            .filter(|p| *p < Self::plate_count(self.mode))
        else {
            return;
        };
        let Some(alpha) = self
            .saved_sels
            .iter()
            .find(|(nm, _)| *nm == name)
            .map(|(_, mask)| mask.clone())
        else {
            return;
        };
        let mode = self.mode;
        let profile = self.mode_profile.clone();
        let canvas_w = self.w as i32;
        let canvas_h = self.h as i32;
        let layer = &self.layers[self.active];
        let (origin_x, origin_y) = (
            layer.pixel_bounds.x + layer.ox,
            layer.pixel_bounds.y + layer.oy,
        );
        self.apply16("Apply Channel", |px, sel| {
            for i in 0..(sel.w * sel.h) as usize {
                let cov = sel.coverage(i);
                if cov <= 0.0 {
                    continue;
                }
                // The alpha channel is canvas-space; the plane may sit at an
                // offset, so pixels outside the canvas simply have no source.
                let x = origin_x + (i % sel.w as usize) as i32;
                let y = origin_y + (i / sel.w as usize) as i32;
                if x < 0 || y < 0 || x >= canvas_w || y >= canvas_h {
                    continue;
                }
                let Some(value) = alpha.get((y * canvas_w + x) as usize) else {
                    continue;
                };
                let o = i * 4;
                let rgb = [
                    px[o] as f32 / 65535.0,
                    px[o + 1] as f32 / 65535.0,
                    px[o + 2] as f32 / 65535.0,
                ];
                let mut plates = Self::doc_plates_of(profile.as_deref(), mode, rgb);
                plates[plate] = *value as f32 / 255.0;
                let out = Self::doc_rgb_of_plates(profile.as_deref(), mode, plates);
                for c in 0..3 {
                    px[o + c] = color::to16(color::lerp(rgb[c], out[c], cov));
                }
            }
        });
    }
    pub fn has_selection(&self) -> bool {
        self.sel.active
    }
    pub fn selection_ptr(&self) -> *const u8 {
        self.sel.mask.as_ptr()
    }
    pub fn selection_bounds(&self) -> Vec<i32> {
        self.sel.bounds().to_vec()
    }

    // ── Quick Mask (true rubylith overlay) ─────────────────────
    /// Enter Quick Mask: seed the buffer from the current selection (selected
    /// pixels → 255; if nothing is selected the whole canvas starts selected /
    /// unmasked) and suspend the live marquee so the marching ants vanish while
    /// the mask is painted. Bumps qm_gen + sel_gen.
    pub fn enter_quick_mask(&mut self) {
        if self.qm_on {
            return;
        }
        let n = (self.w * self.h) as usize;
        self.quick_mask = if self.sel.active {
            self.sel.mask.clone()
        } else {
            vec![255u8; n]
        };
        self.sel.active = false; // suspend the marquee while in Quick Mask
        self.qm_on = true;
        self.qm_gen = self.qm_gen.wrapping_add(1);
        self.sel_dirty();
    }

    /// Exit Quick Mask: convert the buffer back into the active selection (an
    /// all-255 buffer means "select all" — no marquee), recording one Sel undo
    /// step so the whole round-trip is undoable, then drop the buffer.
    pub fn exit_quick_mask(&mut self) {
        if !self.qm_on {
            return;
        }
        if self.push_sel_undo("Quick Mask") {
            return;
        }
        let buf = std::mem::take(&mut self.quick_mask); // clears the field too
        if buf.iter().all(|&v| v == 255) {
            self.sel.select_all(); // active=false, whole-canvas selection
        } else {
            self.sel.set_mask(&buf); // active=true, coverage = buffer
        }
        self.qm_on = false;
        self.qm_gen = self.qm_gen.wrapping_add(1);
        self.sel_dirty();
    }

    pub fn quick_mask_on(&self) -> bool {
        self.qm_on
    }
    pub fn quick_mask_generation(&self) -> u32 {
        self.qm_gen
    }
    pub fn quick_mask_ptr(&self) -> *const u8 {
        self.quick_mask.as_ptr()
    }

    // ── Adjustments (active layer, masked by selection) ─────────
    pub fn adjust_brightness_contrast(&mut self, brightness: f32, contrast: f32) {
        // NaN/Infinity through the transfer become 0 and blacken the layer.
        if self.reject_invalid_edit_params(
            "Brightness/Contrast",
            !brightness.is_finite() || !contrast.is_finite(),
        ) {
            return;
        }
        self.apply16("Brightness/Contrast", |px, sel| {
            adjust::brightness_contrast(px, sel, brightness, contrast)
        });
    }
    pub fn adjust_levels(&mut self, ib: f32, iw: f32, gamma: f32, ob: f32, ow: f32, channel: u8) {
        let p = [ib, iw, gamma, ob, ow];
        if self.reject_invalid_edit_params("Levels", p.iter().any(|v| !v.is_finite())) {
            return;
        }
        if self.apply32("Levels", |px, _, _| {
            for pixel in px.chunks_exact_mut(4) {
                for c in 0..3 {
                    if !(1..=3).contains(&channel) || channel as usize == c + 1 {
                        pixel[c] = adjust::levels_float(pixel[c], &p);
                    }
                }
            }
        }) { return; }
        self.apply16("Levels", |px, sel| {
            adjust::levels(px, sel, ib, iw, gamma, ob, ow, channel)
        });
    }
    // Levels with a Channel selector: composite + per-channel applied together in one
    // pass (each slice is [in_black, in_white, gamma, out_black, out_white], 0..1).
    pub fn adjust_levels_multi(&mut self, comp: &[f32], red: &[f32], grn: &[f32], blu: &[f32]) {
        if self.reject_invalid_edit_params("Levels", [comp, red, grn, blu].iter().any(|p| {
            p.len() < 5 || p[..5].iter().any(|v| !v.is_finite())
        })) {
            return;
        }
        if self.apply32("Levels", |px, _, _| {
            for pixel in px.chunks_exact_mut(4) {
                for (c, p) in [red, grn, blu].iter().enumerate() {
                    pixel[c] = adjust::levels_float(adjust::levels_float(pixel[c], comp), p);
                }
            }
        }) { return; }
        self.apply16("Levels", |px, sel| {
            adjust::levels_multi(px, sel, comp, red, grn, blu)
        });
    }
    pub fn adjust_curves(&mut self, master: &[u8], r: &[u8], g: &[u8], b: &[u8]) {
        // curves() indexes all four as 256-entry transfer LUTs; a short slice
        // (e.g. from the scripting API) would panic, so require full LUTs.
        if self.reject_invalid_edit_params("Curves", [master, r, g, b].iter().any(|lut| lut.len() < 256)) {
            return;
        }
        if self.apply32("Curves", |px, _, _| {
            for pixel in px.chunks_exact_mut(4) {
                for (c, lut) in [r, g, b].iter().enumerate() {
                    pixel[c] = adjust::curve_float(lut, adjust::curve_float(master, pixel[c]));
                }
            }
        }) { return; }
        self.apply16("Curves", |px, sel| adjust::curves(px, sel, master, r, g, b));
    }
    pub fn adjust_hue_saturation(&mut self, hue: f32, sat: f32, light: f32) {
        self.adjust_hue_saturation_params(&[hue, sat, light]);
    }
    pub fn adjust_hue_saturation_params(&mut self, params: &[f32]) {
        if self.reject_invalid_edit_params("Hue/Saturation", params.len() < 3 || params.iter().any(|v| !v.is_finite())) {
            return;
        }
        if self.apply32("Hue/Saturation", |px, _, _| {
            for pixel in px.chunks_exact_mut(4) {
                let (r, g, b) = adjust::hue_saturation_float(pixel[0], pixel[1], pixel[2], params);
                pixel[..3].copy_from_slice(&[r, g, b]);
            }
        }) { return; }
        self.apply16("Hue/Saturation", |px, sel| {
            adjust::hue_saturation_params(px, sel, params)
        });
    }
