    pub fn adjust_exposure(&mut self, exposure: f32, offset: f32, gamma: f32) {
        if self.reject_invalid_edit_params("Exposure", [exposure, offset, gamma].iter().any(|v| !v.is_finite())) {
            return;
        }
        if self.apply32("Exposure", |px, _, _| {
            let (multiplier, inverse_gamma) = (2.0f32.powf(exposure), 1.0 / gamma.max(1e-4));
            for pixel in px.chunks_exact_mut(4) {
                for value in &mut pixel[..3] {
                    // Float authority is scene-linear already.
                    *value = adjust::signed_power(*value * multiplier + offset, inverse_gamma);
                }
            }
        }) { return; }
        self.apply16("Exposure", |px, sel| {
            adjust::exposure(px, sel, exposure, offset, gamma)
        });
    }

    // Image ▸ Auto Tone / Auto Contrast: stretch the active layer's tonal range
    // so the darkest pixels become black and the lightest white, ignoring a
    // 0.1% clip at each end. Auto Tone stretches each RGB channel independently
    // (can shift colour); Auto Contrast pools all channels into one black/white
    // point (preserves colour balance). Photoshop parity.
    pub fn auto_tone(&mut self) {
        self.auto_stretch(true, "Auto Tone");
    }
    pub fn auto_contrast(&mut self) {
        self.auto_stretch(false, "Auto Contrast");
    }

    // Image ▸ Auto Color: per-channel contrast stretch (like Auto Tone) followed
    // by a midtone neutralization — a per-channel gamma that maps each channel's
    // mean toward the average gray, removing colour casts Auto Tone can introduce.
    pub fn auto_color(&mut self) {
        if self.refuse_locked_transform() {
            return;
        }
        if self.reject_legacy_float_edit("Auto Color") {
            return;
        }
        // The PLANE's pixel count: the canvas count sampled and rewrote only the
        // first w*h pixels of a larger plane, so on a cropped document Auto Color
        // did nothing visible.
        let Some(_) = self.plane_local_selection() else {
            return; // plane and bounds disagree
        };
        let n = self.layers[self.active].pixels.len() / 4;
        let px = &self.layers[self.active].pixels;
        let mut ranges = [(0u32, 255u32); 3];
        for (c, rc) in ranges.iter_mut().enumerate() {
            let mut hist = [0u32; 256];
            for i in 0..n {
                if px[i * 4 + 3] > 0 {
                    hist[(px[i * 4 + c] >> 8) as usize] += 1;
                }
            }
            *rc = Engine::hist_bounds(&hist, 0.001);
        }
        if ranges.iter().all(|&(lo, hi)| hi <= lo) {
            return;
        }
        if self.push_layer_undo("Auto Color") {
            return;
        }
        let px = Arc::make_mut(&mut self.layers[self.active].pixels);
        for i in 0..n {
            for c in 0..3 {
                let (lo, hi) = ranges[c];
                if hi <= lo {
                    continue;
                }
                let v = (px[i * 4 + c] >> 8) as i32;
                let nv = (((v - lo as i32) * 255) / (hi as i32 - lo as i32)).clamp(0, 255) as u16;
                px[i * 4 + c] = nv * 257;
            }
        }
        // Midtone neutralization: per-channel gamma so mean_c → target gray.
        let (mut means, mut count) = ([0f64; 3], 0u64);
        for i in 0..n {
            if px[i * 4 + 3] > 0 {
                count += 1;
                for c in 0..3 {
                    means[c] += (px[i * 4 + c] >> 8) as f64;
                }
            }
        }
        if count > 0 {
            for m in means.iter_mut() {
                *m /= count as f64 * 255.0;
            }
            let target = ((means[0] + means[1] + means[2]) / 3.0).clamp(0.004, 0.996);
            let mut inv_gamma = [1f64; 3];
            for c in 0..3 {
                let m = means[c].clamp(0.004, 0.996);
                inv_gamma[c] = target.ln() / m.ln(); // m^(inv_gamma) == target
            }
            for i in 0..n {
                for c in 0..3 {
                    let v = (px[i * 4 + c] >> 8) as f64 / 255.0;
                    let nv = (v.powf(inv_gamma[c]) * 255.0).round().clamp(0.0, 255.0) as u16;
                    px[i * 4 + c] = nv * 257;
                }
            }
        }
        self.composite();
    }

    // Image ▸ Adjustments ▸ HDR Toning — local tone mapping on the active layer.
    // The four-slider shorthand the scripting API and recorded actions already
    // speak; `hdr_toning_pro` is the full Local Adaptation panel and does the
    // work, so both doors get the same tone map.
    pub fn hdr_toning(&mut self, radius: f32, detail: f32, gamma: f32, exposure: f32) {
        let neutral = LocalAdaptation::default();
        self.hdr_toning_pro(&[
            radius,
            neutral.strength,
            gamma,
            exposure,
            detail,
            neutral.shadow,
            neutral.highlight,
            neutral.vibrance,
            neutral.saturation,
        ]);
    }

    /// Image ▸ Adjustments ▸ HDR Toning ▸ Local Adaptation. `p` is
    /// `[radius, strength, gamma, exposure, detail, shadow, highlight, vibrance,
    /// saturation]`, optionally followed by a 256-entry 0..1 toning-curve LUT.
    ///
    /// Runs on the 32-bit float authority when the layer has one, which is what
    /// makes the radiance document `merge_to_hdr` produces tone-mappable at all
    /// — the u16-proxy path was refused as float-unsafe, leaving Merge to HDR
    /// Pro with no way back to a display-referred image.
    pub fn hdr_toning_pro(&mut self, p: &[f32]) {
        // Trust boundary: the slice arrives straight from JS.
        if p.len() < 9 || p.iter().any(|value| !value.is_finite()) {
            return;
        }
        if self.active_layer().locked || self.active_layer().kind != 0 {
            return;
        }
        if self.push_layer_undo("HDR Toning") {
            return;
        }
        let params = LocalAdaptation {
            // Photoshop's Radius ceiling. `blur_f32` is O(n·radius), so a
            // scripted 500 on a large document is slow but bounded; a summed-
            // area (or IIR) blur is the upgrade path if that ever bites.
            radius: p[0].clamp(0.0, 500.0),
            strength: p[1].clamp(0.0, 4.0),
            gamma: p[2].clamp(0.05, 10.0),
            exposure: p[3].clamp(-20.0, 20.0),
            detail: p[4].clamp(0.0, 4.0),
            shadow: p[5].clamp(-1.0, 1.0),
            highlight: p[6].clamp(-1.0, 1.0),
            vibrance: p[7].clamp(-1.0, 1.0),
            saturation: p[8].clamp(-1.0, 1.0),
        };
        let curve = if p.len() >= 9 + 256 { &p[9..9 + 256] } else { &[][..] };
        let layer = &mut self.layers[self.active];
        let (w, h) = (layer.pixel_bounds.w, layer.pixel_bounds.h);
        if layer.pixels_f32.len() == layer.pixels.len() {
            local_adaptation(Arc::make_mut(&mut layer.pixels_f32), w, h, params, curve);
            sync_preview_plane(Arc::make_mut(&mut layer.pixels), &layer.pixels_f32);
        } else {
            // 8/16-bit: the u16 store is the authority, so tone-map a 0..1 copy
            // and write it back through the same rounding every float path uses.
            let mut px: Vec<f32> = layer.pixels.iter().map(|v| *v as f32 / 65_535.0).collect();
            local_adaptation(&mut px, w, h, params, curve);
            for (dst, src) in Arc::make_mut(&mut layer.pixels).iter_mut().zip(&px) {
                *dst = float_preview_u16(*src);
            }
        }
        self.composite();
    }

    // Per-channel mean & standard deviation (normalized 0..1) over the OPAQUE
    // pixels of a layer. Returns None when the layer has no opaque pixels.
    fn channel_stats(px: &[u16]) -> Option<([f32; 3], [f32; 3])> {
        let mut sum = [0f64; 3];
        let mut sumsq = [0f64; 3];
        let mut count = 0u64;
        let n = px.len() / 4;
        for i in 0..n {
            if px[i * 4 + 3] == 0 {
                continue;
            }
            count += 1;
            for c in 0..3 {
                let v = px[i * 4 + c] as f64 / 65535.0;
                sum[c] += v;
                sumsq[c] += v * v;
            }
        }
        if count == 0 {
            return None;
        }
        let mut mean = [0f32; 3];
        let mut std = [0f32; 3];
        for c in 0..3 {
            let m = sum[c] / count as f64;
            let var = (sumsq[c] / count as f64 - m * m).max(0.0);
            mean[c] = m as f32;
            std[c] = var.sqrt() as f32;
        }
        Some((mean, std))
    }

    // Image ▸ Adjustments ▸ Match Color. Shifts the active layer's colour
    // statistics toward a source layer (per-channel Reinhard transfer): each
    // channel is re-centred on the source mean and rescaled toward the source
    // spread. `luminance` (0..2) scales the result's brightness, `intensity`
    // (0..2) scales how strongly the colour match is applied, `fade` (0..1)
    // blends back toward the original, and `neutralize` removes the target's
    // colour cast first. Honors the active selection as a coverage mask.
    pub fn match_color(
        &mut self,
        source_id: u32,
        luminance: f32,
        intensity: f32,
        fade: f32,
        neutralize: bool,
    ) {
        if self.active_layer().locked || self.active_layer().kind != 0 {
            return;
        }
        if self.reject_legacy_float_edit("Match Color") {
            return;
        }
        let si = match self.layer_index(source_id) {
            Some(i) => i,
            None => return,
        };
        let (mean_s, std_s) = match Engine::channel_stats(&self.layers[si].pixels) {
            Some(s) => s,
            None => return,
        };
        let (mut mean_t, std_t) = match Engine::channel_stats(&self.layers[self.active].pixels) {
            Some(s) => s,
            None => return,
        };
        let Some(local) = self.plane_local_selection() else {
            return;
        };
        // Neutralize: collapse the target means to their average so a colour cast
        // doesn't survive the transfer (the per-channel offset is removed).
        let mut cast = [0f32; 3];
        if neutralize {
            let avg = (mean_t[0] + mean_t[1] + mean_t[2]) / 3.0;
            for c in 0..3 {
                cast[c] = mean_t[c] - avg;
                mean_t[c] = avg;
            }
        }
        // Per-channel rescale ratio toward the source spread (guarded for flat
        // channels where the target has no measurable variance).
        let mut ratio = [1f32; 3];
        for c in 0..3 {
            ratio[c] = if std_t[c] > 1e-4 {
                (std_s[c] / std_t[c]).clamp(0.2, 5.0)
            } else {
                1.0
            };
        }
        if self.push_layer_undo("Match Color") {
            return;
        }
        let n = self.layers[self.active].pixels.len() / 4;
        let sel_active = local.active;
        let px = Arc::make_mut(&mut self.layers[self.active].pixels);
        for i in 0..n {
            let cov = if sel_active {
                local.coverage(i)
            } else {
                1.0
            };
            if cov <= 0.0 {
                continue;
            }
            for c in 0..3 {
                let inp = px[i * 4 + c] as f32 / 65535.0;
                let centered = inp - cast[c]; // remove cast (0 when not neutralizing)
                let mut m = (centered - mean_t[c]) * ratio[c] + mean_s[c];
                // colour-match intensity: pull deviation from the source mean
                m = mean_s[c] + (m - mean_s[c]) * intensity;
                m *= luminance; // brightness of the matched result
                let out = (m * (1.0 - fade) + inp * fade).clamp(0.0, 1.0);
                px[i * 4 + c] =
                    (px[i * 4 + c] as f32 * (1.0 - cov) + out * 65535.0 * cov).round() as u16;
            }
        }
        self.composite();
    }

    fn auto_stretch(&mut self, per_channel: bool, label: &str) {
        if self.refuse_locked_transform() {
            return;
        }
        if self.reject_legacy_float_edit(label) {
            return;
        }
        if self.plane_rect(self.active).is_none() {
            return;
        }
        let n = self.layers[self.active].pixels.len() / 4;
        let px = &self.layers[self.active].pixels;
        let ranges: [(u32, u32); 3] = if per_channel {
            let mut r = [(0u32, 255u32); 3];
            for (c, rc) in r.iter_mut().enumerate() {
                let mut hist = [0u32; 256];
                for i in 0..n {
                    if px[i * 4 + 3] > 0 {
                        hist[(px[i * 4 + c] >> 8) as usize] += 1;
                    }
                }
                *rc = Engine::hist_bounds(&hist, 0.001);
            }
            r
        } else {
            let mut hist = [0u32; 256];
            for i in 0..n {
                if px[i * 4 + 3] > 0 {
                    for c in 0..3 {
                        hist[(px[i * 4 + c] >> 8) as usize] += 1;
                    }
                }
            }
            let g = Engine::hist_bounds(&hist, 0.001);
            [g, g, g]
        };
        if ranges.iter().all(|&(lo, hi)| hi <= lo) {
            return; // flat / nothing to stretch
        }
        if self.push_layer_undo(label) {
            return;
        }
        let px = Arc::make_mut(&mut self.layers[self.active].pixels);
        for i in 0..n {
            for c in 0..3 {
                let (lo, hi) = ranges[c];
                if hi <= lo {
                    continue;
                }
                let v = (px[i * 4 + c] >> 8) as i32;
                let nv = (((v - lo as i32) * 255) / (hi as i32 - lo as i32)).clamp(0, 255) as u16;
                px[i * 4 + c] = nv * 257;
            }
        }
        self.composite();
    }

    // Black/white points from a 256-bin histogram, ignoring `clip_frac` of the
    // samples at each end (Photoshop's 0.1% clip).
    fn hist_bounds(hist: &[u32; 256], clip_frac: f32) -> (u32, u32) {
        let total: u32 = hist.iter().sum();
        if total == 0 {
            return (0, 255);
        }
        let clip = (total as f32 * clip_frac).floor() as u32;
        let (mut lo, mut acc) = (0u32, 0u32);
        for (b, &h) in hist.iter().enumerate() {
            acc += h;
            if acc > clip {
                lo = b as u32;
                break;
            }
        }
        let (mut hi, mut acc2) = (255u32, 0u32);
        for b in (0..256).rev() {
            acc2 += hist[b];
            if acc2 > clip {
                hi = b as u32;
                break;
            }
        }
        (lo, hi)
    }
    pub fn adjust_color_balance(&mut self, s: &[f32], m: &[f32], h: &[f32], preserve: bool) {
        if s.len() < 3 || m.len() < 3 || h.len() < 3 {
            return;
        }
        let (sa, ma, ha) = ([s[0], s[1], s[2]], [m[0], m[1], m[2]], [h[0], h[1], h[2]]);
        self.apply16("Color Balance", move |px, sel| {
            adjust::color_balance(px, sel, sa, ma, ha, preserve)
        });
    }
