    // Filter ▸ Camera Raw Filter — raw tone/colour controls in one pass.
    #[allow(clippy::too_many_arguments)]
    pub fn camera_raw(
        &mut self,
        temp: f32,
        exposure: f32,
        contrast: f32,
        highlights: f32,
        shadows: f32,
        clarity: f32,
        dehaze: f32,
        vibrance: f32,
        saturation: f32,
        grain: f32,
    ) {
        self.apply16("Camera Raw", move |px, sel| {
            adjust::camera_raw(
                px, sel, temp, exposure, contrast, highlights, shadows, clarity, dehaze, vibrance,
                saturation, grain,
            )
        });
    }
    // Camera Raw ▸ Develop — apply a full recipe (versioned flat params, see
    // `develop_buf`) to the active layer as one history step. Destructive path;
    // the smart-object route rides fid 17 via `smart_add_filter`/`smart_update_filter`.
    //
    // On a RAW import the develop reads the camera's highlight headroom, which
    // stays put: Undo returns the layer to the decode it describes, and
    // `camera_raw_commit` releases it once the develop is final.
    pub fn camera_raw_develop(&mut self, p: &[f32]) {
        let (w, h) = self.active_pixel_plane_dimensions();
        let params = p.to_vec();
        let usable = !self.painting_mask() && self.raw_headroom_for(self.active).is_some();
        let stored = self.raw_headroom.take();
        let headroom = stored.as_ref().filter(|_| usable).map(|(_, headroom)| headroom);
        let working_profile = self.profile;
        self.apply16("Camera Raw", move |px, sel| {
            develop_buf_with_headroom(px, w, h, sel, &params, headroom, working_profile)
        });
        self.raw_headroom = stored;
    }

    /// Camera Raw ▸ Open, after `camera_raw_develop` baked `p` into a RAW
    /// import. The import headroom only describes the undeveloped decode, so it
    /// is released here. With `float_document` the document becomes 32
    /// Bits/Channel on the same scale Image ▸ Mode ▸ 32 Bits uses (a sample is
    /// its 16-bit value / 65535, so it looks and exports the same), and a
    /// sample the develop left at white keeps the camera's headroom above 1.0:
    /// Basic's tone applied without the white clip, as long as the recipe left
    /// pixels where they were. Returns false, with `last_edit_error`, when the
    /// float document cannot be built.
    pub fn camera_raw_commit(&mut self, p: &[f32], float_document: bool) -> bool {
        let index = self.active;
        // The calibrated warp/gain has no native HDR path yet. Refuse before
        // taking the source headroom, so a retry can keep the recorded detail.
        if float_document
            && self.raw_headroom_for(index).is_some_and(|h| !h.is_empty())
            && parse_develop_advanced(p).is_some_and(|a| a.has_lens_correction())
        {
            self.last_edit_error = "Could not open this RAW at 32 bits without losing highlight detail. Disable Profile Corrections or choose 16 Bits/Channel.".into();
            return false;
        }
        let matches = self.raw_headroom_for(index).is_some();
        let headroom = self.raw_headroom.take().filter(|_| matches);
        if !float_document {
            return true;
        }
        let Some(rect) = self.plane_rect(index) else {
            self.last_edit_error = "Could not open the RAW at 32 bits: invalid layer bounds.".into();
            return false;
        };
        if self.depth == 32 || self.layers[index].kind != 0 {
            self.last_edit_error = "Could not open the RAW at 32 bits: the layer is not a 16-bit RAW decode.".into();
            return false;
        }
        let pixels = &self.layers[index].pixels;
        let mut float: Vec<f32> = pixels.iter().map(|value| *value as f32 / 65535.0).collect();
        if let Some((_, headroom)) = headroom.filter(|_| develop_preserves_headroom(p, rect.w, rect.h)) {
            let basic = DevelopBasicTone::from_params(p);
            for (pixel, source) in headroom.iter() {
                let Some(developed) = pixels.get(pixel * 4..pixel * 4 + 3) else {
                    continue;
                };
                let toned = basic.apply_extended(source);
                for c in 0..3 {
                    if developed[c] == u16::MAX {
                        float[pixel * 4 + c] = toned[c].clamp(1.0, MAX_HDR_SAMPLE);
                    }
                }
            }
        }
        self.layers[index].pixels_f32 = float.into();
        self.depth = 32;
        self.fx_cache.clear();
        self.composite();
        true
    }

