    /// Calibrated Lens Correction plus the six unchanged manual controls.
    pub fn filter_lens_profile(&mut self, params: &[f32]) {
        let Some((manual, correction)) = lens_profile::filter_params(params) else {
            self.last_edit_error = "Could not apply Lens Profile: invalid calibration or controls.".into();
            return;
        };
        let (w, h) = self.active_pixel_plane_dimensions();
        let profile = self.profile;
        self.apply16("Lens Profile Correction", move |px, sel| {
            lens_profile::apply(px, w, h, sel, profile, correction, manual);
        });
    }
