    // Filter ▸ Render ▸ Lighting Effects (point light over a luminance-bump surface).
    #[allow(clippy::too_many_arguments)]
    pub fn filter_lighting_effects(
        &mut self,
        lx: f32,
        ly: f32,
        lz: f32,
        intensity: f32,
        ambient: f32,
        bump: f32,
        r: f32,
        g: f32,
        b: f32,
        light_type: u8,
    ) {
        let (w, h) = self.active_pixel_plane_dimensions();
        // The light position arrives in CANVAS coordinates (the TS side places it on
        // the document) while the kernel below works in PLANE space, so shift it by
        // the plane origin — otherwise the light lands offset on any cropped or
        // canvas-resized document. (#42)
        let Some(rect) = self.plane_rect(self.active) else {
            return;
        };
        let (lx, ly) = (lx - rect.x as f32, ly - rect.y as f32);
        self.apply16("Lighting Effects", move |px, sel| {
            filters::lighting_effects(
                px, w, h, sel, lx, ly, lz, intensity, ambient, bump, r, g, b, light_type,
            )
        });
    }
    // Filter ▸ Blur Gallery ▸ Spin Blur (rotational blur around the centre).
    pub fn filter_spin_blur(&mut self, angle: f32, strobe_flashes: i32) {
        let (w, h) = self.active_pixel_plane_dimensions();
        let samples = (angle.abs() * 0.7).clamp(6.0, 48.0) as i32;
        self.apply16("Spin Blur", move |px, sel| {
            filters::spin_blur(px, w, h, sel, angle, samples, strobe_flashes)
        });
    }
