    #[test]
    fn live_text_reapply_returns_the_union_dirty_rect() {
        let mut e = Engine::new(100, 100);
        let id = e.add_layer("type");
        e.text_edit_session(true);
        // The first apply of a session takes the full path and seeds the footprint.
        let first = e.set_text_layer_spec(id, 20, 20, 6, 6, &[255u8, 0, 0, 255].repeat(36), "{\"text\":\"Hi\"}");
        assert!(first.is_empty());
        assert_eq!(e.pick_color(24, 24), 0xff00_00ff);
        // The next keystroke clears only the previous footprint and repaints the union.
        let second = e.set_text_layer_spec(id, 20, 20, 2, 2, &[0u8, 0, 255, 255].repeat(4), "{\"text\":\"H\"}");
        assert_eq!(second, vec![20, 20, 6, 6]);
        // Engine::new seeds an opaque white Background, so a cleared texel
        // composites to white rather than transparent.
        assert_eq!(e.pick_color(24, 24), 0xffff_ffff, "previous-footprint-only texel is cleared");
        assert_eq!(e.pick_color(20, 20), 0x0000_ffff, "new raster is painted");
        // Coalesced applies add no undo steps.
        let depth = e.undo_depth();
        let _ = e.set_text_layer_spec(id, 20, 20, 3, 3, &[0u8, 0, 255, 255].repeat(9), "{\"text\":\"He\"}");
        assert_eq!(e.undo_depth(), depth);
    }

