    #[test]
    fn artboard_background_defaults_to_white_then_recolours() {
        let mut e = Engine::new(8, 8);
        let ab = e.new_artboard_rect(1, 1, 4, 4, "Artboard 1");
        // Every artboard saved before backgrounds were colourable has a 4-slot
        // header — it must still read (and paint) as opaque white.
        assert_eq!(e.artboard_background(ab), vec![255, 255, 255, 255]);
        let png = e.export_artboard_png(0).expect("artboard PNG");
        assert_eq!(png_pixel(&png, 0, 0), [255, 255, 255, 255]);

        assert!(e.set_artboard_background(ab, 0, 0, 0, 255));
        assert_eq!(e.artboard_background(ab), vec![0, 0, 0, 255]);
        let png = e.export_artboard_png(0).expect("black artboard PNG");
        assert_eq!(png_pixel(&png, 2, 2), [0, 0, 0, 255]);
        // Re-picking the same colour is not an edit (no stray undo step).
        assert!(!e.set_artboard_background(ab, 0, 0, 0, 255));
    }

    #[test]
    fn transparent_artboard_exports_with_alpha_and_stays_an_artboard() {
        let mut e = Engine::new(8, 8);
        let leaf = e.add_layer("icon");
        e.select_rect(2, 2, 1, 1, 0);
        e.fill_selection(255, 0, 0, 255);
        e.select_none();
        let ab = e.new_artboard(1, 1, 4, 4, "Artboard 1");
        assert!(e.set_artboard_background(ab, 255, 255, 255, 0));

        let png = e.export_artboard_png(0).expect("transparent artboard PNG");
        assert_eq!(png_pixel(&png, 0, 0), [0, 0, 0, 0]); // no white plate
        assert_eq!(png_pixel(&png, 1, 1), [255, 0, 0, 255]); // contents survive
        // Transparent is a background colour, not a Frame: the Artboard tool and
        // the artboard list must still see it.
        assert!(e.artboard_ids().contains(&ab));
        assert_eq!(e.layers[e.layer_index(leaf).unwrap()].group, ab);

        // The extra header slots are length-prefixed, so they survive a save.
        let loaded = Engine::load_project(&e.save_project()).expect("artboard project loads");
        assert_eq!(loaded.artboard_background(ab), vec![255, 255, 255, 0]);
        assert!(loaded.artboard_ids().contains(&ab));
    }

