// Filter ▸ Artistic ▸ Rough Pastels — a relief texture overlaid on the image,
// stronger in dark areas (chalk scraped off), plus pastel-stroke smearing.
#[cfg(test)]
mod rough_pastels_tests {
    use super::*;

    fn r(e: &Engine, x: i32, y: i32) -> i32 {
        ((e.pick_color(x, y) >> 24) & 255) as i32
    }
    fn flat(v: u8) -> Engine {
        let mut e = Engine::new(32, 32);
        e.select_rect(0, 0, 32, 32, 0);
        e.fill_selection(v, v, v, 255);
        e.select_none();
        e
    }
    // Variance of the red channel across the whole 32×32 doc.
    fn variance(e: &Engine) -> f32 {
        let vals: Vec<f32> = (0..32)
            .flat_map(|y| (0..32).map(move |x| (x, y)))
            .map(|(x, y)| r(e, x, y) as f32)
            .collect();
        let mean = vals.iter().sum::<f32>() / vals.len() as f32;
        vals.iter().map(|v| (v - mean).powi(2)).sum::<f32>() / vals.len() as f32
    }
    fn split() -> Engine {
        let mut e = Engine::new(32, 32);
        e.select_rect(0, 0, 16, 32, 0);
        e.fill_selection(0, 0, 0, 255);
        e.select_rect(16, 0, 16, 32, 0);
        e.fill_selection(255, 255, 255, 255);
        e.select_none();
        e
    }

    #[test]
    fn relief_adds_texture() {
        let mut none = flat(128);
        none.filter_rough_pastels(0, 0, 0.5, 0.0, 1); // no relief, no stroke → flat
        assert!(
            variance(&none) < 0.01,
            "relief 0 leaves the flat field flat"
        );
        let mut relief = flat(128);
        relief.filter_rough_pastels(0, 0, 0.5, 0.5, 1);
        assert!(
            variance(&relief) > 1.0,
            "relief embosses a repeating texture (variance {})",
            variance(&relief)
        );
    }

    #[test]
    fn texture_stronger_in_dark_areas() {
        let mut dark = flat(60);
        dark.filter_rough_pastels(0, 0, 0.5, 0.5, 1);
        let mut light = flat(210);
        light.filter_rough_pastels(0, 0, 0.5, 0.5, 1);
        assert!(
            variance(&dark) > variance(&light),
            "the chalk texture shows more in dark areas (dark var {}, light var {})",
            variance(&dark),
            variance(&light)
        );
    }

    #[test]
    fn stroke_length_smears_edges() {
        let mut e = split();
        assert_eq!(r(&e, 15, 16), 0, "dark side starts black");
        e.filter_rough_pastels(40, 0, 0.5, 0.0, 1); // long strokes, no relief
        assert!(
            r(&e, 15, 16) > 5,
            "pastel strokes smear the dark edge toward light neighbours (got {})",
            r(&e, 15, 16)
        );
    }

    #[test]
    fn preserves_alpha_and_respects_selection() {
        let mut e = split();
        let before_right = r(&e, 24, 16);
        e.select_rect(0, 0, 12, 32, 0);
        e.filter_rough_pastels(40, 0, 0.5, 0.5, 1);
        e.select_none();
        assert_eq!(
            r(&e, 24, 16),
            before_right,
            "unselected pixels are untouched"
        );
        assert_eq!((e.pick_color(4, 16) & 255), 255, "alpha stays opaque");
    }
}

