    #[test]
    fn raw_text_effect_and_adjustment_blocks_survive_all_round_trips() {
        let mut source = Engine::new(3, 2);
        source.layers[0].kind = 2;
        source.layers[0].text_spec = r#"{
            "v":1,"kind":"point","vertical":false,"ax":1,"ay":1,
            "runs":[{"text":"Semantic authority","font":"Inter","size":14.0,
                     "color":[12,34,56,255]}],
            "font":"Inter","size":14.0,"color":[12,34,56,255],
            "bold":false,"italic":false,"tracking":0.0,"kerning":"metrics",
            "leading":0.0,"hScale":1.0,"vScale":1.0,"align":"left",
            "direction":"ltr","composer":"latin","boxW":0.0,"boxH":0.0,
            "firstIndent":0.0,"leftIndent":0.0,"rightIndent":0.0,
            "spaceBefore":0.0,"spaceAfter":0.0,"antialias":"sharp",
            "digits":"latin","kashida":"none","diacriticX":0.0,"diacriticY":0.0,
            "path":[],"liga":false,"dlig":false,"frac":false,"ordn":false,
            "features":{},"stroke":null,"shadow":null,
            "warp":{"style":"none","bend":0.0,"h":0.0,"v":0.0,"orient":"h"}
        }"#
        .into();
        let mut bytes = source.export_psd().expect("PSD exports");
        for (index, key) in RETAINED_SEMANTIC_KEYS.iter().skip(1).enumerate() {
            bytes = tag_first_psd_layer_with_data(
                bytes,
                *key,
                &[0xA5, index as u8, 0x5A],
            );
        }
        let expected = parsed_retained_semantic_blocks(&bytes);
        assert_eq!(
            expected.iter().map(|block| block.key).collect::<Vec<_>>(),
            RETAINED_SEMANTIC_KEYS
        );

        let imported = Engine::from_format(&bytes).expect("semantic PSD imports");
        assert_eq!(
            imported.layers[0]
                .psd_smart_blocks
                .iter()
                .filter(|block| RETAINED_SEMANTIC_KEYS.contains(&block.key))
                .cloned()
                .collect::<Vec<_>>(),
            expected
        );

        let mut native = Engine::load_project(&imported.save_project())
            .expect("semantic project reloads");
        assert_eq!(parsed_retained_semantic_blocks(&native.export_psd().expect("PSD exports")), expected);

        let mut graphics = load_graphics_container_impl(&imported.save_graphics_container())
            .expect("semantic graphics reloads");
        assert_eq!(parsed_retained_semantic_blocks(&graphics.export_psd().expect("PSD exports")), expected);

        let mut direct = imported;
        assert_eq!(parsed_retained_semantic_blocks(&direct.export_psd().expect("PSD exports")), expected);
    }

