    fn raw_crop_precedes_orientation_and_rotates_pixel_order() {
        let (width, height) = (4usize, 3usize);
        let mut samples = Vec::new();
        for index in 0..width * height {
            let value = (index as u16 + 1) * 4000;
            samples.extend_from_slice(&[value, value, value]);
        }
        let cfa = rawloader::CFA::new("");
        let matrix = raw_fallback_camera_to_xyz();
        let rendered = render_raw(RawRenderSpec {
            width,
            height,
            cpp: 3,
            samples: RawSamples::Integer(&samples),
            cfa: &cfa,
            crops: [1, 1, 0, 0], // crop to x=0..2, y=1..2 (3×2)
            orientation: rawloader::Orientation::Rotate90,
            black: [0; 4],
            white: [65535; 4],
            wb: [1.0; 4],
            camera_to_xyz: matrix,
            demosaic: RawDemosaic::Adaptive,
        })
        .expect("crop and rotate RAW");
        assert_eq!((rendered.width, rendered.height), (2, 3));
        assert_eq!(rendered.crops, [1, 1, 0, 0]);
        // Clockwise rotation after the crop: bottom-to-top in each source column.
        let source_indices = [8usize, 4, 9, 5, 10, 6];
        let actual: Vec<u16> = rendered
            .pixels
            .chunks_exact(4)
            .map(|pixel| pixel[0])
            .collect();
        let expected: Vec<u16> = source_indices
            .iter()
            .map(|index| {
                let value = (*index as f32 + 1.0) * 4000.0 / 65535.0;
                raw_camera_to_srgb([value, value, value, 0.0], matrix)[0]
            })
            .collect();
        assert_eq!(actual, expected);
    }

