    #[test]
    fn develop_optics_defringe_changes_colour_edges() {
        // Defringe (param 1052) desaturates purple colour fringes along
        // high-contrast edges — paint one beside dev_doc's bright central block.
        // (#444: the old alpha-edge op only touched the border of an opaque photo.)
        let mut e = dev_doc();
        for y in 8..16usize {
            let p = (y * 24 + 7) * 4;
            Arc::make_mut(&mut e.layers[0].pixels)[p..p + 3].copy_from_slice(&[30000, 10000, 40000]);
        }
        let before = px(&e);
        let mut p = neutral_params();
        p[1052] = 1.0; // full Purple Defringe
        e.camera_raw_develop(&p);
        let after = px(&e);
        assert_ne!(after, before, "defringe alters fringed colour edges");
        let chroma = |buf: &[u16], i: usize| {
            buf[i..i + 3].iter().max().unwrap() - buf[i..i + 3].iter().min().unwrap()
        };
        let fringe = (10 * 24 + 7) * 4; // an interior pixel of the painted fringe
        assert!(
            chroma(&after, fringe) < chroma(&before, fringe),
            "the purple fringe beside the block is desaturated"
        );
    }

    #[test]
    fn develop_hsl_band_desaturates_only_its_hue() {
        // Red-band saturation = -1 turns the red pixel grey; the green pixel (a
        // different band) and the neutral-grey pixel (saturation gate) stay put.
        let mut e = rgb_strip();
        let mut p = neutral_params();
        p[1061] = -1.0; // sat[0] — Red band
        e.camera_raw_develop(&p);
        let out = px(&e);
        let (r, g, b) = (out[0] as i32, out[1] as i32, out[2] as i32);
        assert!(
            (r - g).abs() < 600 && (g - b).abs() < 600,
            "red desaturated to grey: {r},{g},{b}"
        );
        assert!(
            (25000..40000).contains(&r),
            "grey sits near mid, not red: {r}"
        );
        assert_eq!(
            (out[4], out[5], out[6]),
            (0, 65535, 0),
            "green pixel unchanged"
        );
        assert_eq!(
            (out[8], out[9], out[10]),
            (32768, 32768, 32768),
            "grey pixel unchanged (saturation gate)"
        );
    }

    #[test]
    fn develop_hsl_band_luminance_brightens_only_its_hue() {
        // Green-band luminance = +1 lightens the green pixel toward white; the red
        // pixel (a different band) is untouched.
        let mut e = rgb_strip();
        let before = px(&e);
        let mut p = neutral_params();
        p[1069 + 3] = 1.0; // lum[3] — Green band
        e.camera_raw_develop(&p);
        let out = px(&e);
        assert!(
            out[5] as i32 >= before[5] as i32,
            "green channel did not darken"
        );
        assert!(
            out[4] > before[4] || out[6] > before[6],
            "green pixel lightened toward white"
        );
        assert_eq!(
            (out[0], out[1], out[2]),
            (65535, 0, 0),
            "red pixel unchanged"
        );
    }

    #[test]
    fn develop_color_grade_pushes_midtones_toward_the_wheel_hue() {
        // A red Midtones wheel (hue 0°, sat 1) warms the mid-grey pixel: its red
        // channel rises above green/blue. Shadows/Highlights wheels stay neutral.
        let mut e = rgb_strip();
        let before = px(&e);
        let mut p = neutral_params();
        p[1077 + 2] = 0.0; // Midtones hue = 0° (red)
        p[1077 + 3] = 1.0; // Midtones saturation = 1
        e.camera_raw_develop(&p);
        let out = px(&e);
        assert!(
            out[8] as i32 > before[8] as i32 && out[8] > out[9] && out[8] > out[10],
            "grey midtone warmed toward red: {},{},{}",
            out[8],
            out[9],
            out[10]
        );
    }

    #[test]
    fn develop_geometry_rotate_warps_the_image() {
        // The straighten rotation (param 1085) resamples the asymmetric doc.
        let mut e = dev_doc();
        let before = px(&e);
        let mut p = neutral_params();
        p[1085] = 0.5;
        e.camera_raw_develop(&p);
        assert_ne!(px(&e), before, "a straighten rotation resamples the image");
    }

    #[test]
    fn develop_geometry_keystone_warps_geometry() {
        // Vertical keystone (param 1083) tapers the frame — a projective warp.
        let mut e = dev_doc();
        let before = px(&e);
        let mut p = neutral_params();
        p[1083] = 0.6;
        e.camera_raw_develop(&p);
        assert_ne!(px(&e), before, "vertical keystone resamples the image");
    }

    #[test]
    fn develop_matches_camera_raw_for_shared_params() {
        let mut p = neutral_params();
        p[2] = 0.3; // temp
        p[4] = 0.2; // exposure
        p[5] = 0.15; // contrast
        p[6] = -0.2; // highlights
        p[7] = 0.3; // shadows
        p[11] = 0.25; // clarity
        p[12] = 0.1; // dehaze
        p[13] = 0.4; // vibrance
        p[14] = 0.2; // saturation

        let mut via_develop = dev_doc();
        via_develop.camera_raw_develop(&p);

        let mut via_camera_raw = dev_doc();
        via_camera_raw.camera_raw(0.3, 0.2, 0.15, -0.2, 0.3, 0.25, 0.1, 0.4, 0.2, 0.0);

        assert_eq!(
            px(&via_develop),
            px(&via_camera_raw),
            "develop with only the shared Basic sliders == a direct camera_raw call"
        );
    }

    #[test]
    fn develop_is_a_single_history_step() {
        let mut e = dev_doc();
        let before = px(&e);
        let mut p = neutral_params();
        p[4] = 0.4; // exposure
        p[8] = 0.3; // whites
        e.camera_raw_develop(&p);
        assert_ne!(px(&e), before);
        e.undo();
        assert_eq!(px(&e), before, "one undo restores the pre-develop pixels");
    }

    #[test]
    fn develop_short_params_are_safe() {
        // Truncated to header + temp + tint + exposure; every later stage defaults
        // to neutral and must not panic.
        let mut e = dev_doc();
        let before = px(&e);
        let short = vec![1.0f32, 1.0, 0.0, 0.0, 0.5];
        e.camera_raw_develop(&short);
        assert_ne!(
            px(&e),
            before,
            "the exposure that was present still applies"
        );
    }

    #[test]
    fn develop_proxy_scale_scales_radii() {
        // Texture is a spatial stage: halving its radius via proxyScale changes the
        // result. A purely pointwise recipe is unaffected by proxyScale.
        let mut p = neutral_params();
        p[10] = 0.8; // texture amount

        let mut full = dev_doc();
        full.camera_raw_develop(&p);

        let mut half = dev_doc();
        p[1] = 0.5; // proxyScale
        half.camera_raw_develop(&p);
        assert_ne!(
            px(&full),
            px(&half),
            "a spatial stage's radius shrinks with proxyScale"
        );

        // Pointwise-only recipe: proxyScale must not matter.
        let mut pw = neutral_params();
        pw[4] = 0.3; // exposure only
        let mut a = dev_doc();
        a.camera_raw_develop(&pw);
        pw[1] = 0.5;
        let mut b = dev_doc();
        b.camera_raw_develop(&pw);
        assert_eq!(px(&a), px(&b), "pointwise stages ignore proxyScale");
    }

    fn smart_dev_object() -> (Engine, u32) {
        let mut e = dev_doc();
        let id = e.layers[e.active].id;
        e.convert_to_smart_object(id);
        (e, id)
    }

    #[test]
    fn develop_as_smart_filter_rerenders_deterministically() {
        let mut p = neutral_params();
        p[4] = 0.35; // exposure
        p[13] = 0.5; // vibrance

        let (mut a, ida) = smart_dev_object();
        a.smart_add_filter(ida, 17, &p);
        let (mut b, idb) = smart_dev_object();
        b.smart_add_filter(idb, 17, &p);
        assert_eq!(
            px(&a),
            px(&b),
            "fid 17 renders identically for the same recipe"
        );

        // Re-render (disable then re-enable) reproduces the exact same pixels.
        let once = px(&a);
        a.set_smart_filters_enabled(ida, false);
        a.set_smart_filters_enabled(ida, true);
        assert_eq!(px(&a), once, "a stack re-render is deterministic");
    }

    #[test]
    fn smart_filter_params_roundtrip() {
        let mut p = neutral_params();
        p[4] = 0.2;
        p[9] = 0.4; // blacks
        let (mut e, id) = smart_dev_object();
        e.smart_add_filter(id, 17, &p);
        assert_eq!(
            e.smart_filter_params(id, 0),
            p,
            "params round-trip verbatim"
        );
        assert!(
            e.smart_filter_params(id, 5).is_empty(),
            "absent index → empty vec"
        );
        assert!(
            e.smart_filter_params(999, 0).is_empty(),
            "absent layer → empty vec"
        );
    }

    #[test]
    fn smart_update_filter_replaces_in_place() {
        let mut p = neutral_params();
        p[4] = 0.2;
        let (mut e, id) = smart_dev_object();
        e.smart_add_filter(id, 17, &p);
        let after_add = px(&e);
        assert_eq!(e.smart_filter_count(id), 1);

        let mut p2 = neutral_params();
        p2[4] = -0.4; // opposite exposure
        e.smart_update_filter(id, 0, &p2);
        assert_eq!(e.smart_filter_count(id), 1, "count unchanged (in-place)");
        assert_eq!(e.smart_filter_params(id, 0), p2, "params replaced");
        assert_ne!(px(&e), after_add, "the composite reflects the new recipe");
    }

    #[test]
    fn smart_update_filter_out_of_range_is_noop() {
        let mut p = neutral_params();
        p[4] = 0.2;
        let (mut e, id) = smart_dev_object();
        e.smart_add_filter(id, 17, &p);
        let hist = e.history_current();
        let before = px(&e);
        e.smart_update_filter(id, 5, &neutral_params()); // out of range
        assert_eq!(e.history_current(), hist, "no history entry added");
        assert_eq!(px(&e), before, "no pixels touched");
        e.smart_update_filter(4242, 0, &neutral_params()); // absent layer
        assert_eq!(e.history_current(), hist, "still no history entry");
    }

    #[test]
    fn smart_update_filter_unchanged_is_noop() {
        let mut p = neutral_params();
        p[4] = 0.2;
        let (mut e, id) = smart_dev_object();
        e.smart_add_filter(id, 17, &p);
        let hist = e.history_current();
        let pushes = e.undo_pushes();

        e.smart_update_filter(id, 0, &p);

        assert_eq!(e.history_current(), hist, "no history entry added");
        assert_eq!(e.undo_pushes(), pushes, "no dirty/history signal emitted");
    }

    #[test]
    fn develop_fid17_survives_save_load() {
        let mut p = neutral_params();
        p[4] = 0.3;
        p[13] = 0.6;
        let (mut e, id) = smart_dev_object();
        e.smart_add_filter(id, 17, &p);
        let bytes = e.save_project();
        let e2 = Engine::load_project(&bytes).expect("load");
        assert_eq!(e2.smart_filter_count(id), 1, "the fid-17 stack round-trips");
        assert_eq!(
            e2.smart_filter_params(id, 0),
            p,
            "the recipe params survive save/load"
        );
    }

    #[test]
    fn advanced_fid17_tail_survives_save_load_verbatim() {
        let mut mask = exposure_mask(1, vec![[0.2, 0.5, 1.0], [0.8, 0.5, 1.0]]);
        mask.adjustments[10] = 0.25;
        let mut params = advanced_params(&[[1.0, 0.7, 0.5, 0.3, 0.5, 0.06, 0.5, 0.8]], &[mask]);
        params[1088] = 1.0;
        params[1090] = 0.15;
        params[1107] = 1.0;
        params[1108] = 0.35;
        let (mut engine, id) = smart_dev_object();
        engine.smart_add_filter(id, 17, &params);
        let rendered = px(&engine);
        let bytes = engine.save_project();
        let loaded = Engine::load_project(&bytes).expect("load advanced fid17");
        assert_eq!(loaded.smart_filter_id(id, 0), 17);
        assert_eq!(
            loaded.smart_filter_params(id, 0),
            params,
            "the variable tail remains byte-for-byte re-editable"
        );
        assert_eq!(
            loaded.layers[loaded.layer_index(id).unwrap()].pixels.to_vec(),
            rendered,
            "the loaded smart object re-renders the same advanced recipe"
        );
    }

    #[test]
    fn persisted_fid17_spatial_cost_multipliers_are_bounded_on_rerender() {
        let mut hostile = neutral_params();
        hostile[1] = f32::MAX; // proxy scale drives the Texture radius
        hostile[10] = 1.0;
        hostile[15] = 1.0;
        hostile[16] = f32::MAX; // Smart Sharpen radius
        hostile[1052] = f32::MAX; // repeated Defringe passes

        // Model an untrusted project without rendering the hostile stack before
        // serialization. Enabling it after load must stay bounded while retaining
        // the original params for Camera Raw re-editing.
        let (mut crafted, id) = smart_dev_object();
        let layer_index = crafted.layer_index(id).unwrap();
        crafted.layers[layer_index]
            .smart_filters
            .push((17, hostile.clone()));
        crafted.layers[layer_index].smart_enabled = false;
        let bytes = crafted.save_project();
        let mut loaded = Engine::load_project(&bytes).expect("load crafted fid-17 project");
        assert_eq!(loaded.smart_filter_params(id, 0), hostile);
        loaded.set_smart_filters_enabled(id, true);

        let mut bounded = hostile;
        bounded[1] = 1.0;
        bounded[16] = 3.0;
        bounded[1052] = 1.0;
        let (mut expected, expected_id) = smart_dev_object();
        expected.smart_add_filter(expected_id, 17, &bounded);
        assert_eq!(
            loaded.layers[loaded.layer_index(id).unwrap()].pixels.to_vec(),
            expected.layers[expected.layer_index(expected_id).unwrap()].pixels.to_vec(),
            "crafted spatial multipliers render with canonical finite bounds"
        );
    }

    #[test]
    fn smart_filter_identity_and_proxy_match_live_replacement_without_mutation() {
        let mut current_params = neutral_params();
        current_params[4] = 0.25;
        current_params[13] = 0.3;
        let (mut live, id) = smart_dev_object();
        live.smart_add_filter(id, 17, &current_params);
        assert_eq!(live.smart_filter_id(id, 0), 17);
        assert_eq!(live.smart_filter_id(id, 1), -1);
        assert_eq!(live.smart_filter_id(9999, 0), -1);

        let live_pixels = px(&live);
        let history_before = live.history_current();
        let initial = live
            .smart_filter_proxy_engine(
                id,
                0,
                17,
                &current_params,
                0,
                0,
                live.width(),
                live.height(),
                0,
            )
            .expect("initial smart-filter proxy");
        assert_eq!(
            initial.layers[0].pixels.to_vec(), live_pixels,
            "seeding with the stored params must not double-apply fid 17"
        );

        let mut changed_params = neutral_params();
        changed_params[1] = 0.25; // UI display scale; full smart render normalizes this to 1
        changed_params[4] = -0.45;
        changed_params[10] = 0.4;
        let changed = live
            .smart_filter_proxy_engine(
                id,
                0,
                17,
                &changed_params,
                0,
                0,
                live.width(),
                live.height(),
                0,
            )
            .expect("replacement smart-filter proxy");

        let (mut committed, committed_id) = smart_dev_object();
        committed.smart_add_filter(committed_id, 17, &current_params);
        let mut committed_params = changed_params.clone();
        committed_params[1] = 1.0; // OK renders at full document resolution
        committed.smart_update_filter(committed_id, 0, &committed_params);
        assert_eq!(
            changed.layers[0].pixels.to_vec(),
            px(&committed),
            "temporary preview must equal the pixels produced by OK/update"
        );
        assert_eq!(
            px(&live),
            live_pixels,
            "preview never changes the live cache"
        );
        assert_eq!(
            live.smart_filter_params(id, 0),
            current_params,
            "preview never changes the stored recipe"
        );
        assert_eq!(
            live.history_current(),
            history_before,
            "preview never adds a live history state"
        );
    }

    #[test]
    fn smart_filter_proxy_can_preview_a_temporary_append() {
        let mut params = neutral_params();
        params[4] = 0.4;
        let (live, id) = smart_dev_object();
        let preview = live
            .smart_filter_proxy_engine(id, -1, 17, &params, 0, 0, live.width(), live.height(), 0)
            .expect("append preview");

        let (mut committed, committed_id) = smart_dev_object();
        committed.smart_add_filter(committed_id, 17, &params);
        assert_eq!(preview.layers[0].pixels.to_vec(), px(&committed));
        assert_eq!(
            live.smart_filter_count(id),
            0,
            "temporary append is non-mutating"
        );
    }

    #[test]
    fn proxy_engine_region_scales_and_crops() {
        let e = dev_doc();
        // Crop an 8×8 region and cap the long edge at 4 → a 4×4 proxy.
        let proxy = e.proxy_engine(4, 4, 8, 8, 4);
        assert_eq!(proxy.width(), 4, "long edge scaled to max_dim");
        assert_eq!(proxy.height(), 4);
        // The proxy carries the cropped content, not a fresh white background.
        let all_white = proxy.layers[0]
            .pixels
            .chunks_exact(4)
            .all(|c| c[0] == 65535 && c[1] == 65535 && c[2] == 65535);
        assert!(!all_white, "proxy holds the source region, not white");

        // No downscale when the region already fits under max_dim.
        let same = e.proxy_engine(0, 0, 6, 6, 32);
        assert_eq!(same.width(), 6);
        assert_eq!(same.height(), 6);
    }

    // ── VIS-LS-03: the whole Filter menu rides the smart-filter stack ──────

    // A 16×16 two-tone smart object with enough structure for every kernel.
    fn smart_menu_object() -> (Engine, u32) {
        let mut e = Engine::new(16, 16);
        let id = e.add_layer("S");
        e.select_rect(0, 0, 8, 16, 0);
        e.fill_selection(200, 40, 40, 255);
        e.select_rect(8, 0, 8, 16, 0);
        e.fill_selection(40, 40, 200, 255);
        e.select_none();
        e.convert_to_smart_object(id);
        (e, id)
    }

